test("JS oracle: SSO select is an unsigned STRICT below-0x10", () => {
  eq(anm2SsoUsesHeap(0), false);
  eq(anm2SsoUsesHeap(0xf), false);
  eq(anm2SsoUsesHeap(0x10), true);   /* boundary: cap == 16 already heap */
  eq(anm2SsoUsesHeap(0x11), true);
  eq(anm2SsoUsesHeap(0xffffffff), true); /* unsigned, not a negative */
  eq(anm2SsoDataPtr(0x1000, 0xf, 0x2000), 0x1000);
  eq(anm2SsoDataPtr(0x1000, 0x10, 0x2000), 0x2000);
  eq(anm2SsoDataPtr(0x1000, 0xffffffff, 0x2000), 0x2000);
  COUNT.cases += 8;
});

test("JS oracle: inline strcmp is an unsigned byte compare to -1/0/1", () => {
  const b = (s) => {
    const out = [];
    for (const ch of s) out.push(ch.codePointAt(0) & 0xff);
    out.push(0);
    return out;
  };
  eq(anm2StrcmpBytes(b(""), b("")), 0);
  eq(anm2StrcmpBytes(b("Cursor"), b("Cursor")), 0);
  eq(anm2StrcmpBytes(b("Cursor"), b("Cursos")), -1);
  eq(anm2StrcmpBytes(b("Cursos"), b("Cursor")), 1);
  eq(anm2StrcmpBytes(b("Curso"), b("Cursor")), -1);   /* prefix is smaller */
  eq(anm2StrcmpBytes(b("Cursor"), b("Curso")), 1);
  eq(anm2StrcmpBytes(b(""), b("a")), -1);
  /* odd-length mismatch on the SECOND byte of a pair */
  eq(anm2StrcmpBytes(b("ab"), b("aa")), 1);
  eq(anm2StrcmpBytes(b("aa"), b("ab")), -1);
  /* high-bit byte: unsigned ordering, a signed char compare would flip this */
  eq(anm2StrcmpBytes([0x80, 0], [0x01, 0]), 1);
  eq(anm2StrcmpBytes([0x01, 0], [0x80, 0]), -1);
  COUNT.cases += 11;
});

test("JS oracle: Reset scalar arithmetic and residual plan", () => {
  eq(anm2ResetNameHostNeeded(0), false);
  eq(anm2ResetNameHostNeeded(1), true);
  eq(anm2ResetNameHostNeeded(-1), true);
  eq(anm2ResetNameHostNeeded(0x100), true);  /* full dword test, not a byte */
  eq(anm2ResetTeardownNeeded(0), false);
  eq(anm2ResetTeardownNeeded(4), true);
  eq(anm2ResetArrayHeader(0x1000), 0xffc);
  eq(anm2ResetArrayHeader(0), 0xfffffffc);   /* wraps, no null guard */
  eq(anm2ResetFreeSize(0), 4);
  eq(anm2ResetFreeSize(1), 0xa0 + 4);
  eq(anm2ResetFreeSize(3), 3 * 0xa0 + 4);
  eq(anm2ResetFreeSize(0x1999999), (Math.imul(0x1999999, 0xa0) + 4) >>> 0);

  /* The freed size comes from the count RE-READ after the destructor pass. */
  const torn = anm2ResetTeardownPlan({
    layerState7c: 0x2000,
    countBefore: 5,
    countAfter: 2,
  });
  eq(torn.dtorCount, 5);
  eq(torn.freeCount, 2);
  eq(torn.freeSize, 2 * 0xa0 + 4);
  eq(torn.headerPtr, 0x1ffc);
  eq(torn.dtorArrayPtr, 0x2000);

  const none = anm2ResetTeardownPlan({ layerState7c: 0, countBefore: 9, countAfter: 9 });
  eq(none.teardownNeeded, false);
  eq(none.freeSize, 0);
  eq(none.dtorCount, 0);

  const plan = anm2ResetPlan({ filenameSize10: 0, layerState7c: 0 });
  eq(plan.hostCallCount, 2);           /* the two apply calls are unconditional */
  eq(plan.pureComplete, false);
  const plan2 = anm2ResetPlan({
    filenameSize10: 7,
    layerState7c: 0x800,
    countAfter: 3,
  });
  eq(plan2.hostCallCount, 5);
  eq(plan2.freeSize, 3 * 0xa0 + 4);
  COUNT.cases += 24;
});

test("JS oracle: Reset field-write table widths and values", () => {
  const writes = anm2ResetFieldWrites({});
  const byOffset = new Map(writes.map((w) => [w.offset, w]));
  eq(byOffset.get(ANM2_OFF_OVERLAY_FIRST_70).width, 1);
  eq(byOffset.get(ANM2_OFF_FLIP_PAIR_100).width, 2);
  eq(byOffset.get(ANM2_OFF_LOADED_PAIR_108).width, 2);
  eq(byOffset.get(ANM2_OFF_PLAYBACK_SPEED_104).width, 4);
  eq(byOffset.get(ANM2_OFF_PLAYBACK_SPEED_104).value, ANM2_F32_ONE_BITS);
  eq(byOffset.get(ANM2_OFF_UNNAMED_10C).value >>> 0, 0xffffffff);
  eq(byOffset.get(ANM2_OFF_BITFLAGS_110).value, 0);
  /* first colour block: four leading ones */
  for (let k = 0; k < 4; ++k) {
    eq(byOffset.get(ANM2_OFF_COLOR_A8 + k * 4).value, ANM2_F32_ONE_BITS);
  }
  /* second colour block: only three, then a zero (defect D5) */
  for (let k = 0; k < 3; ++k) {
    eq(byOffset.get(ANM2_OFF_CHAMPION_COLOR_D4 + k * 4).value, ANM2_F32_ONE_BITS);
  }
  eq(byOffset.get(ANM2_OFF_CHAMPION_COLOR_D4 + 12).value, 0);
  /* nothing inside the two host-owned animation states */
  for (const w of writes) {
    ok(
      w.offset < ANM2_OFF_ANIM_STATE_30 ||
        w.offset >= ANM2_OFF_OVERLAY_STATE_50 + ANM2_ANIM_STATE_SIZE,
      `field write at ${w.offset.toString(16)} lands in a host sub-object`,
    );
    ok(w.offset + w.width <= ANM2_SIZE, "field write past sizeof(ANM2)");
  }
  COUNT.cases += 12;
});

test("JS oracle: GetLayer(int) bounds are SIGNED and re-tested", () => {
  eq(anm2LayerIndexInRange(0, 1), true);
  eq(anm2LayerIndexInRange(-1, 5), false);
  eq(anm2LayerIndexInRange(4, 4), false);   /* strict upper bound */
  eq(anm2LayerIndexInRange(3, 4), true);
  /* signed: a count with bit 31 set rejects every index */
  eq(anm2LayerIndexInRange(0, -1), false);
  eq(anm2LayerIndexInRange(0, 0x80000000 | 0), false);
  eq(anm2LayerByteOffset(0), 0);
  eq(anm2LayerByteOffset(3), 3 * 0xa0);
  eq(anm2LayerByteOffset(0x1999999), Math.imul(0x1999999, 0xa0) >>> 0);

  /* fast path: in range before the diagnostic, no second look */
  const fast = anm2GetLayerPlan({ index: 2, countPre: 4, countPost: 0, basePost: 0x3000 });
  eq(fast.logNeeded, false);
  eq(fast.inRangePost, true);
  eq(fast.resultPtr, 0x3000 + 2 * 0xa0);
  eq(fast.usesStaticFallback, false);

  /* recapture: rejected first, accepted against the reloaded count */
  const recap = anm2GetLayerPlan({ index: 2, countPre: 1, countPost: 4, basePost: 0x3000 });
  eq(recap.logNeeded, true);
  eq(recap.inRangePre, false);
  eq(recap.inRangePost, true);
  eq(recap.resultPtr, 0x3000 + 2 * 0xa0);

  /* still out of range -> shared function-local static, never null (D1) */
  const miss = anm2GetLayerPlan({ index: 9, countPre: 1, countPost: 1, basePost: 0x3000 });
  eq(miss.logNeeded, true);
  eq(miss.inRangePost, false);
  eq(miss.usesStaticFallback, true);
  eq(miss.resultPtr, ANM2_GET_LAYER_STATIC_VA);
  ok(miss.resultPtr !== 0, "GetLayer(int) miss must not be null");
  COUNT.cases += 22;
});

test("JS oracle: name-walk loop bound is UNSIGNED (D2 asymmetry)", () => {
  eq(anm2LayerWalkEnter(0), false);
  eq(anm2LayerWalkEnter(1), true);
  eq(anm2LayerWalkEnter(0xffffffff), true);
  eq(anm2LayerWalkContinue(1, 2), true);
  eq(anm2LayerWalkContinue(2, 2), false);
  eq(anm2LayerWalkContinue(2, 0xffffffff), true);  /* unsigned, unlike GetLayer(int) */
  /* the same count value: signed overload rejects, unsigned walk accepts */
  eq(anm2LayerIndexInRange(0, -1), false);
  eq(anm2LayerWalkEnter(0xffffffff), true);
  eq(anm2AnimDataByteOffset(0), 0);
  eq(anm2AnimDataByteOffset(3), 3 * 0x13c);
  eq(anm2AnimDataByteOffset(0x1000000), Math.imul(0x1000000, 0x13c) >>> 0);
  COUNT.cases += 11;
});

test("JS oracle: 0x0040a5d0 apply residual", () => {
  const miss = anm2AnimApplyPlan(-1, 1);
  eq(miss.found, false);
  eq(miss.warnLogNeeded, true);
  eq(miss.warnLogLevel, 1);
  eq(miss.warnLogStrVa, ANM2_ANIM_MISS_LOG_STR_VA);
  eq(miss.applyVa, 0);
  eq(miss.result, 0);

  const hitReset = anm2AnimApplyPlan(2, 1);
  eq(hitReset.applyVa, ANM2_HOST_VA_ANIM_STATE_APPLY);
  eq(hitReset.elemByteOffset, 2 * 0x13c);
  eq(hitReset.applyRecvOff, ANM2_OFF_ANIM_STATE_30);
  eq(hitReset.result, 1);

  const hitAlt = anm2AnimApplyPlan(2, 0);
  eq(hitAlt.applyVa, ANM2_HOST_VA_ANIM_STATE_APPLY_ALT);

  /* only the LOW BYTE of the flag is tested: 0x100 reads as false */
  eq(anm2AnimApplyPlan(0, 0x100).applyVa, ANM2_HOST_VA_ANIM_STATE_APPLY_ALT);
  eq(anm2AnimApplyPlan(0, 0x101).applyVa, ANM2_HOST_VA_ANIM_STATE_APPLY);
  COUNT.cases += 13;
});

test("Wasm matches JS: SSO select + inline strcmp", () => {
  const caps = [0, 1, 0xf, 0x10, 0x11, 0x7fffffff, 0x80000000, 0xffffffff];
  for (const cap of caps) {
    eq(
      wasm.isaac_anm2_sso_uses_heap(cap) !== 0,
      anm2SsoUsesHeap(cap),
      `sso heap cap=${cap}`,
    );
    eq(
      wasm.isaac_anm2_sso_data_ptr(0x1000, cap, 0x2000) >>> 0,
      anm2SsoDataPtr(0x1000, cap, 0x2000),
      `sso ptr cap=${cap}`,
    );
    COUNT.cases += 1;
  }
  const pairs = [
    ["", ""],
    ["Cursor", "Cursor"],
    ["Cursor", "Cursos"],
    ["Cursos", "Cursor"],
    ["Curso", "Cursor"],
    ["Cursor", "Curso"],
    ["", "a"],
    ["a", ""],
    ["ab", "aa"],
    ["aa", "ab"],
    ["abc", "abd"],
    ["Head", "HeadOverlay"],
  ];
  for (const [a, b] of pairs) {
    pokeCString(STR_A, a);
    pokeCString(STR_B, b);
    eq(
      wasm.isaac_anm2_strcmp_inline(STR_A, STR_B),
      anm2StrcmpMem(shadow, STR_A, STR_B),
      `strcmp ${a}|${b}`,
    );
    COUNT.cases += 1;
  }
  /* high-bit byte ordering must stay unsigned */
  poke(STR_A, [0x80, 0]);
  poke(STR_B, [0x01, 0]);
  eq(wasm.isaac_anm2_strcmp_inline(STR_A, STR_B), 1, "0x80 > 0x01 unsigned");
  eq(anm2StrcmpMem(shadow, STR_A, STR_B), 1);
  poke(STR_A, [0x41, 0xff, 0]);
  poke(STR_B, [0x41, 0x01, 0]);
  eq(wasm.isaac_anm2_strcmp_inline(STR_A, STR_B), 1, "second-byte unsigned");
  eq(anm2StrcmpMem(shadow, STR_A, STR_B), 1);
  COUNT.cases += 2;
});

