/* ============ v54-band4: state-receiver frame set/get trio ============ */

/* IsaacAnm2StateSetLayerFramePlan: 5 x 4 bytes. */
const STATE_SET_LAYER_FRAME_OFF = {
  entered: 0, needsLog: 4, needsWalk: 8, walkIndex: 12, frameBits: 16,
};
const PLAN_STATE_SET_LAYER_FRAME = V5_BASE + 0x1080; /* 5 x 4 = 20 bytes */
/* IsaacAnm2StateSetNullFramePlan: 6 x 4 bytes. */
const STATE_SET_NULL_FRAME_OFF = {
  entered: 0, needsLog1: 4, needsLog2: 8, needsWalk: 12, walkIndex: 16,
  frameBits: 20,
};
const PLAN_STATE_SET_NULL_FRAME = V5_BASE + 0x10a0; /* 6 x 4 = 24 bytes */
/* IsaacAnm2StateGetLayerFramePlan: 4 x 4 bytes. */
const STATE_GET_LAYER_FRAME_OFF = {
  entered: 0, needsLog: 4, inRange: 8, result: 12,
};
const PLAN_STATE_GET_LAYER_FRAME = V5_BASE + 0x10c0; /* 4 x 4 = 16 bytes */

function readStateSetLayerFramePlan(base) {
  return readPlanFields(base, STATE_SET_LAYER_FRAME_OFF, {
    entered: "i", needsLog: "i", needsWalk: "i", walkIndex: "i",
    frameBits: "u",
  });
}
