  return readPlanFields(base, REWIND_OFF, {
    prewalkLogNeeded: "i", prewalkFaulted: "i", faultsAtCount: "i",
    count0: "u", count1: "u", zeros0: "i", zeros1: "i", faultsAtSlot: "i",
  });
