test("Wasm differential: Play(int) plan + apply incl. wide host AL", () => {
  for (const [index, label] of [[0, "match"], [1, "mismatch"], [-1, "neg"], [2, "past-end"]]) {
    seedVData({ name: "Cursor", length: 1, flag34: 0, count0: 1, count1: 1 });
    seedVAnm({ dataPtr: V5_DATA, elemsPtr: V5_ELEMS, animCount: 2, flag44: 1 });
    seedVElement(V5_ELEMS, "Cursor");
    seedVElement(V5_ELEMS + 0x13c, "Death");
    wasm.isaac_anm2_play_index_plan(V5_ANM, index, PLAN_PLAY_INDEX);
    const jsP = numify(anm2PlayIndexPlan(shadow, { anm2Addr: V5_ANM, index }));
    assertStructEqual(readPlayIndexPlan(PLAN_PLAY_INDEX), jsP, `play-index plan ${label}`);
    wasm.isaac_anm2_play_index_apply(V5_ANM, index, 0x1ff, PLAN_PLAY_INDEX);
    const jsA = numify(anm2PlayIndexApply(shadow, { anm2Addr: V5_ANM, index, hostApplyAl: 0x1ff }));
    assertStructEqual(readPlayIndexPlan(PLAN_PLAY_INDEX), jsA, `play-index apply ${label}`);
  }
  /* wide host AL 0x100 must not run the rewind tail */
  seedVData({ name: "Cursor", length: 1, flag34: 0, count0: 1, count1: 1 });
  seedVAnm({ dataPtr: V5_DATA, elemsPtr: V5_ELEMS, animCount: 2, flag44: 0 });
  seedVElement(V5_ELEMS, "Cursor");
  seedVElement(V5_ELEMS + 0x13c, "Death");
  wasm.isaac_anm2_play_index_apply(V5_ANM, 1, 0x100, PLAN_PLAY_INDEX);
  const jsW = numify(anm2PlayIndexApply(shadow, { anm2Addr: V5_ANM, index: 1, hostApplyAl: 0x100 }));
  assertStructEqual(readPlayIndexPlan(PLAN_PLAY_INDEX), jsW, "play-index wide-al");
  eq(jsW.rewindRan, 0, "AL 0x100 does not rewind");
  eq(jsW.flag44Set, 0, "AL 0x100 does not set flag44");
  COUNT.cases += 14;
});

test("Wasm differential: rewind + advance-position", () => {
  seedWalkState(V5_ANM + ANM2_OFF_ANIM_STATE_30, { count0: 1, count1: 2, frameBits: 0x11223344, bits18: 0x10, bits1c: 0x20 });
  wasm.isaac_anm2_rewind_apply(V5_ANM + ANM2_OFF_ANIM_STATE_30, PLAN_REWIND);
  const js = numify(anm2RewindApply(shadow, V5_ANM + ANM2_OFF_ANIM_STATE_30));
  assertStructEqual(readRewindPlan(PLAN_REWIND), js, "rewind");
  eq(js.zeros0, 1, "one layer-0 slot zeroed");
  eq(js.zeros1, 2, "two layer-1 slots zeroed");
  checkV5Bytes("rewind");

  seedWalkState(V5_ANM + ANM2_OFF_ANIM_STATE_30, { frameBits: bits(0.5), count0: 2, count1: 1, dataLength: 3, data34: 0 });
  wasm.isaac_anm2_advance_position_apply(V5_ANM + ANM2_OFF_ANIM_STATE_30, 2, PLAN_ADV_POS);
  const jsA = numify(anm2AdvancePositionApply(shadow, V5_ANM + ANM2_OFF_ANIM_STATE_30, 2));
  assertStructEqual(readAdvPosPlan(PLAN_ADV_POS), jsA, "advance fwd");
  /* PE loop at 0x00408d70: frame = floor(frame)+1.0f, prewalk, then
     `comiss (float)target, frame ; ja loop`. The check happens AFTER the
     step, so 0.5 -> 1.0 keeps looping (2 > 1) and only 2.0 stops (2 > 2 is
     false): the loop body (and its prewalk) runs TWICE. iterations == 2. */
  eq(jsA.iterations, 2, "0.5 -> 1.0 -> 2.0: two loop-body steps before target");
  eq(jsA.walk0Iterations, 2, "layer-0 walk stepped twice");
  checkV5Bytes("advance fwd");

  /* D28: no loop progress once |frame| >= 2^24. 0x4b800000 IS 2^24 (ulp
     2.0, so floor+1.0f rounds back); the old 0x4b000000 was 2^23, whose ulp
     is 1.0 and which advances 1 frame per iteration. Target 0x2000000 keeps
     the `comiss ja` gate open above a 2^24 frame. */
  seedWalkState(V5_ANM + ANM2_OFF_ANIM_STATE_30, { frameBits: 0x4b800000, count0: 0, count1: 0 });
  wasm.isaac_anm2_advance_position_apply(V5_ANM + ANM2_OFF_ANIM_STATE_30, 0x2000000, PLAN_ADV_POS);
  const jsRun = numify(anm2AdvancePositionApply(shadow, V5_ANM + ANM2_OFF_ANIM_STATE_30, 0x2000000));
  assertStructEqual(readAdvPosPlan(PLAN_ADV_POS), jsRun, "advance runaway");
  eq(jsRun.runaway, 1, "2^24 frame cannot progress");
  eq(jsRun.iterations, 0, "runaway stops before any step");

  seedWalkState(V5_ANM + ANM2_OFF_ANIM_STATE_30, { frameBits: bits(0.5) });
  wasm.isaac_anm2_advance_position_apply(V5_ANM + ANM2_OFF_ANIM_STATE_30, -5, PLAN_ADV_POS);
  const jsBack = numify(anm2AdvancePositionApply(shadow, V5_ANM + ANM2_OFF_ANIM_STATE_30, -5));
  assertStructEqual(readAdvPosPlan(PLAN_ADV_POS), jsBack, "advance backward");
  eq(jsBack.logNeeded, 1, "backward move logs");
  eq(jsBack.loopEntered, 0, "no forward loop");
  COUNT.cases += 16;
});

test("Wasm differential: state update + anm update", () => {
  /* advance path: frame 0.5 + speed 1.0 -> fps 1.5 -> floor 1 < length 10 */
  runStateDiff({
    dataPtr: V5_DATA,
    speedBits: ANM2_F32_ONE_BITS,
    loadedByte: 1,
    state0: { anm2: V5_ANM, data: V5_DATA, frameBits: bits(0.5), count0: 1, count1: 1, dataLength: 10, data34: 0, tailByte: 1 },
    state1: { anm2: V5_ANM, data: V5_DATA, frameBits: bits(0.5), count0: 0, count1: 0, dataLength: 10, data34: 0, tailByte: 0 },
  }, "state advance");
  /* wrap path with advance call: frame 9.5 + speed 1.0 -> fps 10.5 -> floor 10 >= len 10;
     wrapTarget 9 >= floor(frame) 9 -> advance called, then flag cleared */
  runStateDiff({
    speedBits: ANM2_F32_ONE_BITS,
    loadedByte: 1,
    state0: { anm2: V5_ANM, data: V5_DATA, frameBits: bits(9.5), count0: 1, count1: 1, dataLength: 10, data34: 0, tailByte: 1 },
  }, "state wrap-advance");
  /* wrap without advance: frame 20.0, speed 0 -> floor 20 >= len 10; wrapTarget 9 < floor(frame) */
  runStateDiff({
    speedBits: 0,
    loadedByte: 1,
    state0: { anm2: V5_ANM, data: V5_DATA, frameBits: bits(20), count0: 1, count1: 1, dataLength: 10, data34: 0, tailByte: 1 },
  }, "state wrap");
  /* rewind path: data34 byte set */
  runStateDiff({
    speedBits: ANM2_F32_ONE_BITS,
    loadedByte: 1,
    state0: { anm2: V5_ANM, data: V5_DATA, frameBits: bits(20), count0: 1, count1: 1, dataLength: 10, data34: 1, tailByte: 1 },
  }, "state rewind");
  /* not loaded: anm update runs nothing */
  runStateDiff({
    loadedByte: 0,
    state0: { anm2: V5_ANM, data: V5_DATA, frameBits: bits(0.5), count0: 0, count1: 0, dataLength: 10, data34: 0, tailByte: 1 },
  }, "not loaded");
  /* data null exits before anything */
  runStateDiff({
    dataPtr: 0,
    loadedByte: 1,
    state0: { anm2: V5_ANM, data: 0, frameBits: bits(0.5), count0: 0, count1: 0, dataLength: 10, data34: 0, tailByte: 1 },
  }, "data null");
  COUNT.cases += 12;
});

