  eq(n.result, 0);
  eq(n.logVa, ANM2_HOST_VA_LOG);
  eq(n.logLevel, 0x10);
  eq(n.logNullStrVa, 0x00b1a504);
  eq(n.logBoundStrVa, 0x00b1a564);

  /* hit: layer 0, map 0, frame 0, listCount 2 -> ELEM0 */
  const hit = runLayerFrameDiff("hit", 0, {
    anm2LayerCount: 2, count1c: 1, maps: [0], frames0: [0], listCount: 2,
  });
