test("v15 Walk-apply SSO trampoline fixed edges (inline/heap/null/wide)", () => {
  eq(ANM2_WALK_APPLY_SSO_VA, 0x0040a5b0);
  eq(ANM2_WALK_APPLY_SSO_END_VA, 0x0040a5c7);
  eq(ANM2_WALK_APPLY_SSO_TARGET_VA, 0x0040a5d0);
  eq(ANM2_WALK_APPLY_SSO_CALLSITE_COUNT, 0);
  eq(ANM2_WALK_APPLY_SSO_LUA_PUSH_VA, 0x0086739d);
  eq(ANM2_WALK_APPLY_SSO_LUA_PUSH_COUNT, 1);
  eq(ANM2_WALK_APPLY_SSO_NEXT_VA, 0x0040a690);

  /* inline SSO + first-element hit, reset low byte != 0 */
  const hit = runWalkApplySsoDiff("inline-hit", {
    text: "Cursor", heap: false, resetFlag: 1,
  });
  eq(hit.entered, 1);
  eq(hit.strAddr, V5_STR);
  eq(hit.cap, 0xf);
  eq(hit.heapUsed, 0);
  eq(hit.nameAddr, V5_STR);
  eq(hit.resetFlag, 1);
  eq(hit.found, 1);
  eq(hit.foundIndex, 0);
  eq(hit.elemByteOffset, 0);
  eq(hit.warnLogNeeded, 0);
  eq(hit.applyVa, ANM2_HOST_VA_ANIM_STATE_APPLY);
  eq(hit.applyRecvOff, ANM2_OFF_ANIM_STATE_30);
  eq(hit.result, 1);
  eq(hit.hostCallCount, 1);

  /* cap == 0x10 already heap (UNSIGNED jb) */
  const bound = runWalkApplySsoDiff("cap-eq-10", {
    text: "Cursor", heap: true, cap: 0x10, resetFlag: 1,
  });
  eq(bound.cap, 0x10);
  eq(bound.heapUsed, 1, "cap==0x10 already heap");
  eq(bound.nameAddr, V5_STR_HEAP);
  eq(bound.found, 1);
  eq(bound.foundIndex, 0);

  /* heap name miss */
  const miss = runWalkApplySsoDiff("heap-miss", {
    text: "Idle", heap: true, cap: 0x1f, resetFlag: 1,
  });
  eq(miss.heapUsed, 1);
  eq(miss.nameAddr, V5_STR_HEAP);
  eq(miss.found, 0);
  eq(miss.foundIndex, -1);
  eq(miss.warnLogNeeded, 1);
  eq(miss.warnLogVa, ANM2_HOST_VA_LOG);
  eq(miss.warnLogLevel, ANM2_ANIM_MISS_LOG_LEVEL);
  eq(miss.warnLogStrVa, ANM2_ANIM_MISS_LOG_STR_VA);
  eq(miss.applyVa, 0);
  eq(miss.result, 0);
  eq(miss.hostCallCount, 1);

  /* second-element hit + reset low byte 0 -> apply alt */
  const second = runWalkApplySsoDiff("second-alt", {
    text: "Death", heap: false, resetFlag: 0,
  });
  eq(second.found, 1);
  eq(second.foundIndex, 1);
  eq(second.elemByteOffset, 0x13c);
  eq(second.applyVa, ANM2_HOST_VA_ANIM_STATE_APPLY_ALT);
  eq(second.result, 1);

  /* count 0: miss before any dereference */
  const empty = runWalkApplySsoDiff("count-0", {
    text: "Cursor", heap: false, animCount: 0, resetFlag: 1,
  });
  eq(empty.found, 0, "count 0 -> miss");
  eq(empty.warnLogNeeded, 1);

  /* wide reset: only low byte decides apply receiver */
  const wideOn = runWalkApplySsoDiff("wide-reset-on", {
    text: "Cursor", heap: false, resetFlag: 0x1ff,
  });
  eq(wideOn.resetFlag, 0x1ff);
  eq(wideOn.applyVa, ANM2_HOST_VA_ANIM_STATE_APPLY);
  const wideOff = runWalkApplySsoDiff("wide-reset-off", {
    text: "Cursor", heap: false, resetFlag: 0x100,
  });
  eq(wideOff.resetFlag, 0x100);
  eq(wideOff.applyVa, ANM2_HOST_VA_ANIM_STATE_APPLY_ALT);

  /* null std::string*: harness reports cap/name 0, walk still runs */
  seedVAnm({ elemsPtr: V5_ELEMS, animCount: 2 });
  seedElemByName(V5_ELEMS, "Cursor");
  seedElemByName(V5_ELEMS + 0x13c, "Death");
  wasm.isaac_anm2_walk_apply_sso_plan(V5_ANM, 0, 1, PLAN_WALK_APPLY_SSO);
  const jsNullStr = numify(anm2WalkApplySsoPlan(shadow, {
    anm2Addr: V5_ANM, strAddr: 0, resetFlag: 1,
  }));
  assertStructEqual(readWalkApplySsoPlan(PLAN_WALK_APPLY_SSO), jsNullStr, "null-str plan");
  eq(jsNullStr.cap, 0);
  eq(jsNullStr.heapUsed, 0);
  eq(jsNullStr.nameAddr, 0);
  eq(jsNullStr.found, 0, "null nameAddr is not an element name");

  /* null ANM2: trampoline still SSO-selects, walk keeps miss posture */
  seedPlaySsoStr({ text: "Cursor", heap: false });
  wasm.isaac_anm2_walk_apply_sso_plan(0, V5_STR, 1, PLAN_WALK_APPLY_SSO);
  const jsNullAnm = numify(anm2WalkApplySsoPlan(shadow, {
    anm2Addr: 0, strAddr: V5_STR, resetFlag: 1,
  }));
  assertStructEqual(readWalkApplySsoPlan(PLAN_WALK_APPLY_SSO), jsNullAnm, "null-anm plan");
  eq(jsNullAnm.entered, 0);
  eq(jsNullAnm.heapUsed, 0);
  eq(jsNullAnm.nameAddr, V5_STR);
  eq(jsNullAnm.found, 0);
  eq(jsNullAnm.result, 0);
  eq(jsNullAnm.hostCallCount, 1);

  COUNT.cases += 20;
});

