test("v17 SetFrame cstr mutations are caught by the pins", () => {
  const original = readFileSync(source, "utf8");
  const base = original.replaceAll("\r\n", "\n");
  const withMutantV17 = (label, mutate, check, probe) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(bad);
    let threw = false;
    try {
      wasm = loadExports();
      wmem = new Uint8Array(wasm.memory.buffer);
      if (probe) {
        const diverged = probe();
        assert.ok(diverged, `${label}: rebuilt module not mutant (stale build)`);
      }
      check();
    } catch (e) {
      threw = true;
    }
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    /* M1: drop the [this+0x34] gate so a hit with data==0 still advances. */
    withMutantV17("setframe-cstr drop-data-gate",
      (s) => s.replace(
        "  /* v17: walk AL && [this+0x34] both required for 0x408e00. */\n" +
        "  plan.advance_ran =\n" +
        "      (plan.walk_result != 0 && plan.data_present != 0) ? 1 : 0;",
        "  /* v17: walk AL && [this+0x34] both required for 0x408e00. */\n" +
        "  plan.advance_ran =\n" +
        "      (plan.walk_result != 0) ? 1 : 0;"),
      () => {
        const p = runSetFrameCstrDiff("m1", {
          text: "Cursor", frame: 1, dataPtr: 0, flag44: 1,
        });
        eq(p.walkResult, 1);
        eq(p.dataPresent, 0);
        eq(p.advanceRan, 0, "null data skips 0x408e00");
        eq(p.flag44Cleared, 0);
      },
      () => {
        const p = runSetFrameCstrDiff("m1probe", {
          text: "Cursor", frame: 1, dataPtr: 0, flag44: 1,
          apply: false,
        });
        return p.advanceRan === 1;
      });
    /* M2: drop the BYTE AL gate so a miss still advances. */
    withMutantV17("setframe-cstr drop-al-gate",
      (s) => s.replace(
        "  /* v17: test al,al after 0x0040a5d0 — BYTE gate. walk.result is\n" +
        "     already the PE AL (0/1). */\n" +
        "  plan.walk_result = walk.result;",
        "  /* v17: test al,al after 0x0040a5d0 — BYTE gate. walk.result is\n" +
        "     already the PE AL (0/1). */\n" +
        "  plan.walk_result = 1;"),
      () => {
        const p = runSetFrameCstrDiff("m2", {
          text: "Idle", frame: 1, flag44: 1,
        });
        eq(p.found, 0);
        eq(p.walkResult, 0, "miss AL stays 0");
        eq(p.advanceRan, 0);
      },
      () => {
        const p = runSetFrameCstrDiff("m2probe", {
          text: "Idle", frame: 1, flag44: 1, apply: false,
        });
        return p.walkResult === 1;
      });
  } finally {
    writeSourceRetry(original);
  }
  wasm = loadExports();
  wmem = new Uint8Array(wasm.memory.buffer);
  COUNT.cases += 2;
});

