test("v19 advance cur mutations are caught by the pins", () => {
  const original = readFileSync(source, "utf8");
  const base = original.replaceAll("\r\n", "\n");
  const withMutantV19 = (label, mutate, check, probe) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(bad);
    let threw = false;
    try {
      wasm = loadExports();
      wmem = new Uint8Array(wasm.memory.buffer);
      if (probe) {
        const diverged = probe();
        assert.ok(diverged, `${label}: rebuilt module not mutant (stale build)`);
      }
      check();
    } catch (e) {
      threw = true;
    }
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    /* M1: drop FULL-dword test to low-byte, so 0x100 is not needed. */
    withMutantV19("advance-cur low-byte needed",
      (s) => s.replace(
        "  /* v19: cmp dword [ecx+0x34], 0 ; je SKIP — FULL dword, so 0x100 is needed. */\n" +
        "  return data_dword != 0u ? 1 : 0;",
        "  /* v19: cmp dword [ecx+0x34], 0 ; je SKIP — FULL dword, so 0x100 is needed. */\n" +
        "  return (data_dword & 0xffu) != 0u ? 1 : 0;"),
      () => {
        eq(wasm.isaac_anm2_advance_cur_needed(0x100), 1, "0x100 is FULL-dword needed");
        const p = runAdvanceCurDiff("m1", { dataPtr: 0x100 });
        eq(p.needed, 1, "0x100 must stay needed");
        eq(p.advanceRan, 1);
      },
      () => wasm.isaac_anm2_advance_cur_needed(0x100) === 0);
    /* M2: drop FULL-dword test to AL, so 0x1000000 is not needed. */
    withMutantV19("advance-cur AL needed",
      (s) => s.replace(
        "  /* v19: cmp dword [ecx+0x34], 0 ; je SKIP — FULL dword, so 0x100 is needed. */\n" +
        "  return data_dword != 0u ? 1 : 0;",
        "  /* v19: cmp dword [ecx+0x34], 0 ; je SKIP — FULL dword, so 0x100 is needed. */\n" +
        "  return (data_dword & 0xffu) != 0u ? 1 : 0;"),
      () => {
        eq(wasm.isaac_anm2_advance_cur_needed(0x1000000), 1, "0x1000000 is FULL-dword needed");
        const p = runAdvanceCurDiff("m2", { dataPtr: 0x1000000 });
        eq(p.needed, 1, "0x1000000 must stay needed");
        eq(p.advanceRan, 1);
      },
      () => wasm.isaac_anm2_advance_cur_needed(0x1000000) === 0);
  } finally {
    writeSourceRetry(original);
  }
  wasm = loadExports();
  wmem = new Uint8Array(wasm.memory.buffer);
  COUNT.cases += 2;
});

