test("v20 advance pos cur fixed edges (hit/null-data/wrap/wide-dword/null-anm)", () => {
  eq(ANM2_ADVANCE_POS_CUR_VA, 0x0040a760);
  eq(ANM2_ADVANCE_POS_CUR_END_VA, 0x0040a778);
  eq(ANM2_ADVANCE_POS_CUR_BODY_BYTES, 0x19);
  eq(ANM2_ADVANCE_POS_CUR_DATA_OFF, 0x34);
  eq(ANM2_ADVANCE_POS_CUR_STATE_OFF, 0x30);
  eq(ANM2_ADVANCE_POS_CUR_ADVANCE_VA, 0x00408d00);
  eq(ANM2_ADVANCE_POS_CUR_NEXT_VA, 0x0040a780);

  eq(anm2AdvancePosCurNeeded(0), 0);
  eq(anm2AdvancePosCurNeeded(1), 1);
  eq(anm2AdvancePosCurNeeded(0x100), 1);       /* FULL dword: mid-byte is needed */
  eq(anm2AdvancePosCurNeeded(0x1000000), 1);   /* FULL dword: high byte is needed */
  eq(wasm.isaac_anm2_advance_pos_cur_needed(0), 0);
  eq(wasm.isaac_anm2_advance_pos_cur_needed(0x100), 1);
  eq(wasm.isaac_anm2_advance_pos_cur_needed(0x1000000), 1);

  eq(anm2AdvancePosCurTargetFromData(0), -1);
  eq(anm2AdvancePosCurTargetFromData(1), 0);
  eq(anm2AdvancePosCurTargetFromData(5), 4);
  eq(anm2AdvancePosCurTargetFromData(0x80000000), 0x7fffffff);
  eq(wasm.isaac_anm2_advance_pos_cur_target_from_data(0), -1);
  eq(wasm.isaac_anm2_advance_pos_cur_target_from_data(1), 0);
  eq(wasm.isaac_anm2_advance_pos_cur_target_from_data(0x80000000), 0x7fffffff);

  /* data present: AdvancePosition(this+0x30, length-1), no store */
  const hit = runAdvancePosCurDiff("pos-hit", { dataPtr: V5_DATA, length: 5 });
  eq(hit.entered, 1);
  eq(hit.needed, 1);
  eq(hit.dataDword, V5_DATA);
  eq(hit.target, 4);
  eq(hit.advanceRan, 1);
  eq(hit.advanceRecvOff, 0x30);
  eq(hit.hostOrAdvanceVa, 0x00408d00);
  eq(hit.hostCallCount, 1);
  eq(shadow[V5_ANM + ANM2_OFF_PLAYING_FLAG_44], 1, "no +0x44 store");

  /* length==0 wraps to -1 */
  const wrap0 = runAdvancePosCurDiff("pos-wrap0", { dataPtr: V5_DATA, length: 0 });
  eq(wrap0.needed, 1);
  eq(wrap0.target, -1);
  eq(wrap0.advanceRan, 1);

  /* 0x80000000-1 stays 0x7fffffff (i32 wrap of dec) */
  const wrapHi = runAdvancePosCurDiff("pos-wrap-hi", {
    dataPtr: V5_DATA, length: 0x80000000,
  });
  eq(wrapHi.needed, 1);
  eq(wrapHi.target, 0x7fffffff);

  /* data==0: skip 0x408d00, target stays 0 */
  const noData = runAdvancePosCurDiff("pos-null-data", { dataPtr: 0, length: 9 });
  eq(noData.entered, 1);
  eq(noData.needed, 0);
  eq(noData.dataDword, 0);
  eq(noData.target, 0);
  eq(noData.advanceRan, 0);
  eq(noData.hostCallCount, 0);
  eq(shadow[V5_ANM + ANM2_OFF_PLAYING_FLAG_44], 1);

  /* V5_DATA low byte is 0 (0x10e300): a low-byte gate would skip it. */
  eq((V5_DATA & 0xff), 0, "V5_DATA is a FULL-dword-only hit");
  eq(hit.needed, 1, "V5_DATA mid/high bytes keep the gate open");


  /* null ANM2: entered=0, no advance */
  wasm.isaac_anm2_advance_pos_cur_plan(0, PLAN_ADVANCE_POS_CUR);
  const jsNullAnm = numify(anm2AdvancePosCurPlan(shadow, {
    anm2Addr: 0,
  }));
  assertStructEqual(readAdvancePosCurPlan(PLAN_ADVANCE_POS_CUR), jsNullAnm, "null-anm plan");
  eq(jsNullAnm.entered, 0);
  eq(jsNullAnm.needed, 0);
  eq(jsNullAnm.dataDword, 0);
  eq(jsNullAnm.target, 0);
  eq(jsNullAnm.advanceRan, 0);
  eq(jsNullAnm.hostCallCount, 0);

  COUNT.cases += 18;
});

