  eq(anm2StateSetLayerFrameNeeded(0x1000000), 1);
  eq(wasm.isaac_anm2_state_set_layer_frame_needed(0), 0);
  eq(wasm.isaac_anm2_state_set_layer_frame_needed(0x100), 1);
  eq(wasm.isaac_anm2_state_set_layer_frame_needed(0x1000000), 1);

  eq(anm2StateSetLayerFrameInRange(0, 2), 1);
  eq(anm2StateSetLayerFrameInRange(1, 2), 1);
  eq(anm2StateSetLayerFrameInRange(2, 2), 0);
  eq(anm2StateSetLayerFrameInRange(-1, 2), 0);
  eq(anm2StateSetLayerFrameInRange(0x80000000, 2), 0);
  eq(anm2StateSetLayerFrameInRange(0, 0x80000000), 0);
