  eq(hit.frameBits >>> 0, 0x40a00000);

  /* KEY v54-vs-v22 difference: log1 has NO top data gate — at data==0 with
     an IN-RANGE layer the plan still reports needsLog 0 (no gate fire). */
  const noData = runStateSetLayerFrameDiff("null-data", { dataPtr: 0, layer: 0, frame: 5 });
  eq(noData.entered, 1);
  eq(noData.needsLog, 0);
  eq(noData.needsWalk, 0);
  eq(noData.walkIndex, 0);
