test("v54 state set-null-frame mutations are caught by the pins", () => {
  const original = readFileSync(source, "utf8");
  const base = original.replaceAll("\r\n", "\n");
  const withMutant = (label, mutate, check, probe) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(bad);
    let threw = false;
    try {
      wasm = loadExports();
      wmem = new Uint8Array(wasm.memory.buffer);
      if (probe) {
        const diverged = probe();
        assert.ok(diverged, `${label}: rebuilt module not mutant (stale build)`);
      }
      check();
    } catch (e) {
      threw = true;
    }
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    /* M1: count offset 0x88 -> 0x80 (the sibling body's count). */
    withMutant("null count offset shift",
      (s) => s.replace(
        "load_guest_u32(anim + ISAAC_ANM2_STATE_SET_NULL_FRAME_COUNT_OFF));",
        "load_guest_u32(anim + ISAAC_ANM2_STATE_SET_LAYER_FRAME_COUNT_OFF));"),
      () => {
        const p = runStateSetNullFrameDiff("m1", { index: 3, count88: 8, count24: 4 });
        eq(p.needsLog1, 0, "index 3 < count88 8 must not log1");
      },
      () => runStateSetNullFrameDiff("m1probe", { index: 3, count88: 8, count24: 4 }).needsLog1 === 1);
    /* M2: walk made conditional (in-range only) — the tail is unconditional. */
    withMutant("walk conditional",
      (s) => s.replace(
        "    /* The tail (frames[index]=0 + the 0x00408c10 call) is UNCONDITIONAL\n"
        + "       once entered — even after log1/log2 with a negative index (the walk\n"
        + "       law re-evaluates and faults internally BY REFERENCE). */\n"
        + "    plan.needs_walk = 1;\n"
        + "    plan.walk_index = index;",
        "    plan.needs_walk = plan.needs_log_1 == 0 && plan.needs_log_2 == 0 ? 1 : 0;\n"
        + "    plan.walk_index = plan.needs_walk != 0 ? index : 0;"),
      () => {
        const p = runStateSetNullFrameDiff("m2", { index: 0x80000000, frame: 3 });
        eq(p.needsWalk, 1, "negative index still walks (unconditional tail)");
        eq(p.walkIndex, 0x80000000 | 0);
      },
      () => runStateSetNullFrameDiff("m2probe", { index: 0x80000000, frame: 3 }).needsWalk === 0);
    /* M3: unsigned range so a negative index looks in-range for log1. */
    withMutant("null unsigned range",
      (s) => s.replace(
        "  /* v54: test esi,esi ; js / cmp esi,[anim+0x88] ; jl — SIGNED. */\n" +
        "  return isaac_anm2_set_layer_frame_layer_in_range(index, count);",
        "  /* v54: test esi,esi ; js / cmp esi,[anim+0x88] ; jl — SIGNED. */\n" +
        "  return static_cast<uint32_t>(index) < static_cast<uint32_t>(count) ? 1 : 0;"),
      () => {
        const p = runStateSetNullFrameDiff("m3", { index: 0x80000000, count88: 0xffffffff });
        eq(p.needsLog1, 1, "0x80000000 is SIGNED-negative");
      },
      () => runStateSetNullFrameDiff("m3probe", { index: 0x80000000, count88: 0xffffffff }).needsLog1 === 0);
  } finally {
    writeSourceRetry(original);
  }
  wasm = loadExports();
  wmem = new Uint8Array(wasm.memory.buffer);
  COUNT.cases += 1;
});

test("v54 state get-layer-frame fixed edges (needed/range/result/harness-zero)", () => {
  eq(ANM2_STATE_GET_LAYER_FRAME_VA, 0x00408f70);
  eq(ANM2_STATE_GET_LAYER_FRAME_END_VA, 0x00408fb5);
  eq(ANM2_STATE_GET_LAYER_FRAME_BODY_BYTES, 0x46);
  eq(ANM2_STATE_GET_LAYER_FRAME_CALLSITE_COUNT, 1);
  eq(ANM2_STATE_GET_LAYER_FRAME_FRAMES_OFF, 0x08);
  eq(ANM2_STATE_GET_LAYER_FRAME_LOG_STR_VA, 0x00b1a564);

  eq(anm2StateGetLayerFrameNeeded(0), 0);
  eq(anm2StateGetLayerFrameNeeded(0x100), 1);
  eq(wasm.isaac_anm2_state_get_layer_frame_needed(0), 0);
  eq(wasm.isaac_anm2_state_get_layer_frame_needed(0x100), 1);

  eq(anm2StateGetLayerFrameInRange(1, 2), 1);
  eq(anm2StateGetLayerFrameInRange(2, 2), 0);
  eq(anm2StateGetLayerFrameInRange(-1, 2), 0);
  eq(wasm.isaac_anm2_state_get_layer_frame_in_range(2, 2), 0);
  eq(wasm.isaac_anm2_state_get_layer_frame_in_range(0x80000000, 2), 0);

  const hit = runStateGetLayerFrameDiff("hit", {
    index: 1, count80: 2, maps: [0, 1], frames: { 0: 11, 1: 22 },
  });
  eq(hit.entered, 1);
  eq(hit.needsLog, 0);
  eq(hit.inRange, 1);
  eq(hit.result, 22);

  /* mapped value is NOT re-checked against any count — the law reproduces
     the raw frames[mapped] read (machine has no map bound test). */
  const oorMap = runStateGetLayerFrameDiff("mapped-oor", {
    index: 0, count80: 2, maps: [99], frames: { 99: 7 },
  });
  eq(oorMap.result, 7, "raw out-of-map read");

  const oob = runStateGetLayerFrameDiff("oob", { index: 2, count80: 2, maps: [0, 1] });
  eq(oob.needsLog, 1);
  eq(oob.inRange, 0);
  eq(oob.result, 0, "harness-zero OOB");

  const neg = runStateGetLayerFrameDiff("neg", { index: 0x80000000, count80: 2 });
  eq(neg.needsLog, 1);
  eq(neg.inRange, 0);
  eq(neg.result, 0);

  /* data==0 with in-range index: machine faults at the unguarded deref
     (unobservable) — folded to result 0, no log. */
  const noData = runStateGetLayerFrameDiff("null-data", { dataPtr: 0, index: 0, count80: 2 });
  eq(noData.needsLog, 0);
  eq(noData.inRange, 1);
  eq(noData.result, 0);

  wasm.isaac_anm2_state_get_layer_frame_plan(0, 0, PLAN_STATE_GET_LAYER_FRAME);
  const jsNull = numify(anm2StateGetLayerFramePlan(shadow, { stateAddr: 0, index: 0 }));
  assertStructEqual(readStateGetLayerFramePlan(PLAN_STATE_GET_LAYER_FRAME), jsNull, "null-state");
  eq(jsNull.entered, 0);
  eq(jsNull.result, 0);

  COUNT.cases += 15;
});

