test("v24 Stop wasm-vs-JS differential (wide dword)", () => {
  const rng = makeRng(0x40a910);
  for (let t = 0; t < 32; ++t) {
    const dataPtr = t % 7 === 0 ? 0
      : t % 7 === 1 ? 0x100
      : t % 7 === 2 ? 0x1000000
      : t % 7 === 3 ? 0xff000000
      : rng.u32() || 1;
    const flag44 = t & 1 ? 1 : 0xaa;
    runStopDiff(`t${t}`, { dataPtr, flag44 });
  }
  COUNT.cases += 32;
});

test("v24 Stop mutations are caught by the pins", () => {
  const original = readFileSync(source, "utf8");
  const base = original.replaceAll("\r\n", "\n");
  const withMutantV24 = (label, mutate, check, probe) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(bad);
    let threw = false;
    try {
      wasm = loadExports();
      wmem = new Uint8Array(wasm.memory.buffer);
      if (probe) {
        const diverged = probe();
        assert.ok(diverged, `${label}: rebuilt module not mutant (stale build)`);
      }
      check();
    } catch (e) {
      threw = true;
    }
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    /* M1: drop FULL-dword test to low-byte, so 0x100 is not needed. */
    withMutantV24("stop low-byte needed",
      (s) => s.replace(
        "  /* v24: cmp dword [ecx+0x34], 0 ; je SKIP — FULL dword, so 0x100 is needed. */\n" +
        "  return isaac_anm2_advance_cur_needed(data_dword);",
        "  /* v24: cmp dword [ecx+0x34], 0 ; je SKIP — FULL dword, so 0x100 is needed. */\n" +
        "  return (data_dword & 0xffu) != 0u ? 1 : 0;"),
      () => {
        eq(wasm.isaac_anm2_stop_needed(0x100), 1, "0x100 is FULL-dword needed");
        const p = runStopDiff("m1", { dataPtr: 0x100, flag44: 1 });
        eq(p.needed, 1, "0x100 must stay needed");
        eq(p.flag44, 0, "0x100 must store");
      },
      () => wasm.isaac_anm2_stop_needed(0x100) === 0);
  } finally {
    writeSourceRetry(original);
  }
  wasm = loadExports();
  wmem = new Uint8Array(wasm.memory.buffer);
  COUNT.cases += 1;
});

/* ================= v25: 0x0040a920 overlay Play SSO + 0x0040a9c0 Stop === */

function runOverlayPlaySsoDiff(label, {
  text = "Cursor", heap = false, cap,
  dataName = "Cursor", data34 = 0, flag64 = 0,
  resetFlag = 0, hostAl = 0, rewindWorld = false,
  dataNull = false, overlayDataPtr, strAddr = V5_STR,
} = {}) {
  seedPlaySsoStr({ text, heap, cap });
  seedVData({ name: dataName, length: 1, flag34: data34 });
  const dataPtr = overlayDataPtr !== undefined
    ? overlayDataPtr
    : (dataNull ? 0 : V5_DATA);
  seedVAnm({
    overlayDataPtr: dataPtr,
    flag64,
    speedBits: ANM2_F32_ONE_BITS,
    loadedByte: 1,
  });
  if (rewindWorld) {
    seedWalkState(V5_ANM + ANM2_OFF_OVERLAY_STATE_50, {
      data: ANIM_DATA, count0: 2, count1: 1, frameBits: 0,
    });
  }
  wasm.isaac_anm2_overlay_play_sso_plan(V5_ANM, strAddr, resetFlag,
                                        PLAN_OVERLAY_PLAY_SSO);
  const js = numify(anm2OverlayPlaySsoPlan(shadow, {
    anm2Addr: V5_ANM, strAddr, resetFlag,
  }));
  assertStructEqual(readOverlayPlaySsoPlan(PLAN_OVERLAY_PLAY_SSO), js,
                    `${label} plan`);
  wasm.isaac_anm2_overlay_play_sso_apply(
    V5_ANM, strAddr, resetFlag, hostAl, PLAN_OVERLAY_PLAY_SSO);
  const jsA = numify(anm2OverlayPlaySsoApply(shadow, {
    anm2Addr: V5_ANM, strAddr, resetFlag, hostApplyAl: hostAl,
  }));
  assertStructEqual(readOverlayPlaySsoPlan(PLAN_OVERLAY_PLAY_SSO), jsA,
                    `${label} apply`);
  eq(wmem[V5_ANM + ANM2_OVERLAY_PLAY_FLAG_OFF],
     shadow[V5_ANM + ANM2_OVERLAY_PLAY_FLAG_OFF], `${label} flag64`);
  return jsA;
}

test("v25 overlay Play SSO fixed edges (inline/heap/null/wide)", () => {
  eq(ANM2_OVERLAY_PLAY_SSO_VA, 0x0040a920);
  eq(ANM2_OVERLAY_PLAY_SSO_END_VA, 0x0040a936);
  eq(ANM2_OVERLAY_PLAY_VA, 0x0040a940);
  eq(ANM2_OVERLAY_PLAY_END_VA, 0x0040a9b3);
  eq(ANM2_OVERLAY_PLAY_APPLY_VA, 0x0040aaf0);
  eq(ANM2_OVERLAY_PLAY_DATA_OFF, 0x54);
  eq(ANM2_OVERLAY_PLAY_FLAG_OFF, 0x64);
  eq(ANM2_OVERLAY_PLAY_STATE_OFF, 0x50);

  const inline = runOverlayPlaySsoDiff("ov-inline-skip", {
    text: "Cursor", heap: false, dataName: "Cursor", data34: 0, flag64: 0,
  });
  eq(inline.entered, 1);
  eq(inline.strAddr, V5_STR);
  eq(inline.cap, 0xf);
  eq(inline.heapUsed, 0);
  eq(inline.nameAddr, V5_STR);
  eq(inline.nameEqual, 1);
  eq(inline.skip, 1);
  eq(inline.callApply, 0);
  eq(inline.applyVa, ANM2_OVERLAY_PLAY_APPLY_VA);
  eq(inline.rewindVa, ANM2_REWIND_VA);

  const bound = runOverlayPlaySsoDiff("ov-cap-eq-10", {
    text: "Cursor", heap: true, cap: 0x10,
    dataName: "Cursor", data34: 0, flag64: 0,
  });
  eq(bound.cap, 0x10);
  eq(bound.heapUsed, 1, "cap==0x10 already heap");
  eq(bound.nameAddr, V5_STR_HEAP);
  eq(bound.skip, 1);

  const miss = runOverlayPlaySsoDiff("ov-heap-miss", {
    text: "Death", heap: true, cap: 0x1f,
    dataName: "Cursor", data34: 0, flag64: 0,
  });
  eq(miss.nameEqual, 0);
  eq(miss.skip, 0);
  eq(miss.callApply, 1);

  const call = runOverlayPlaySsoDiff("ov-restart-not-playing", {
    text: "Cursor", heap: false, dataName: "Cursor", data34: 1, flag64: 0,
  });
  eq(call.skip, 0);
  eq(call.callApply, 1);

  const applied = runOverlayPlaySsoDiff("ov-al-tail", {
    text: "Cursor", heap: false, dataName: "Cursor", data34: 1, flag64: 0,
    hostAl: 1, rewindWorld: true,
  });
  eq(applied.rewindRan, 1);
  eq(applied.flag44Set, 1);
  eq(shadow[V5_ANM + ANM2_OVERLAY_PLAY_FLAG_OFF], 1);

  const wideAl = runOverlayPlaySsoDiff("ov-al-wide-0", {
    text: "Cursor", heap: false, dataName: "Cursor", data34: 1, flag64: 0,
    hostAl: 0x100, rewindWorld: true,
  });
  eq(wideAl.rewindRan, 0, "AL 0x100 must not rewind");
  eq(wideAl.flag44Set, 0);

  /* reset 0x100: LOW BYTE is 0, so reset is NOT set. */
  const wideReset = runOverlayPlaySsoDiff("ov-reset-0x100", {
    text: "Cursor", heap: false, dataName: "Cursor", data34: 0, flag64: 0,
    resetFlag: 0x100,
  });
  eq(wideReset.resetFlag, 0x100);
  eq(wideReset.skip, 1, "reset 0x100 low byte 0 does not force call");

  const setReset = runOverlayPlaySsoDiff("ov-reset-0x1ff", {
    text: "Cursor", heap: false, dataName: "Cursor", data34: 0, flag64: 0,
    resetFlag: 0x1ff,
  });
  eq(setReset.skip, 0, "reset 0x1ff low byte ff forces call");

  /* data present is FULL dword: V5_DATA has low byte 0, still present. */
  ok((V5_DATA & 0xff) === 0, "V5_DATA low byte 0 pins the FULL-dword test");
  const dataMid = runOverlayPlaySsoDiff("ov-data-low0", {
    text: "Cursor", heap: false, dataName: "Cursor", data34: 0, flag64: 0,
    overlayDataPtr: V5_DATA,
  });
  eq(dataMid.dataNull, 0, "overlay data with low byte 0 is present");

  wasm.isaac_anm2_overlay_play_sso_plan(V5_ANM, 0, 0, PLAN_OVERLAY_PLAY_SSO);
  const jsNullStr = numify(anm2OverlayPlaySsoPlan(shadow, {
    anm2Addr: V5_ANM, strAddr: 0, resetFlag: 0,
  }));
  assertStructEqual(readOverlayPlaySsoPlan(PLAN_OVERLAY_PLAY_SSO), jsNullStr,
                    "ov-null-str plan");
  eq(jsNullStr.nameAddr, 0);
  eq(jsNullStr.callApply, 1, "null str still runs overlay Play");

  seedPlaySsoStr({ text: "Cursor", heap: false });
  wasm.isaac_anm2_overlay_play_sso_plan(0, V5_STR, 0, PLAN_OVERLAY_PLAY_SSO);
  const jsNullAnm = numify(anm2OverlayPlaySsoPlan(shadow, {
    anm2Addr: 0, strAddr: V5_STR, resetFlag: 0,
  }));
  assertStructEqual(readOverlayPlaySsoPlan(PLAN_OVERLAY_PLAY_SSO), jsNullAnm,
                    "ov-null-anm plan");
  eq(jsNullAnm.entered, 0);
  eq(jsNullAnm.callApply, 1);

  COUNT.cases += 24;
});

test("v25 overlay Play SSO wasm-vs-JS differential (wide cap / reset)", () => {
  const rng = makeRng(0x40a920);
  for (let t = 0; t < 32; ++t) {
    const heap = t % 3 !== 1;
    const cap = heap
      ? (t % 5 === 0 ? 0x10
        : t % 5 === 1 ? 0xffffffff
        : 0x10 + (rng.u32() % 16))
      : (rng.u32() % 0x10);
    const text = t % 4 === 0 ? "Death" : "Cursor";
    const resetFlag = t % 6 === 0 ? 0x1ff
      : t % 6 === 1 ? 0x100
      : t % 6 === 2 ? (0xffffffff | 0)
      : 0;
    runOverlayPlaySsoDiff(`ovt${t}`, {
      text, heap, cap,
      dataName: "Cursor",
      data34: t % 2,
      flag64: (t >> 1) % 2,
      resetFlag,
      hostAl: t % 5 === 0 ? 0x100 : (t % 3),
    });
  }
  COUNT.cases += 32;
});

test("v25 overlay Play SSO mutations are caught by the pins", () => {
  const original = readFileSync(source, "utf8");
  const base = original.replaceAll("\r\n", "\n");
  const withMutantV25 = (label, mutate, check, probe) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(bad);
    let threw = false;
    try {
      wasm = loadExports();
      wmem = new Uint8Array(wasm.memory.buffer);
      if (probe) {
        const diverged = probe();
        assert.ok(diverged, `${label}: rebuilt module not mutant (stale build)`);
      }
      check();
    } catch (e) {
      threw = true;
    }
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    /* M1: unsigned reset — 0x100 must stay NOT set (low-byte). */
    withMutantV25("overlay play unsigned reset",
      (s) => s.replace(
        "  /* v25 overlay Play: cmp byte [ebp+0xc],0 — LOW BYTE, so 0x100 is NOT set. */\n" +
        "  if ((static_cast<uint32_t>(reset_flag) & 0xffu) != 0u) {",
        "  /* v25 overlay Play: cmp byte [ebp+0xc],0 — LOW BYTE, so 0x100 is NOT set. */\n" +
        "  if (reset_flag != 0) {"),
      () => {
        const p = runOverlayPlaySsoDiff("m1", {
          text: "Cursor", heap: false, dataName: "Cursor", data34: 0, flag64: 0,
          resetFlag: 0x100,
        });
        eq(p.skip, 1, "reset 0x100 low byte 0 must skip");
        eq(p.callApply, 0);
      },
      () => {
        const p = runOverlayPlaySsoDiff("m1probe", {
          text: "Cursor", heap: false, dataName: "Cursor", data34: 0, flag64: 0,
          resetFlag: 0x100,
        });
        return p.skip === 0;
      });
    /* M2: low-byte data — V5_DATA low byte 0 must stay present. */
    withMutantV25("overlay play low-byte data",
      (s) => s.replace(
        "    /* v25 overlay Play: test esi,esi — FULL dword [this+0x54], so 0x100 is present. */\n" +
        "    plan.data_null = data == 0u ? 1 : 0;",
        "    /* v25 overlay Play: test esi,esi — FULL dword [this+0x54], so 0x100 is present. */\n" +
        "    plan.data_null = (data & 0xffu) == 0u ? 1 : 0;"),
      () => {
        const p = runOverlayPlaySsoDiff("m2", {
          text: "Cursor", heap: false, dataName: "Cursor", data34: 0, flag64: 0,
          overlayDataPtr: V5_DATA,
        });
        eq(p.dataNull, 0, "overlay data with low byte 0 must stay present");
      },
      () => {
        const p = runOverlayPlaySsoDiff("m2probe", {
          text: "Cursor", heap: false, dataName: "Cursor", data34: 0, flag64: 0,
          overlayDataPtr: V5_DATA,
        });
        return p.dataNull === 1;
      });
  } finally {
    writeSourceRetry(original);
  }
  wasm = loadExports();
  wmem = new Uint8Array(wasm.memory.buffer);
  COUNT.cases += 2;
});

