/* ================= v26: 0x0040a9d0 overlay Playing SSO + 0x0040a9f0 === */

function runOverlayPlayingSsoDiff(label, {
  text = "Cursor", heap = false, cap,
  dataName = "Cursor", flag64 = 1,
  dataNull = false, strAddr = V5_STR,
  latchDword,
} = {}) {
  seedPlaySsoStr({ text, heap, cap });
  seedVData({ name: dataName, length: 1, flag34: 0 });
  seedVAnm({
    overlayDataPtr: dataNull ? 0 : V5_DATA,
    flag64,
    speedBits: ANM2_F32_ONE_BITS,
    loadedByte: 1,
  });
  if (latchDword !== undefined) {
    pokeU32(V5_ANM + ANM2_OVERLAY_PLAYING_FLAG_OFF, latchDword >>> 0);
  }
  wasm.isaac_anm2_overlay_playing_sso_plan(V5_ANM, strAddr, PLAN_OVERLAY_PLAYING_SSO);
  const js = numify(anm2OverlayPlayingSsoPlan(shadow, {
    anm2Addr: V5_ANM, strAddr,
  }));
  assertStructEqual(readOverlayPlayingSsoPlan(PLAN_OVERLAY_PLAYING_SSO), js, `${label} plan`);
  return js;
}

