test("v26 overlay Playing SSO wasm-vs-JS differential (wide cap/latch)", () => {
  const rng = makeRng((0x40a9d0 ^ 0x40a9f0) >>> 0);
  for (let t = 0; t < 32; ++t) {
    const heap = t % 3 !== 1;
    const cap = heap
      ? (t % 5 === 0 ? 0x10
        : t % 5 === 1 ? 0xffffffff
        : 0x10 + (rng.u32() % 16))
      : (rng.u32() % 0x10);
    const text = t % 4 === 0 ? "Death" : t % 4 === 1 ? "" : "Cursor";
    const latch = t % 6 === 0 ? 0x100
      : t % 6 === 1 ? 0x101
      : t % 6 === 2 ? 0x1000000
      : t & 1;
    runOverlayPlayingSsoDiff(`ovt${t}`, {
      text, heap, cap,
      dataName: "Cursor",
      latchDword: latch,
      dataNull: t % 7 === 0,
    });
  }
  COUNT.cases += 32;
});

test("v26 overlay Playing mutations are caught by the pins", () => {
  const original = readFileSync(source, "utf8");
  const base = original.replaceAll("\r\n", "\n");
  const withMutantV26 = (label, mutate, check, probe) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(bad);
    let threw = false;
    try {
      wasm = loadExports();
      wmem = new Uint8Array(wasm.memory.buffer);
      if (probe) {
        const diverged = probe();
        assert.ok(diverged, `${label}: rebuilt module not mutant (stale build)`);
      }
      check();
    } catch (e) {
      threw = true;
    }
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    /* M1: full-dword latch test — 0x100 must stay CLEAR */
    withMutantV26("overlay playing latch full-dword",
      (s) => s.replace(
        "  /* v26: cmp byte [this+0x64],0 ; je FALSE — LOW BYTE latch, so 0x100 is CLEAR. */\n" +
        "  if (anm2[ISAAC_ANM2_OVERLAY_PLAYING_FLAG_OFF] == 0u) {",
        "  /* v26: cmp byte [this+0x64],0 ; je FALSE — LOW BYTE latch, so 0x100 is CLEAR. */\n" +
        "  if (load_u32(anm2 + ISAAC_ANM2_OVERLAY_PLAYING_FLAG_OFF) == 0u) {"),
      () => {
        const p = runOverlayPlayingSsoDiff("m1", {
          text: "Cursor", heap: false, dataName: "Cursor", latchDword: 0x100,
        });
        eq(p.result, 0, "latch 0x100 is CLEAR");
        eq(wasm.isaac_anm2_overlay_playing_name_pred(V5_ANM, V5_STR), 0);
      },
      () => {
        const p = runOverlayPlayingSsoDiff("m1probe", {
          text: "Cursor", heap: false, dataName: "Cursor", latchDword: 0x100,
        });
        return p.result === 1;
      });
  } finally {
    writeSourceRetry(original);
  }
  wasm = loadExports();
  wmem = new Uint8Array(wasm.memory.buffer);
  COUNT.cases += 1;
});




