function runOverlayPlayingSsoAltDiff(label, {
  text = "Cursor", heap = false, cap,
  dataName = "Cursor", flag64 = 0,
  dataNull = false, strAddr = V5_STR,
  latchDword,
} = {}) {
  seedPlaySsoStr({ text, heap, cap });
  seedVData({ name: dataName, length: 1, flag34: 0 });
  seedVAnm({
    overlayDataPtr: dataNull ? 0 : V5_DATA,
    flag64,
    speedBits: ANM2_F32_ONE_BITS,
    loadedByte: 1,
  });
  if (latchDword !== undefined) {
    pokeU32(V5_ANM + ANM2_OVERLAY_PLAYING_ALT_FLAG_OFF, latchDword >>> 0);
  }
  wasm.isaac_anm2_overlay_playing_sso_alt_plan(V5_ANM, strAddr, PLAN_OVERLAY_PLAYING_SSO_ALT);
  const js = numify(anm2OverlayPlayingSsoAltPlan(shadow, {
    anm2Addr: V5_ANM, strAddr,
  }));
  assertStructEqual(readOverlayPlayingSsoPlan(PLAN_OVERLAY_PLAYING_SSO_ALT), js, `${label} plan`);
  return js;
}

