  eq(jsNullAnm.entered, 0);
  eq(jsNullAnm.heapUsed, 0);
  eq(jsNullAnm.nameAddr, V5_STR);
  eq(jsNullAnm.resetFlag, 0x1ff);
  eq(jsNullAnm.hostCallCount, 1);

