/* ================== v32: 0x0040ac60 forwarder + 0x0040ac70 id lookup ===== */

const PLAN_ANIM_ID_LOOKUP = V5_BASE + 0x1600; /* 14 x 4 = 56 bytes */
const ANIM_ID_LOOKUP_OFF = {
  entered: 0, anim: 4, count: 8, found: 12, idVal: 16, elemBase: 20,
  elemByteOffset: 24, result: 28, logNeeded: 32, logVa: 36, logLevel: 40,
  logStrVa: 44, hostCallCount: 48, pureComplete: 52,
};
const PLAN_FORWARDER60 = V5_BASE + 0x1700; /* 6 x 4 = 24 bytes */
const FORWARDER60_OFF = {
  entered: 0, callVa: 4, recvOff: 8, argCount: 12, hostCallCount: 16, pureComplete: 20,
};

function readAnimIdLookupPlan(base) {
  return readPlanFields(base, ANIM_ID_LOOKUP_OFF, {
    entered: "i", anim: "u", count: "u", found: "i", idVal: "i",
    elemBase: "u", elemByteOffset: "i", result: "i", logNeeded: "i",
    logVa: "u", logLevel: "i", logStrVa: "u", hostCallCount: "i",
    pureComplete: "i",
  });
}
function readForwarder60Plan(base) {
  return readPlanFields(base, FORWARDER60_OFF, {
    entered: "i", callVa: "u", recvOff: "u", argCount: "i",
    hostCallCount: "i", pureComplete: "i",
  });
}

/* Seed an ANM2 image with an anim-data block, id array and 0x10-stride
   elements. elems[i] = {id, base, limit}; idArr[i] = id value. */
function seedAnimIdImage({ count = 0, animNull = false, elems = [], idArr = [] }) {
  const animData = V5_BASE + 0x2000;
  const ids = V5_BASE + 0x2400;
  const elemBase = V5_BASE + 0x2800;
  /* pokeU32 writes BOTH module memory and the oracle shadow; never
     shadow.fill(0) here — that desyncs the wasm side and a stale
     [anm2+4] leaks into the null-anim arm. Zero the consumed fields. */
  pokeU32(V5_ANM + ANM2_ANIM_ID_LOOKUP_ANIM_OFF, 0);
  pokeU32(V5_ANM + ANM2_ANIM_ID_LOOKUP_IDS_OFF, 0);
  pokeU32(animData + ANM2_ANIM_ID_LOOKUP_COUNT_OFF, 0);
  pokeU32(animData + ANM2_ANIM_ID_LOOKUP_ELEMS_OFF, 0);
  if (!animNull) {
    pokeU32(V5_ANM + ANM2_ANIM_ID_LOOKUP_ANIM_OFF, animData);
    pokeU32(animData + ANM2_ANIM_ID_LOOKUP_COUNT_OFF, count);
    pokeU32(animData + ANM2_ANIM_ID_LOOKUP_ELEMS_OFF, elemBase);
    for (let i = 0; i < count; ++i) {
      const e = elems[i] || { id: i, base: 0, limit: count };
      pokeU32(elemBase + i * ANM2_ANIM_ID_LOOKUP_ELEM_STRIDE + ANM2_ANIM_ID_LOOKUP_ID_OFF, e.id >>> 0);
      pokeU32(elemBase + i * ANM2_ANIM_ID_LOOKUP_ELEM_STRIDE + ANM2_ANIM_ID_LOOKUP_BASE_OFF, (e.base || 0) >>> 0);
      pokeU32(elemBase + i * ANM2_ANIM_ID_LOOKUP_ELEM_STRIDE + ANM2_ANIM_ID_LOOKUP_LIMIT_OFF, (e.limit ?? count) >>> 0);
    }
  }
  pokeU32(V5_ANM + ANM2_ANIM_ID_LOOKUP_IDS_OFF, ids);
  for (let i = 0; i < count; ++i) {
    pokeU32(ids + i * 4, (idArr[i] ?? i) >>> 0);
  }
  return { animData, ids, elemBase };
}

function runAnimIdLookupDiff(label, opts) {
  seedAnimIdImage(opts);
  wasm.isaac_anm2_anim_id_lookup_plan(V5_ANM, opts.id ?? 0, PLAN_ANIM_ID_LOOKUP);
  wasm.isaac_anm2_forwarder60_plan(V5_ANM, PLAN_FORWARDER60);
  const js = numify(anm2AnimIdLookupPlan(shadow, { anm2Addr: V5_ANM, id: opts.id ?? 0 }));
  const jsF = numify(anm2Forwarder60Plan(shadow, { anm2Addr: V5_ANM }));
  assertStructEqual(readAnimIdLookupPlan(PLAN_ANIM_ID_LOOKUP), js, label + " lookup");
  assertStructEqual(readForwarder60Plan(PLAN_FORWARDER60), jsF, label + " forwarder");
  return { lookup: js, forwarder: jsF };
}

test("v32 anim-id lookup fixed edges (found/miss/count0/null/negative)", () => {
  eq(ANM2_ANIM_ID_LOOKUP_VA, 0x0040ac70);
  eq(ANM2_ANIM_ID_LOOKUP_END_VA, 0x0040acca);
  eq(ANM2_ANIM_ID_LOOKUP_LOG_VA, 0x00a112c0);
  eq(ANM2_ANIM_ID_LOOKUP_LOG_LEVEL, 0x10);
  eq(ANM2_ANIM_ID_LOOKUP_FOUND_STRIDE, 0x54);
  eq(ANM2_FORWARDER_60_VA, 0x0040ac60);
  eq(ANM2_FORWARDER_60_END_VA, 0x0040ac6a);
  eq(ANM2_FORWARDER_60_CALL_VA, 0x0040882e);
  eq(ANM2_FORWARDER_60_RECV_OFF, 0x50);
  eq(ANM2_FORWARDER_60_ARG_COUNT, 1);
  eq(ANM2_FORWARDER_60_HOST_CALL_COUNT, 1);

  /* found: elem 1 matches lookup id 1; idArr[1]=1; base 0x100; limit 4. */
  const hit = runAnimIdLookupDiff("v32-hit", {
    count: 3, id: 1, idArr: [10, 1, 20],
    elems: [{ id: 10, base: 0x40 }, { id: 1, base: 0x100, limit: 4 }, { id: 20, base: 0x200 }],
  });
  eq(hit.lookup.found, 1);
  eq(hit.lookup.idVal, 1);
  eq(hit.lookup.elemByteOffset, 0x54);
  eq(hit.lookup.result, 0x54 + 0x100);
  eq(hit.lookup.logNeeded, 0);
  eq(hit.lookup.pureComplete, 1);

  /* miss: no elem matches -> result 0, pure. */
  const miss = runAnimIdLookupDiff("v32-miss", {
    count: 2, id: 5, idArr: [0, 1],
    elems: [{ id: 0, base: 0x40 }, { id: 1, base: 0x100 }],
  });
  eq(miss.lookup.found, 0);
  eq(miss.lookup.result, 0);
  eq(miss.lookup.pureComplete, 1);

  /* count 0 -> result 0 with no walk. */
  const empty = runAnimIdLookupDiff("v32-empty", { count: 0, id: 3 });
  eq(empty.lookup.count, 0);
  eq(empty.lookup.found, 0);
  eq(empty.lookup.result, 0);
  eq(empty.lookup.pureComplete, 1);

  /* null anim -> log host edge + reload (defect); still pure-incomplete. */
  const nullAnim = runAnimIdLookupDiff("v32-null", { animNull: true, count: 0, id: 3 });
  eq(nullAnim.lookup.logNeeded, 1);
  eq(nullAnim.lookup.hostCallCount, 1);
  eq(nullAnim.lookup.pureComplete, 0);

  /* negative or out-of-limit idVal -> skip (signed js / jge). */
  const negId = runAnimIdLookupDiff("v32-negid", {
    count: 2, id: 1, idArr: [0, -1],
    elems: [{ id: 0, base: 0x40 }, { id: 1, base: 0x100, limit: 4 }],
  });
  eq(negId.lookup.found, 0, "idVal -1 skipped by signed js");
  const oob = runAnimIdLookupDiff("v32-oolimit", {
    count: 2, id: 1, idArr: [0, 5],
    elems: [{ id: 0, base: 0x40 }, { id: 1, base: 0x100, limit: 4 }],
  });
  eq(oob.lookup.found, 0, "idVal 5 >= limit skipped by signed jge");

  /* forwarder always hosts one call on a non-null anm2. */
  eq(hit.forwarder.entered, 1);
  eq(hit.forwarder.callVa, 0x0040882e);
  eq(hit.forwarder.recvOff, 0x50);
  eq(hit.forwarder.argCount, 1);
  eq(hit.forwarder.hostCallCount, 1);
  eq(hit.forwarder.pureComplete, 0);

  wasm.isaac_anm2_forwarder60_plan(0, PLAN_FORWARDER60);
  const nullF = readForwarder60Plan(PLAN_FORWARDER60);
  eq(nullF.entered, 0);
  COUNT.cases += 8;
});

test("v32 anim-id lookup signed bounds cross the wide domain", () => {
  /* idVal 0x80000000 (bit 31) -> signed negative -> skip. */
  const neg = runAnimIdLookupDiff("v32-wide-neg", {
    count: 1, id: 1, idArr: [0x80000000],
    elems: [{ id: 1, base: 0x100, limit: 4 }],
  });
  eq(neg.lookup.found, 0, "0x80000000 idVal is signed-negative");
  /* limit 0x80000000 as int32 is -2147483648; idVal 1 >= that (signed jge)
     -> skip, exactly like the PE. A large positive limit 0x7fffffff accepts. */
  const bigNeg = runAnimIdLookupDiff("v32-wide-limit-neg", {
    count: 1, id: 1, idArr: [1],
    elems: [{ id: 1, base: 0x100, limit: 0x80000000 }],
  });
  eq(bigNeg.lookup.found, 0, "signed limit INT_MIN rejects idVal 1 (jge taken)");
  const big = runAnimIdLookupDiff("v32-wide-limit", {
    count: 1, id: 1, idArr: [1],
    elems: [{ id: 1, base: 0x100, limit: 0x7fffffff }],
  });
  eq(big.lookup.found, 1, "signed limit INT_MAX accepts idVal 1");
  eq(big.lookup.result, 0x54 + 0x100);
  COUNT.cases += 2;
});

test("v32 anim-id lookup header pins hold", () => {
  const headerText = readFileSync(header, "utf8");
  assert.match(headerText, /ISAAC_ANM2_ANIM_ID_LOOKUP_VA = 0x0040ac70u/);
  assert.match(headerText, /ISAAC_ANM2_FORWARDER_60_VA = 0x0040ac60u/);
  assert.match(headerText, /IsaacAnm2AnimIdLookupPlan/);
  assert.match(headerText, /IsaacAnm2Forwarder60Plan/);
  const sourceText = readFileSync(source, "utf8");
  assert.match(sourceText, /ISAAC_ANM2_NO_NARROW_PARAMS\(isaac_anm2_anim_id_lookup_plan\)/);
  assert.match(sourceText, /static_assert\(sizeof\(IsaacAnm2AnimIdLookupPlan\) == 56/);
  assert.match(sourceText, /static_assert\(sizeof\(IsaacAnm2Forwarder60Plan\) == 24/);
  COUNT.cases += 2;
});
/* ================== v33/v47: 0x0040ace0 extras name->index + stage-2 ===== */

const PLAN_EXTRAS_NAME_INDEX = V5_BASE + 0x1800; /* 19 x 4 = 76 bytes */
const EXTRAS_NAME_INDEX_OFF = {
  entered: 0, anim: 4, count: 8, found: 12, result: 16, logNeeded: 20,
  logVa: 24, logLevel: 28, logStrVa: 32, hostCallCount: 36, pureComplete: 40,
  anim2: 44, count2: 48, elems2: 52, idArr: 56, idVal: 60,
  elemByteOffset: 64, found2: 68, stage2Log: 72,
};

function readExtrasNameIndexPlan(base) {
  return readPlanFields(base, EXTRAS_NAME_INDEX_OFF, {
    entered: "i", anim: "u", count: "u", found: "i", result: "i",
    logNeeded: "i", logVa: "u", logLevel: "i", logStrVa: "u",
    hostCallCount: "i", pureComplete: "i",
    anim2: "u", count2: "u", elems2: "u", idArr: "u", idVal: "i",
    elemByteOffset: "i", found2: "i", stage2Log: "i",
  });
}

/* Seed an ANM2 image whose [this+4] -> animData at +anim, [anim] -> obj,
   [obj+0x88] count, [obj+0x84] list of 0x18-stride SSO extras.
   v47: also seed the stage-2 structures — [anim+0x24] count2,
   [anim+0x20] elems2 (stride 0x10), [this+0xc] id array. */
function seedExtrasImage({ count = 0, animNull = false, names = [], listHeap = false,
                           count2 = 0, elems2Ids = [], idVals = [], idArrNull = false,
                           elem2Base = 0, elem2Limit = 0 }) {
  /* PE: [this+4] gates the null-log; the walk base is [this] (offset 0),
     count at [base+0x88], list at [base+0x84]. */
  const animData = V5_BASE + 0x3000;
  const obj = animData; /* the walk base is [anm2+0] -> animData */
  const list = V5_BASE + 0x3400;
  pokeU32(V5_ANM + ANM2_EXTRAS_NAME_INDEX_ANIM_OFF, animNull ? 0 : animData);
  pokeU32(V5_ANM + ANM2_EXTRAS_NAME_INDEX_DATA_OFF, obj);
  pokeU32(obj + ANM2_EXTRAS_NAME_INDEX_COUNT_OFF, count);
  pokeU32(obj + ANM2_EXTRAS_NAME_INDEX_LIST_OFF, list);
  for (let i = 0; i < count; ++i) {
    const elem = list + i * ANM2_EXTRAS_NAME_INDEX_STRIDE;
    const name = names[i] ?? "";
    pokeU32(elem + ANM2_EXTRAS_NAME_INDEX_SSO_CAP_OFF, name.length + 1);
    if (name.length + 1 >= ANM2_EXTRAS_NAME_INDEX_SSO_CAP && listHeap) {
      const heap = V5_BASE + 0x3c00 + i * 0x20;
      pokeU32(elem, heap);
      pokeCString(heap, name);
    } else if (name.length + 1 < ANM2_EXTRAS_NAME_INDEX_SSO_CAP) {
      pokeCString(elem, name);
    } else {
      pokeU32(elem, 0); /* overflow'd but no heap: reproduce a bad SSO */
    }
  }
  /* v47 stage-2: [anim+0x24] count2, [anim+0x20] elems2 (stride 0x10),
     [this+0xc] id array. elems2Ids[j] is the key compared to the found
     extras index; idVals[j] is the id used for id_val*0x54+[elem+8]. */
  const elems2 = V5_BASE + 0x4400;
  const idArr = V5_BASE + 0x4800;
  pokeU32(V5_ANM + ANM2_EXTRAS_NAME_INDEX_ID_ARR_OFF, idArrNull ? 0 : idArr);
  pokeU32(animData + ANM2_EXTRAS_NAME_INDEX_COUNT2_OFF, count2);
  pokeU32(animData + ANM2_EXTRAS_NAME_INDEX_ELEMS2_OFF, elems2);
  for (let j = 0; j < Math.max(elems2Ids.length, idVals.length, count2); ++j) {
    const elem = elems2 + j * ANM2_EXTRAS_NAME_INDEX_ELEM2_STRIDE;
    pokeU32(elem + ANM2_EXTRAS_NAME_INDEX_ELEM2_ID_OFF, elems2Ids[j] ?? 0);
    pokeU32(elem + ANM2_EXTRAS_NAME_INDEX_ELEM2_BASE_OFF, elem2Base);
    pokeU32(elem + ANM2_EXTRAS_NAME_INDEX_ELEM2_LIMIT_OFF, elem2Limit);
    pokeU32(idArr + j * 4, idVals[j] ?? 0);
  }
  return { animData, obj, list, elems2, idArr };
}

function runExtrasNameIndexDiff(label, opts) {
  seedExtrasImage(opts);
  pokeCString(V5_NAME, opts.id ?? "");
  wasm.isaac_anm2_extras_name_index_plan(V5_ANM, V5_NAME, PLAN_EXTRAS_NAME_INDEX);
  const js = numify(anm2ExtrasNameIndexPlan(shadow, { anm2Addr: V5_ANM, nameAddr: V5_NAME }));
  assertStructEqual(readExtrasNameIndexPlan(PLAN_EXTRAS_NAME_INDEX), js, label + " plan");
  return js;
}

test("v33/v47 extras name->index + stage-2 fixed edges", () => {
  if (wasm === undefined) {
    /* pattern-filtered run: the build test did not execute */
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  eq(ANM2_EXTRAS_NAME_INDEX_VA, 0x0040ace0);
  eq(ANM2_EXTRAS_NAME_INDEX_END_VA, 0x0040adcc);
  eq(ANM2_EXTRAS_NAME_INDEX_LOG_VA, 0x00a112c0);
  eq(ANM2_EXTRAS_NAME_INDEX_LOG_LEVEL, 0x10);
  eq(ANM2_EXTRAS_NAME_INDEX_STRIDE, 0x18);
  eq(ANM2_EXTRAS_NAME_INDEX_COUNT_OFF, 0x88);
  eq(ANM2_EXTRAS_NAME_INDEX_LIST_OFF, 0x84);
  eq(ANM2_EXTRAS_NAME_INDEX_SSO_CAP, 0x10);
  eq(ANM2_EXTRAS_NAME_INDEX_COUNT2_OFF, 0x24);
  eq(ANM2_EXTRAS_NAME_INDEX_ELEMS2_OFF, 0x20);
  eq(ANM2_EXTRAS_NAME_INDEX_ELEM2_STRIDE, 0x10);
  eq(ANM2_EXTRAS_NAME_INDEX_ID_ARR_OFF, 0x0c);
  eq(ANM2_EXTRAS_NAME_INDEX_ELEM2_ID_OFF, 0x00);
  eq(ANM2_EXTRAS_NAME_INDEX_ELEM2_BASE_OFF, 0x08);
  eq(ANM2_EXTRAS_NAME_INDEX_ELEM2_LIMIT_OFF, 0x0c);
  eq(ANM2_EXTRAS_NAME_INDEX_FOUND_STRIDE, 0x54);

  /* hit on index 1 -> STAGE-2: [elem]==1 && id_val 5 < limit 10 ->
     result = 5*0x54 + base. NOT the raw index (v33's fold). */
  const hit = runExtrasNameIndexDiff("v47-hit", {
    count: 3, names: ["one", "wanted", "three"], id: "wanted",
    count2: 2, elems2Ids: [0, 1], idVals: [9, 5], elem2Base: 0x1234, elem2Limit: 10,
  });
  eq(hit.found, 1, "extras index");
  eq(hit.found2, 1, "stage-2 match");
  eq(hit.idVal, 5);
  eq(hit.elemByteOffset, 0x10, "matched elem at j=1 stride 0x10");
  eq(hit.result, 5 * 0x54 + 0x1234, "id_val*0x54 + [elem+8], NOT raw index");
  eq(hit.count2, 2);
  eq(hit.logNeeded, 0);
  eq(hit.pureComplete, 1);

  /* miss -> found -1, result 0, no stage-2. */
  const miss = runExtrasNameIndexDiff("v47-miss", {
    count: 2, names: ["a", "b"], id: "zzz", count2: 1, elems2Ids: [0], idVals: [1],
  });
  eq(miss.found, -1);
  eq(miss.result, 0);
  eq(miss.found2, 0);
  eq(miss.pureComplete, 1);

  /* count 0 -> result 0, no walk. */
  const empty = runExtrasNameIndexDiff("v47-empty", { count: 0, id: "x" });
  eq(empty.count, 0);
  eq(empty.result, 0);
  eq(empty.pureComplete, 1);

  /* null anim -> log host edge, pure-incomplete — but the WALK STILL RUNS
     (v47: v33's early-out was a fold; the machine logs and continues). With
     a HIT, the stage-2 continuation re-reads [this+4] (still null) and
     re-logs, so BOTH logs fire. */
  const nullAnim = runExtrasNameIndexDiff("v47-null", {
    animNull: true, count: 2, names: ["a", "wanted"], id: "wanted",
    count2: 1, elems2Ids: [1], idVals: [3], elem2Base: 0x40, elem2Limit: 4,
  });
  eq(nullAnim.logNeeded, 1);
  eq(nullAnim.hostCallCount, 2, "stage-1 null log + stage-2 null re-log");
  eq(nullAnim.found, 1, "walk still runs after the null log");
  eq(nullAnim.found2, 0, "anim2 still null after reload -> no stage-2 match");
  eq(nullAnim.result, 0, "null anim2 after reload -> 0");
  eq(nullAnim.pureComplete, 0);

  /* null anim + MISS: only the stage-1 log fires (walk still runs). */
  const nullMiss = runExtrasNameIndexDiff("v47-null-miss", {
    animNull: true, count: 2, names: ["a", "b"], id: "zzz",
    count2: 1, elems2Ids: [0], idVals: [3], elem2Base: 0x40, elem2Limit: 4,
  });
  eq(nullMiss.logNeeded, 1);
  eq(nullMiss.hostCallCount, 1, "only stage-1 null log on a miss");
  eq(nullMiss.found, -1);
  eq(nullMiss.result, 0);
  eq(nullMiss.pureComplete, 0);

  /* hit but stage-2 count2==0 -> result 0 (continuation gate). */
  const noCount2 = runExtrasNameIndexDiff("v47-no-count2", {
    count: 1, names: ["wanted"], id: "wanted", count2: 0,
  });
  eq(noCount2.found, 0);
  eq(noCount2.count2, 0);
  eq(noCount2.elems2, 0, "elems2 read is gated by count2 != 0");
  eq(noCount2.idArr, 0, "id_arr read is gated by count2 != 0");
  eq(noCount2.result, 0, "count2==0 -> 0");
  eq(noCount2.pureComplete, 1);

  /* hit, stage-2 elem key mismatch -> 0. */
  const keyMiss = runExtrasNameIndexDiff("v47-key-miss", {
    count: 1, names: ["wanted"], id: "wanted",
    count2: 2, elems2Ids: [1, 2], idVals: [1, 7], elem2Base: 0x10, elem2Limit: 100,
  });
  eq(keyMiss.found, 0);
  eq(keyMiss.found2, 0);
  eq(keyMiss.result, 0, "no [elem]==extrasIndex -> 0");

  /* hit, id_val < 0 (SIGNED js) -> skipped. */
  const negId = runExtrasNameIndexDiff("v47-neg-id", {
    count: 1, names: ["wanted"], id: "wanted",
    count2: 2, elems2Ids: [0, 0], idVals: [-1, 7], elem2Base: 0x20, elem2Limit: 100,
  });
  eq(negId.found, 0);
  eq(negId.found2, 1, "second j matches after the negative id_val is skipped");
  eq(negId.idVal, 7);
  eq(negId.result, 7 * 0x54 + 0x20);

  /* hit, id_val == limit -> SIGNED jl strict <, rejected. */
  const limEq = runExtrasNameIndexDiff("v47-limit-eq", {
    count: 1, names: ["wanted"], id: "wanted",
    count2: 1, elems2Ids: [0], idVals: [10], elem2Base: 0x30, elem2Limit: 10,
  });
  eq(limEq.found2, 0, "id_val == limit is NOT < limit (jl strict)");
  eq(limEq.result, 0);

  /* hit, stage-2 null anim -> second log + RELOAD + pure-incomplete. */
  const nullAnim2 = runExtrasNameIndexDiff("v47-null-anim2", {
    count: 1, names: ["wanted"], id: "wanted",
    count2: 1, elems2Ids: [0], idVals: [2], elem2Base: 0x8, elem2Limit: 9,
    animNull: true,
  });
  eq(nullAnim2.found, 0);
  eq(nullAnim2.stage2Log, 1, "stage-2 null anim re-log");
  eq(nullAnim2.hostCallCount, 2, "stage-1 log + stage-2 re-log");
  eq(nullAnim2.pureComplete, 0);
  eq(nullAnim2.result, 0, "anim2 null after reload -> 0");

  /* heap-backed SSO (cap >= 0x10 but <= heap) matches. */
  const heap = runExtrasNameIndexDiff("v47-heap", {
    count: 2, names: ["short", "a-very-long-extra-name-over-16"],
    id: "a-very-long-extra-name-over-16", listHeap: true,
    count2: 1, elems2Ids: [1], idVals: [4], elem2Base: 0x50, elem2Limit: 9,
  });
  eq(heap.found, 1, "heap-backed extra matched via [elem]");
  eq(heap.result, 4 * 0x54 + 0x50);

  /* hit with empty string -> index 0. */
  const emptyStr = runExtrasNameIndexDiff("v47-empty-name", {
    count: 2, names: ["", "b"], id: "", count2: 1, elems2Ids: [0], idVals: [1],
    elem2Base: 0x60, elem2Limit: 3,
  });
  eq(emptyStr.found, 0);
  eq(emptyStr.result, 1 * 0x54 + 0x60);
  COUNT.cases += 12;
});

test("v47 extras name->index wide-value gates (0x100 / 0xffffffff)", () => {
  if (wasm === undefined) {
    /* pattern-filtered run: the build test did not execute */
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  /* Stage-2 id_val SIGNED gate: 0x100 is positive -> accepted; the wide
     value must NOT be pre-masked. */
  const wide = runExtrasNameIndexDiff("v47-wide-id", {
    count: 1, names: ["wanted"], id: "wanted",
    count2: 1, elems2Ids: [0], idVals: [0x100], elem2Base: 0x1, elem2Limit: 0x1000,
  });
  eq(wide.found2, 1);
  eq(wide.idVal, 0x100);
  eq(wide.result, 0x100 * 0x54 + 0x1, "wide id_val passes the signed >=0 gate");

  /* 0xffffffff as id_val is NEGATIVE (js skips) — full dword, not low byte. */
  const negWide = runExtrasNameIndexDiff("v47-neg-wide-id", {
    count: 1, names: ["wanted"], id: "wanted",
    count2: 1, elems2Ids: [0], idVals: [0xffffffff], elem2Base: 0x1, elem2Limit: 0x1000,
  });
  eq(negWide.found2, 0, "0xffffffff id_val is signed-negative -> skipped");
  eq(negWide.result, 0);

  /* elem2Limit SIGNED: 0x1000 limit accepts id_val 0x100; a limit of
     0xffffffff is signed -1, so NO id_val can be < it. */
  const limNeg = runExtrasNameIndexDiff("v47-limit-neg", {
    count: 1, names: ["wanted"], id: "wanted",
    count2: 1, elems2Ids: [0], idVals: [0x100], elem2Base: 0x2, elem2Limit: 0xffffffff,
  });
  eq(limNeg.found2, 0, "limit 0xffffffff signed -1 -> no id_val qualifies");
  eq(limNeg.result, 0);

  /* stage-1 count 0x100 -> walks all extras; hit at index 1. */
  const wideCount = runExtrasNameIndexDiff("v47-wide-count", {
    count: 0x100, names: ["a", "wanted"], id: "wanted",
    count2: 1, elems2Ids: [1], idVals: [0x100], elem2Base: 0x3, elem2Limit: 0x200,
  });
  eq(wideCount.found, 1);
  eq(wideCount.result, 0x100 * 0x54 + 0x3);
  COUNT.cases += 4;
});

