test("v47 extras stage-2 mutations are caught by the pins", () => {
  if (wasm === undefined) {
    /* pattern-filtered run: the build test did not execute */
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const seedHit = () => seedExtrasImage({
    count: 2, names: ["one", "wanted"], id: "wanted",
    count2: 2, elems2Ids: [0, 1], idVals: [9, 5], elem2Base: 0x1234, elem2Limit: 10,
  });
  const withMutant = (label, mutate, check, probe) => {
  const bad = mutate(base);
  assert.notEqual(bad, base, `${label}: mutant did not apply`);
  writeSourceRetry(toFile(bad));
  wasm = loadExports();
    let threw = false;
    try {
      wasm = loadExports();
      wmem = new Uint8Array(wasm.memory.buffer);
      if (probe) {
        const diverged = probe();
        assert.ok(diverged, `${label}: rebuilt module not mutant (stale build)`);
      }
      check();
    } catch {
      threw = true;
    }
    writeSourceRetry(original);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    /* the v33 fold: hit returns the raw extras index instead of the
       stage-2 id_val*0x54+[elem+8] result */
    withMutant("extras hit folded to raw index (v33 defect)",
      (s) => s.replace(
        "plan.result = id_val *\n              static_cast<int32_t>(ISAAC_ANM2_EXTRAS_NAME_INDEX_FOUND_STRIDE) +\n              static_cast<int32_t>(load_u32(\n                  elem2 + ISAAC_ANM2_EXTRAS_NAME_INDEX_ELEM2_BASE_OFF));",
        "plan.result = found;"),
      () => {
        seedHit();
        wasm.isaac_anm2_extras_name_index_plan(V5_ANM, V5_NAME, PLAN_EXTRAS_NAME_INDEX);
        const p = readExtrasNameIndexPlan(PLAN_EXTRAS_NAME_INDEX);
        eq(p.result, 5 * 0x54 + 0x1234, "stage-2 result published");
      },
      () => {
        seedHit();
        wasm.isaac_anm2_extras_name_index_plan(V5_ANM, V5_NAME, PLAN_EXTRAS_NAME_INDEX);
        return readExtrasNameIndexPlan(PLAN_EXTRAS_NAME_INDEX).result === 1;
      });

    /* stage-2 elem stride: 0x10 -> 0x8 (second elem at wrong offset) */
    withMutant("stage-2 elem stride halved",
      (s) => s.replace("ISAAC_ANM2_EXTRAS_NAME_INDEX_ELEM2_STRIDE);\n          const int32_t elem_id",
                       "ISAAC_ANM2_EXTRAS_NAME_INDEX_ELEM2_STRIDE / 2);\n          const int32_t elem_id"),
      () => {
        seedHit();
        wasm.isaac_anm2_extras_name_index_plan(V5_ANM, V5_NAME, PLAN_EXTRAS_NAME_INDEX);
        const p = readExtrasNameIndexPlan(PLAN_EXTRAS_NAME_INDEX);
        eq(p.found2, 1, "stage-2 match found");
        eq(p.idVal, 5);
      },
      () => {
        seedHit();
        wasm.isaac_anm2_extras_name_index_plan(V5_ANM, V5_NAME, PLAN_EXTRAS_NAME_INDEX);
        return readExtrasNameIndexPlan(PLAN_EXTRAS_NAME_INDEX).found2 === 0;
      });

    /* stage-2 id_val SIGNED gate dropped: -1 id_val wrongly accepted */
    withMutant("stage-2 negative id_val accepted",
      (s) => s.replace("if (id_val < 0) continue;", "if (false) continue;"),
      () => {
        seedExtrasImage({
          count: 1, names: ["wanted"], id: "wanted",
          count2: 1, elems2Ids: [0], idVals: [-1], elem2Base: 0x20, elem2Limit: 100,
        });
        wasm.isaac_anm2_extras_name_index_plan(V5_ANM, V5_NAME, PLAN_EXTRAS_NAME_INDEX);
        const p = readExtrasNameIndexPlan(PLAN_EXTRAS_NAME_INDEX);
        eq(p.found2, 0, "negative id_val rejected (js)");
        eq(p.result, 0);
      },
      () => {
        seedExtrasImage({
          count: 1, names: ["wanted"], id: "wanted",
          count2: 1, elems2Ids: [0], idVals: [-1], elem2Base: 0x20, elem2Limit: 100,
        });
        wasm.isaac_anm2_extras_name_index_plan(V5_ANM, V5_NAME, PLAN_EXTRAS_NAME_INDEX);
        return readExtrasNameIndexPlan(PLAN_EXTRAS_NAME_INDEX).found2 === 1;
      });

    /* stage-2 limit: jl strict < folded to <= (id_val == limit accepted) */
    withMutant("stage-2 limit <= instead of <",
      (s) => s.replace("if (id_val >= limit) continue;", "if (id_val > limit) continue;"),
      () => {
        seedExtrasImage({
          count: 1, names: ["wanted"], id: "wanted",
          count2: 1, elems2Ids: [0], idVals: [10], elem2Base: 0x30, elem2Limit: 10,
        });
        wasm.isaac_anm2_extras_name_index_plan(V5_ANM, V5_NAME, PLAN_EXTRAS_NAME_INDEX);
        const p = readExtrasNameIndexPlan(PLAN_EXTRAS_NAME_INDEX);
        eq(p.found2, 0, "id_val == limit rejected (jl strict)");
      },
      () => {
        seedExtrasImage({
          count: 1, names: ["wanted"], id: "wanted",
          count2: 1, elems2Ids: [0], idVals: [10], elem2Base: 0x30, elem2Limit: 10,
        });
        wasm.isaac_anm2_extras_name_index_plan(V5_ANM, V5_NAME, PLAN_EXTRAS_NAME_INDEX);
        return readExtrasNameIndexPlan(PLAN_EXTRAS_NAME_INDEX).found2 === 1;
      });

    /* stage-2 id array base: [this+0xc] -> [anim+0xc] (wrong receiver) */
    withMutant("stage-2 id array read from anim",
      (s) => s.replace("anm2 + ISAAC_ANM2_EXTRAS_NAME_INDEX_ID_ARR_OFF",
                       "anim_bytes + ISAAC_ANM2_EXTRAS_NAME_INDEX_ID_ARR_OFF"),
      () => {
        seedHit();
        wasm.isaac_anm2_extras_name_index_plan(V5_ANM, V5_NAME, PLAN_EXTRAS_NAME_INDEX);
        const p = readExtrasNameIndexPlan(PLAN_EXTRAS_NAME_INDEX);
        eq(p.idVal, 5, "id_val from [this+0xc]");
      },
      () => {
        seedHit();
        wasm.isaac_anm2_extras_name_index_plan(V5_ANM, V5_NAME, PLAN_EXTRAS_NAME_INDEX);
        return readExtrasNameIndexPlan(PLAN_EXTRAS_NAME_INDEX).idVal !== 5;
      });

    /* stage-1 null anim no longer continues the walk (v33 early-out fold) */
    withMutant("stage-1 null anim early-out (v33 fold)",
      (s) => s.replace("plan.pure_complete = 0;\n  }\n  /* PE 0x40ad04 mov esi,[edi]:",
                       "plan.pure_complete = 0;\n    if (out != nullptr) *out = plan;\n    return;\n  }\n  /* PE 0x40ad04 mov esi,[edi]:"),
      () => {
        runExtrasNameIndexDiff("v47-null-walk", {
          animNull: true, count: 2, names: ["a", "wanted"], id: "wanted",
          count2: 1, elems2Ids: [1], idVals: [3], elem2Base: 0x40, elem2Limit: 4,
        });
      },
      () => {
        seedExtrasImage({
          animNull: true, count: 2, names: ["a", "wanted"], id: "wanted",
          count2: 1, elems2Ids: [1], idVals: [3], elem2Base: 0x40, elem2Limit: 4,
        });
        wasm.isaac_anm2_extras_name_index_plan(V5_ANM, V5_NAME, PLAN_EXTRAS_NAME_INDEX);
        return readExtrasNameIndexPlan(PLAN_EXTRAS_NAME_INDEX).found === -1;
      });

    /* stage-2 count2 gate dropped (elems2/id_arr published even when
       count2==0 — the reads live inside the gate) */
    withMutant("stage-2 count2 gate dropped",
      (s) => s.replace("if (count2 != 0u) {", "if (true) {"),
      () => {
        runExtrasNameIndexDiff("v47-no-count2-gate", {
          count: 1, names: ["wanted"], id: "wanted", count2: 0,
        });
      },
      () => {
        seedExtrasImage({
          count: 1, names: ["wanted"], id: "wanted", count2: 0,
          elems2Ids: [0], idVals: [1], elem2Base: 0x10, elem2Limit: 9,
        });
        wasm.isaac_anm2_extras_name_index_plan(V5_ANM, V5_NAME, PLAN_EXTRAS_NAME_INDEX);
        return readExtrasNameIndexPlan(PLAN_EXTRAS_NAME_INDEX).elems2 !== 0;
      });
  } finally {
    writeSourceRetry(original);
  }
  /* rebind a clean build so nothing downstream runs a mutant module */
  wasm = loadExports();
  wmem = new Uint8Array(wasm.memory.buffer);
  COUNT.cases += 7;
});
/* ================== v34: 0x0040af10 GetAnimation two-stage =============== */

const PLAN_GET_ANIM_TWO_STAGE = V5_BASE + 0x1a00; /* 15 x 4 = 60 bytes */
const GET_ANIM_TWO_STAGE_OFF = {
  entered: 0, outer: 4, count: 8, foundOuter: 12, innerCount: 16,
  frameInt: 20, bestDelta: 24, bestPayload: 28, result: 32, logNeeded: 36,
  logVa: 40, logLevel: 44, logStrVa: 48, hostCallCount: 52, pureComplete: 56,
};

function readGetAnimTwoStagePlan(base) {
  return readPlanFields(base, GET_ANIM_TWO_STAGE_OFF, {
    entered: "i", outer: "i", count: "u", foundOuter: "i", innerCount: "u",
    frameInt: "i", bestDelta: "i", bestPayload: "i", result: "i",
    logNeeded: "i", logVa: "u", logLevel: "i", logStrVa: "u",
    hostCallCount: "i", pureComplete: "i",
  });
}

/* Seed the GetAnimation image: outer name list at [data+0x90]/[data+0x8c],
   inner id->payload pairs at [inner+0x28]/[inner+0x2c], frame float at
   [anm2+0x10]. innerElems = [[id,payload],[id,payload],...] 8-byte stride. */
function seedGetAnimImage({ names = [], inner = [], frameF = 0 }) {
  const data = V5_BASE + 0x4000;
  const innerData = V5_BASE + 0x4400;
  const list = V5_BASE + 0x4800;
  const elems = V5_BASE + 0x4c00;
  pokeU32(V5_ANM + ANM2_GET_ANIM_TWO_STAGE_ANIM_OFF, innerData);
  pokeU32(V5_ANM + ANM2_GET_ANIM_TWO_STAGE_DATA_OFF, data);
  pokeU32(V5_ANM + ANM2_GET_ANIM_TWO_STAGE_FRAME_FLOAT_OFF, f32BitsOf(frameF));
  pokeU32(data + ANM2_GET_ANIM_TWO_STAGE_COUNT_OFF, names.length);
  pokeU32(data + ANM2_GET_ANIM_TWO_STAGE_LIST_OFF, list);
  for (let i = 0; i < names.length; ++i) {
    const elem = list + i * ANM2_GET_ANIM_TWO_STAGE_STRIDE;
    pokeU32(elem + ANM2_GET_ANIM_TWO_STAGE_SSO_CAP_OFF, names[i].length + 1);
    pokeCString(elem, names[i]);
  }
  pokeU32(innerData + ANM2_GET_ANIM_TWO_STAGE_INNER_COUNT_OFF, inner.length);
  pokeU32(innerData + ANM2_GET_ANIM_TWO_STAGE_INNER_ELEMS_OFF, elems);
  for (let i = 0; i < inner.length; ++i) {
    const p = inner[i] || { id: i, payload: 0 };
    pokeU32(elems + i * 8, p.id >>> 0);
    pokeU32(elems + i * 8 + 4, (p.payload ?? 0) >>> 0);
  }
  return { data, innerData, list, elems };
}

function runGetAnimTwoStageDiff(label, { names = [], inner = [], frameF = 0, id = "" }) {
  seedGetAnimImage({ names, inner, frameF });
  pokeCString(V5_NAME, id);
  wasm.isaac_anm2_get_anim_two_stage_plan(V5_ANM, V5_NAME, PLAN_GET_ANIM_TWO_STAGE);
  const js = numify(anm2GetAnimTwoStagePlan(shadow, { anm2Addr: V5_ANM, nameAddr: V5_NAME }));
  assertStructEqual(readGetAnimTwoStagePlan(PLAN_GET_ANIM_TWO_STAGE), js, label + " plan");
  return js;
}

test("v34 GetAnimation two-stage fixed edges (miss/inner-miss/min-delta)", () => {
  eq(ANM2_GET_ANIM_TWO_STAGE_VA, 0x0040af10);
  eq(ANM2_GET_ANIM_TWO_STAGE_END_VA, 0x0040aff5);
  eq(ANM2_GET_ANIM_TWO_STAGE_LOG_VA, 0x00a112c0);
  eq(ANM2_GET_ANIM_TWO_STAGE_STRIDE, 0x18);
  eq(ANM2_GET_ANIM_TWO_STAGE_INNER_COUNT_OFF, 0x2c);
  eq(ANM2_GET_ANIM_TWO_STAGE_INNER_ELEMS_OFF, 0x28);
  eq(ANM2_GET_ANIM_TWO_STAGE_FRAME_FLOAT_OFF, 0x10);
  eq(ANM2_GET_ANIM_TWO_STAGE_MISS, -1);

  /* stage-1 miss -> result -1, no inner scan. */
  const miss = runGetAnimTwoStageDiff("v34-miss", {
    names: ["one", "two"], inner: [{ id: 0, payload: 5 }, { id: 1, payload: 9 }], frameF: 10, id: "zzz",
  });
  eq(miss.foundOuter, 0);
  eq(miss.result, -1, "outer miss -> -1");
  eq(miss.pureComplete, 1);

  /* outer hit 'one' (idx 0), inner match id 0 payload 5, frame 10 -> delta 5. */
  const hit = runGetAnimTwoStageDiff("v34-hit", {
    names: ["one", "two"], inner: [{ id: 0, payload: 5 }, { id: 1, payload: 9 }], frameF: 10, id: "one",
  });
  eq(hit.outer, 0);
  eq(hit.foundOuter, 1);
  eq(hit.innerCount, 2);
  eq(hit.frameInt, 10, "cvttss2si(10.0)");
  eq(hit.bestDelta, 5);
  eq(hit.bestPayload, 5);
  eq(hit.result, 5);

  /* min-delta: two matches for outer 1, pick the smaller positive delta. */
  const min = runGetAnimTwoStageDiff("v34-min", {
    names: ["a", "two"], inner: [{ id: 1, payload: 3 }, { id: 1, payload: 7 }], frameF: 10, id: "two",
  });
  eq(min.outer, 1);
  eq(min.bestDelta, 3, "min positive delta kept (10-7=3 over 10-3=7)");
  eq(min.bestPayload, 7, "payload of the min-delta match");
  eq(min.result, 7);

  /* delta <= 0 skipped: payload 10 with frame 10 -> non-positive, miss. */
  const nonpos = runGetAnimTwoStageDiff("v34-nonpos", {
    names: ["x"], inner: [{ id: 0, payload: 10 }], frameF: 10, id: "x",
  });
  eq(nonpos.foundOuter, 1);
  eq(nonpos.bestDelta, -1, "delta 0 is not positive");
  eq(nonpos.result, -1);

  /* inner count 0 -> result -1. */
  const noInner = runGetAnimTwoStageDiff("v34-noinner", {
    names: ["x"], inner: [], frameF: 10, id: "x",
  });
  eq(noInner.foundOuter, 1);
  eq(noInner.result, -1);

  /* frame float truncation: frame 10.75 -> 10, payload 8 -> delta 2. */
  const trunc = runGetAnimTwoStageDiff("v34-trunc", {
    names: ["x"], inner: [{ id: 0, payload: 8 }], frameF: 10.75, id: "x",
  });
  eq(trunc.frameInt, 10, "cvttss2si truncates 10.75 -> 10");
  eq(trunc.result, 8);
  COUNT.cases += 6;
});

