/* ================== v35: 0x0040b0c0 three-stage lookup =================== */

const PLAN_THREE_STAGE = V5_BASE + 0x1c00; /* 15 x 4 = 60 bytes */
const THREE_STAGE_OFF = {
  entered: 0, data: 4, dataFound: 8, extraIndex: 12, extraFound: 16,
  innerCount: 20, innerIdVal: 24, elemByteOffset: 28, result: 32,
  failLogNeeded: 36, failLogVa: 40, failLogLevel: 44, failLogStrVa: 48,
  hostCallCount: 52, pureComplete: 56,
};

function readThreeStagePlan(base) {
  return readPlanFields(base, THREE_STAGE_OFF, {
    entered: "i", data: "u", dataFound: "i", extraIndex: "i", extraFound: "i",
    innerCount: "u", innerIdVal: "i", elemByteOffset: "i", result: "i",
    failLogNeeded: "i", failLogVa: "u", failLogLevel: "i", failLogStrVa: "u",
    hostCallCount: "i", pureComplete: "i",
  });
}

/* Seed: AD array at [anm2+0x74]/[0x78] (0x13c stride, name at elem+0 SSO),
   extras at [anm2+0x88]/[0x84], inner elems [data+0x20]/[0x24] stride 0x10. */
function seedThreeStage({ adCount = 0, adNames = [], extras = [], inner = [], id = 0 }) {
  const adBase = V5_BASE + 0x5000;
  const exList = V5_BASE + 0x5400;
  const data = V5_BASE + 0x5800; /* stage-1 element 0 -> data block */
  const innerElems = V5_BASE + 0x5c00;
  pokeU32(V5_ANM + ANM2_OFF_ANIM_DATA_74, adBase);
  pokeU32(V5_ANM + ANM2_OFF_ANIM_COUNT_78, adCount);
  pokeU32(V5_ANM + ANM2_THREE_STAGE_LOOKUP_EXTRAS_COUNT_OFF, extras.length);
  pokeU32(V5_ANM + ANM2_THREE_STAGE_LOOKUP_EXTRAS_LIST_OFF, exList);
  for (let i = 0; i < adCount; ++i) {
    const e = adBase + i * ANM2_ANIM_DATA_STRIDE;
    const name = adNames[i] ?? "";
    pokeU32(e + 0x14, name.length + 1); /* std::string cap at +0x14 */
    pokeCString(e, name);
  }
  for (let i = 0; i < extras.length; ++i) {
    const e = exList + i * ANM2_THREE_STAGE_LOOKUP_EXTRAS_STRIDE;
    pokeU32(e + ANM2_THREE_STAGE_LOOKUP_SSO_CAP_OFF, extras[i].length + 1);
    pokeCString(e, extras[i]);
  }
  /* stage-1 element 0 IS the data block (its name matched); the inner
     count/elems live at the element's +0x20/+0x24. The model computes
     data = adBase + index*0x13c, so the inner block must be THERE. */
  const dataBlock = adBase + 0 * ANM2_ANIM_DATA_STRIDE;
  pokeU32(dataBlock + ANM2_THREE_STAGE_LOOKUP_INNER_COUNT_OFF, inner.length);
  pokeU32(dataBlock + ANM2_THREE_STAGE_LOOKUP_INNER_ELEMS_OFF, innerElems);
  for (let i = 0; i < inner.length; ++i) {
    const p = inner[i] || { id: i, base: 0, limit: inner.length };
    pokeU32(innerElems + i * ANM2_THREE_STAGE_LOOKUP_INNER_STRIDE + ANM2_THREE_STAGE_LOOKUP_INNER_ID_OFF, p.id >>> 0);
    pokeU32(innerElems + i * ANM2_THREE_STAGE_LOOKUP_INNER_STRIDE + ANM2_THREE_STAGE_LOOKUP_INNER_BASE_OFF, (p.base || 0) >>> 0);
    pokeU32(innerElems + i * ANM2_THREE_STAGE_LOOKUP_INNER_STRIDE + ANM2_THREE_STAGE_LOOKUP_INNER_LIMIT_OFF, (p.limit ?? inner.length) >>> 0);
  }
  return { adBase, exList, data, innerElems };
}

function runThreeStageDiff(label, opts) {
  const { dataName, extraName, id } = opts;
  seedThreeStage(opts);
  pokeCString(V5_NAME, dataName);
  pokeCString(V5_NAME_HEAP, extraName);
  wasm.isaac_anm2_three_stage_lookup_plan(V5_ANM, V5_NAME, V5_NAME_HEAP, id, PLAN_THREE_STAGE);
  const js = numify(anm2ThreeStageLookupPlan(shadow, {
    anm2Addr: V5_ANM, dataNameAddr: V5_NAME, extraNameAddr: V5_NAME_HEAP, id,
  }));
  assertStructEqual(readThreeStagePlan(PLAN_THREE_STAGE), js, label + " plan");
  return js;
}

test("v35 three-stage lookup fixed edges (full/miss-fail/extra-miss/inner)", () => {
  eq(ANM2_THREE_STAGE_LOOKUP_VA, 0x0040b0c0);
  eq(ANM2_THREE_STAGE_LOOKUP_END_VA, 0x0040b19f);
  eq(ANM2_THREE_STAGE_LOOKUP_AD_WALK_VA, 0x0040bcd0);
  eq(ANM2_THREE_STAGE_LOOKUP_FAIL_LOG_LEVEL, 1);
  eq(ANM2_THREE_STAGE_LOOKUP_EXTRAS_STRIDE, 0x18);
  eq(ANM2_THREE_STAGE_LOOKUP_INNER_STRIDE, 0x10);
  eq(ANM2_THREE_STAGE_LOOKUP_FOUND_STRIDE, 0x54);

  /* full: AD 'data' found, extras 'ex0', inner id 1 -> 0x54+0x100. */
  const full = runThreeStageDiff("v35-full", {
    adCount: 1, adNames: ["data"], extras: ["ex0"],
    inner: [{ id: 1, base: 0x100, limit: 3 }], id: 1,
    dataName: "data", extraName: "ex0",
  });
  eq(full.dataFound, 1);
  eq(full.extraFound, 1);
  eq(full.extraIndex, 0);
  eq(full.innerIdVal, 1);
  eq(full.elemByteOffset, 0x54);
  eq(full.result, 0x54 + 0x100);
  eq(full.failLogNeeded, 0);
  eq(full.pureComplete, 1);

  /* stage-1 AD miss -> result 0, no fail log (PE returns 0). */
  const adMiss = runThreeStageDiff("v35-admiss", {
    adCount: 1, adNames: ["data"], extras: ["ex0"], inner: [{ id: 1, base: 0x100 }], id: 1,
    dataName: "nope", extraName: "ex0",
  });
  eq(adMiss.dataFound, 0);
  eq(adMiss.result, 0);
  eq(adMiss.failLogNeeded, 0);

  /* stage-2 extras miss -> fail log host edge. */
  const exMiss = runThreeStageDiff("v35-exmiss", {
    adCount: 1, adNames: ["data"], extras: ["ex0"], inner: [{ id: 1, base: 0x100 }], id: 1,
    dataName: "data", extraName: "zzz",
  });
  eq(exMiss.dataFound, 1);
  eq(exMiss.extraFound, 0);
  eq(exMiss.failLogNeeded, 1);
  eq(exMiss.hostCallCount, 1);
  eq(exMiss.pureComplete, 0);

  /* stage-3 inner miss -> result 0, no fail log. */
  const innerMiss = runThreeStageDiff("v35-inner-miss", {
    adCount: 1, adNames: ["data"], extras: ["ex0"], inner: [{ id: 1, base: 0x100 }], id: 9,
    dataName: "data", extraName: "ex0",
  });
  eq(innerMiss.extraFound, 1);
  eq(innerMiss.result, 0);

  /* inner id out of signed bounds -> skip. */
  const oob = runThreeStageDiff("v35-oob", {
    adCount: 1, adNames: ["data"], extras: ["ex0"],
    inner: [{ id: 1, base: 0x100, limit: 1 }], id: 1,
    dataName: "data", extraName: "ex0",
  });
  eq(oob.result, 0, "id 1 >= limit 1 skipped");
  COUNT.cases += 5;
});

