/* ================== v36: 0x0040b23a bounds-checked element getter ========= */

const PLAN_BOUNDED_ELEM = V5_BASE + 0x1e00; /* 12 x 4 = 48 bytes */
const BOUNDED_ELEM_OFF = {
  entered: 0, count: 4, base: 8, index: 12, elem: 16, inRange: 20,
  logNeeded: 24, logVa: 28, logLevel: 32, logStrVa: 36, hostCallCount: 40,
  pureComplete: 44,
};

function readBoundedElemPlan(base) {
  return readPlanFields(base, BOUNDED_ELEM_OFF, {
    entered: "i", count: "i", base: "u", index: "i", elem: "u", inRange: "i",
    logNeeded: "i", logVa: "u", logLevel: "i", logStrVa: "u",
    hostCallCount: "i", pureComplete: "i",
  });
}

function seedBoundedElem({ count = 4, base = 0x1000 }) {
  pokeU32(V5_ANM + ANM2_BOUNDED_ELEM_GET_COUNT_OFF, count >>> 0);
  pokeU32(V5_ANM + ANM2_BOUNDED_ELEM_GET_BASE_OFF, base >>> 0);
}

function runBoundedElemDiff(label, { count = 4, base = 0x1000, index = 0 }) {
  seedBoundedElem({ count, base });
  wasm.isaac_anm2_bounded_elem_get_plan(V5_ANM, index, PLAN_BOUNDED_ELEM);
  const js = numify(anm2BoundedElemGetPlan(shadow, { anm2Addr: V5_ANM, index }));
  assertStructEqual(readBoundedElemPlan(PLAN_BOUNDED_ELEM), js, label + " plan");
  return js;
}

test("v36 bounded element getter fixed edges (in-range/neg/overflow)", () => {
  eq(ANM2_BOUNDED_ELEM_GET_VA, 0x0040b23a);
  eq(ANM2_BOUNDED_ELEM_GET_END_VA, 0x0040b2e8);
  eq(ANM2_BOUNDED_ELEM_GET_LOG_VA, 0x00a112c0);
  eq(ANM2_BOUNDED_ELEM_GET_LOG_LEVEL, 0x10);
  eq(ANM2_BOUNDED_ELEM_GET_BASE_OFF, 0x7c);
  eq(ANM2_BOUNDED_ELEM_GET_COUNT_OFF, 0x80);
  eq(ANM2_BOUNDED_ELEM_GET_STRIDE, 0xa0);

  /* in-range index 2 -> base + 2*0xa0. */
  const hit = runBoundedElemDiff("v36-hit", { count: 4, base: 0x1000, index: 2 });
  eq(hit.inRange, 1);
  eq(hit.elem, 0x1000 + 2 * 0xa0, "base + index*0xa0");
  eq(hit.logNeeded, 0);
  eq(hit.pureComplete, 1);

  /* index 0 -> base. */
  const zero = runBoundedElemDiff("v36-zero", { count: 4, base: 0x1000, index: 0 });
  eq(zero.elem, 0x1000);
  eq(zero.inRange, 1);

  /* negative index -> range log host edge. */
  const neg = runBoundedElemDiff("v36-neg", { count: 4, base: 0x1000, index: -1 });
  eq(neg.inRange, 0);
  eq(neg.logNeeded, 1);
  eq(neg.hostCallCount, 1);
  eq(neg.pureComplete, 0);

  /* index == count -> out of range (jge). */
  const eqc = runBoundedElemDiff("v36-eqcount", { count: 4, base: 0x1000, index: 4 });
  assert.ok(eqc.inRange === 0, "index == count out of range");
  assert.ok(eqc.logNeeded === 1);

  /* index > count -> out of range. */
  const big = runBoundedElemDiff("v36-big", { count: 4, base: 0x1000, index: 9 });
  assert.ok(big.inRange === 0);
  assert.ok(big.logNeeded === 1);

  /* count signed-negative: 0x80000000 as count; index 0 -> in range (0 < INT_MIN? no,
     signed: 0 >= INT_MIN -> in range). */
  /* count INT_MIN (0x80000000): signed index 0 >= INT_MIN -> jge taken
     -> OUT of range -> log. */
  const negCount = runBoundedElemDiff("v36-negcount", { count: 0x80000000, base: 0x1000, index: 0 });
  assert.ok(negCount.inRange === 0, "signed compare: 0 >= INT_MIN takes jge");
  assert.ok(negCount.logNeeded === 1);
  COUNT.cases += 6;
});

