/* ================== v37: 0x0040b44a layer-array name->index ============== */

const PLAN_LAYER_NAME = V5_BASE + 0x1e30; /* 12 x 4 = 48 bytes */
const LAYER_NAME_OFF = {
  entered: 0, count: 4, base: 8, foundIndex: 12, elem: 16, result: 20,
  logNeeded: 24, logVa: 28, logLevel: 32, logStrVa: 36, hostCallCount: 40,
  pureComplete: 44,
};

const LNBASE = V5_BASE + 0x7000;        /* layer array base (count/stride) */
const LN_EL1 = V5_BASE + 0x8000;        /* slot-1 element (SSO name) */
const LN_EL2 = V5_BASE + 0x9000;        /* slot-2 element (heap name) */
const LN_HEAP = V5_BASE + 0xa000;       /* heap-backed long name */
const LN_NAMES = V5_BASE + 0xb000;      /* probe name strings */

function readLayerNamePlan(base) {
  return readPlanFields(base, LAYER_NAME_OFF, {
    entered: "i", count: "i", base: "u", foundIndex: "i", elem: "u",
    result: "u", logNeeded: "i", logVa: "u", logLevel: "i", logStrVa: "u",
    hostCallCount: "i", pureComplete: "i",
  });
}

function seedLayerArray() {
  pokeU32(V5_ANM + ANM2_LAYER_NAME_INDEX_COUNT_OFF, 3);
  pokeU32(V5_ANM + ANM2_LAYER_NAME_INDEX_BASE_OFF, LNBASE);
  pokeU32(LNBASE, 0);                                   /* slot 0: null */
  pokeU32(LNBASE + ANM2_LAYER_NAME_INDEX_STRIDE, LN_EL1);
  pokeU32(LNBASE + 2 * ANM2_LAYER_NAME_INDEX_STRIDE, LN_EL2);
  pokeCString(LN_EL1 + ANM2_LAYER_NAME_INDEX_NAME_OFF, 'aloe');
  pokeU32(LN_EL1 + ANM2_LAYER_NAME_INDEX_NAME_OFF + 0x14, 0);
  pokeU32(LN_EL2 + ANM2_LAYER_NAME_INDEX_NAME_OFF, LN_HEAP);
  pokeU32(LN_EL2 + ANM2_LAYER_NAME_INDEX_NAME_OFF + 0x10, 40);
  pokeU32(LN_EL2 + ANM2_LAYER_NAME_INDEX_NAME_OFF + 0x14, 0x40);
  pokeCString(LN_HEAP, 'a-very-long-layer-name-string-over-16-bytes');
  /* slot 3: cap EXACTLY 0x10 -> PE jb NOT taken -> heap path. */
  const LN_EL3 = V5_BASE + 0x9c00;
  pokeU32(V5_ANM + ANM2_LAYER_NAME_INDEX_COUNT_OFF, 4);
  pokeU32(LNBASE + 3 * ANM2_LAYER_NAME_INDEX_STRIDE, LN_EL3);
  pokeU32(LN_EL3 + ANM2_LAYER_NAME_INDEX_NAME_OFF, LN_HEAP + 0x40);
  pokeU32(LN_EL3 + ANM2_LAYER_NAME_INDEX_NAME_OFF + 0x14, 0x10);
  pokeCString(LN_HEAP + 0x40, 'cap-exactly-0x10!');
  pokeCString(LN_NAMES, 'aloe');
  pokeCString(LN_NAMES + 0x40, 'a-very-long-layer-name-string-over-16-bytes');
  pokeCString(LN_NAMES + 0x80, 'not-there');
}

function runLayerNameDiff(label, { nameAddr = LN_NAMES } = {}) {
  seedLayerArray();
  wasm.isaac_anm2_layer_name_index_plan(V5_ANM, nameAddr, PLAN_LAYER_NAME);
  const js = numify(anm2LayerNameIndexPlan(shadow, { anm2Addr: V5_ANM, nameAddr }));
  assertStructEqual(readLayerNamePlan(PLAN_LAYER_NAME), js, label + " plan");
  return js;
}

test("v37 layer-array name->index fixed edges (match/skip/miss/count0)", () => {
  eq(ANM2_LAYER_NAME_INDEX_VA, 0x0040b44a);
  eq(ANM2_LAYER_NAME_INDEX_END_VA, 0x0040b4ab);
  eq(ANM2_LAYER_NAME_INDEX_BASE_OFF, 0x7c);
  eq(ANM2_LAYER_NAME_INDEX_COUNT_OFF, 0x80);
  eq(ANM2_LAYER_NAME_INDEX_STRIDE, 0xa0);
  eq(ANM2_LAYER_NAME_INDEX_NAME_OFF, 0x08);
  eq(ANM2_LAYER_NAME_INDEX_SSO_CAP_OFF, 0x1c);
  eq(ANM2_LAYER_NAME_INDEX_SSO_CAP, 0x10);

  /* slot 0 null skip, slot 1 'aloe' match -> LNBASE + 1*0xa0. */
  const hit = runLayerNameDiff("v37-hit");
  eq(hit.foundIndex, 1);
  eq(hit.elem, LNBASE + 1 * ANM2_LAYER_NAME_INDEX_STRIDE, "base + index*0xa0");
  eq(hit.result, LNBASE + 1 * ANM2_LAYER_NAME_INDEX_STRIDE);
  eq(hit.pureComplete, 1);

  /* long heap-backed name match (slot 2). */
  const heap = runLayerNameDiff("v37-heap", { nameAddr: LN_NAMES + 0x40 });
  eq(heap.foundIndex, 2);
  eq(heap.elem, LNBASE + 2 * ANM2_LAYER_NAME_INDEX_STRIDE);

  /* miss -> 0, foundIndex stays -1. */
  const miss = runLayerNameDiff("v37-miss", { nameAddr: LN_NAMES + 0x80 });
  eq(miss.foundIndex, -1);
  eq(miss.result, 0);
  eq(miss.pureComplete, 1);

  /* cap == 0x10 element: heap path (jb strict <). */
  pokeCString(LN_NAMES + 0xc0, 'cap-exactly-0x10!');
  const cap10 = runLayerNameDiff("v37-cap10", { nameAddr: LN_NAMES + 0xc0 });
  eq(cap10.foundIndex, 3);
  eq(cap10.elem, LNBASE + 3 * ANM2_LAYER_NAME_INDEX_STRIDE);

  /* count == 0 -> 0. */
  /* source cap EXACTLY 0x10 -> heap path (`>=`); a `>` mutant
     reads inline bytes and misses. */
  const cap10s = runSlotEqDiff("v38-cap10", "mint");
  eq(cap10s.foundIndex, 4);
  eq(cap10s.slot, SQBASE + 4 * ANM2_LAYER_SLOT_SIZED_EQ_STRIDE);
  eq(cap10s.localHeapCount, 3); /* slots 2,3,4 heap before break at 4 */

  /* count UINT_MAX: PE `3b eb ; 72`-style unsigned jb loop must enter
     at i=0. A SIGNED loop would never enter. */
  seedSlotEq();
  pokeU32(SQBASE, SQ_EL1); /* slot 0 -> 'aloe' */
  pokeU32(V5_ANM + ANM2_LAYER_SLOT_SIZED_EQ_COUNT_OFF, 0xffffffff);
  seedSlotEqArg("aloe");
  wasm.isaac_anm2_layer_slot_sized_eq_plan(V5_ANM, SQ_ARG, PLAN_SLOT_EQ);
  const jsU38 = numify(anm2LayerSlotSizedEqPlan(shadow, { anm2Addr: V5_ANM, argAddr: SQ_ARG }));
  assertStructEqual(readSlotEqPlan(PLAN_SLOT_EQ), jsU38, "v38-uintmax plan");
  eq(jsU38.foundIndex, 0, "unsigned jb loop enters at i=0");

  /* count == 0 -> 0. */
  /* count 0xffffffff (UINT_MAX): PE `3b f3 ; 72` is UNSIGNED jb.
     Slot 0 match at i=0 -> found 0. A SIGNED loop would never enter. */
  seedLayerArray(); /* slot 0 is null; make it 'aloe' too */
  pokeU32(LNBASE, LN_EL1);
  pokeU32(V5_ANM + ANM2_LAYER_NAME_INDEX_COUNT_OFF, 0xffffffff);
  wasm.isaac_anm2_layer_name_index_plan(V5_ANM, LN_NAMES, PLAN_LAYER_NAME);
  const jsU = numify(anm2LayerNameIndexPlan(shadow, { anm2Addr: V5_ANM, nameAddr: LN_NAMES }));
  assertStructEqual(readLayerNamePlan(PLAN_LAYER_NAME), jsU, "v37-uintmax plan");
  eq(jsU.foundIndex, 0, "unsigned jb loop enters at i=0");

  /* count == 0 -> 0. */
  pokeU32(V5_ANM + ANM2_LAYER_NAME_INDEX_COUNT_OFF, 0);
  wasm.isaac_anm2_layer_name_index_plan(V5_ANM, LN_NAMES + 0x20, PLAN_LAYER_NAME);
  const js0 = numify(anm2LayerNameIndexPlan(shadow, { anm2Addr: V5_ANM, nameAddr: LN_NAMES + 0x80 }));
  assertStructEqual(readLayerNamePlan(PLAN_LAYER_NAME), js0, "v37-count0 plan");
  eq(js0.result, 0);
  eq(js0.entered, 1);

  COUNT.cases += 4;
});

