/* ================== v38: 0x0040b310 layer name->slot sized-eq ============ */

const PLAN_SLOT_EQ = V5_BASE + 0x1e60; /* 14 x 4 = 56 bytes */
const SLOT_EQ_OFF = {
  entered: 0, count: 4, base: 8, foundIndex: 12, slot: 16, result: 20,
  argSize: 24, localHeapCount: 28, logNeeded: 32, logVa: 36, logLevel: 40,
  logStrVa: 44, hostCallCount: 48, pureComplete: 52,
};

function readSlotEqPlan(base) {
  return readPlanFields(base, SLOT_EQ_OFF, {
    entered: "i", count: "i", base: "u", foundIndex: "i", slot: "u",
    result: "u", argSize: "i", localHeapCount: "i", logNeeded: "i",
    logVa: "u", logLevel: "i", logStrVa: "u", hostCallCount: "i",
    pureComplete: "i",
  });
}

/* Seed the layer array + an ARG std::string. Slots 0..N hold element
   pointers; element names are std::string at elem+8 (cap elem+0x1c). */
const SQBASE = V5_BASE + 0xc000;       /* layer array base */
const SQ_EL1 = V5_BASE + 0xd000;       /* slot-1 element (SSO name) */
const SQ_EL2 = V5_BASE + 0xe000;       /* slot-2 element (heap name) */
const SQ_EL3 = V5_BASE + 0xf000;       /* slot-3 element (heap long) */
const SQ_HEAP2 = V5_BASE + 0xfa00;     /* heap chars for slot 2 */
const SQ_HEAP3 = V5_BASE + 0xfb00;     /* heap chars for slot 3 */
const SQ_ARG = V5_BASE + 0xfc00;       /* arg std::string object */

const SQ_LONG = "a-long-name-that-exceeds-the-sso-buffer";

function seedSlotEq() {
  pokeU32(V5_ANM + ANM2_LAYER_SLOT_SIZED_EQ_COUNT_OFF, 5);
  pokeU32(V5_ANM + ANM2_LAYER_SLOT_SIZED_EQ_BASE_OFF, SQBASE);
  pokeU32(SQBASE, 0);                                 /* slot 0: null */
  pokeU32(SQBASE + ANM2_LAYER_SLOT_SIZED_EQ_STRIDE, SQ_EL1);
  pokeU32(SQBASE + 2 * ANM2_LAYER_SLOT_SIZED_EQ_STRIDE, SQ_EL2);
  pokeU32(SQBASE + 3 * ANM2_LAYER_SLOT_SIZED_EQ_STRIDE, SQ_EL3);
  /* slot 1: 'aloe' SSO. */
  pokeCString(SQ_EL1 + ANM2_LAYER_SLOT_SIZED_EQ_NAME_OFF, "aloe");
  pokeU32(SQ_EL1 + ANM2_LAYER_SLOT_SIZED_EQ_NAME_OFF + 0x10, 4);
  pokeU32(SQ_EL1 + ANM2_LAYER_SLOT_SIZED_EQ_NAME_OFF + 0x14, 0xf);
  /* slot 2: 'beta' heap. */
  pokeU32(SQ_EL2 + ANM2_LAYER_SLOT_SIZED_EQ_NAME_OFF, SQ_HEAP2);
  pokeU32(SQ_EL2 + ANM2_LAYER_SLOT_SIZED_EQ_NAME_OFF + 0x10, 4);
  pokeU32(SQ_EL2 + ANM2_LAYER_SLOT_SIZED_EQ_NAME_OFF + 0x14, 0x20);
  pokeCString(SQ_HEAP2, "beta");
  /* slot 3: long heap name. */
  pokeU32(SQ_EL3 + ANM2_LAYER_SLOT_SIZED_EQ_NAME_OFF, SQ_HEAP3);
  pokeU32(SQ_EL3 + ANM2_LAYER_SLOT_SIZED_EQ_NAME_OFF + 0x10, SQ_LONG.length);
  pokeU32(SQ_EL3 + ANM2_LAYER_SLOT_SIZED_EQ_NAME_OFF + 0x14, 0x40);
  pokeCString(SQ_HEAP3, SQ_LONG);
  /* slot 4: source cap EXACTLY 0x10 -> family boundary says HEAP (ptr at
     elem+8). A mutant using > instead of >= reads inline bytes -> miss. */
  const SQ_EL4 = V5_BASE + 0xfc80;
  const SQ_HEAP4 = V5_BASE + 0xfd80;
  pokeU32(SQBASE + 4 * ANM2_LAYER_SLOT_SIZED_EQ_STRIDE, SQ_EL4);
  pokeU32(SQ_EL4 + ANM2_LAYER_SLOT_SIZED_EQ_NAME_OFF, SQ_HEAP4);
  pokeU32(SQ_EL4 + ANM2_LAYER_SLOT_SIZED_EQ_NAME_OFF + 0x10, 4);
  pokeU32(SQ_EL4 + ANM2_LAYER_SLOT_SIZED_EQ_NAME_OFF + 0x14, 0x10);
  pokeCString(SQ_HEAP4, "mint");
}

/* arg = std::string at SQ_ARG with the given content (SSO when short). */
function seedSlotEqArg(text, { heap = false } = {}) {
  if (heap || text.length >= 0x10) {
    pokeU32(SQ_ARG, V5_BASE + 0xfd00);
    pokeU32(SQ_ARG + 0x10, text.length);
    pokeU32(SQ_ARG + 0x14, 0x40);
    pokeCString(V5_BASE + 0xfd00, text);
  } else {
    pokeCString(SQ_ARG, text);
    pokeU32(SQ_ARG + 0x10, text.length);
    pokeU32(SQ_ARG + 0x14, 0xf);
  }
}

function runSlotEqDiff(label, text, { heap = false } = {}) {
  seedSlotEq();
  seedSlotEqArg(text, { heap });
  wasm.isaac_anm2_layer_slot_sized_eq_plan(V5_ANM, SQ_ARG, PLAN_SLOT_EQ);
  const js = numify(anm2LayerSlotSizedEqPlan(shadow, { anm2Addr: V5_ANM, argAddr: SQ_ARG }));
  assertStructEqual(readSlotEqPlan(PLAN_SLOT_EQ), js, label + " plan");
  return js;
}

test("v38 layer name->slot sized-eq fixed edges (hit/size-mismatch/empty/count0)", () => {
  eq(ANM2_LAYER_SLOT_SIZED_EQ_VA, 0x0040b310);
  eq(ANM2_LAYER_SLOT_SIZED_EQ_END_VA, 0x0040b421);
  eq(ANM2_LAYER_SLOT_SIZED_EQ_BASE_OFF, 0x7c);
  eq(ANM2_LAYER_SLOT_SIZED_EQ_COUNT_OFF, 0x80);
  eq(ANM2_LAYER_SLOT_SIZED_EQ_STRIDE, 0xa0);
  eq(ANM2_LAYER_SLOT_SIZED_EQ_NAME_OFF, 0x08);
  eq(ANM2_LAYER_SLOT_SIZED_EQ_SSO_CAP_OFF, 0x1c);
  eq(ANM2_LAYER_SLOT_SIZED_EQ_SSO_CAP, 0x10);
  eq(ANM2_LAYER_SLOT_SIZED_EQ_EQ_HELPER_VA, 0x0040cae0);
  eq(ANM2_LAYER_SLOT_SIZED_EQ_FREE_VA, 0x00aef15c);
  eq(ANM2_LAYER_SLOT_SIZED_EQ_INVALID_PARAM_VA, 0x00b18894);

  /* 'aloe' (slot 1) hit via SSO name -> SLOT address. */
  const hit = runSlotEqDiff("v38-hit", "aloe");
  eq(hit.foundIndex, 1);
  eq(hit.slot, SQBASE + 1 * ANM2_LAYER_SLOT_SIZED_EQ_STRIDE, "slot address");
  eq(hit.result, SQBASE + 1 * ANM2_LAYER_SLOT_SIZED_EQ_STRIDE);
  eq(hit.argSize, 4);
  eq(hit.localHeapCount, 0); /* break at i=1; slots 2/3 unvisited */

  /* 'beta' (slot 2) hit via heap name. */
  const heap = runSlotEqDiff("v38-heap", "beta");
  eq(heap.foundIndex, 2);
  eq(heap.localHeapCount, 1); /* slot 2 heap; break there */

  /* long heap name in slot 3. */
  const longHit = runSlotEqDiff("v38-long", SQ_LONG, { heap: true });
  eq(longHit.foundIndex, 3);

  /* SIZE mismatch: 'alo' (3) vs 'aloe' (4) -> NO match. */
  const sizeMiss = runSlotEqDiff("v38-sizemiss", "alo");
  eq(sizeMiss.foundIndex, -1);
  eq(sizeMiss.result, 0);
  eq(sizeMiss.localHeapCount, 3); /* full scan sees slots 2,3,4 heap */

  /* same size, different bytes: 'abcd' vs 'aloe' -> NO match. */
  const byteMiss = runSlotEqDiff("v38-bytemiss", "abcd");
  eq(byteMiss.foundIndex, -1);

  /* empty arg matches the first NULL slot (empty string). */
  const empty = runSlotEqDiff("v38-empty", "");
  eq(empty.foundIndex, 0);
  eq(empty.slot, SQBASE, "null slot is empty string");

  /* empty arg with NO null slot -> miss. */
  seedSlotEq();
  pokeU32(SQBASE, SQ_EL1);
  seedSlotEqArg("");
  wasm.isaac_anm2_layer_slot_sized_eq_plan(V5_ANM, SQ_ARG, PLAN_SLOT_EQ);
  const jsE = numify(anm2LayerSlotSizedEqPlan(shadow, { anm2Addr: V5_ANM, argAddr: SQ_ARG }));
  assertStructEqual(readSlotEqPlan(PLAN_SLOT_EQ), jsE, "v38-empty-nonnull plan");
  eq(jsE.foundIndex, -1);

  /* count == 0 -> 0. */
  seedSlotEq();
  pokeU32(V5_ANM + ANM2_LAYER_SLOT_SIZED_EQ_COUNT_OFF, 0);
  seedSlotEqArg("aloe");
  wasm.isaac_anm2_layer_slot_sized_eq_plan(V5_ANM, SQ_ARG, PLAN_SLOT_EQ);
  const js0 = numify(anm2LayerSlotSizedEqPlan(shadow, { anm2Addr: V5_ANM, argAddr: SQ_ARG }));
  assertStructEqual(readSlotEqPlan(PLAN_SLOT_EQ), js0, "v38-count0 plan");
  eq(js0.entered, 1);
  eq(js0.result, 0);
  eq(js0.foundIndex, -1);

  COUNT.cases += 6;
});

test("v38 bytesEqual primitive semantics", () => {
  pokeCString(V5_BASE + 0xfe00, "abcd");
  pokeCString(V5_BASE + 0xfe10, "abce");
  pokeCString(V5_BASE + 0xfe20, "abcd");
  ok(bytesEqual(shadow, V5_BASE + 0xfe00, V5_BASE + 0xfe20, 4), "equal bytes");
  ok(!bytesEqual(shadow, V5_BASE + 0xfe00, V5_BASE + 0xfe10, 4), "differing bytes");
  ok(bytesEqual(shadow, V5_BASE + 0xfe00, V5_BASE + 0xfe10, 0), "zero length");
  COUNT.cases += 3;
});

