/* ================== v39: 0x0040b4d0 +0x84/+0x88 bounded getter =========== */

const PLAN_SUBARRAY = V5_BASE + 0x1e90; /* 13 x 4 = 52 bytes */
const SUBARRAY_OFF = {
  entered: 0, count: 4, base: 8, index: 12, result: 16, inRange: 20,
  logNeeded: 24, logVa: 28, logLevel: 32, logStrVa: 36, logNameAddr: 40,
  hostCallCount: 44, pureComplete: 48,
};

function readSubarrayPlan(base) {
  return readPlanFields(base, SUBARRAY_OFF, {
    entered: "i", count: "i", base: "u", index: "i", result: "u",
    inRange: "i", logNeeded: "i", logVa: "u", logLevel: "i",
    logStrVa: "u", logNameAddr: "u", hostCallCount: "i", pureComplete: "i",
  });
}

const SAB_BASE = V5_BASE + 0x10000; /* sub-array base (in scratch) */

function seedSubarray({ count = 4, base = SAB_BASE, nameCap = 0xf }) {
  pokeU32(V5_ANM + ANM2_SUBARRAY_GET_COUNT_OFF, count >>> 0);
  pokeU32(V5_ANM + ANM2_SUBARRAY_GET_BASE_OFF, base >>> 0);
  /* this-name SSO: chars inline at V5_ANM (already 'anm'); cap controls heap. */
  pokeU32(V5_ANM + ANM2_SUBARRAY_GET_NAME_CAP_OFF, nameCap >>> 0);
  pokeU32(V5_ANM, V5_BASE + 0x10100);      /* heap name ptr when cap >= 0x10 */
  pokeCString(V5_BASE + 0x10100, "anm-heap");
  return base;
}

function runSubarrayDiff(label, { count = 4, base = SAB_BASE, nameCap = 0xf, index = 0 }) {
  seedSubarray({ count, base, nameCap });
  wasm.isaac_anm2_subarray_get_plan(V5_ANM, index, PLAN_SUBARRAY);
  const js = numify(anm2SubarrayGetPlan(shadow, { anm2Addr: V5_ANM, index }));
  assertStructEqual(readSubarrayPlan(PLAN_SUBARRAY), js, label + " plan");
  return js;
}

test("v39 +0x84/+0x88 bounded getter fixed edges (hit/neg/overflow/count-signed)", () => {
  eq(ANM2_SUBARRAY_GET_VA, 0x0040b4d0);
  eq(ANM2_SUBARRAY_GET_END_VA, 0x0040b513);
  eq(ANM2_SUBARRAY_GET_BASE_OFF, 0x84);
  eq(ANM2_SUBARRAY_GET_COUNT_OFF, 0x88);
  eq(ANM2_SUBARRAY_GET_STRIDE, 0x0c);
  eq(ANM2_SUBARRAY_GET_LOG_LEVEL, 0x10);

  /* in-range index 2 -> base + 2*0xc; log not needed; SSO name logged addr. */
  const hit = runSubarrayDiff("v39-hit", { index: 2 });
  eq(hit.inRange, 1);
  eq(hit.result, SAB_BASE + 2 * 0xc, "base + index*0xc");
  eq(hit.logNeeded, 0);
  eq(hit.logNameAddr, V5_ANM, "SSO this-name inline");
  eq(hit.pureComplete, 1);

  /* index 0 -> base. */
  const zero = runSubarrayDiff("v39-zero", { index: 0 });
  eq(zero.result, SAB_BASE);
  eq(zero.inRange, 1);

  /* negative index -> log; result STILL computed (unconditional). */
  const neg = runSubarrayDiff("v39-neg", { index: -1 });
  eq(neg.inRange, 0);
  eq(neg.logNeeded, 1);
  eq(neg.hostCallCount, 1);
  eq(neg.pureComplete, 0);
  eq(neg.result, (SAB_BASE + (-1) * 0xc) >>> 0, "result unconditional");

  /* index == count -> out of range (jl). */
  const eqc = runSubarrayDiff("v39-eqcount", { index: 4 });
  assert.ok(eqc.inRange === 0, "index == count out of range");
  assert.ok(eqc.logNeeded === 1);

  /* index > count -> out of range. */
  const big = runSubarrayDiff("v39-big", { index: 9 });
  assert.ok(big.inRange === 0);
  assert.ok(big.logNeeded === 1);

  /* count INT_MIN (0x80000000): signed index 0 >= INT_MIN -> jl NOT taken
     -> out of range -> log (0 >= INT_MIN is true). */
  const negCount = runSubarrayDiff("v39-negcount", { count: 0x80000000, index: 0 });
  assert.ok(negCount.inRange === 0, "signed: 0 >= INT_MIN takes log path");
  assert.ok(negCount.logNeeded === 1);

  /* heap this-name (cap >= 0x10) -> logNameAddr is the heap ptr. */
  const heapName = runSubarrayDiff("v39-heapname", { nameCap: 0x20, index: -1 });
  eq(heapName.logNameAddr, V5_BASE + 0x10100, "heap this-name");

  COUNT.cases += 7;
});

