/* ================== v40: 0x0040b520 +0x84/+0x88 name->index ============== */

const PLAN_SUBARRAY_NI = V5_BASE + 0x1ec0; /* 12 x 4 = 48 bytes */
const SUBARRAY_NI_OFF = {
  entered: 0, count: 4, base: 8, foundIndex: 12, result: 16, nameAddr: 20,
  heapCount: 24, logNeeded: 28, logVa: 32, logLevel: 36, hostCallCount: 40,
  pureComplete: 44,
};

function readSubarrayNiPlan(base) {
  return readPlanFields(base, SUBARRAY_NI_OFF, {
    entered: "i", count: "i", base: "u", foundIndex: "i", result: "i",
    nameAddr: "u", heapCount: "i", logNeeded: "i", logVa: "u",
    logLevel: "i", hostCallCount: "i", pureComplete: "i",
  });
}

const NIBASE = V5_BASE + 0x9000; /* sub-array base */
const NI_EL1 = V5_BASE + 0xa000; /* element 1 (SSO name) */
const NI_EL2 = V5_BASE + 0xb000; /* element 2 (heap name) */
const NI_EL3 = V5_BASE + 0xc000; /* element 3 (SSO long-ish) */
const NI_HEAP2 = V5_BASE + 0x10200; /* heap chars for element 2 */
const NI_NAMES = V5_BASE + 0x11000; /* probe C-strings */

function seedSubarrayNi() {
  pokeU32(V5_ANM + ANM2_SUBARRAY_NAME_INDEX_COUNT_OFF, 3);
  pokeU32(V5_ANM + ANM2_SUBARRAY_NAME_INDEX_BASE_OFF, NIBASE);
  /* Elements are INLINE 24-byte structs at base+i*0x18 (name SSO at elem+0,
     cap elem+0x14) — NOT pointer slots (v37/v38 layer array differs). */
  /* element 0: SSO 'aloe'. */
  pokeCString(NIBASE, "aloe");
  pokeU32(NIBASE + ANM2_SUBARRAY_NAME_INDEX_SSO_CAP_OFF, 0xf);
  /* element 1: heap 'beta' (ptr at elem+0). */
  pokeU32(NIBASE + ANM2_SUBARRAY_NAME_INDEX_STRIDE, NI_HEAP2);
  pokeU32(NIBASE + ANM2_SUBARRAY_NAME_INDEX_STRIDE + ANM2_SUBARRAY_NAME_INDEX_SSO_CAP_OFF, 0x20);
  pokeCString(NI_HEAP2, "beta");
  /* element 2: SSO 'gamma'. */
  pokeCString(NIBASE + 2 * ANM2_SUBARRAY_NAME_INDEX_STRIDE, "gamma");
  pokeU32(NIBASE + 2 * ANM2_SUBARRAY_NAME_INDEX_STRIDE + ANM2_SUBARRAY_NAME_INDEX_SSO_CAP_OFF, 0xf);
  /* probes. */
  pokeCString(NI_NAMES, "aloe");
  pokeCString(NI_NAMES + 0x40, "beta");
  pokeCString(NI_NAMES + 0x80, "gamma");
  pokeCString(NI_NAMES + 0xc0, "not-there");
  pokeCString(NI_NAMES + 0x100, "");
}

function runSubarrayNiDiff(label, nameAddr) {
  seedSubarrayNi();
  wasm.isaac_anm2_subarray_name_index_plan(V5_ANM, nameAddr, PLAN_SUBARRAY_NI);
  const js = numify(anm2SubarrayNameIndexPlan(shadow, { anm2Addr: V5_ANM, nameAddr }));
  assertStructEqual(readSubarrayNiPlan(PLAN_SUBARRAY_NI), js, label + " plan");
  return js;
}

test("v40 +0x84/+0x88 name->index fixed edges (hit/miss/count0/signed)", () => {
  eq(ANM2_SUBARRAY_NAME_INDEX_VA, 0x0040b520);
  eq(ANM2_SUBARRAY_NAME_INDEX_END_VA, 0x0040b589);
  eq(ANM2_SUBARRAY_NAME_INDEX_BASE_OFF, 0x84);
  eq(ANM2_SUBARRAY_NAME_INDEX_COUNT_OFF, 0x88);
  eq(ANM2_SUBARRAY_NAME_INDEX_STRIDE, 0x18);
  eq(ANM2_SUBARRAY_NAME_INDEX_SSO_CAP_OFF, 0x14);
  eq(ANM2_SUBARRAY_NAME_INDEX_SSO_CAP, 0x10);

  /* SSO name hit -> index 0. */
  const hit = runSubarrayNiDiff("v40-hit", NI_NAMES);
  eq(hit.foundIndex, 0);
  eq(hit.result, 0);
  eq(hit.heapCount, 0);
  eq(hit.pureComplete, 1);

  /* heap name hit -> index 1. */
  const heap = runSubarrayNiDiff("v40-heap", NI_NAMES + 0x40);
  eq(heap.foundIndex, 1);
  eq(heap.heapCount, 1, "element 2 heap-backed, scanned before break");

  /* miss -> -1 (NOT 0). */
  const miss = runSubarrayNiDiff("v40-miss", NI_NAMES + 0xc0);
  eq(miss.foundIndex, -1);
  eq(miss.result, -1);

  /* empty arg -> miss (no empty names). */
  const empty = runSubarrayNiDiff("v40-empty", NI_NAMES + 0x100);
  eq(empty.foundIndex, -1);

  /* count == 0 -> -1 (jle). */
  seedSubarrayNi();
  pokeU32(V5_ANM + ANM2_SUBARRAY_NAME_INDEX_COUNT_OFF, 0);
  wasm.isaac_anm2_subarray_name_index_plan(V5_ANM, NI_NAMES, PLAN_SUBARRAY_NI);
  const js0 = numify(anm2SubarrayNameIndexPlan(shadow, { anm2Addr: V5_ANM, nameAddr: NI_NAMES }));
  assertStructEqual(readSubarrayNiPlan(PLAN_SUBARRAY_NI), js0, "v40-count0 plan");
  eq(js0.entered, 1);
  eq(js0.result, -1);

  /* count NEGATIVE (0x80000000) -> jle -> -1. */
  seedSubarrayNi();
  pokeU32(V5_ANM + ANM2_SUBARRAY_NAME_INDEX_COUNT_OFF, 0x80000000);
  wasm.isaac_anm2_subarray_name_index_plan(V5_ANM, NI_NAMES, PLAN_SUBARRAY_NI);
  const jsN = numify(anm2SubarrayNameIndexPlan(shadow, { anm2Addr: V5_ANM, nameAddr: NI_NAMES }));
  assertStructEqual(readSubarrayNiPlan(PLAN_SUBARRAY_NI), jsN, "v40-negcount plan");
  eq(jsN.result, -1, "signed count INT_MIN takes jle");

  COUNT.cases += 6;
});

