/* ================== v41: 0x0040bbf0 0x6c-byte struct copy ================ */

const PLAN_COPY6C = V5_BASE + 0x1f00; /* 9 x 4 = 36 bytes */
const COPY6C_OFF = {
  entered: 0, dstAddr: 4, srcAddr: 8, byteCount: 12, logNeeded: 16,
  logVa: 20, logLevel: 24, hostCallCount: 28, pureComplete: 32,
};

function readCopy6cPlan(base) {
  return readPlanFields(base, COPY6C_OFF, {
    entered: "i", dstAddr: "u", srcAddr: "u", byteCount: "i",
    logNeeded: "i", logVa: "u", logLevel: "i", hostCallCount: "i",
    pureComplete: "i",
  });
}

const CPY_SRC = V5_BASE + 0x11500; /\* 0x6c-byte struct source (in scratch) */
const CPY_DST = V5_BASE + 0x11600; /\* 0x6c-byte struct dest */

function seedCopySrc() {
  /* byte-distinct pattern per field so any offset/width defect diverges. */
  for (let i = 0; i < ANM2_STRUCT_COPY_6C_SIZE; i++) {
    poke(CPY_SRC + i, [(i * 7 + 3) & 0xff]);
  }
}

test("v41 0x6c-byte struct copy fixed edges (byte-exact/order)", () => {
  eq(ANM2_STRUCT_COPY_6C_VA, 0x0040bbf0);
  eq(ANM2_STRUCT_COPY_6C_END_VA, 0x0040bc3b);
  eq(ANM2_STRUCT_COPY_6C_SIZE, 0x6c);

  seedCopySrc();
  poke(CPY_DST, new Array(ANM2_STRUCT_COPY_6C_SIZE).fill(0xaa));
  wasm.isaac_anm2_struct_copy_6c(CPY_DST, CPY_SRC, PLAN_COPY6C);
  /* plan fields (wasm writes the plan itself). */
  const w = readCopy6cPlan(PLAN_COPY6C);
  eq(w.entered, 1);
  eq(w.dstAddr, CPY_DST);
  eq(w.srcAddr, CPY_SRC);
  eq(w.byteCount, 0x6c);
  eq(w.logNeeded, 0);
  eq(w.pureComplete, 1);
  /* js oracle plan agrees. */
  const js = numify(
    anm2StructCopy6cPlan(shadow, { dstAddr: CPY_DST, srcAddr: CPY_SRC })
  );
  assertStructEqual(w, js, "v41-copy plan");
  /* THE behavioral assertion: every FIELD byte is copied (PE field ranges:
     dword pairs 0x00..0x28, byte 0x2c, movups 0x30..0x4f, movq 0x50..0x57,
     dwords 0x58/0x5c, byte 0x60, dwords 0x64/0x68). */
  const fieldRanges = [[0x00, 0x2c], [0x2c, 0x2d], [0x30, 0x50], [0x50, 0x58],
                       [0x58, 0x5c], [0x5c, 0x5d], [0x60, 0x61],
                       [0x64, 0x65], [0x68, 0x6c]];
  for (const [lo, hi] of fieldRanges) {
    for (let i = lo; i < hi; i++) {
      eq(wmem[CPY_DST + i], wmem[CPY_SRC + i], "dst field[" + i + "] == src[" + i + "]");
    }
  }
  /* PADDING is NOT written by the PE (0x2d..0x2f, 0x61..0x63): stays 0xaa. */
  for (const i of [0x2d, 0x2e, 0x2f, 0x61, 0x62, 0x63]) {
    eq(wmem[CPY_DST + i], 0xaa, "padding dst[" + i + "] preserved");
  }

  /* null src -> no op. */
  wasm.isaac_anm2_struct_copy_6c(CPY_DST, 0, PLAN_COPY6C);
  const w0 = readCopy6cPlan(PLAN_COPY6C);
  eq(w0.entered, 0);
  eq(w0.pureComplete, 1);

  COUNT.cases += 10;
});

