/* ================== v43: 0x0040c340 SSO C-string ctor ==================== */

const PLAN_CSTR_CTOR = V5_BASE + 0x1f80; /* 11 x 4 = 44 bytes */
const CSTR_CTOR_OFF = {
  entered: 0, thisAddr: 4, cstrAddr: 8, strLen: 12, hostNeeded: 16,
  hostVa: 20, logNeeded: 24, logVa: 28, logLevel: 32, hostCallCount: 36,
  pureComplete: 40,
};

function readCstrCtorPlan(base) {
  return readPlanFields(base, CSTR_CTOR_OFF, {
    entered: "i", thisAddr: "u", cstrAddr: "u", strLen: "i",
    hostNeeded: "i", hostVa: "u", logNeeded: "i", logVa: "u",
    logLevel: "i", hostCallCount: "i", pureComplete: "i",
  });
}

const CTC_IFACE = V5_BASE + 0x11c00;  /* this string (in scratch) */
const CTC_STR = V5_BASE + 0x11d00;    /* C-string input */

function seedCstr(text) {
  pokeCString(CTC_STR, text);
}

function runCstrCtorDiff(label, text) {
  seedCstr(text);
  wasm.isaac_anm2_sso_cstr_ctor_plan(CTC_IFACE, CTC_STR, PLAN_CSTR_CTOR);
  const js = numify(
    anm2SsoCstrCtorPlan(shadow, { anm2Addr: CTC_IFACE, cstrAddr: CTC_STR })
  );
  assertStructEqual(readCstrCtorPlan(PLAN_CSTR_CTOR), js, label + " plan");
  return js;
}

test("v43 SSO C-string ctor fixed edges (strlen/empty/long/host)", () => {
  eq(ANM2_SSO_CSTR_CTOR_VA, 0x0040c340);
  eq(ANM2_SSO_CSTR_CTOR_END_VA, 0x0040c37d);
  eq(ANM2_SSO_CSTR_CTOR_HOST_VA, 0x0040ccd0);
  eq(ANM2_SSO_CSTR_CTOR_SSO_CAP, 0x0f);

  /* normal string: strlen is the pure decode. */
  const hit = runCstrCtorDiff("v43-hit", "hello");
  eq(hit.entered, 1);
  eq(hit.strLen, 5);
  eq(hit.hostNeeded, 1);
  eq(hit.hostVa, ANM2_SSO_CSTR_CTOR_HOST_VA);
  eq(hit.hostCallCount, 1);
  eq(hit.pureComplete, 0, "host assign required");

  /* empty string: strlen 0. */
  const empty = runCstrCtorDiff("v43-empty", "");
  eq(empty.strLen, 0);

  /* longer than SSO: strlen still pure (assign decides heap). */
  const long_ = runCstrCtorDiff("v43-long", "this-string-is-way-past-the-sso-limit");
  eq(long_.strLen, "this-string-is-way-past-the-sso-limit".length);

  /* NUL-terminated at the boundary: probe char 63. */
  const edge = runCstrCtorDiff("v43-edge", "x".repeat(63));
  eq(edge.strLen, 63);

  COUNT.cases += 6;
});

