/* ================== v44: 0x0040d0e0 float ctor (7 float inputs) ===========
   v62-corrected: body 0x0040d0e0..0x0040d13a (`ret 0x10` @ 0x40d138);
   seven distinct float sources (a0/a1/a2/a6 stack + xmm1/xmm2/xmm3). */

const PLAN_FVC = V5_BASE + 0x1fc0; /* 14 x 4 = 56 bytes */
const FVC_OFF = {
  entered: 0, thisAddr: 4, a0: 8, a1: 12, a2: 16, x1: 20, x2: 24, x3: 28,
  a6: 32, logNeeded: 36, logVa: 40, logLevel: 44, hostCallCount: 48,
  pureComplete: 52,
};

function readFvcPlan(base) {
  return readPlanFields(base, FVC_OFF, {
    entered: "i", thisAddr: "u", a0: "u", a1: "u", a2: "u", x1: "u",
    x2: "u", x3: "u", a6: "u",
    logNeeded: "i", logVa: "u", logLevel: "i", hostCallCount: "i",
    pureComplete: "i",
  });
}

const FVC_IFACE = V5_BASE + 0x18000;   /* this float-vector */

function f32v(x) {
  const dv = new DataView(new ArrayBuffer(4));
  dv.setFloat32(0, Math.fround(x), true);
  return dv.getUint32(0, true);
}

test("v44 float ctor fixed edges (bit-exact/pure, v62-corrected)", () => {
  eq(ANM2_FLOATVEC_CTOR_VA, 0x0040d0e0);
  eq(ANM2_FLOATVEC_CTOR_END_VA, 0x0040d13a);
  eq(ANM2_FLOATVEC_CTOR_RET_BYTES, 0x10);

  /* distinctive float bits incl. negative; the four register/stack
     tail inputs all differ so a replication mutant cannot pass. */
  wasm.isaac_anm2_floatvec_ctor(
    FVC_IFACE, 1.5, -2.25, 0.0, 3.0, -4.5, 5.25, -6.75, PLAN_FVC);
  const w = readFvcPlan(PLAN_FVC);
  eq(w.entered, 1);
  eq(w.thisAddr, FVC_IFACE);
  eq(w.a0, f32v(1.5));
  eq(w.a1, f32v(-2.25));
  eq(w.a2, f32v(0.0));
  eq(w.x1, f32v(3.0));
  eq(w.x2, f32v(-4.5));
  eq(w.x3, f32v(5.25));
  eq(w.a6, f32v(-6.75));
  eq(w.logNeeded, 0);
  eq(w.pureComplete, 1);
  /* JS oracle agrees. */
  const js = numify(
    anm2FloatVecCtorPlan(shadow, {
      anm2Addr: FVC_IFACE,
      args: [1.5, -2.25, 0.0, 3.0, -4.5, 5.25, -6.75],
    })
  );
  assertStructEqual(w, js, "v44-fvc plan");

  /* THE behavioral assertion: the PE store layout is byte-exact. */
  const u32At = (a) => new DataView(wmem.buffer).getUint32(a, true);
  eq(u32At(FVC_IFACE + 0x10), 0, "zero dword 0x10");
  eq(u32At(FVC_IFACE + 0x14), 0, "zero dword 0x14");
  eq(u32At(FVC_IFACE + 0x18), 0, "zero dword 0x18");
  eq(u32At(FVC_IFACE + 0x1c), 0, "zero dword 0x1c");
  eq(u32At(FVC_IFACE + 0x0c), f32v(1.5), "a0 -> +0x0c");
  eq(u32At(FVC_IFACE + 0x20), f32v(-2.25), "a1 -> +0x20");
  eq(u32At(FVC_IFACE + 0x24), f32v(0.0), "a2 -> +0x24");
  eq(u32At(FVC_IFACE + 0x00), f32v(3.0), "xmm1 -> +0x00 (0x40d124)");
  eq(u32At(FVC_IFACE + 0x04), f32v(-4.5), "xmm2 -> +0x04 (0x40d128)");
  eq(u32At(FVC_IFACE + 0x08), f32v(5.25), "xmm3 -> +0x08 (0x40d12d)");
  eq(u32At(FVC_IFACE + 0x28), f32v(-6.75), "[ebp+0x14] -> +0x28 (0x40d132)");

  /* NaN arg: bits pass through untouched. */
  const nanBits = f32v(NaN);
  wasm.isaac_anm2_floatvec_ctor(FVC_IFACE, NaN, 0, 0, 0, 0, 0, 0, PLAN_FVC);
  eq(u32At(FVC_IFACE + 0x0c), nanBits, "NaN bits stored verbatim");
  const jsN = numify(
    anm2FloatVecCtorPlan(shadow, {
      anm2Addr: FVC_IFACE, args: [NaN, 0, 0, 0, 0, 0, 0],
    })
  );
  eq(jsN.a0, nanBits);

  COUNT.cases += 18;
});

test("v44 float ctor randomized differential (wasm vs oracle)", () => {
  const rng = makeRng(0x40d0e0);
  for (let t = 0; t < 120; ++t) {          /* <= 500 draws (coordinator) */
    const args = [
      (rng.u32() / 0xffffffff) * 200.0 - 100.0,
      (rng.u32() / 0xffffffff) * 200.0 - 100.0,
      (rng.u32() / 0xffffffff) * 200.0 - 100.0,
      (rng.u32() / 0xffffffff) * 200.0 - 100.0,
      (rng.u32() / 0xffffffff) * 200.0 - 100.0,
      (rng.u32() / 0xffffffff) * 200.0 - 100.0,
      (rng.u32() / 0xffffffff) * 200.0 - 100.0,
    ];
    wasm.isaac_anm2_floatvec_ctor(FVC_IFACE, ...args, PLAN_FVC);
    const w = readFvcPlan(PLAN_FVC);
    const js = numify(anm2FloatVecCtorPlan(shadow, {
      anm2Addr: FVC_IFACE, args,
    }));
    assertStructEqual(w, js, `fvc t${t}`);
    const u32At = (a) => new DataView(wmem.buffer).getUint32(a, true);
    eq(u32At(FVC_IFACE + 0x00), w.x1 >>> 0, `x1 store t${t}`);
    eq(u32At(FVC_IFACE + 0x04), w.x2 >>> 0, `x2 store t${t}`);
    eq(u32At(FVC_IFACE + 0x08), w.x3 >>> 0, `x3 store t${t}`);
    eq(u32At(FVC_IFACE + 0x28), w.a6 >>> 0, `a6 store t${t}`);
  }
  COUNT.cases += 120;
});

