test("v49 was-event-triggered SSO vs event-trigger twin delta (call target)", () => {
  /* The two wrappers are byte-identical except the HOST callee: 0x0040b000
     -> 0x0040add0 (frame-opaque +0x18 twin), 0x0040b060 -> 0x0040ae70
     (ANM2 +0x1c twin). Same plan shape, different call contract. */
  eq(ANM2_EVENT_TRIGGER_SSO_CALL_VA, 0x0040add0);
  eq(ANM2_WAS_EVENT_TRIGGERED_SSO_CALL_VA, 0x0040ae70);
  eq(ANM2_EVENT_TRIGGER_SSO_VA + 0x60, ANM2_WAS_EVENT_TRIGGERED_SSO_VA);
  eq(ANM2_EVENT_TRIGGER_SSO_END_VA + 0x60, ANM2_WAS_EVENT_TRIGGERED_SSO_END_VA);
  COUNT.cases += 2;
});

/* ================== v49 band-b: 0x0040b030 const-char twin =============== */

/* 386 direct .text e8 callers (rel32 census). The const-char twin pushes
   [ebp+8] UNCHANGED — charsAddr MUST be the raw arg verbatim even when
   [name+0x14] (the cap the SSO twin reads) is >= 0x10. Gate [this+0x34]
   FULL-dword; closed -> pure bool 0; open -> HOST 0x40add0 on this+0x30.
   Oracle transcribed branch-by-branch from cpu-dump/0040b030.txt. */

const PLAN_EVENT_TRIGGER_CSTR = V5_BASE + 0x3200; /* 8 x 4 = 32 bytes */
const EVENT_TRIGGER_CSTR_OFF = {
  entered: 0, gate34: 4, charsAddr: 8, callVa: 12, recvOff: 16,
  result: 20, hostCallCount: 24, pureComplete: 28,
};

function readEventTriggerCstrPlan(base) {
  return readPlanFields(base, EVENT_TRIGGER_CSTR_OFF, {
    entered: "i", gate34: "i", charsAddr: "u", callVa: "u",
    recvOff: "u", result: "i", hostCallCount: "i", pureComplete: "i",
  });
}

const ETC_ANM2 = V5_BASE + 0x3300; /* anm2 image (gate read at +0x34) */
const ETC_NAME = V5_BASE + 0x3400; /* RAW const char* target; bytes laid out
                                      so [name+0x14] reads a heap-like cap —
                                      the twin contrast must keep it verbatim */

function seedEtcWorld({ gate34, rawDwordAt14 = 0x14 }) {
  pokeU32(ETC_ANM2 + ANM2_EVENT_TRIGGER_CSTR_GATE_OFF, gate34 >>> 0);
  /* A raw C string; +0x14 deliberately holds a >= 0x10 value so an SSO
     decode would dereference ETC_NAME as a heap pointer. The const-char
     twin must NOT touch it. */
  pokeCString(ETC_NAME, "Cursor");
  pokeU32(ETC_NAME + 0x14, rawDwordAt14 >>> 0);
}

function runEventTriggerCstrDiff(label, o = {}) {
  const { gate34 = 0, rawDwordAt14 = 0x14 } = o;
  seedEtcWorld({ gate34, rawDwordAt14 });
  wasm.isaac_anm2_event_trigger_cstr_plan(ETC_ANM2, ETC_NAME, PLAN_EVENT_TRIGGER_CSTR);
  const js = numify(anm2EventTriggerCstrPlan(shadow, {
    anm2Addr: ETC_ANM2, nameAddr: ETC_NAME,
  }));
  assertStructEqual(readEventTriggerCstrPlan(PLAN_EVENT_TRIGGER_CSTR), js, label + " plan");
  return js;
}

test("v49 band-b event-trigger cstr fixed edges (gate full-word/wide, RAW passthrough)", () => {
  eq(ANM2_EVENT_TRIGGER_CSTR_VA, 0x0040b030);
  eq(ANM2_EVENT_TRIGGER_CSTR_END_VA, 0x0040b04e);
  eq(ANM2_EVENT_TRIGGER_CSTR_GATE_OFF, 0x34);
  eq(ANM2_EVENT_TRIGGER_CSTR_STATE_OFF, 0x30);
  eq(ANM2_EVENT_TRIGGER_CSTR_CALL_VA, 0x0040add0);
  eq(ANM2_EVENT_TRIGGER_CSTR_CALLSITE_COUNT, 386);
  eq(ANM2_EVENT_TRIGGER_SSO_VA + 0x30, ANM2_EVENT_TRIGGER_CSTR_VA);

  /* Gate closed -> pure bool 0, no host call; charsAddr is the RAW arg. */
  const closed = runEventTriggerCstrDiff("v49-etc-closed", { gate34: 0 });
  eq(closed.entered, 1);
  eq(closed.gate34, 0);
  eq(closed.charsAddr, ETC_NAME, "raw arg passthrough");
  eq(closed.callVa, ANM2_EVENT_TRIGGER_CSTR_CALL_VA);
  eq(closed.recvOff, ANM2_EVENT_TRIGGER_CSTR_STATE_OFF);
  eq(closed.result, 0);
  eq(closed.hostCallCount, 0);
  eq(closed.pureComplete, 1);

  /* Gate open -> one host call to the frame-opaque walk on this+0x30. */
  const open = runEventTriggerCstrDiff("v49-etc-open", { gate34: 1 });
  eq(open.gate34, 1);
  eq(open.charsAddr, ETC_NAME);
  eq(open.hostCallCount, 1);
  eq(open.pureComplete, 0);

  /* WIDE gate 0x100 IS set (FULL-dword test). */
  const wide = runEventTriggerCstrDiff("v49-etc-wide-gate", { gate34: 0x100 });
  eq(wide.gate34, 1);
  eq(wide.hostCallCount, 1);

  /* 0xffffffff also open. */
  const all = runEventTriggerCstrDiff("v49-etc-all-gate", { gate34: 0xffffffff });
  eq(all.gate34, 1);

  /* THE twin discriminant: [name+0x14] reads a heap-like cap (0x100), but
     the const-char twin pushes [ebp+8] verbatim — charsAddr MUST stay the
     raw arg. */
  const raw = runEventTriggerCstrDiff("v49-etc-no-sso-decode", {
    gate34: 1, rawDwordAt14: 0x100,
  });
  eq(raw.charsAddr, ETC_NAME, "no SSO decode on a heap-like cap");
  eq(raw.gate34, 1);

  /* Null anm2 -> not entered (defaults). */
  wasm.isaac_anm2_event_trigger_cstr_plan(0, ETC_NAME, PLAN_EVENT_TRIGGER_CSTR);
  const js0 = numify(anm2EventTriggerCstrPlan(shadow, { anm2Addr: 0, nameAddr: ETC_NAME }));
  assertStructEqual(readEventTriggerCstrPlan(PLAN_EVENT_TRIGGER_CSTR), js0, "v49-etc-null plan");
  eq(js0.entered, 0);

  COUNT.cases += 9;
});

test("v49 band-b event-trigger cstr differential (randomized gates)", () => {
  const rng = makeRng(0x40b030 ^ 0xadd0);
  const gates = [0, 1, 0xff, 0x100, 0x1ff, 0x10000, 0xffffffff];
  const caps = [0, 1, 0xf, 0x10, 0x11, 0x100, 0xffffffff];
  for (let t = 0; t < 64; ++t) {
    const gate = gates[rng.u32() % gates.length];
    const cap = caps[rng.u32() % caps.length];
    const js = runEventTriggerCstrDiff(`v49-etc-t${t}`, { gate34: gate, rawDwordAt14: cap });
    eq(js.gate34, gate !== 0 ? 1 : 0, `t${t} gate=0x${(gate >>> 0).toString(16)}`);
    eq(js.charsAddr, ETC_NAME, `t${t} raw passthrough despite cap=0x${(cap >>> 0).toString(16)}`);
    eq(js.hostCallCount, gate !== 0 ? 1 : 0);
    eq(js.pureComplete, gate !== 0 ? 0 : 1);
    eq(js.result, 0);
  }
  COUNT.cases += 64;
});

