test("v57 hash insert: mutations are caught by the pins", () => {
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const withMutant = (label, mutate, check, probe) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      wasm = loadExports();
      wmem = new Uint8Array(wasm.memory.buffer);
      if (probe) {
        const diverged = probe();
        assert.ok(diverged, `${label}: rebuilt module not mutant (stale build)`);
      }
      check();
    } catch {
      threw = true;
    }
    writeSourceRetry(original);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    withMutant("v57 grow gate inverted",
      (s) => s.replace(
        "  return cur <= end_hi + 1u ? 1u : 0u;",
        "  return cur > end_hi + 1u ? 1u : 0u;"),
      () => {
        eq(wasm.isaac_anm2_hash_grow_gate(8, 1), 0, "gate 8 > 2 skips");
      },
      () => wasm.isaac_anm2_hash_grow_gate(8, 1) !== 0);
    withMutant("v57 grow gate byte-masked",
      (s) => s.replace(
        "  return cur <= end_hi + 1u ? 1u : 0u;",
        "  return (cur & 0xffu) <= end_hi + 1u ? 1u : 0u;"),
      () => {
        eq(wasm.isaac_anm2_hash_grow_gate(0x100, 0xfe), 0,
          "FULL dword cur: 0x100 > 0xff skips");
      },
      () => wasm.isaac_anm2_hash_grow_gate(0x100, 0xfe) === 1);
    withMutant("v57 capacity doubling broken",
      (s) => s.replace("    eax *= 2u;", "    eax += 1u;"),
      () => {
        eq(wasm.isaac_anm2_hash_grow_capacity(8) >>> 0, 16,
          "capacity(8) doubles to 16");
      },
      () => wasm.isaac_anm2_hash_grow_capacity(8) === 16);
    withMutant("v57 slot mask off-by-one",
      (s) => s.replace(
        "  const uint32_t mask = cur - 1u;",
        "  const uint32_t mask = cur;"),
      () => {
        eq(wasm.isaac_anm2_hash_insert_slot(7, 8, 4) >>> 0, 3,
          "slot uses (cur-1) mask");
      },
      () => wasm.isaac_anm2_hash_insert_slot(7, 8, 4) === 3);
    withMutant("v57 motion case A/B flipped",
      (s) => s.replace(
        "  plan.case_b = old_cap > delta ? 1 : 0; /* 0x40c949 `ja` */",
        "  plan.case_b = old_cap <= delta ? 1 : 0; /* flipped */"),
      () => {
        const { p } = runV58Motion(0x1000, 16, 8, 4, 0x5000);
        eq(p.caseB, 1, "old_cap 16 > delta 4 is case B");
      },
      () => {
        wasm.isaac_anm2_hash_grow_motion_plan(0x1000, 16, 8, 4, 0x5000,
                                              V58_MOTION);
        return readPlanU32At(V58_MOTION, 1) !== 1;
      });
    withMutant("v57 node alloc size changed",
      (s) => s.replace(
        "plan.node_alloc_size = static_cast<uint32_t>(ISAAC_ANM2_HASH_INSERT_NODE_SIZE);",
        "plan.node_alloc_size = static_cast<uint32_t>(0x54u);"),
      () => {
        const { p } = runV58Insert(0, 0, 0, 0, 0x9000);
        eq(p.nodeAllocSize >>> 0, 0x2c, "node alloc size 0x2c");
      },
      () => {
        wasm.isaac_anm2_hash_insert_plan(0, 0, 0, 0, 0x9000, V58_IPLAN);
        return readPlanU32At(V58_IPLAN, 26 * 4) !== 0x2c;
      });
  } finally {
    writeSourceRetry(original);
  }
  wasm = loadExports(); /* clean rebuild after the round-trip */
  wmem = new Uint8Array(wasm.memory.buffer);
  COUNT.cases += 6;
});

/* ============== v58: 0x0040c2d0 string empty + 0x0040c2f0 clear ========== */

const V59_BASE = V58_HASH_BASE + 0x1400;    /* 0x116c00 */
const V59_STR = V59_BASE + 0x0000;          /* fake string object (self) */
const V59_BUF = V59_BASE + 0x0080;          /* heap buffer image */
const V59_CPLAN = V59_BASE + 0x0100;        /* clear plan (48 B) */
const V59_SELF = V59_BASE + 0x1000;         /* SSO receiver base */

const V59_CLEAR_FIELDS = [
  "entered", "cap", "buf", "self", "heapPath", "sizeStore", "sizeOff",
  "sizeValue", "byteStore", "byteAddr", "byteValue", "pureComplete",
];

function runV59Clear(cap, buf, self) {
  wasm.isaac_anm2_string_clear_plan(cap, buf, self, V59_CPLAN);
  const p = readV58Fields(V59_CPLAN, V59_CLEAR_FIELDS);
  const o = anm2StringClearPlan({ cap, buf, self });
  return { p, o };
}

test("v58 string empty/clear: fixed edges (laws + plans)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }

  eq(ANM2_STRING_EMPTY_VA, 0x0040c2d0);
  eq(ANM2_STRING_EMPTY_END_VA, 0x0040c2d7);
  eq(ANM2_STRING_EMPTY_BODY_BYTES, 0x8);
  eq(ANM2_STRING_EMPTY_CALLSITE_COUNT, 4);
  eq(ANM2_STRING_EMPTY_CALLER_FIRST_VA, 0x005dbe88);
  eq(ANM2_STRING_EMPTY_CALLER_LAST_VA, 0x007891d7);
  eq(ANM2_STRING_SIZE_OFF, 0x10);
  eq(ANM2_STRING_CAP_OFF, 0x14);
  eq(ANM2_STRING_CLEAR_VA, 0x0040c2f0);
  eq(ANM2_STRING_CLEAR_END_VA, 0x0040c30d);
  eq(ANM2_STRING_CLEAR_BODY_BYTES, 0x1e);
  eq(ANM2_STRING_CLEAR_CALLSITE_COUNT, 7);
  eq(ANM2_STRING_CLEAR_CALLER_FIRST_VA, 0x00687897);
  eq(ANM2_STRING_CLEAR_CALLER_LAST_VA, 0x0094ce31);

  /* empty: FULL-dword size test (0x40c2d4 sete al). */
  const emptyEdges = [
    [0, 1], [1, 0], [0x100, 0], [0xffffffff, 0],
  ];
  for (const [size, want] of emptyEdges) {
    eq(wasm.isaac_anm2_string_empty(size), want, `empty(${size})`);
    eq(anm2StringEmpty(size), want, `oracle empty(${size})`);
  }

  /* clear: cap gate `jb` (0x40c2f4) is UNSIGNED — SSO iff cap < 0x10;
     the byte store lands at self (SSO) or buf (heap). */
  for (const cap of [0, 0xf, 0x10, 0x100, 0x10000000, 0xffffffff]) {
    const { p, o } = runV59Clear(cap, V59_BUF, V59_SELF);
    eqV58PlanFields(p, o, V59_CLEAR_FIELDS, `clear cap ${cap}`);
  }
  const { p: sso, o: oSso } = runV59Clear(0xf, V59_BUF, V59_SELF);
  eq(sso.heapPath, 0, "cap 0xf -> SSO path");
  eq(sso.byteAddr >>> 0, V59_SELF, "SSO first byte at self (0x40c30a)");
  eqV58PlanFields(sso, oSso, V59_CLEAR_FIELDS, "clear SSO");
  const { p: heap, o: oHeap } = runV59Clear(0x10, V59_BUF, V59_SELF);
  eq(heap.heapPath, 1, "cap 0x10 -> heap path");
  eq(heap.byteAddr >>> 0, V59_BUF, "heap first byte at buf (0x40c2ff)");
  eqV58PlanFields(heap, oHeap, V59_CLEAR_FIELDS, "clear heap");
  eq(sso.sizeStore, 1, "size store on SSO path");
  eq(heap.sizeStore, 1, "size store on heap path (shared 0x40c2f8/0x40c303)");
  eq(sso.sizeOff >>> 0, 0x10, "size store offset 0x10");
  eq(sso.sizeValue >>> 0, 0, "size store value 0");
  eq(sso.byteValue >>> 0, 0, "byte store value 0");
  eq(sso.pureComplete, 1, "zero host calls");

  eq(wasm.isaac_anm2_pure_helpers_abi_version(), 77, "ABI 73 export");
  COUNT.cases += 1;
});

test("v58 string empty/clear: randomized differential (wasm vs oracle)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  const rng = makeRng(0x40c2d0);
  for (let t = 0; t < 150; ++t) {            /* <= 500 draws (coordinator) */
    const cap = (rng.u32() & 3) === 0
      ? rng.u32() % 0x10                     /* SSO band incl. 0 */
      : (rng.u32() & 1)
        ? 0x10 + (rng.u32() % 0x40)          /* small heap caps */
        : rng.u32();                         /* full-range incl. wrap */
    const buf = V59_BASE + (rng.u32() % 0x400);
    const self = V59_BASE + 0x800 + (rng.u32() % 0x800);
    const size = rng.u32();
    eq(wasm.isaac_anm2_string_empty(size), anm2StringEmpty(size),
      `empty t${t}`);
    const { p, o } = runV59Clear(cap, buf, self);
    eqV58PlanFields(p, o, V59_CLEAR_FIELDS, `clear t${t}`);
  }
  COUNT.cases += 150;
});

