test("v60-c380 default ctor: mutations are caught by the pins", () => {
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const withMutant = (label, mutate, check, probe) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      wasm = loadExports();
      wmem = new Uint8Array(wasm.memory.buffer);
      if (probe) {
        const diverged = probe();
        assert.ok(diverged, `${label}: rebuilt module not mutant (stale build)`);
      }
      check();
    } catch {
      threw = true;
    }
    writeSourceRetry(original);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    /* M1: cap 0xf -> 0x10 — the machine stores BUF_SIZE-1 = 0xf (0x40c38f). */
    withMutant("v60ctor cap value 0x10",
      (s) => s.replace(
        "  /* 0x40c38f mov dword [ecx+0x14], 0xf — cap := 0xf (BUF_SIZE - 1). */\n" +
        "  plan.cap_off = static_cast<uint32_t>(ISAAC_ANM2_STRING_CAP_OFF);\n" +
        "  plan.cap_value =\n" +
        "      static_cast<uint32_t>(ISAAC_ANM2_STRING_DEFAULT_CTOR_CAP_VALUE);",
        "  /* 0x40c38f mov dword [ecx+0x14], 0xf — cap := 0xf (BUF_SIZE - 1). */\n" +
        "  plan.cap_off = static_cast<uint32_t>(ISAAC_ANM2_STRING_CAP_OFF);\n" +
        "  plan.cap_value = 0x10u;"),
      () => {
        const { p } = runV61DefCtor(V61_SELF);
        eq(p.capValue >>> 0, 0xf, "cap value 0xf");
      },
      () => {
        wasm.isaac_anm2_string_default_ctor_plan(V61_SELF, V61_PLAN);
        return readPlanU32At(V61_PLAN, 9 * 4) !== 0xf;
      });
    /* M2: size store 0 -> 1 — the machine stores size := 0 (0x40c388). */
    withMutant("v60ctor size store 1",
      (s) => s.replace(
        "  /* 0x40c388 mov dword [ecx+0x10], 0 — size := 0. */\n" +
        "  plan.size_off = static_cast<uint32_t>(ISAAC_ANM2_STRING_SIZE_OFF);\n" +
        "  plan.size_value = 0u;",
        "  /* 0x40c388 mov dword [ecx+0x10], 0 — size := 0. */\n" +
        "  plan.size_off = static_cast<uint32_t>(ISAAC_ANM2_STRING_SIZE_OFF);\n" +
        "  plan.size_value = 1u;"),
      () => {
        const { p } = runV61DefCtor(V61_SELF);
        eq(p.sizeValue >>> 0, 0, "size value 0");
      },
      () => {
        wasm.isaac_anm2_string_default_ctor_plan(V61_SELF, V61_PLAN);
        return readPlanU32At(V61_PLAN, 7 * 4) !== 0;
      });
    /* M3: chars dword store 0 -> 1 — the machine clears the inline buf. */
    withMutant("v60ctor chars store 1",
      (s) => s.replace(
        "  /* 0x40c380 mov dword [ecx], 0 — chars dword (inline SSO buf at +0). */\n" +
        "  plan.chars_off = 0u;\n" +
        "  plan.chars_value = 0u;",
        "  /* 0x40c380 mov dword [ecx], 0 — chars dword (inline SSO buf at +0). */\n" +
        "  plan.chars_off = 0u;\n" +
        "  plan.chars_value = 1u;"),
      () => {
        const { p } = runV61DefCtor(V61_SELF);
        eq(p.charsValue >>> 0, 0, "chars value 0");
      },
      () => {
        wasm.isaac_anm2_string_default_ctor_plan(V61_SELF, V61_PLAN);
        return readPlanU32At(V61_PLAN, 5 * 4) !== 0;
      });
    /* M4: result dropped — the machine returns this (mov eax,ecx 0x40c386). */
    withMutant("v60ctor result dropped",
      (s) => s.replace(
        "  plan.result = plan.entered != 0 ? self : 0u;",
        "  plan.result = 0u;"),
      () => {
        const { p } = runV61DefCtor(V61_SELF);
        eq(p.result >>> 0, V61_SELF, "result = self");
      },
      () => {
        wasm.isaac_anm2_string_default_ctor_plan(V61_SELF, V61_PLAN);
        return readPlanU32At(V61_PLAN, 2 * 4) !== V61_SELF;
      });
  } finally {
    writeSourceRetry(original);
  }
  wasm = loadExports(); /* clean rebuild after the round-trip */
  wmem = new Uint8Array(wasm.memory.buffer);
  COUNT.cases += 4;
});

/* =========== v61-c5b0: 0x0040c5b0 2-dword pair ctor ======================= */

const V62_BASE = V61_BASE + 0x2400;      /* 0x11c800 (< SCRATCH_HI) */
const V62_SELF = V62_BASE + 0x0100;      /* receiver base (fake pair) */
const V62_PLAN = V62_BASE + 0x0200;      /* plan (10 x 4 = 40 bytes) */

const V62_PAIR_FIELDS = [
  "entered", "self", "result", "storeCount", "firstOff", "firstValue",
  "secondOff", "secondValue", "pureComplete", "hostCallCount",
];

function runV62Pair(self) {
  wasm.isaac_anm2_pair_ctor_plan(self, V62_PLAN);
  const p = readV58Fields(V62_PLAN, V62_PAIR_FIELDS);
  const o = anm2PairCtorPlan({ self });
  return { p, o };
}

test("v61-c5b0 pair ctor: constants + census pins + fixed edges", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }

  eq(ANM2_PAIR_CTOR_VA, 0x0040c5b0);
  eq(ANM2_PAIR_CTOR_END_VA, 0x0040c5bf);
  eq(ANM2_PAIR_CTOR_BODY_BYTES, 0xf);
  eq(ANM2_PAIR_CTOR_CALLSITE_COUNT, 0);
  eq(ANM2_PAIR_CTOR_ADDR_TAKEN, 5);
  eq(ANM2_PAIR_CTOR_FIRST_OFF, 0);
  eq(ANM2_PAIR_CTOR_SECOND_OFF, 4);

  let { p, o } = runV62Pair(V62_SELF);
  eqV58PlanFields(p, o, V62_PAIR_FIELDS, "pair self");
  eq(p.entered, 1, "entered");
  eq(p.self >>> 0, V62_SELF, "self");
  eq(p.result >>> 0, V62_SELF, "result = self (0x40c5b6 mov eax,ecx)");
  eq(p.storeCount, 2, "two constant dword stores");
  eq(p.firstOff >>> 0, 0, "first dword at +0");
  eq(p.firstValue >>> 0, 0, "first value 0");
  eq(p.secondOff >>> 0, 4, "second dword at +4");
  eq(p.secondValue >>> 0, 0, "second value 0");
  eq(p.pureComplete, 1, "zero host calls");
  eq(p.hostCallCount, 0, "host call count 0");

  /* null self -> not-entered zeroed plan (the machine has no null guard;
     the law folds to the v42 not-entered posture). */
  ({ p, o } = runV62Pair(0));
  eqV58PlanFields(p, o, V62_PAIR_FIELDS, "pair null");
  eq(p.entered, 0, "null not entered");
  eq(p.self >>> 0, 0, "null self 0");
  eq(p.result >>> 0, 0, "null result 0");

  /* odd/wide addresses still report the constant stores verbatim. */
  ({ p, o } = runV62Pair(0x11c999));
  eqV58PlanFields(p, o, V62_PAIR_FIELDS, "pair odd addr");
  eq(p.result >>> 0, 0x11c999, "odd result");

  /* null plan out is a no-op. */
  wasm.isaac_anm2_pair_ctor_plan(V62_SELF, 0);

  eq(wasm.isaac_anm2_pure_helpers_abi_version(), 77, "ABI 73 export");
  COUNT.cases += 1;
});

