test("v61-c5b0 pair ctor: mutations are caught by the pins", () => {
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const withMutant = (label, mutate, check, probe) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      wasm = loadExports();
      wmem = new Uint8Array(wasm.memory.buffer);
      if (probe) {
        const diverged = probe();
        assert.ok(diverged, `${label}: rebuilt module not mutant (stale build)`);
      }
      check();
    } catch {
      threw = true;
    }
    writeSourceRetry(original);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    /* M1: second store offset 4 -> 8 — the machine stores [ecx+4]
       (0x40c5b8). */
    withMutant("v61ctor second off 8",
      (s) => s.replace(
        "  plan.second_off = static_cast<uint32_t>(ISAAC_ANM2_PAIR_CTOR_SECOND_OFF);\n" +
        "  plan.second_value = 0u;",
        "  plan.second_off = 8u;\n" +
        "  plan.second_value = 0u;"),
      () => {
        const { p } = runV62Pair(V62_SELF);
        eq(p.secondOff >>> 0, 4, "second off 4");
      },
      () => {
        wasm.isaac_anm2_pair_ctor_plan(V62_SELF, V62_PLAN);
        return readPlanU32At(V62_PLAN, 6 * 4) !== 4;
      });
    /* M2: second store value 0 -> 1 — the machine stores 0 (0x40c5b8). */
    withMutant("v61ctor second value 1",
      (s) => s.replace(
        "  plan.first_off = static_cast<uint32_t>(ISAAC_ANM2_PAIR_CTOR_FIRST_OFF);\n" +
        "  plan.first_value = 0u;\n" +
        "  /* 0x40c5b8 mov dword [ecx+4], 0 — dword [self+4] := 0. */\n" +
        "  plan.second_off = static_cast<uint32_t>(ISAAC_ANM2_PAIR_CTOR_SECOND_OFF);\n" +
        "  plan.second_value = 0u;",
        "  plan.first_off = static_cast<uint32_t>(ISAAC_ANM2_PAIR_CTOR_FIRST_OFF);\n" +
        "  plan.first_value = 0u;\n" +
        "  /* 0x40c5b8 mov dword [ecx+4], 0 — dword [self+4] := 0. */\n" +
        "  plan.second_off = static_cast<uint32_t>(ISAAC_ANM2_PAIR_CTOR_SECOND_OFF);\n" +
        "  plan.second_value = 1u;"),
      () => {
        const { p } = runV62Pair(V62_SELF);
        eq(p.secondValue >>> 0, 0, "second value 0");
      },
      () => {
        wasm.isaac_anm2_pair_ctor_plan(V62_SELF, V62_PLAN);
        return readPlanU32At(V62_PLAN, 7 * 4) !== 0;
      });
    /* M3: first store value 0 -> 1 — the machine clears dword [self+0]
       (0x40c5b0). */
    withMutant("v61ctor first value 1",
      (s) => s.replace(
        "  /* 0x40c5b0 mov dword [ecx], 0 — dword [self+0] := 0. */\n" +
        "  plan.first_off = static_cast<uint32_t>(ISAAC_ANM2_PAIR_CTOR_FIRST_OFF);\n" +
        "  plan.first_value = 0u;",
        "  /* 0x40c5b0 mov dword [ecx], 0 — dword [self+0] := 0. */\n" +
        "  plan.first_off = static_cast<uint32_t>(ISAAC_ANM2_PAIR_CTOR_FIRST_OFF);\n" +
        "  plan.first_value = 1u;"),
      () => {
        const { p } = runV62Pair(V62_SELF);
        eq(p.firstValue >>> 0, 0, "first value 0");
      },
      () => {
        wasm.isaac_anm2_pair_ctor_plan(V62_SELF, V62_PLAN);
        return readPlanU32At(V62_PLAN, 5 * 4) !== 0;
      });
    /* M4: result dropped — the machine returns this (mov eax,ecx
       0x40c5b6). Anchored on the pair-ctor block so the v60 ctor's
       identical line is NOT the one mutated. */
    withMutant("v61ctor result dropped",
      (s) => s.replace(
        "  IsaacAnm2PairCtorPlan plan;\n" +
        "  plan.entered = self != 0u ? 1 : 0;\n" +
        "  plan.self = self;\n" +
        "  plan.result = plan.entered != 0 ? self : 0u;",
        "  IsaacAnm2PairCtorPlan plan;\n" +
        "  plan.entered = self != 0u ? 1 : 0;\n" +
        "  plan.self = self;\n" +
        "  plan.result = 0u;"),
      () => {
        const { p } = runV62Pair(V62_SELF);
        eq(p.result >>> 0, V62_SELF, "result = self");
      },
      () => {
        wasm.isaac_anm2_pair_ctor_plan(V62_SELF, V62_PLAN);
        return readPlanU32At(V62_PLAN, 2 * 4) !== V62_SELF;
      });
  } finally {
    writeSourceRetry(original);
  }
  wasm = loadExports(); /* clean rebuild after the round-trip */
  wmem = new Uint8Array(wasm.memory.buffer);
  COUNT.cases += 4;
});

