const V63_PLAN = V63_BASE + 0x0200;      /* plan (9 x 4 = 36 bytes) */

const V63_CTOR_FIELDS = [
  "entered", "self", "result", "storeCount", "aOff", "bOff", "ssoCap",
  "pureComplete", "hostCallCount",
];
const V63_ID_FIELDS = [
  "entered", "self", "result", "storeCount", "oneBits", "onesFirstOff",
  "byteOff", "pureComplete", "hostCallCount",
];

function runV63StrPair(self) {
  wasm.isaac_anm2_strpair_ctor_plan(self, V63_PLAN);
  const p = readV58Fields(V63_PLAN, V63_CTOR_FIELDS);
  const o = anm2StrPairCtorPlan({ self });
  return { p, o };
}

function runV63Identity(self) {
  wasm.isaac_anm2_identity_ctor_plan(self, V63_PLAN);
  const p = readV58Fields(V63_PLAN, V63_ID_FIELDS);
  const o = anm2IdentityCtorPlan({ self });
  return { p, o };
}

test("v62 unit: constants + census pins + fixed edges (3 new laws)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }

  /* 0x0040d140 two-string zero-init ctor. */
  eq(ANM2_STRPAIR_CTOR_VA, 0x0040d140);
  eq(ANM2_STRPAIR_CTOR_END_VA, 0x0040d16c);
  eq(ANM2_STRPAIR_CTOR_BODY_BYTES, 0x2d);
  eq(ANM2_STRPAIR_CTOR_CALLSITE_COUNT, 0);
  eq(ANM2_STRPAIR_CTOR_ADDR_TAKEN, 2);
  eq(ANM2_STRPAIR_CTOR_STORE_COUNT, 7);
  eq(ANM2_STRPAIR_CTOR_A_OFF, 8);
  eq(ANM2_STRPAIR_CTOR_B_OFF, 0x20);
  eq(ANM2_STRPAIR_CTOR_SSO_CAP, 0xf);

  let { p, o } = runV63StrPair(V63_SELF);
  eqV58PlanFields(p, o, V63_CTOR_FIELDS, "strpair self");
  eq(p.entered, 1, "strpair entered");
  eq(p.result >>> 0, V63_SELF, "strpair result = self (0x40d147)");
  eq(p.storeCount, 7, "seven constant dword stores");
  eq(p.aOff >>> 0, 8, "string A at +0x8");
  eq(p.bOff >>> 0, 0x20, "string B at +0x20");
  eq(p.ssoCap >>> 0, 0xf, "cap stores 0xf");
  ({ p, o } = runV63StrPair(0));
  eqV58PlanFields(p, o, V63_CTOR_FIELDS, "strpair null");
  eq(p.entered, 0, "strpair null not entered");
  wasm.isaac_anm2_strpair_ctor_plan(V63_SELF, 0); /* null plan no-op */

  /* 0x0040d170 wide zero/identity ctor. */
  eq(ANM2_IDENTITY_CTOR_VA, 0x0040d170);
  eq(ANM2_IDENTITY_CTOR_END_VA, 0x0040d208);
  eq(ANM2_IDENTITY_CTOR_BODY_BYTES, 0x99);
  eq(ANM2_IDENTITY_CTOR_CALLSITE_COUNT, 0);
  eq(ANM2_IDENTITY_CTOR_ADDR_TAKEN, 0);
  eq(ANM2_IDENTITY_CTOR_DWORD_STORE_COUNT, 21);
  eq(ANM2_IDENTITY_CTOR_ONE_BITS, 0x3f800000);
  eq(ANM2_IDENTITY_CTOR_ONES_FIRST_OFF, 0x30);
  eq(ANM2_IDENTITY_CTOR_BYTE_OFF, 0x60);

  ({ p, o } = runV63Identity(V63_SELF));
  eqV58PlanFields(p, o, V63_ID_FIELDS, "identity self");
  eq(p.entered, 1, "identity entered");
  eq(p.result >>> 0, V63_SELF, "identity result = self (0x40d177)");
  eq(p.storeCount, 22, "22 constant stores (21 dwords + 1 byte)");
  eq(p.oneBits >>> 0, 0x3f800000, "1.0f bits");
  eq(p.onesFirstOff >>> 0, 0x30, "ones at +0x30");
  eq(p.byteOff >>> 0, 0x60, "byte store at +0x60");
  ({ p, o } = runV63Identity(0));
  eqV58PlanFields(p, o, V63_ID_FIELDS, "identity null");
  eq(p.entered, 0, "identity null not entered");
  wasm.isaac_anm2_identity_ctor_plan(V63_SELF, 0); /* null plan no-op */

  /* 0x0040d210 global-base getter. */
  eq(ANM2_GLOBAL_BASE_GETTER_VA, 0x0040d210);
  eq(ANM2_GLOBAL_BASE_GETTER_END_VA, 0x0040d21a);
  eq(ANM2_GLOBAL_BASE_GETTER_BODY_BYTES, 0xb);
  eq(ANM2_GLOBAL_BASE_GETTER_CALLSITE_COUNT, 0);
  eq(ANM2_GLOBAL_BASE_GETTER_ADDR_TAKEN, 0);
  eq(ANM2_GLOBAL_BASE_PTR_VA, 0x00c7169c);
  eq(ANM2_GLOBAL_BASE_DELTA, 0x2a6c0);

  eq(wasm.isaac_anm2_global_base_getter(0), 0x2a6c0, "getter loaded 0");
  eq(wasm.isaac_anm2_global_base_getter(0x100000), 0x12a6c0, "getter add");
  /* 32-bit wrap: the PE dword add. */
  eq(wasm.isaac_anm2_global_base_getter(0xfffd5940) >>> 0, 0, "getter wrap to 0");
  eq(wasm.isaac_anm2_global_base_getter(0xffffffff) >>> 0, 0x2a6bf,
     "getter wrap 0xffffffff");
  eq(anm2GlobalBaseGetter(0xfffd5940) >>> 0, 0, "oracle wrap agrees");

  eq(wasm.isaac_anm2_pure_helpers_abi_version(), 77, "ABI 73 export");
  COUNT.cases += 40;
});

test("v62 unit: randomized differential (wasm vs oracle)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  const rng = makeRng((0x40d140 ^ 0x40d170) >>> 0);
  for (let t = 0; t < 150; ++t) {          /* <= 500 draws (coordinator) */
    const self = (rng.u32() & 3) === 0
      ? 0
      : (rng.u32() % 0x10000) + 0x100000;
    { const { p, o } = runV63StrPair(self);
      eqV58PlanFields(p, o, V63_CTOR_FIELDS, `strpair t${t}`);
      if (self !== 0) {
        eq(p.result >>> 0, self, `strpair result t${t}`);
        eq(p.storeCount, 7, `strpair stores t${t}`);
      } }
    { const { p, o } = runV63Identity(self);
      eqV58PlanFields(p, o, V63_ID_FIELDS, `identity t${t}`);
      if (self !== 0) {
        eq(p.result >>> 0, self, `identity result t${t}`);
        eq(p.storeCount, 22, `identity stores t${t}`);
      } }
    const loaded = rng.u32();
    eq(wasm.isaac_anm2_global_base_getter(loaded) >>> 0,
       anm2GlobalBaseGetter(loaded) >>> 0, `getter t${t}`);
  }
  COUNT.cases += 150;
});

