test("v62 unit: mutations are caught by the pins", () => {
  const sha256 = (txt) =>
    createHash("sha256").update(txt, "utf8").digest("hex");
  const originalBuf = readFileSync(source);
  const originalHash = sha256(originalBuf.toString("utf8"));
  const original = originalBuf.toString("utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const withMutant = (label, mutate, check, probe) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      wasm = loadExports();
      wmem = new Uint8Array(wasm.memory.buffer);
      if (probe) {
        const diverged = probe();
        assert.ok(diverged, `${label}: rebuilt module not mutant (stale build)`);
      }
      check();
    } catch {
      threw = true;
    }
    writeSourceRetry(original);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    /* M1 (floatvec repair): x1 store offset +0x00 -> +0x0c — the machine
       stores xmm1 at [ecx] (0x40d124). */
    withMutant("fvc x1 store off 0xc",
      (s) => s.replace(
        "  store_u32(anm2 + 0x24u, b2);\n" +
        "  store_u32(anm2 + 0x00u, b3);",
        "  store_u32(anm2 + 0x24u, b2);\n" +
        "  store_u32(anm2 + 0x0cu, b3);"),
      () => {
        wasm.isaac_anm2_floatvec_ctor(
          FVC_IFACE, 1.5, -2.25, 0.0, 3.0, -4.5, 5.25, -6.75, PLAN_FVC);
        const u32At = (a) => new DataView(wmem.buffer).getUint32(a, true);
        eq(u32At(FVC_IFACE + 0x00), f32v(3.0), "xmm1 -> +0x00");
      },
      () => {
        wasm.isaac_anm2_floatvec_ctor(
          FVC_IFACE, 1.5, -2.25, 0.0, 3.0, -4.5, 5.25, -6.75, PLAN_FVC);
        const u32At = (a) => new DataView(wmem.buffer).getUint32(a, true);
        return u32At(FVC_IFACE + 0x00) !== f32v(3.0);
      });
    /* M2 (floatvec repair): a6 -> x3 slot swap — the machine stores
       [ebp+0x14] at +0x28 and xmm3 at +0x08; swapping them diverges on
       distinct inputs. */
    withMutant("fvc a6/x3 swapped",
      (s) => s.replace(
        "  store_u32(anm2 + 0x08u, b5);\n" +
        "  store_u32(anm2 + 0x28u, b6);",
        "  store_u32(anm2 + 0x08u, b6);\n" +
        "  store_u32(anm2 + 0x28u, b5);"),
      () => {
        wasm.isaac_anm2_floatvec_ctor(
          FVC_IFACE, 1.5, -2.25, 0.0, 3.0, -4.5, 5.25, -6.75, PLAN_FVC);
        const u32At = (a) => new DataView(wmem.buffer).getUint32(a, true);
        eq(u32At(FVC_IFACE + 0x08), f32v(5.25), "xmm3 -> +0x08");
      },
      () => {
        wasm.isaac_anm2_floatvec_ctor(
          FVC_IFACE, 1.5, -2.25, 0.0, 3.0, -4.5, 5.25, -6.75, PLAN_FVC);
        const u32At = (a) => new DataView(wmem.buffer).getUint32(a, true);
        return u32At(FVC_IFACE + 0x08) !== f32v(5.25);
      });
    /* M3 (strpair): sso cap 0xf -> 0x10 — the machine stores 0xf
       (0x40d150/0x40d165). */
    withMutant("strpair cap 0x10",
      (s) => s.replace(
        "  plan.sso_cap = static_cast<uint32_t>(ISAAC_ANM2_STRPAIR_CTOR_SSO_CAP);",
        "  plan.sso_cap = 0x10u;"),
      () => {
        const { p } = runV63StrPair(V63_SELF);
        eq(p.ssoCap >>> 0, 0xf, "sso cap 0xf");
      },
      () => {
        wasm.isaac_anm2_strpair_ctor_plan(V63_SELF, V63_PLAN);
        return readPlanU32At(V63_PLAN, 6 * 4) !== 0xf;
      });
    /* M4 (strpair): B base 0x20 -> 0x24 — the machine's string B sits at
       +0x20 (size +0x30/cap +0x34 stores). */
    withMutant("strpair b off 0x24",
      (s) => s.replace(
        "  plan.b_off = static_cast<uint32_t>(ISAAC_ANM2_STRPAIR_CTOR_B_OFF);",
        "  plan.b_off = 0x24u;"),
      () => {
        const { p } = runV63StrPair(V63_SELF);
        eq(p.bOff >>> 0, 0x20, "B base 0x20");
      },
      () => {
        wasm.isaac_anm2_strpair_ctor_plan(V63_SELF, V63_PLAN);
        return readPlanU32At(V63_PLAN, 5 * 4) !== 0x20;
      });
    /* M5 (identity): one bits 0x3f800000 -> 0x3f800001 — the machine
       stores exact 1.0f words (0x40d1b7..0x40d1cc). */
    withMutant("identity one bits +1",
      (s) => s.replace(
        "  plan.one_bits = static_cast<uint32_t>(ISAAC_ANM2_IDENTITY_CTOR_ONE_BITS);",
        "  plan.one_bits = 0x3f800001u;"),
      () => {
        const { p } = runV63Identity(V63_SELF);
        eq(p.oneBits >>> 0, 0x3f800000, "1.0f bits verbatim");
      },
      () => {
        wasm.isaac_anm2_identity_ctor_plan(V63_SELF, V63_PLAN);
        return readPlanU32At(V63_PLAN, 4 * 4) !== 0x3f800000;
      });
    /* M6 (identity): byte store offset 0x60 -> 0x64 — the machine zeroes
       byte [self+0x60] (0x40d204). */
    withMutant("identity byte off 0x64",
      (s) => s.replace(
        "  plan.byte_off = static_cast<uint32_t>(ISAAC_ANM2_IDENTITY_CTOR_BYTE_OFF);",
        "  plan.byte_off = 0x64u;"),
      () => {
        const { p } = runV63Identity(V63_SELF);
        eq(p.byteOff >>> 0, 0x60, "byte at +0x60");
      },
      () => {
        wasm.isaac_anm2_identity_ctor_plan(V63_SELF, V63_PLAN);
        return readPlanU32At(V63_PLAN, 6 * 4) !== 0x60;
      });
    /* M7 (getter): delta 0x2a6c0 -> 0x2a6c1 — the PE adds 0x2a6c0
       (0x40d215). */
    withMutant("getter delta +1",
      (s) => s.replace(
        "  return loaded + static_cast<uint32_t>(ISAAC_ANM2_GLOBAL_BASE_DELTA);",
        "  return loaded + static_cast<uint32_t>(ISAAC_ANM2_GLOBAL_BASE_DELTA) + 1u;"),
      () => {
        eq(wasm.isaac_anm2_global_base_getter(0) >>> 0, 0x2a6c0, "delta");
      },
      () => wasm.isaac_anm2_global_base_getter(0) !== 0x2a6c0);
  } finally {
    writeSourceRetry(original);
  }
  wasm = loadExports(); /* clean rebuild after the round-trip */
  wmem = new Uint8Array(wasm.memory.buffer);
  /* sha256-identical restore proof. */
  const restoredHash = sha256(readFileSync(source).toString("utf8"));
  eq(restoredHash, originalHash, "source restored sha256-identical");
  COUNT.cases += 7;
});

/* =========== v64 unit: 0x00413b40 / 0x00413b90 ============================ */

const V64_BASE = V63_BASE + 0x2400;      /* 0x121000 (< SCRATCH_HI) */
const V64_SELF = V64_BASE + 0x0100;      /* receiver base */
const V64_PLAN = V64_BASE + 0x0200;      /* plan (9 x 4 = 36 bytes) */

const V64_FIELDS = [
  "entered", "self", "result", "storeCount", "baseOff", "sentinelOff",
  "alignedValue", "pureComplete", "hostCallCount",
];

function runV64(self) {
  wasm.isaac_anm2_aligned_state_ctor_plan(self, V64_PLAN);
  const p = readV58Fields(V64_PLAN, V64_FIELDS);
  const o = anm2AlignedStateCtorPlan({ self });
  return { p, o };
}

test("v64 unit: constants + census pins + fixed edges", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }

  /* 0x00413b40 SEH container-clear wrapper — HOST census row. */
  eq(ANM2_SEH_CLEAR_WRAP_VA, 0x00413b40);
  eq(ANM2_SEH_CLEAR_WRAP_END_VA, 0x00413b7f);
  eq(ANM2_SEH_CLEAR_WRAP_BODY_BYTES, 0x40);
  eq(ANM2_SEH_CLEAR_WRAP_CALLSITE_COUNT, 0);
  eq(ANM2_SEH_CLEAR_WRAP_ADDR_TAKEN, 0);
  eq(ANM2_SEH_CLEAR_WRAP_FRAME_VA, 0x00af11c0);
  eq(ANM2_SEH_CLEAR_WRAP_CLEAR_VA, 0x00414730);
  eq(ANM2_SEH_CLEAR_WRAP_RECV_OFF, 0x30);

  /* 0x00413b90 aligned-buffer state ctor — LANDED. */
  eq(ANM2_ALIGNED_STATE_CTOR_VA, 0x00413b90);
  eq(ANM2_ALIGNED_STATE_CTOR_END_VA, 0x00413bea);
  eq(ANM2_ALIGNED_STATE_CTOR_BODY_BYTES, 0x5b);
  eq(ANM2_ALIGNED_STATE_CTOR_CALLSITE_COUNT, 0);
  eq(ANM2_ALIGNED_STATE_CTOR_ADDR_TAKEN, 0);
  eq(ANM2_ALIGNED_STATE_CTOR_STORE_COUNT, 11);
  eq(ANM2_ALIGNED_STATE_CTOR_BASE_OFF, 0x3c);
  eq(ANM2_ALIGNED_STATE_CTOR_SENTINEL_OFF, 0x1003c);
  eq(ANM2_ALIGNED_STATE_CTOR_ALIGN_MASK, 3);

  /* alignment law fixed edges: round UP to multiple of 4, 32-bit wrap. */
  eq(anm2AlignedStateCtorAligned(0x3c) >>> 0, 0x3c, "already aligned");
  eq(anm2AlignedStateCtorAligned(0x3d) >>> 0, 0x40, "round up 1");
  eq(anm2AlignedStateCtorAligned(0x3e) >>> 0, 0x40, "round up 2");
  eq(anm2AlignedStateCtorAligned(0x3f) >>> 0, 0x40, "round up 3");
  eq(anm2AlignedStateCtorAligned(0) >>> 0, 0, "base 0");
  eq(anm2AlignedStateCtorAligned(0xffffffff) >>> 0, 0,
     "wrap 0xffffffff -> 0 (round-up carries out)");
  eq(wasm.isaac_anm2_aligned_state_ctor_aligned(0x3d) >>> 0, 0x40,
     "wasm align round up");
  eq(wasm.isaac_anm2_aligned_state_ctor_aligned(0xffffffff) >>> 0, 0,
     "wasm align wrap");

  let { p, o } = runV64(V64_SELF);
  eqV58PlanFields(p, o, V64_FIELDS, "v64 self");
  eq(p.entered, 1, "entered");
  eq(p.result >>> 0, V64_SELF, "result = self (0x413bd0 mov eax,esi)");
  eq(p.storeCount, 11, "eleven dword stores");
  eq(p.baseOff >>> 0, 0x3c, "base member +0x3c");
  eq(p.sentinelOff >>> 0, 0x1003c, "sentinel member +0x1003c");
  /* V64_SELF+0x3c is 16-aligned here; use an unaligned self too. */
  eq(p.alignedValue >>> 0, (V64_SELF + 0x3c) >>> 0, "aligned value");

  const ODD = V64_SELF + 1;
  ({ p, o } = runV64(ODD));
  eqV58PlanFields(p, o, V64_FIELDS, "v64 odd self");
  eq(p.alignedValue >>> 0, (ODD + 0x3c + 3) & ~3, "odd self rounds up");

  ({ p, o } = runV64(0));
  eqV58PlanFields(p, o, V64_FIELDS, "v64 null");
  eq(p.entered, 0, "null not entered");
  eq(p.result >>> 0, 0, "null result 0");

  wasm.isaac_anm2_aligned_state_ctor_plan(V64_SELF, 0); /* null plan no-op */

  eq(wasm.isaac_anm2_pure_helpers_abi_version(), 77, "ABI 73 export");
  COUNT.cases += 34;
});

test("v64 unit: randomized differential (wasm vs oracle)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  const rng = makeRng((0x413b90 ^ 0x413b40) >>> 0);
  for (let t = 0; t < 150; ++t) {          /* <= 500 draws (coordinator) */
    const base = rng.u32();
    eq(wasm.isaac_anm2_aligned_state_ctor_aligned(base) >>> 0,
       anm2AlignedStateCtorAligned(base) >>> 0, `align t${t}`);
    const self = (rng.u32() & 3) === 0
      ? 0
      : (rng.u32() % 0x10000) + 0x100000;
    const { p, o } = runV64(self);
    eqV58PlanFields(p, o, V64_FIELDS, `ctor t${t}`);
    if (self !== 0) {
      eq(p.result >>> 0, self, `result t${t}`);
      eq(p.alignedValue >>> 0,
         ((self + 0x3c) + ((0 - (self + 0x3c)) & 3)) >>> 0, `aligned t${t}`);
    }
  }
  COUNT.cases += 150;
});

