test("v64 unit: mutations are caught by the pins", () => {
  const sha256 = (txt) =>
    createHash("sha256").update(txt, "utf8").digest("hex");
  const originalBuf = readFileSync(source);
  const originalHash = sha256(originalBuf.toString("utf8"));
  const original = originalBuf.toString("utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const withMutant = (label, mutate, check, probe) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      wasm = loadExports();
      wmem = new Uint8Array(wasm.memory.buffer);
      if (probe) {
        const diverged = probe();
        assert.ok(diverged, `${label}: rebuilt module not mutant (stale build)`);
      }
      check();
    } catch {
      threw = true;
    }
    writeSourceRetry(original);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    /* M1 (alignment law): mask 3 -> 1 — the PE rounds up to a multiple
       of 4 (`and eax,3` @ 0x413bba). */
    withMutant("align mask 1",
      (s) => s.replace(
        "  return base + ((0u - base) &\n" +
        "                 static_cast<uint32_t>(ISAAC_ANM2_ALIGNED_STATE_CTOR_ALIGN_MASK));",
        "  return base + ((0u - base) & 1u);"),
      () => {
        eq(wasm.isaac_anm2_aligned_state_ctor_aligned(0x3d) >>> 0, 0x40,
           "round up to 4");
      },
      () => wasm.isaac_anm2_aligned_state_ctor_aligned(0x3d) !== 0x40);
    /* M2 (alignment law): round DOWN (base & ~3) instead of UP. */
    withMutant("align round down",
      (s) => s.replace(
        "  return base + ((0u - base) &\n" +
        "                 static_cast<uint32_t>(ISAAC_ANM2_ALIGNED_STATE_CTOR_ALIGN_MASK));",
        "  return base - (base & 3u);"),
      () => {
        eq(wasm.isaac_anm2_aligned_state_ctor_aligned(0x3e) >>> 0, 0x40,
           "rounds up");
      },
      () => wasm.isaac_anm2_aligned_state_ctor_aligned(0x3e) !== 0x40);
    /* M3 (plan): store count 11 -> 10 — the machine performs exactly 11
       dword stores. */
    withMutant("ctor store count 10",
      (s) => s.replace(
        "  plan.store_count = 11;\n" +
        "  plan.base_off = static_cast<uint32_t>(ISAAC_ANM2_ALIGNED_STATE_CTOR_BASE_OFF);",
        "  plan.store_count = 10;\n" +
        "  plan.base_off = static_cast<uint32_t>(ISAAC_ANM2_ALIGNED_STATE_CTOR_BASE_OFF);"),
      () => {
        const { p } = runV64(V64_SELF);
        eq(p.storeCount, 11, "eleven stores");
      },
      () => {
        wasm.isaac_anm2_aligned_state_ctor_plan(V64_SELF, V64_PLAN);
        return readPlanU32At(V64_PLAN, 3 * 4) !== 11;
      });
    /* M4 (plan): aligned_value dropped to 0 — the plan must report the
       +0x34 store value (0x413bcd). */
    withMutant("ctor aligned dropped",
      (s) => s.replace(
        "  plan.aligned_value = isaac_anm2_aligned_state_ctor_aligned(b);",
        "  plan.aligned_value = 0u;"),
      () => {
        const { p } = runV64(V64_SELF);
        eq(p.alignedValue >>> 0, (V64_SELF + 0x3c) >>> 0, "aligned reported");
      },
      () => {
        wasm.isaac_anm2_aligned_state_ctor_plan(V64_SELF, V64_PLAN);
        return readPlanU32At(V64_PLAN, 6 * 4) === 0;
      });
  } finally {
    writeSourceRetry(original);
  }
  wasm = loadExports(); /* clean rebuild after the round-trip */
  wmem = new Uint8Array(wasm.memory.buffer);
  /* sha256-identical restore proof. */
  const restoredHash = sha256(readFileSync(source).toString("utf8"));
  eq(restoredHash, originalHash, "source restored sha256-identical");
  COUNT.cases += 4;
});

/* =========== v65 unit: 0x00413bf0 / 0x00413c70 twin list finds ============ */

/* FIX 2: v65 pins its OWN scratch base inside bounds; the V*_BASE chain
   overflowed SCRATCH_HI at v64 (0x121000 > 0x120000) and plan-only laws
   never noticed because they never poke. This unit pokes, so it stays
   under SCRATCH_HI. Footprint ~0xb00 bytes. */
const V65_BASE = SCRATCH_HI - 0x1000;    /* 0x11f000 (< SCRATCH_HI) */
const V65_THIS_A = V65_BASE + 0x0100;    /* list A owner (head @ +0x20) */
const V65_THIS_B = V65_BASE + 0x0140;    /* list B owner (head @ +0x18) */
const V65_PLAN = V65_BASE + 0x0200;      /* plan (12 x 4 = 48 bytes) */
const V65_NODES = V65_BASE + 0x0400;     /* node area (stride 0x30) */
const V65_STRS = V65_BASE + 0x0800;      /* needle + name chars */

const V65_FIELDS = [
  "entered", "thisAddr", "needleAddr", "head", "found", "result",
  "walkedCount", "logNeeded", "logVa", "logLevel", "hostCallCount",
  "pureComplete",
];

function readV65Plan(base) {
  return readPlanFields(base, {
    entered: 0, thisAddr: 4, needleAddr: 8, head: 12, found: 16, result: 20,
    walkedCount: 24, logNeeded: 28, logVa: 32, logLevel: 36,
    hostCallCount: 40, pureComplete: 44,
  }, {
    entered: "i", thisAddr: "u", needleAddr: "u", head: "u", found: "i",
    result: "u", walkedCount: "i", logNeeded: "i", logVa: "u",
    logLevel: "i", hostCallCount: "i", pureComplete: "i",
  });
}

/* Build one twin-consistent world: the SAME logical chain exists twice,
   once with next@+0x18 under THIS_A (head @[THIS_A+0x20]) and once with
   next@+0x2c under THIS_B (head @[THIS_B+0x18]).
   entries: [[name|null, lenOverride?], ...] */
function buildV65World(entries) {
  const NA = V65_NODES;
  const NB = V65_NODES + 0x180;
  let sp = V65_STRS;
  const nameAddrs = [];
  for (const [name] of entries) {
    if (name === null) {
      nameAddrs.push(0);
    } else {
      pokeCString(sp, name);
      nameAddrs.push(sp);
      sp += name.length + 1;
    }
  }
  for (let i = 0; i < entries.length; ++i) {
    const [name, lenOverride] = entries[i];
    const a = NA + i * 0x30;
    const b = NB + i * 0x30;
    const nextA = i + 1 < entries.length ? NA + (i + 1) * 0x30 : 0;
    const nextB = i + 1 < entries.length ? NB + (i + 1) * 0x30 : 0;
    const nm = name === null ? 0 : nameAddrs[i];
    const ln = lenOverride !== undefined
      ? lenOverride
      : (name === null ? 0 : name.length);
    for (const [base, nx] of [[a, nextA], [b, nextB]]) {
      pokeU32(base + 0x00, nm);          /* name ptr */
      pokeU32(base + 0x08, ln);          /* len */
      pokeU32(base + 0x18, nx);          /* A next slot */
      pokeU32(base + 0x2c, nx);          /* B next slot */
    }
  }
  pokeU32(V65_THIS_A + 0x20, entries.length ? NA : 0);
  pokeU32(V65_THIS_B + 0x18, entries.length ? NB : 0);
}

function runV65Find(twin, thisAddr, needleAddr) {
  /* FIX 1: fail LOUDLY if the export is missing -- never vacuously. */
  const fn = twin === "a"
    ? wasm.isaac_anm2_list_find_a_plan
    : wasm.isaac_anm2_list_find_b_plan;
  assert.equal(typeof fn, "function", `missing export list_find_${twin}_plan`);
  fn(thisAddr, needleAddr, V65_PLAN);
  const p = readV65Plan(V65_PLAN);
  const o = numify(anm2ListFindPlan(shadow, {
    thisAddr, needleAddr,
    headOff: twin === "a" ? ANM2_LIST_FIND_A_HEAD_OFF : ANM2_LIST_FIND_B_HEAD_OFF,
    nextOff: twin === "a" ? ANM2_LIST_FIND_A_NEXT_OFF : ANM2_LIST_FIND_B_NEXT_OFF,
  }));
  return { p, o };
}

test("v65 unit: constants + census pins + fixed edges (twin list finds)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  /* loud export presence check BEFORE any behavioural assertion */
  assert.equal(typeof wasm.isaac_anm2_list_find_a_plan, "function",
               "EXPORTS: isaac_anm2_list_find_a_plan");
  assert.equal(typeof wasm.isaac_anm2_list_find_b_plan, "function",
               "EXPORTS: isaac_anm2_list_find_b_plan");

  eq(ANM2_LIST_FIND_A_VA, 0x00413bf0);
  eq(ANM2_LIST_FIND_A_END_VA, 0x00413c61);
  eq(ANM2_LIST_FIND_A_BODY_BYTES, 0x72);
  eq(ANM2_LIST_FIND_A_HEAD_OFF, 0x20);
  eq(ANM2_LIST_FIND_A_NEXT_OFF, 0x18);
  eq(ANM2_LIST_FIND_B_VA, 0x00413c70);
  eq(ANM2_LIST_FIND_B_END_VA, 0x00413cdf);
  eq(ANM2_LIST_FIND_B_BODY_BYTES, 0x70);
  eq(ANM2_LIST_FIND_B_HEAD_OFF, 0x18);
  eq(ANM2_LIST_FIND_B_NEXT_OFF, 0x2c);
  eq(ANM2_LIST_FIND_CALLSITE_COUNT, 0);
  eq(ANM2_LIST_FIND_ADDR_TAKEN, 0);
  eq(ANM2_LIST_FIND_NAME_OFF, 0);
  eq(ANM2_LIST_FIND_LEN_OFF, 8);
  eq(ANM2_LIST_FIND_EMPTY_GLOBAL, 0x00c71640);
  eq(ANM2_LIST_FIND_RET_BYTES, 0xc);

  /* World: Cursor -> Death -> (null-name node); B twin identical. */
  buildV65World([["Cursor"], ["Death"], [null]]);
  const N1 = V65_NODES;
  const N2 = V65_NODES + 0x30;
  const N3 = V65_NODES + 0x60;

  for (const twin of ["a", "b"]) {
    const thisAddr = twin === "a" ? V65_THIS_A : V65_THIS_B;
    /* twin B's identical chain lives at NB = V65_NODES + 0x180 */
    const nodeBase = twin === "a" ? N1 : N1 + 0x180;

    /* hit on node 1 */
    const needleCursor = V65_STRS + 0x100;
    pokeCString(needleCursor, "Cursor");
    let { p, o } = runV65Find(twin, thisAddr, needleCursor);
    eqV58PlanFields(p, o, V65_FIELDS, `${twin} cursor`);
    eq(p.found, 1, `${twin} cursor found`);
    eq(p.result >>> 0, nodeBase, `${twin} cursor -> node1`);
    eq(p.walkedCount, 1, `${twin} cursor walked 1`);

    /* hit on node 2 (walk continues past a mismatching node) */
    const needleDeath = V65_STRS + 0x120;
    pokeCString(needleDeath, "Death");
    ({ p, o } = runV65Find(twin, thisAddr, needleDeath));
    eqV58PlanFields(p, o, V65_FIELDS, `${twin} death`);
    eq(p.found, 1, `${twin} death found`);
    eq(p.result >>> 0, nodeBase + 0x30, `${twin} death -> node2`);
    eq(p.walkedCount, 2, `${twin} death walked 2`);

    /* miss: right shape, no byte match anywhere */
    const needleMiss = V65_STRS + 0x140;
    pokeCString(needleMiss, "Missed");
    ({ p, o } = runV65Find(twin, thisAddr, needleMiss));
    eqV58PlanFields(p, o, V65_FIELDS, `${twin} miss`);
    eq(p.found, 0, `${twin} miss not found`);
    eq(p.result >>> 0, 0, `${twin} miss result 0`);
    eq(p.walkedCount, 3, `${twin} miss walked all 3`);

    /* empty needle: nodes 1/2 have len 6/5 (no match), node3 is the
       null-name node whose substituted cmpLen is 0 -> match at node3. */
    const needleEmpty = V65_STRS + 0x160;
    pokeCString(needleEmpty, "");
    ({ p, o } = runV65Find(twin, thisAddr, needleEmpty));
    eqV58PlanFields(p, o, V65_FIELDS, `${twin} empty`);
    eq(p.found, 1, `${twin} empty found (null-name node)`);
    eq(p.result >>> 0, nodeBase + 0x60, `${twin} empty -> node3`);
    eq(p.walkedCount, 3, `${twin} empty walked 3`);

    /* null needle -> RAW head, not entered */
    ({ p, o } = runV65Find(twin, thisAddr, 0));
    eqV58PlanFields(p, o, V65_FIELDS, `${twin} null needle`);
    eq(p.entered, 0, `${twin} null needle not entered`);
    eq(p.found, 0, `${twin} null needle not found`);
    eq(p.result >>> 0, twin === "a" ? N1 : N1 + 0x180,
       `${twin} null needle returns raw head`);
    eq(p.walkedCount, 0, `${twin} null needle walked 0`);

    /* null this -> v42 zeroed posture */
    ({ p, o } = runV65Find(twin, 0, needleCursor));
    eqV58PlanFields(p, o, V65_FIELDS, `${twin} null this`);
    eq(p.head >>> 0, 0, `${twin} null this head 0`);
    eq(p.result >>> 0, 0, `${twin} null this result 0`);

    /* empty list: head 0 -> immediate miss */
    pokeU32(thisAddr + (twin === "a" ? 0x20 : 0x18), 0);
    ({ p, o } = runV65Find(twin, thisAddr, needleCursor));
    eqV58PlanFields(p, o, V65_FIELDS, `${twin} empty list`);
    eq(p.found, 0, `${twin} empty list miss`);
    eq(p.walkedCount, 0, `${twin} empty list walked 0`);
  }
  /* restore list heads for later tests */
  pokeU32(V65_THIS_A + 0x20, N1);
  pokeU32(V65_THIS_B + 0x18, V65_NODES + 0x180);

  wasm.isaac_anm2_list_find_a_plan(V65_THIS_A, 0, 0); /* null plan no-op */
  wasm.isaac_anm2_list_find_b_plan(V65_THIS_B, 0, 0);

  eq(wasm.isaac_anm2_pure_helpers_abi_version(), 77, "ABI 73 export");
  COUNT.cases += 60;
});

test("v65 unit: randomized differential (wasm vs oracle)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  assert.equal(typeof wasm.isaac_anm2_list_find_a_plan, "function");
  assert.equal(typeof wasm.isaac_anm2_list_find_b_plan, "function");
  const rng = makeRng((0x413bf0 ^ 0x413c70) >>> 0);
  const alpha = "abcde";
  for (let t = 0; t < 60; ++t) {
    const n = 1 + (rng.u32() % 4);
    const entries = [];
    for (let i = 0; i < n; ++i) {
      const kind = rng.u32() % 5;
      if (kind === 0) {
        entries.push([null]); /* null-name node (cmpLen 0 by substitution) */
      } else {
        let s2 = "";
        const l = 1 + (rng.u32() % 4);
        for (let j = 0; j < l; ++j) s2 += alpha[rng.u32() % alpha.length];
        entries.push([s2]);
      }
    }
    buildV65World(entries);
    for (let q = 0; q < 2; ++q) {
      let needleText;
      if (rng.u32() % 3 === 0 && entries.some(([n2]) => n2 !== null)) {
        const pick = entries.filter(([n2]) => n2 !== null);
        needleText = pick[rng.u32() % pick.length][0];
      } else {
        needleText = "";
        const l = rng.u32() % 4;
        for (let j = 0; j < l; ++j) needleText += alpha[rng.u32() % alpha.length];
      }
      const needleAddr = V65_STRS + 0x300;
      pokeCString(needleAddr, needleText);
      for (const twin of ["a", "b"]) {
        const thisAddr = twin === "a" ? V65_THIS_A : V65_THIS_B;
        const { p, o } = runV65Find(twin, thisAddr, needleAddr);
        eqV58PlanFields(p, o, V65_FIELDS, `t${t} ${twin} q${q}`);
      }
    }
  }
  COUNT.cases += 120;
});

test("v65 unit: header + model pins hold", () => {
  const headerText = readFileSync(header, "utf8");
  const modelText = readFileSync(model, "utf8");
  assert.match(headerText, /ISAAC_ANM2_LIST_FIND_A_VA = 0x00413bf0u/);
  assert.match(headerText, /ISAAC_ANM2_LIST_FIND_A_END_VA = 0x00413c61u/);
  assert.match(headerText, /ISAAC_ANM2_LIST_FIND_A_BODY_BYTES = 0x72u/);
  assert.match(headerText, /ISAAC_ANM2_LIST_FIND_A_HEAD_OFF = 0x20u/);
  assert.match(headerText, /ISAAC_ANM2_LIST_FIND_A_NEXT_OFF = 0x18u/);
  assert.match(headerText, /ISAAC_ANM2_LIST_FIND_B_VA = 0x00413c70u/);
  assert.match(headerText, /ISAAC_ANM2_LIST_FIND_B_END_VA = 0x00413cdfu/);
  assert.match(headerText, /ISAAC_ANM2_LIST_FIND_B_BODY_BYTES = 0x70u/);
  assert.match(headerText, /ISAAC_ANM2_LIST_FIND_B_HEAD_OFF = 0x18u/);
  assert.match(headerText, /ISAAC_ANM2_LIST_FIND_B_NEXT_OFF = 0x2cu/);
  assert.match(headerText, /ISAAC_ANM2_LIST_FIND_EMPTY_GLOBAL = 0x00c71640u/);
  assert.match(headerText, /IsaacAnm2ListFindPlan; \/\* 12 x 4 = 48 bytes \*\//);
  assert.match(modelText, /ANM2_LIST_FIND_A_VA = 0x00413bf0/);
  assert.match(modelText, /ANM2_LIST_FIND_B_VA = 0x00413c70/);
  assert.match(modelText, /export function anm2ListFindPlan/);
  const sourceText = readFileSync(source, "utf8");
  assert.match(sourceText, /ISAAC_ANM2_NO_NARROW_PARAMS\(isaac_anm2_list_find_a_plan\)/);
  assert.match(sourceText, /ISAAC_ANM2_NO_NARROW_PARAMS\(isaac_anm2_list_find_b_plan\)/);
  COUNT.cases += 1;
});

test("v65 unit: mutations are caught by the pins", () => {
  const sha256 = (txt) =>
    createHash("sha256").update(txt, "utf8").digest("hex");
  const originalBuf = readFileSync(source);
  const originalHash = sha256(originalBuf.toString("utf8"));
  const original = originalBuf.toString("utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const withMutant = (label, mutate, check, probe) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      wasm = loadExports();
      wmem = new Uint8Array(wasm.memory.buffer);
      if (probe) {
        const diverged = probe();
        assert.ok(diverged, `${label}: rebuilt module not mutant (stale build)`);
      }
      check();
    } catch {
      threw = true;
    }
    writeSourceRetry(original);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  buildV65World([["Cursor"], ["Death"]]);
  const needleCursor = V65_STRS + 0x100;
  pokeCString(needleCursor, "Cursor");
  try {
    /* M1 (twin A): next offset 0x18 -> 0x1c -- the machine walks
       [node+0x18] (0x413c4a). */
    withMutant("find-a next off 0x1c",
      (s) => s.replace(
        "anm2_list_find_impl(this_addr, needle_addr,\n" +
        "                      static_cast<uint32_t>(ISAAC_ANM2_LIST_FIND_A_HEAD_OFF),\n" +
        "                      static_cast<uint32_t>(ISAAC_ANM2_LIST_FIND_A_NEXT_OFF),\n" +
        "                      out);",
        "anm2_list_find_impl(this_addr, needle_addr,\n" +
        "                      static_cast<uint32_t>(ISAAC_ANM2_LIST_FIND_A_HEAD_OFF),\n" +
        "                      0x1cu,\n" +
        "                      out);"),
      () => {
        const { p } = runV65Find("a", V65_THIS_A, needleCursor);
        eq(p.found, 1, "cursor still found on node1");
        const needleDeath = V65_STRS + 0x120;
        pokeCString(needleDeath, "Death");
        const r = runV65Find("a", V65_THIS_A, needleDeath);
        eq(r.p.found, 1, "death reachable via +0x18 walk");
      },
      () => {
        const needleDeath = V65_STRS + 0x120;
        pokeCString(needleDeath, "Death");
        wasm.isaac_anm2_list_find_a_plan(V65_THIS_A, needleDeath, V65_PLAN);
        return readPlanU32At(V65_PLAN, 6 * 4) !== 2; /* walked_count */
      });
    /* M2 (twin B): head offset 0x18 -> 0x1c -- the machine reads
       [this+0x18] (0x413c89). */
    withMutant("find-b head off 0x1c",
      (s) => s.replace(
        "static_cast<uint32_t>(ISAAC_ANM2_LIST_FIND_B_HEAD_OFF),",
        "0x1cu,"),
      () => {
        const { p } = runV65Find("b", V65_THIS_B, needleCursor);
        eq(p.head >>> 0, V65_NODES + 0x180, "B head from [this+0x18]");
      },
      () => {
        wasm.isaac_anm2_list_find_b_plan(V65_THIS_B, needleCursor, V65_PLAN);
        return readPlanU32At(V65_PLAN, 3 * 4) !== (V65_NODES + 0x180) >>> 0;
      });
    /* M3 (shared walk): length compare off-by-one -- the machine matches
       iff cmpLen == strlen(needle) (0x413c25). */
    withMutant("find len compare +1",
      (s) => s.replace(
        "    if (cmp_len == len &&\n",
        "    if (cmp_len == len + 1u &&\n"),
      () => {
        const { p } = runV65Find("a", V65_THIS_A, needleCursor);
        eq(p.found, 1, "exact-length match");
      },
      () => {
        wasm.isaac_anm2_list_find_a_plan(V65_THIS_A, needleCursor, V65_PLAN);
        return readPlanU32At(V65_PLAN, 4 * 4) !== 1;
      });
    /* M4 (null-needle posture): raw-head return dropped -- the machine
       returns [this+head_off] for a null needle (0x413c5a). */
    withMutant("find null needle result 0",
      (s) => s.replace(
        "    /* Null needle: the machine returns the RAW head (ret 0xc). */\n" +
        "    plan.result = plan.head;",
        "    /* Null needle: the machine returns the RAW head (ret 0xc). */\n" +
        "    plan.result = 0u;"),
      () => {
        const { p } = runV65Find("a", V65_THIS_A, 0);
        eq(p.result >>> 0, V65_NODES, "null needle returns raw head");
      },
      () => {
        wasm.isaac_anm2_list_find_a_plan(V65_THIS_A, 0, V65_PLAN);
        return readPlanU32At(V65_PLAN, 5 * 4) !== V65_NODES;
      });
  } finally {
    writeSourceRetry(original);
  }
  wasm = loadExports(); /* clean rebuild after the round-trip */
  wmem = new Uint8Array(wasm.memory.buffer);
  /* sha256-identical restore proof. */
  const restoredHash = sha256(readFileSync(source).toString("utf8"));
  eq(restoredHash, originalHash, "source restored sha256-identical");
  COUNT.cases += 4;
});

/* =========== v66 unit: 0x00413cf0 manager seek ============================ */

/* Own scratch base (v65 hardening rule): footprint ~0xc00 bytes. */
const V66_BASE = SCRATCH_HI - 0x2000;    /* 0x11e000 (< SCRATCH_HI) */
const V66_THIS = V66_BASE + 0x0100;      /* manager object */
const V66_PLAN = V66_BASE + 0x0300;      /* plan (34 x 4 = 136 bytes) */
const V66_CELLS = V66_BASE + 0x0500;     /* pointed-to cells */
const V66_OUT = V66_BASE + 0x0700;       /* out struct (16 bytes) */

const V66_FIELDS = [
  "entered", "thisAddr", "xLo", "xHi", "yLo", "yHi", "flags",
  "reqLo", "reqHi", "posLo", "limHi", "limitLo", "limitHi",
  "aVal", "cVal", "maxUpdated", "ok", "newLo",
  "abApplied", "abAAddr", "abAValue", "abBAddr", "abBValue",
  "cdApplied", "cdPosAddr", "cdPosValue", "cdCAddr", "cdCValue",
  "cdDAddr", "cdDValue", "outLo", "outHi", "pureComplete", "hostCallCount",
];

function readV66Plan(base) {
  return readPlanFields(base, {
    entered: 0, thisAddr: 4, xLo: 8, xHi: 12, yLo: 16, yHi: 20, flags: 24,
    reqLo: 28, reqHi: 32, posLo: 36, limHi: 40, limitLo: 44, limitHi: 48,
    aVal: 52, cVal: 56, maxUpdated: 60, ok: 64, newLo: 68,
    abApplied: 72, abAAddr: 76, abAValue: 80, abBAddr: 84, abBValue: 88,
    cdApplied: 92, cdPosAddr: 96, cdPosValue: 100, cdCAddr: 104,
    cdCValue: 108, cdDAddr: 112, cdDValue: 116,
    outLo: 120, outHi: 124, pureComplete: 128, hostCallCount: 132,
  }, {
    entered: "i", thisAddr: "u", xLo: "u", xHi: "u", yLo: "u", yHi: "u",
    flags: "u", reqLo: "u", reqHi: "u", posLo: "u", limHi: "u",
    limitLo: "u", limitHi: "u", aVal: "u", cVal: "u", maxUpdated: "i",
    ok: "i", newLo: "u", abApplied: "i", abAAddr: "u", abAValue: "u",
    abBAddr: "u", abBValue: "u", cdApplied: "i", cdPosAddr: "u",
    cdPosValue: "u", cdCAddr: "u", cdCValue: "u", cdDAddr: "u",
    cdDValue: "u", outLo: "u", outHi: "u", pureComplete: "i",
    hostCallCount: "i",
  });
}

/* Seed a manager object + pointed-to cells.
   cfg: {pos, lim, aVal, cVal, cPtrNull, flagByte, dVal} */
function seedV66(cfg) {
  const aPtr = V66_CELLS;
  const cPtr = V66_CELLS + 0x10;
  const bPtr = V66_CELLS + 0x20;
  const dPtr = V66_CELLS + 0x30;
  const posPtr = V66_CELLS + 0x40;
  pokeU32(V66_THIS + 0x0c, posPtr);
  pokeU32(posPtr, cfg.pos);
  pokeU32(V66_THIS + 0x10, V66_CELLS + 0x50);   /* pos cell for arm C/D */
  pokeU32(V66_THIS + 0x1c, aPtr);
  pokeU32(aPtr, cfg.aVal);
  pokeU32(V66_THIS + 0x20, cfg.cPtrNull ? 0 : cPtr);
  if (!cfg.cPtrNull) pokeU32(cPtr, cfg.cVal);
  pokeU32(V66_THIS + 0x2c, bPtr);
  pokeU32(bPtr, 0);
  pokeU32(V66_THIS + 0x30, dPtr);
  pokeU32(dPtr, cfg.dVal);
  pokeU32(V66_THIS + 0x38, cfg.lim);
  pokeU32(V66_THIS + 0x3c, cfg.flagByte);
  return { aPtr, bPtr, cPtr, dPtr };
}

function runV66Seek(xLo, xHi, yLo, yHi, flags) {
  wasm.isaac_anm2_mgr_seek_plan(
    V66_THIS, xLo, xHi, yLo, yHi, flags, V66_PLAN);
  const p = readV66Plan(V66_PLAN);
  const o = numify(anm2MgrSeekPlan(shadow, {
    thisAddr: V66_THIS, xLo, xHi, yLo, yHi, flags,
  }));
  return { p, o };
}

test("v66 unit: constants + census pins + fixed edges (manager seek)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  /* loud export presence check BEFORE any behavioural assertion */
  assert.equal(typeof wasm.isaac_anm2_mgr_seek_plan, "function",
               "EXPORTS: isaac_anm2_mgr_seek_plan");

  eq(ANM2_MGR_SEEK_VA, 0x00413cf0);
  eq(ANM2_MGR_SEEK_END_VA, 0x00413df0);
  eq(ANM2_MGR_SEEK_BODY_BYTES, 0x100);
  eq(ANM2_MGR_SEEK_CALLSITE_COUNT, 0);
  eq(ANM2_MGR_SEEK_ADDR_TAKEN, 1);
  eq(ANM2_MGR_SEEK_VTABLE_SLOT_VA, 0x00b1b1bc);
  eq(ANM2_MGR_SEEK_RET_BYTES, 0x20);
  eq(ANM2_MGR_SEEK_FLAG_MASK, 2);

  /* Simple success: no flags, in-bounds. pos=0x100 lim=0x200
     req = X+Y = 0x30+0x50 = 0x80 <= 0x200 -> ok. */
  let cells = seedV66({ pos: 0x100, lim: 0x200, aVal: 7, cVal: 9,
                        flagByte: 0, dVal: 11 });
  let { p, o } = runV66Seek(0x30, 0, 0x50, 0, 0);
  eqV58PlanFields(p, o, V66_FIELDS, "seek simple");
  eq(p.entered, 1, "entered");
  eq(p.reqLo >>> 0, 0x80, "req64 = X + Y with carry chain");
  eq(p.reqHi >>> 0, 0, "req hi");
  eq(p.posLo >>> 0, 0x100, "pos_lo from *[*[this+0xc]]");
  eq(p.limHi >>> 0, 0x200, "lim_hi");
  eq(p.limitLo >>> 0, 0x200 - 0x100, "limit_lo = lim - pos");
  eq(p.limitHi >>> 0, 0, "limit_hi sext");
  eq(p.aVal >>> 0, 7, "a_val");
  eq(p.cVal >>> 0, 9, "c_val loaded when flag bit1 clear");
  eq(p.maxUpdated, 0, "no max update (lim >= c)");
  eq(p.ok, 1, "in bounds");
  eq(p.newLo >>> 0, 0x180, "new_lo = pos + req");
  eq(p.abApplied, 0, "arm A/B off (flags 0)");
  eq(p.cdApplied, 0, "arm C/D off (flags 0)");
  eq(p.outLo >>> 0, 0x80, "out = req on success");
  eq(p.outHi >>> 0, 0, "out hi");

  /* THE behavioural assertion: bounds fail -> {-1,-1} sentinels. */
  ({ p, o } = runV66Seek(0xfffffff0, 0, 0x50, 0, 0));
  eqV58PlanFields(p, o, V66_FIELDS, "seek bounds fail");
  eq(p.ok, 0, "req > limit fails");
  eq(p.outLo >>> 0, 0xffffffff, "fail sentinel lo");
  eq(p.outHi >>> 0, 0xffffffff, "fail sentinel hi");

  /* Max-update arm: lim < c_val and flag byte bit1 CLEAR -> lim := c_val. */
  cells = seedV66({ pos: 0x10, lim: 5, aVal: 1, cVal: 0x400,
                    flagByte: 0, dVal: 3 });
  ({ p, o } = runV66Seek(0x20, 0, 0, 0, 0));
  eqV58PlanFields(p, o, V66_FIELDS, "seek max update");
  eq(p.maxUpdated, 1, "[this+0x38] := c_val fired");
  eq(p.limHi >>> 0, 0x400, "lim_hi after max update");
  /* limit now = 0x400 - 0x10 = 0x3f0; req 0x20 ok. */
  eq(p.ok, 1, "in bounds after update");

  /* Flag-gate failures (only when req != 0): flags&1 needs a_val != 0. */
  seedV66({ pos: 0x10, lim: 0x400, aVal: 0, cVal: 9, flagByte: 0, dVal: 3 });
  ({ p, o } = runV66Seek(0x20, 0, 0, 0, 1));
  eqV58PlanFields(p, o, V66_FIELDS, "seek gate1 fail");
  eq(p.ok, 0, "flags&1 with a_val == 0 fails");
  eq(p.outLo >>> 0, 0xffffffff, "gate fail sentinel");

  /* flags&2 needs c_val != 0. */
  seedV66({ pos: 0x10, lim: 0x400, aVal: 5, cVal: 0, flagByte: 0, dVal: 3 });
  ({ p, o } = runV66Seek(0x20, 0, 0, 0, 2));
  eqV58PlanFields(p, o, V66_FIELDS, "seek gate2 fail");
  eq(p.ok, 0, "flags&2 with c_val == 0 fails");

  /* Gates SKIPPED when req == 0 (machine: je 0x413d69). */
  seedV66({ pos: 0x10, lim: 0x400, aVal: 0, cVal: 0, flagByte: 0, dVal: 3 });
  ({ p, o } = runV66Seek(0, 0, 0, 0, 3));
  eqV58PlanFields(p, o, V66_FIELDS, "seek zero-req gates skipped");
  eq(p.ok, 1, "req == 0 skips both gates");

  /* Arm A/B fires iff flags&1 && a_val != 0. */
  seedV66({ pos: 0x100, lim: 0x400, aVal: 7, cVal: 9, flagByte: 0, dVal: 11 });
  ({ p, o } = runV66Seek(0x40, 0, 0, 0, 1));
  eqV58PlanFields(p, o, V66_FIELDS, "seek arm AB");
  eq(p.abApplied, 1, "arm A/B fired");
  eq(p.abAAddr >>> 0, cells.aPtr, "A store address = *[this+0x1c]");
  eq(p.abAValue >>> 0, 0x140, "A store value = new_lo");
  eq(p.abBAddr >>> 0, cells.bPtr, "B store address = *[this+0x2c]");
  eq(p.abBValue >>> 0, 0x400 - 0x140, "B store value = lim - new_lo");
  eq(p.cdApplied, 0, "arm C/D off");

  /* Arm C/D fires iff flags&2 && c_val != 0. old_c=9 old_d=11
     new_lo = 0x140 -> D value = (9+11) - 0x140 (wraps). */
  seedV66({ pos: 0x100, lim: 0x400, aVal: 7, cVal: 9, flagByte: 0, dVal: 11 });
  ({ p, o } = runV66Seek(0x40, 0, 0, 0, 2));
  eqV58PlanFields(p, o, V66_FIELDS, "seek arm CD");
  eq(p.cdApplied, 1, "arm C/D fired");
  eq(p.cdPosAddr >>> 0, V66_CELLS + 0x50, "C/D pos cell = [this+0x10]");
  eq(p.cdPosValue >>> 0, 0x100, "pos cell value = pos_lo");
  eq(p.cdCAddr >>> 0, cells.cPtr, "C store address");
  eq(p.cdCValue >>> 0, 0x140, "C store value = new_lo");
  eq(p.cdDAddr >>> 0, cells.dPtr, "D store address");
  eq(p.cdDValue >>> 0, (9 + 11 - 0x140) >>> 0, "D store value = old sums - new_lo");

  /* Manager flag byte bit1 SET forces c_val = 0 (no load, no max-update). */
  seedV66({ pos: 0x10, lim: 5, aVal: 1, cVal: 0x400,
            flagByte: 2, dVal: 3 });
  ({ p, o } = runV66Seek(0x20, 0, 0, 0, 0));
  eqV58PlanFields(p, o, V66_FIELDS, "seek mgr flag2 set");
  eq(p.cVal >>> 0, 0, "c_val forced 0 when [this+0x3c]&2");
  eq(p.maxUpdated, 0, "no max update when flag set");
  eq(p.limHi >>> 0, 5, "lim unchanged");

  /* null this -> v42 zeroed posture. */
  wasm.isaac_anm2_mgr_seek_plan(0, 1, 0, 0, 0, 0, V66_PLAN);
  const z = readV66Plan(V66_PLAN);
  eq(z.entered, 0, "null this not entered");
  eq(z.pureComplete, 1, "zeroed posture still pure_complete");

  wasm.isaac_anm2_mgr_seek_plan(V66_THIS, 0, 0, 0, 0, 0, 0); /* null out */

  eq(wasm.isaac_anm2_pure_helpers_abi_version(), 77, "ABI 73 export");
  COUNT.cases += 70;
});

test("v66 unit: randomized differential (wasm vs oracle)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  assert.equal(typeof wasm.isaac_anm2_mgr_seek_plan, "function");
  const rng = makeRng(0x413cf0);
  for (let t = 0; t < 120; ++t) {
    seedV66({
      pos: rng.u32() & 0xffff,
      lim: rng.u32() & 0xffff,
      aVal: rng.u32() % 3 === 0 ? 0 : rng.u32() & 0xff,
      cVal: rng.u32() % 3 === 0 ? 0 : rng.u32() & 0xff,
      cPtrNull: rng.u32() % 7 === 0,
      flagByte: rng.u32() % 2 === 0 ? 0 : 2,
      dVal: rng.u32() & 0xff,
    });
    const xLo = rng.u32() % 0x30000;
    const yLo = rng.u32() % 0x30000;
    const flags = rng.u32() % 4;
    const { p, o } = runV66Seek(xLo, 0, yLo, 0, flags);
    eqV58PlanFields(p, o, V66_FIELDS, `seek t${t}`);
  }
  COUNT.cases += 120;
});

test("v66 unit: header + model pins hold", () => {
  const headerText = readFileSync(header, "utf8");
  const modelText = readFileSync(model, "utf8");
  assert.match(headerText, /ISAAC_ANM2_MGR_SEEK_VA = 0x00413cf0u/);
  assert.match(headerText, /ISAAC_ANM2_MGR_SEEK_END_VA = 0x00413df0u/);
  assert.match(headerText, /ISAAC_ANM2_MGR_SEEK_BODY_BYTES = 0x100u/);
  assert.match(headerText, /ISAAC_ANM2_MGR_SEEK_CALLSITE_COUNT = 0/);
  assert.match(headerText, /ISAAC_ANM2_MGR_SEEK_ADDR_TAKEN = 1/);
  assert.match(headerText, /ISAAC_ANM2_MGR_SEEK_VTABLE_SLOT_VA = 0x00b1b1bcu/);
  assert.match(headerText, /ISAAC_ANM2_MGR_SEEK_RET_BYTES = 0x20u/);
  assert.match(headerText, /IsaacAnm2MgrSeekPlan; \/\* 34 x 4 = 136 bytes \*\//);
  assert.match(modelText, /ANM2_MGR_SEEK_VA = 0x00413cf0/);
  assert.match(modelText, /export function anm2MgrSeekPlan/);
  const sourceText = readFileSync(source, "utf8");
  assert.match(sourceText, /ISAAC_ANM2_NO_NARROW_PARAMS\(isaac_anm2_mgr_seek_plan\)/);
  assert.match(sourceText, /static_assert\(sizeof\(IsaacAnm2MgrSeekPlan\) == 136/);
  COUNT.cases += 1;
});

test("v66 unit: mutations are caught by the pins", () => {
  const sha256 = (txt) =>
    createHash("sha256").update(txt, "utf8").digest("hex");
  const originalBuf = readFileSync(source);
  const originalHash = sha256(originalBuf.toString("utf8"));
  const original = originalBuf.toString("utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const withMutant = (label, mutate, check, probe) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      wasm = loadExports();
      wmem = new Uint8Array(wasm.memory.buffer);
      if (probe) {
        const diverged = probe();
        assert.ok(diverged, `${label}: rebuilt module not mutant (stale build)`);
      }
      check();
    } catch {
      threw = true;
    }
    writeSourceRetry(original);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    /* M1: carry chain dropped -- the machine's adc folds the x+y hi
       carry into req_hi (0x413d0a adc). */
    withMutant("seek carry dropped",
      (s) => s.replace(
        "  plan.req_hi = x_hi + y_hi + (plan.req_lo < x_lo ? 1u : 0u);",
        "  plan.req_hi = x_hi + y_hi;"),
      () => {
        seedV66({ pos: 0, lim: 0xffffffff, aVal: 1, cVal: 1,
                  flagByte: 0, dVal: 1 });
        const { p } = runV66Seek(0xffffffff, 0, 2, 0, 0);
        eq(p.reqHi >>> 0, 1, "carry folded into req_hi");
      },
      () => {
        wasm.isaac_anm2_mgr_seek_plan(
          V66_THIS, 0xffffffff, 0, 2, 0, 0, V66_PLAN);
        return readPlanU32At(V66_PLAN, 8 * 4) !== 1;
      });
    /* M2: bounds polarity -- the machine FAILS when req >u limit
       (ja 0x413dc2 @ 0x413d43). Invert to fail when LESS. */
    withMutant("seek bounds inverted",
      (s) => s.replace(
        "  if (plan.req_hi > plan.limit_hi) {\n" +
        "    ok = 0;\n" +
        "  } else if (plan.req_hi == plan.limit_hi && plan.req_lo > plan.limit_lo) {\n" +
        "    ok = 0;\n" +
        "  }",
        "  if (plan.req_hi < plan.limit_hi) {\n" +
        "    ok = 0;\n" +
        "  } else if (plan.req_hi == plan.limit_hi && plan.req_lo < plan.limit_lo) {\n" +
        "    ok = 0;\n" +
        "  }"),
      () => {
        seedV66({ pos: 0x100, lim: 0x200, aVal: 7, cVal: 9,
                  flagByte: 0, dVal: 11 });
        const { p } = runV66Seek(0x30, 0, 0x50, 0, 0);
        eq(p.ok, 1, "in-bounds seek passes");
      },
      () => {
        wasm.isaac_anm2_mgr_seek_plan(
          V66_THIS, 0x30, 0, 0x50, 0, 0, V66_PLAN);
        return readPlanU32At(V66_PLAN, 17 * 4) !== 1;
      });
    /* M3: max-update comparison jae -> ja -- the machine updates when
       cur_lim < c_val STRICTLY (unsigned jae skip @ 0x413d29). */
    withMutant("seek max update non-strict",
      (s) => s.replace(
        "    if (c_val != 0u && cur_lim < c_val) {",
        "    if (c_val != 0u && cur_lim <= c_val) {"),
      () => {
        seedV66({ pos: 0x10, lim: 0x400, aVal: 1, cVal: 0x400,
                  flagByte: 0, dVal: 3 });
        const { p } = runV66Seek(0x20, 0, 0, 0, 0);
        eq(p.maxUpdated, 0, "equal lim/c does NOT update");
      },
      () => {
        wasm.isaac_anm2_mgr_seek_plan(
          V66_THIS, 0x20, 0, 0, 0, 0, V66_PLAN);
        return readPlanU32At(V66_PLAN, 15 * 4) !== 0;
      });
    /* M4: fail sentinel -1 -> 0 -- the machine writes 0xffffffff pairs
       on the fail path (0x413dc5). */
    withMutant("seek fail sentinel 0",
      (s) => s.replace(
        "    plan.out_lo = 0xffffffffu;\n" +
        "    plan.out_hi = 0xffffffffu;",
        "    plan.out_lo = 0u;\n" +
        "    plan.out_hi = 0u;"),
      () => {
        seedV66({ pos: 0x100, lim: 0x200, aVal: 7, cVal: 9,
                  flagByte: 0, dVal: 11 });
        const { p } = runV66Seek(0xfffffff0, 0, 0x50, 0, 0);
        eq(p.outLo >>> 0, 0xffffffff, "fail sentinel -1");
      },
      () => {
        wasm.isaac_anm2_mgr_seek_plan(
          V66_THIS, 0xfffffff0, 0, 0x50, 0, 0, V66_PLAN);
        return readPlanU32At(V66_PLAN, 0) === 0xdeadbeef;
      });
  } finally {
    writeSourceRetry(original);
  }
  wasm = loadExports(); /* clean rebuild after the round-trip */
  wmem = new Uint8Array(wasm.memory.buffer);
  /* sha256-identical restore proof. */
  const restoredHash = sha256(readFileSync(source).toString("utf8"));
  eq(restoredHash, originalHash, "source restored sha256-identical");
  COUNT.cases += 4;
});

/* =========== v67 unit: 0x00413e00 whence-switch seek ====================== */

/* Own scratch base (v65 hardening rule): below V66's block. */
const V67_BASE = SCRATCH_HI - 0x3000;    /* 0x11d000 (< V66_BASE) */
const V67_THIS = V67_BASE + 0x0100;
const V67_PLAN = V67_BASE + 0x0300;      /* plan (37 x 4 = 148 bytes) */
const V67_CELLS = V67_BASE + 0x0500;

const V67_FIELDS = [
  "entered", "thisAddr", "offLo", "offHi", "whence", "flags",
  "posLo", "limHi", "aVal", "cVal", "maxUpdated",
  "targetLo", "targetHi", "reqLo", "reqHi", "limitLo", "limitHi",
  "invalidWhence", "alignFail", "ok", "newLo",
  "abApplied", "abAAddr", "abAValue", "abBAddr", "abBValue",
  "cdApplied", "cdPosAddr", "cdPosValue", "cdCAddr", "cdCValue",
  "cdDAddr", "cdDValue", "outLo", "outHi", "pureComplete", "hostCallCount",
];

function readV67Plan(base) {
  return readPlanFields(base, {
    entered: 0, thisAddr: 4, offLo: 8, offHi: 12, whence: 16, flags: 20,
    posLo: 24, limHi: 28, aVal: 32, cVal: 36, maxUpdated: 40,
    targetLo: 44, targetHi: 48, reqLo: 52, reqHi: 56,
    limitLo: 60, limitHi: 64, invalidWhence: 68, alignFail: 72, ok: 76,
    newLo: 80,
    abApplied: 84, abAAddr: 88, abAValue: 92, abBAddr: 96, abBValue: 100,
    cdApplied: 104, cdPosAddr: 108, cdPosValue: 112, cdCAddr: 116,
    cdCValue: 120, cdDAddr: 124, cdDValue: 128,
    outLo: 132, outHi: 136, pureComplete: 140, hostCallCount: 144,
  }, {
    entered: "i", thisAddr: "u", offLo: "u", offHi: "u", whence: "u",
    flags: "u", posLo: "u", limHi: "u", aVal: "u", cVal: "u",
    maxUpdated: "i", targetLo: "u", targetHi: "u", reqLo: "u", reqHi: "u",
    limitLo: "u", limitHi: "u", invalidWhence: "i", alignFail: "i",
    ok: "i", newLo: "u", abApplied: "i", abAAddr: "u", abAValue: "u",
    abBAddr: "u", abBValue: "u", cdApplied: "i", cdPosAddr: "u",
    cdPosValue: "u", cdCAddr: "u", cdCValue: "u", cdDAddr: "u",
    cdDValue: "u", outLo: "u", outHi: "u", pureComplete: "i",
    hostCallCount: "i",
  });
}

function seedV67(cfg) {
  const aPtr = V67_CELLS;
  const cPtr = V67_CELLS + 0x10;
  const bPtr = V67_CELLS + 0x20;
  const dPtr = V67_CELLS + 0x30;
  const posPtr = V67_CELLS + 0x40;
  pokeU32(V67_THIS + 0x0c, posPtr);
  pokeU32(posPtr, cfg.pos);
  pokeU32(V67_THIS + 0x10, V67_CELLS + 0x50);
  pokeU32(V67_THIS + 0x1c, aPtr);
  pokeU32(aPtr, cfg.aVal);
  pokeU32(V67_THIS + 0x20, cfg.cPtrNull ? 0 : cPtr);
  if (!cfg.cPtrNull) pokeU32(cPtr, cfg.cVal);
  pokeU32(V67_THIS + 0x2c, bPtr);
  pokeU32(V67_THIS + 0x30, dPtr);
  pokeU32(dPtr, cfg.dVal);
  pokeU32(V67_THIS + 0x38, cfg.lim);
  pokeU32(V67_THIS + 0x3c, cfg.flagByte || 0);
  return { aPtr, bPtr, cPtr, dPtr };
}

function runV67(offLo, offHi, whence, flags) {
  wasm.isaac_anm2_mgr_seek2_plan(V67_THIS, offLo, offHi, whence, flags,
                                 V67_PLAN);
  const p = readV67Plan(V67_PLAN);
  const o = numify(anm2MgrSeek2Plan(shadow, {
    thisAddr: V67_THIS, offLo, offHi, whence, flags,
  }));
  return { p, o };
}

test("v67 unit: constants + census pins + fixed edges (whence seek)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  assert.equal(typeof wasm.isaac_anm2_mgr_seek2_plan, "function",
               "EXPORTS: isaac_anm2_mgr_seek2_plan");

  eq(ANM2_MGR_SEEK2_VA, 0x00413e00);
  eq(ANM2_MGR_SEEK2_END_VA, 0x00413f8f);
  eq(ANM2_MGR_SEEK2_BODY_BYTES, 0x8f);
  eq(ANM2_MGR_SEEK2_CALLSITE_COUNT, 0);
  eq(ANM2_MGR_SEEK2_ADDR_TAKEN, 1);
  eq(ANM2_MGR_SEEK2_VTABLE_SLOT_VA, 0x00b1b1b8);
  eq(ANM2_MGR_SEEK2_RET_BYTES, 0x14);
  eq(ANM2_MGR_SEEK2_ALIGN_MASK, 3);

  /* whence=0 (set): target = 0, req = off. pos=0x100 lim=0x400. */
  seedV67({ pos: 0x100, lim: 0x400, aVal: 7, cVal: 9, dVal: 11 });
  let { p, o } = runV67(0x30, 0, 0, 0);
  eqV58PlanFields(p, o, V67_FIELDS, "w0 set");
  eq(p.entered, 1, "entered");
  eq(p.targetLo >>> 0, 0, "set target 0");
  eq(p.reqLo >>> 0, 0x30, "req = off");
  eq(p.limitLo >>> 0, 0x300, "limit = lim - pos");
  eq(p.ok, 1, "in bounds");
  eq(p.newLo >>> 0, 0x130, "new_lo = pos + req");
  eq(p.outLo >>> 0, 0x30, "out = req");

  /* whence=2 (end): target = sext(lim-pos) = 0x300; req = 0x300 + off. */
  ({ p, o } = runV67(0xfffffff0, 0xffffffff, 2, 0)); /* off = -16 */
  eqV58PlanFields(p, o, V67_FIELDS, "w2 end");
  eq(p.targetLo >>> 0, 0x300, "end target = lim - pos");
  eq(p.targetHi >>> 0, 0, "end target hi");
  eq(p.reqLo >>> 0, 0x2f0, "req = target + (-16)");
  eq(p.ok, 1, "end seek in bounds");

  /* whence=1 (cur), flags&1: target = sext(a_val - pos) = 7 - 0x100. */
  seedV67({ pos: 0x100, lim: 0x400, aVal: 7, cVal: 9, dVal: 11 });
  ({ p, o } = runV67(0, 0, 1, 1));
  eqV58PlanFields(p, o, V67_FIELDS, "w1 cur a");
  eq(p.targetLo >>> 0, (7 - 0x100) >>> 0, "cur target = a_val - pos");
  eq(p.targetHi >>> 0, 0xffffffff, "negative sext hi");
  /* negative target is >u the positive limit in the machine's
     UNSIGNED 64-bit compare (PE 0x413ed5 ja) -> FAIL. */
  eq(p.ok, 0, "negative cur target exceeds UNSIGNED limit");

  /* whence=1 (cur) with a_val > pos: positive target succeeds. */
  seedV67({ pos: 0x100, lim: 0x400, aVal: 0x200, cVal: 9, dVal: 11 });
  ({ p, o } = runV67(0x50, 0, 1, 1));
  eqV58PlanFields(p, o, V67_FIELDS, "w1 cur a positive");
  eq(p.targetLo >>> 0, 0x100, "cur target = a_val - pos");
  eq(p.reqLo >>> 0, 0x150, "req = target + off");
  eq(p.ok, 1, "positive cur seek passes");

  /* whence=1, flags&2: target = sext(c_val - pos). */
  seedV67({ pos: 0x100, lim: 0x400, aVal: 7, cVal: 0x200, dVal: 11 });
  ({ p, o } = runV67(0x10, 0, 1, 2));
  eqV58PlanFields(p, o, V67_FIELDS, "w1 cur c");
  eq(p.targetLo >>> 0, 0x200 - 0x100, "cur target = c_val - pos");

  /* whence=1, no flag bits -> FAIL. */
  ({ p, o } = runV67(0x10, 0, 1, 0));
  eqV58PlanFields(p, o, V67_FIELDS, "w1 no flags");
  eq(p.ok, 0, "cur seek without flag bit fails");
  eq(p.outLo >>> 0, 0xffffffff, "fail sentinel");

  /* whence=1, flags=3 -> ALIGN GUARD fail. */
  ({ p, o } = runV67(0x10, 0, 1, 3));
  eqV58PlanFields(p, o, V67_FIELDS, "w1 align");
  eq(p.alignFail, 1, "flags&3 == 3 rejected");

  /* whence=1, flags&1, a_val == 0 && pos != 0 -> FAIL. */
  seedV67({ pos: 0x100, lim: 0x400, aVal: 0, cVal: 9, dVal: 11 });
  ({ p, o } = runV67(0x10, 0, 1, 1));
  eqV58PlanFields(p, o, V67_FIELDS, "w1 null a");
  eq(p.ok, 0, "cur seek with null a_val fails");

  /* whence=7 -> invalid. */
  ({ p, o } = runV67(0x10, 0, 7, 1));
  eqV58PlanFields(p, o, V67_FIELDS, "w7 invalid");
  eq(p.invalidWhence, 1, "invalid whence flagged");
  eq(p.ok, 0, "invalid whence fails");

  /* gates: flags&1 needs pos != 0 when req != 0 (differs from v66!). */
  seedV67({ pos: 0, lim: 0x400, aVal: 7, cVal: 9, dVal: 11 });
  ({ p, o } = runV67(0x30, 0, 0, 1));
  eqV58PlanFields(p, o, V67_FIELDS, "gate pos 0");
  eq(p.ok, 0, "flags&1 with pos == 0 fails");

  /* arm A/B fires iff flags&1 && pos != 0. */
  seedV67({ pos: 0x100, lim: 0x400, aVal: 7, cVal: 9, dVal: 11 });
  const cells = seedV67({ pos: 0x100, lim: 0x400, aVal: 7, cVal: 9, dVal: 11 });
  ({ p, o } = runV67(0x40, 0, 0, 1));
  eqV58PlanFields(p, o, V67_FIELDS, "arm AB");
  eq(p.abApplied, 1, "arm A/B fired (pos != 0)");
  eq(p.abAAddr >>> 0, cells.aPtr, "A addr");
  eq(p.abAValue >>> 0, 0x140, "A value = new_lo");
  eq(p.abBValue >>> 0, 0x400 - 0x140, "B value = lim - new_lo");

  /* arm C/D fires iff flags&2 && c_val != 0. */
  seedV67({ pos: 0x100, lim: 0x400, aVal: 7, cVal: 9, dVal: 11 });
  ({ p, o } = runV67(0x40, 0, 0, 2));
  eqV58PlanFields(p, o, V67_FIELDS, "arm CD");
  eq(p.cdApplied, 1, "arm C/D fired");
  eq(p.cdCValue >>> 0, 0x140, "C value = new_lo");
  eq(p.cdDValue >>> 0, (9 + 11 - 0x140) >>> 0, "D value = old sums - new_lo");

  /* max-update arm (shared prologue). */
  seedV67({ pos: 0x10, lim: 5, aVal: 1, cVal: 0x400, dVal: 3 });
  ({ p, o } = runV67(0, 0, 0, 0));
  eqV58PlanFields(p, o, V67_FIELDS, "max update");
  eq(p.maxUpdated, 1, "[this+0x38] := c_val fired");
  eq(p.limHi >>> 0, 0x400, "lim after update");

  /* null this -> zeroed posture. */
  wasm.isaac_anm2_mgr_seek2_plan(0, 1, 0, 0, 0, V67_PLAN);
  const z = readV67Plan(V67_PLAN);
  eq(z.entered, 0, "null this not entered");

  wasm.isaac_anm2_mgr_seek2_plan(V67_THIS, 0, 0, 0, 0, 0); /* null out */

  eq(wasm.isaac_anm2_pure_helpers_abi_version(), 77, "ABI 73 export");
  COUNT.cases += 80;
});

test("v67 unit: randomized differential (wasm vs oracle)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  assert.equal(typeof wasm.isaac_anm2_mgr_seek2_plan, "function");
  const rng = makeRng(0x413e00);
  for (let t = 0; t < 110; ++t) {
    seedV67({
      pos: rng.u32() % 3 === 0 ? 0 : rng.u32() & 0xffff,
      lim: rng.u32() & 0xffff,
      aVal: rng.u32() % 3 === 0 ? 0 : rng.u32() & 0xff,
      cVal: rng.u32() % 3 === 0 ? 0 : rng.u32() & 0xff,
      cPtrNull: rng.u32() % 7 === 0,
      dVal: rng.u32() & 0xff,
    });
    const whence = rng.u32() % 5;
    const flags = rng.u32() % 5;
    const offLo = rng.u32() % 0x30000;
    const { p, o } = runV67(offLo, 0, whence, flags);
    eqV58PlanFields(p, o, V67_FIELDS, `seek2 t${t}`);
  }
  COUNT.cases += 110;
});

test("v67 unit: header + model pins hold", () => {
  const headerText = readFileSync(header, "utf8");
  const modelText = readFileSync(model, "utf8");
  assert.match(headerText, /ISAAC_ANM2_MGR_SEEK2_VA = 0x00413e00u/);
  assert.match(headerText, /ISAAC_ANM2_MGR_SEEK2_END_VA = 0x00413f8fu/);
  assert.match(headerText, /ISAAC_ANM2_MGR_SEEK2_BODY_BYTES = 0x8fu/);
  assert.match(headerText, /ISAAC_ANM2_MGR_SEEK2_CALLSITE_COUNT = 0/);
  assert.match(headerText, /ISAAC_ANM2_MGR_SEEK2_ADDR_TAKEN = 1/);
  assert.match(headerText, /ISAAC_ANM2_MGR_SEEK2_VTABLE_SLOT_VA = 0x00b1b1b8u/);
  assert.match(headerText, /ISAAC_ANM2_MGR_SEEK2_RET_BYTES = 0x14u/);
  assert.match(headerText, /IsaacAnm2MgrSeek2Plan; \/\* 37 x 4 = 148 bytes \*\//);
  assert.match(modelText, /ANM2_MGR_SEEK2_VA = 0x00413e00/);
  assert.match(modelText, /export function anm2MgrSeek2Plan/);
  const sourceText = readFileSync(source, "utf8");
  assert.match(sourceText, /ISAAC_ANM2_NO_NARROW_PARAMS\(isaac_anm2_mgr_seek2_plan\)/);
  assert.match(sourceText, /static_assert\(sizeof\(IsaacAnm2MgrSeek2Plan\) == 148/);
  COUNT.cases += 1;
});

test("v67 unit: mutations are caught by the pins", () => {
  const sha256 = (txt) =>
    createHash("sha256").update(txt, "utf8").digest("hex");
  const originalBuf = readFileSync(source);
  const originalHash = sha256(originalBuf.toString("utf8"));
  const original = originalBuf.toString("utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const withMutant = (label, mutate, check, probe) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      wasm = loadExports();
      wmem = new Uint8Array(wasm.memory.buffer);
      if (probe) {
        const diverged = probe();
        assert.ok(diverged, `${label}: rebuilt module not mutant (stale build)`);
      }
      check();
    } catch {
      threw = true;
    }
    writeSourceRetry(original);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    /* M1: whence-2 target dropped to 0 -- the machine seeks from
       lim-pos for whence 2 (0x413e61..6a). */
    withMutant("seek2 end target 0",
      (s) => s.replace(
        "  } else if (whence == 2u) {\n" +
        "    tgt_lo = diff;",
        "  } else if (whence == 2u) {\n" +
        "    tgt_lo = 0u;"),
      () => {
        seedV67({ pos: 0x100, lim: 0x400, aVal: 7, cVal: 9, dVal: 11 });
        const { p } = runV67(0x10, 0, 2, 0);
        eq(p.targetLo >>> 0, 0x300, "end target = diff");
      },
      () => {
        wasm.isaac_anm2_mgr_seek2_plan(V67_THIS, 0x10, 0, 2, 0, V67_PLAN);
        return readPlanU32At(V67_PLAN, 11 * 4) !== 0x300;
      });
    /* M2: align mask 3 -> 1 -- the machine rejects flags&3 == 3
       (0x413e71 cmp al,3). */
    withMutant("seek2 align mask 1",
      (s) => s.replace(
        "    if ((flags & 3u) == 3u) {",
        "    if ((flags & 1u) == 1u) {"),
      () => {
        seedV67({ pos: 0x100, lim: 0x400, aVal: 7, cVal: 9, dVal: 11 });
        const { p } = runV67(0x10, 0, 1, 3);
        eq(p.alignFail, 1, "flags=3 align-fails");
      },
      () => {
        wasm.isaac_anm2_mgr_seek2_plan(V67_THIS, 0x10, 0, 1, 3, V67_PLAN);
        return readPlanU32At(V67_PLAN, 18 * 4) !== 1;
      });
    /* M3: arm A/B condition pos != 0 -> c_val != 0 -- the machine gates
       the arm on POS (0x413f0d..14), unlike the v66 seek. */
    withMutant("seek2 ab gate cval",
      (s) => s.replace(
        "    /* Arm A/B: iff flags&1 && pos_lo != 0 (0x413f0d..24). */\n" +
        "    if ((dl & 1u) != 0u && plan.pos_lo != 0u) {",
        "    /* Arm A/B: iff flags&1 && pos_lo != 0 (0x413f0d..24). */\n" +
        "    if ((dl & 1u) != 0u && plan.c_val != 0u) {"),
      () => {
        seedV67({ pos: 0, lim: 0x400, aVal: 7, cVal: 9, dVal: 11 });
        const { p } = runV67(0x10, 0, 0, 1);
        eq(p.abApplied, 0, "pos == 0 keeps arm A/B off");
      },
      () => {
        wasm.isaac_anm2_mgr_seek2_plan(V67_THIS, 0x10, 0, 0, 1, V67_PLAN);
        return readPlanU32At(V67_PLAN, 21 * 4) !== 0;
      });
    /* M4: fail sentinel -1 -> 0 (0x413f63). */
    withMutant("seek2 fail sentinel 0",
      (s) => s.replace(
        "    plan.out_lo = 0xffffffffu;\n" +
        "    plan.out_hi = 0xffffffffu;\n" +
        "  }\n" +
        "\n" +
        "  if (out != nullptr) *out = plan;\n" +
        "}\n" +
        "\n" +
        "ISAAC_ANM2_NO_NARROW_PARAMS(isaac_anm2_mgr_seek2_plan);",
        "    plan.out_lo = 0u;\n" +
        "    plan.out_hi = 0u;\n" +
        "  }\n" +
        "\n" +
        "  if (out != nullptr) *out = plan;\n" +
        "}\n" +
        "\n" +
        "ISAAC_ANM2_NO_NARROW_PARAMS(isaac_anm2_mgr_seek2_plan);"),
      () => {
        seedV67({ pos: 0x100, lim: 0x400, aVal: 7, cVal: 9, dVal: 11 });
        const { p } = runV67(0x10, 0, 1, 0);
        eq(p.outLo >>> 0, 0xffffffff, "fail sentinel -1");
      },
      () => {
        wasm.isaac_anm2_mgr_seek2_plan(V67_THIS, 0x10, 0, 1, 0, V67_PLAN);
        return readPlanU32At(V67_PLAN, 33 * 4) !== 0xffffffff;
      });
  } finally {
    writeSourceRetry(original);
  }
  wasm = loadExports(); /* clean rebuild after the round-trip */
  wmem = new Uint8Array(wasm.memory.buffer);
  /* sha256-identical restore proof. */
  const restoredHash = sha256(readFileSync(source).toString("utf8"));
  eq(restoredHash, originalHash, "source restored sha256-identical");
  COUNT.cases += 4;
});

/* =========== v68-retry: 0x00413ff0 put-char + 0x00413f90 get-byte ========= */

/* Own scratch base (v65 hardening rule): below V67's block. */
const V68_BASE = SCRATCH_HI - 0x3800;    /* 0x11c800 (< V67_BASE) */
const V68_THIS = V68_BASE + 0x0100;
const V68_PLAN = V68_BASE + 0x0300;      /* plans <= 88 bytes */
const V68_CELLS = V68_BASE + 0x0500;

const PUT_FIELDS = [
  "entered", "thisAddr", "ch", "pos", "sizeVal", "mismatch", "ok",
  "endIncApplied", "endIncAddr", "endIncValue", "posDecApplied",
  "posDecAddr", "posDecValue", "chStoreApplied", "chStoreAddr",
  "chStoreValue", "result", "pureComplete", "hostCallCount",
];
const GET_FIELDS = [
  "entered", "thisAddr", "pos", "endBase", "endVal", "directHit",
  "directByte", "refreshUsed", "eVal", "refreshFlag4Fail", "limOld",
  "limNew", "limCommitted", "endWrApplied", "endWrAddr", "endWrValue",
  "posWrApplied", "posWrAddr", "posWrValue", "result", "pureComplete",
  "hostCallCount",
];

function readPutFields(base) {
  return readPlanFields(base, {
    entered: 0, thisAddr: 4, ch: 8, pos: 12, sizeVal: 16, mismatch: 20,
    ok: 24, endIncApplied: 28, endIncAddr: 32, endIncValue: 36,
    posDecApplied: 40, posDecAddr: 44, posDecValue: 48,
    chStoreApplied: 52, chStoreAddr: 56, chStoreValue: 60,
    result: 64, pureComplete: 68, hostCallCount: 72,
  }, {
    entered: "i", thisAddr: "u", ch: "u", pos: "u", sizeVal: "u",
    mismatch: "i", ok: "i", endIncApplied: "i", endIncAddr: "u",
    endIncValue: "u", posDecApplied: "i", posDecAddr: "u",
    posDecValue: "u", chStoreApplied: "i", chStoreAddr: "u",
    chStoreValue: "u", result: "i", pureComplete: "i", hostCallCount: "i",
  });
}

function readGetFields(base) {
  return readPlanFields(base, {
    entered: 0, thisAddr: 4, pos: 8, endBase: 12, endVal: 16,
    directHit: 20, directByte: 24, refreshUsed: 28, eVal: 32,
    refreshFlag4Fail: 36, limOld: 40, limNew: 44, limCommitted: 48,
    endWrApplied: 52, endWrAddr: 56, endWrValue: 60,
    posWrApplied: 64, posWrAddr: 68, posWrValue: 72,
    result: 76, pureComplete: 80, hostCallCount: 84,
  }, {
    entered: "i", thisAddr: "u", pos: "u", endBase: "u", endVal: "u",
    directHit: "i", directByte: "u", refreshUsed: "i", eVal: "u",
    refreshFlag4Fail: "i", limOld: "u", limNew: "u", limCommitted: "i",
    endWrApplied: "i", endWrAddr: "u", endWrValue: "u", posWrApplied: "i",
    posWrAddr: "u", posWrValue: "u", result: "i", pureComplete: "i",
    hostCallCount: "i",
  });
}

/* seed manager for putc/getc. LESSON 3: every byte the oracle reads is
   seeded via poke/pokeU32 (dual wmem+shadow image). */
function seedV68(cfg) {
  const posCell = V68_CELLS;
  const sizeCell = V68_CELLS + 0x10;
  const endCell = V68_CELLS + 0x20;
  const cPtr = V68_CELLS + 0x30;
  pokeU32(V68_THIS + 0x1c, posCell);
  pokeU32(posCell, cfg.pos !== undefined ? cfg.pos : 0);
  pokeU32(V68_THIS + 0x0c, sizeCell);
  pokeU32(sizeCell, cfg.size !== undefined ? cfg.size : 0);
  pokeU32(V68_THIS + 0x2c, cfg.endNull ? 0 : endCell);
  pokeU32(endCell, cfg.end !== undefined ? cfg.end : 0);
  pokeU32(V68_THIS + 0x20, cPtr);
  pokeU32(cPtr, cfg.e !== undefined ? cfg.e : 0);
  pokeU32(V68_THIS + 0x38, cfg.lim !== undefined ? cfg.lim : 0);
  pokeU32(V68_THIS + 0x3c, cfg.flagByte || 0);
}

/* putc reads byte[pos-1]: park pos so pos-1 is always a poked byte. */
const PUT_POS = V68_CELLS + 0x61;

function runV68Putc(ch) {
  wasm.isaac_anm2_mgr_putc_plan(V68_THIS, ch, V68_PLAN);
  const p = readPutFields(V68_PLAN);
  const o = numify(anm2MgrPutcPlan(shadow, { thisAddr: V68_THIS, ch }));
  return { p, o };
}

function runV68Getc() {
  wasm.isaac_anm2_mgr_getc_plan(V68_THIS, V68_PLAN);
  const p = readGetFields(V68_PLAN);
  const o = numify(anm2MgrGetcPlan(shadow, { thisAddr: V68_THIS }));
  return { p, o };
}

test("v68-retry: constants + census pins + fixed edges (putc/get-byte)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  /* loud export presence checks BEFORE any behavioural assertion */
  assert.equal(typeof wasm.isaac_anm2_mgr_putc_plan, "function",
               "EXPORTS: isaac_anm2_mgr_putc_plan");
  assert.equal(typeof wasm.isaac_anm2_mgr_getc_plan, "function",
               "EXPORTS: isaac_anm2_mgr_getc_plan");

  eq(ANM2_MGR_PUTC_VA, 0x00413ff0);
  eq(ANM2_MGR_PUTC_END_VA, 0x00414041);
  eq(ANM2_MGR_PUTC_BODY_BYTES, 0x52);
  eq(ANM2_MGR_PUTC_CALLSITE_COUNT, 0);
  eq(ANM2_MGR_PUTC_ADDR_TAKEN, 1);
  eq(ANM2_MGR_PUTC_VTABLE_SLOT_VA, 0x00b1b1a0);
  eq(ANM2_MGR_PUTC_RET_BYTES, 4);
  eq(ANM2_MGR_GETC_VA, 0x00413f90);
  eq(ANM2_MGR_GETC_END_VA, 0x00413fe5);
  eq(ANM2_MGR_GETC_BODY_BYTES, 0x56);
  eq(ANM2_MGR_GETC_CALLSITE_COUNT, 0);
  eq(ANM2_MGR_GETC_ADDR_TAKEN, 1);
  eq(ANM2_MGR_GETC_VTABLE_SLOT_VA, 0x00b1b1a8);
  eq(ANM2_MGR_GETC_FLAG4_MASK, 4);

  /* --- put-char --- */
  /* matching byte at pos-1 -> pass; PE-ordered gate evaluated. */
  seedV68({ pos: PUT_POS, size: 0x10 });
  poke(PUT_POS - 1, [0x7e]);
  let { p, o } = runV68Putc(0x7e);
  eqV58PlanFields(p, o, PUT_FIELDS, "putc match");
  eq(p.ok, 1, "matching byte passes");
  eq(p.mismatch, 0, "no mismatch");
  eq(p.endIncApplied, 1, "end++ arm fired");
  eq(p.endIncAddr >>> 0, V68_CELLS + 0x20, "end cell address");
  eq(p.endIncValue >>> 0, 1, "end value = old 0 + 1");
  eq(p.posDecApplied, 1, "pos-- arm fired");
  eq(p.posDecAddr >>> 0, V68_CELLS, "pos cell address");
  eq(p.posDecValue >>> 0, PUT_POS - 1, "post-dec pos");
  eq(p.chStoreApplied, 1, "char store fired");
  eq(p.chStoreAddr >>> 0, PUT_POS - 1, "LESSON 2: store addr = POST-DEC pos");
  eq(p.chStoreValue >>> 0, 0x7e, "char value");
  eq(p.result, 0x7e, "result = ch");

  /* sentinel ch = -1: gate skipped entirely, no store, result 0. */
  ({ p, o } = runV68Putc(0xffffffff));
  eqV58PlanFields(p, o, PUT_FIELDS, "putc sentinel");
  eq(p.mismatch, 0, "sentinel skips gate");
  eq(p.chStoreApplied, 0, "sentinel skips store");
  eq(p.result, 0, "sentinel result 0");

  /* mismatch + flag bit1 set -> FAIL. */
  seedV68({ pos: PUT_POS, size: 0x10, flagByte: 2 });
  poke(PUT_POS - 1, [0x7e]);
  ({ p, o } = runV68Putc(0x21));
  eqV58PlanFields(p, o, PUT_FIELDS, "putc mismatch fail");
  eq(p.mismatch, 1, "mismatch detected");
  eq(p.ok, 0, "flag bit1 turns mismatch into fail");
  eq(p.result, -1, "fail result -1");

  /* mismatch WITHOUT flag -> still succeeds, result = full ch dword. */
  seedV68({ pos: PUT_POS, size: 0x10, flagByte: 0 });
  poke(PUT_POS - 1, [0x7e]);
  ({ p, o } = runV68Putc(0x21));
  eqV58PlanFields(p, o, PUT_FIELDS, "putc mismatch ok");
  eq(p.ok, 1, "no flag: mismatch tolerated");
  eq(p.result >>> 0, 0x21, "result = full ch dword");

  /* LESSON 1 behavioural edge: bounds fails SKIP the gate -- pos == 0
     with ch != -1 must NOT trap (machine je 0x413ff9 jumps past the
     [esi-1] read). A trap here throws -> test fails loudly. */
  seedV68({ pos: 0, size: 0x10 });
  ({ p, o } = runV68Putc(0x41));
  eqV58PlanFields(p, o, PUT_FIELDS, "putc pos 0");
  eq(p.ok, 0, "pos 0 fails");
  eq(p.mismatch, 0, "gate never evaluated on fail path");

  /* pos <=u size -> FAIL, gate also skipped. */
  seedV68({ pos: PUT_POS, size: 0x200000 });
  ({ p, o } = runV68Putc(0x41));
  eqV58PlanFields(p, o, PUT_FIELDS, "putc small pos");
  eq(p.ok, 0, "pos <=u size fails");

  wasm.isaac_anm2_mgr_putc_plan(V68_THIS, 0x41, 0); /* null out */

  /* --- get-byte --- */
  /* direct hit: end cell 0x40 -> endVal = 0x40 + pos > pos. */
  seedV68({ pos: PUT_POS, size: 0x10, end: 0x40 });
  poke(PUT_POS, [0x5a]);
  ({ p, o } = runV68Getc());
  eqV58PlanFields(p, o, GET_FIELDS, "getc direct");
  eq(p.directHit, 1, "direct hit when pos <u end (=*endPtr+pos)");
  eq(p.endVal >>> 0, (0x40 + PUT_POS) >>> 0, "end_val includes pos");
  eq(p.refreshUsed, 0, "no refresh");
  eq(p.result, 0x5a, "direct byte returned");

  /* refresh arm: end cell 0 -> endVal = pos -> NOT <u pos -> refresh.
     e=0x130000 grows lim past pos (pos ~0x11cd61) -> commit +
     same-value writeback. */
  seedV68({ pos: PUT_POS, size: 0x10, end: 0, e: 0x130000, lim: 0x100 });
  poke(PUT_POS, [0x5a]);
  ({ p, o } = runV68Getc());
  eqV58PlanFields(p, o, GET_FIELDS, "getc refresh");
  eq(p.refreshUsed, 1, "refresh arm used (endVal == pos)");
  eq(p.eVal >>> 0, 0x130000, "e_val");
  eq(p.limOld >>> 0, 0x100, "lim_old");
  eq(p.limNew >>> 0, 0x130000, "lim_new = max(lim, e)");
  eq(p.limCommitted, 1, "[this+0x38] committed");
  eq(p.endWrAddr >>> 0, V68_CELLS + 0x20, "end cell address");
  eq(p.endWrValue >>> 0, (0x130000 - PUT_POS) >>> 0, "end writeback = lim-pos");
  eq(p.posWrApplied, 1, "pos writeback applied");
  eq(p.posWrAddr >>> 0, V68_CELLS, "pos cell address");
  eq(p.posWrValue >>> 0, PUT_POS, "SAME-VALUE writeback");
  eq(p.result, wmem[PUT_POS], "byte re-read after refresh");

  /* refresh fail: flag4 set. */
  seedV68({ pos: PUT_POS, size: 0x10, end: 0, e: 0x300, flagByte: 4 });
  ({ p, o } = runV68Getc());
  eqV58PlanFields(p, o, GET_FIELDS, "getc flag4");
  eq(p.refreshFlag4Fail, 1, "flag4 fails refresh");
  eq(p.result, -1, "fail -1");

  /* refresh fail: e == 0. */
  seedV68({ pos: PUT_POS, size: 0x10, end: 0, e: 0 });
  ({ p, o } = runV68Getc());
  eqV58PlanFields(p, o, GET_FIELDS, "getc e 0");
  eq(p.result, -1, "e == 0 fails");

  /* refresh fail: lim_new <=u pos. */
  seedV68({ pos: PUT_POS, size: 0x10, end: 0, e: 0x50, lim: 0x40 });
  ({ p, o } = runV68Getc());
  eqV58PlanFields(p, o, GET_FIELDS, "getc lim small");
  eq(p.limNew >>> 0, 0x50, "lim_new = max(0x40, 0x50)");
  eq(p.result, -1, "lim_new <=u pos fails");

  /* pos == 0 -> FAIL. */
  seedV68({});
  ({ p, o } = runV68Getc());
  eqV58PlanFields(p, o, GET_FIELDS, "getc pos 0");
  eq(p.result, -1, "pos 0 fails");

  wasm.isaac_anm2_mgr_putc_plan(V68_THIS, 0x41, 0); /* null out */
  wasm.isaac_anm2_mgr_getc_plan(V68_THIS, 0);       /* null out */

  eq(wasm.isaac_anm2_pure_helpers_abi_version(), 77, "ABI 73 export");
  COUNT.cases += 75;
});

test("v68-retry: randomized differential (wasm vs oracle)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  assert.equal(typeof wasm.isaac_anm2_mgr_putc_plan, "function");
  assert.equal(typeof wasm.isaac_anm2_mgr_getc_plan, "function");
  const rng = makeRng((0x413ff0 ^ 0x413f90) >>> 0);
  for (let t = 0; t < 110; ++t) {
    const pos = (rng.u32() % 3 === 0 ? 0 : rng.u32() % 0x60) +
                V68_CELLS + 0x61;
    const endCellVal = rng.u32() % 3 === 0 ? 0 : rng.u32() % 0x30;
    seedV68({
      pos,
      size: rng.u32() % 4 === 0 ? pos - 1 : rng.u32() & 0xf,
      end: endCellVal,
      e: rng.u32() % 3 === 0 ? 0 : rng.u32() % 0x300,
      lim: rng.u32() % 0x200,
      flagByte: rng.u32() % 2 === 0 ? 0 : (rng.u32() % 2 === 0 ? 2 : 4),
    });
    poke(pos - 1, [rng.u32() & 0xff]);
    poke(pos, [rng.u32() & 0xff]);
    const ch = rng.u32() % 2 === 0 ? 0xffffffff : rng.u32() & 0xffff;
    const r1 = runV68Putc(ch);
    eqV58PlanFields(r1.p, r1.o, PUT_FIELDS, `putc t${t}`);
    const r2 = runV68Getc();
    eqV58PlanFields(r2.p, r2.o, GET_FIELDS, `getc t${t}`);
  }
  COUNT.cases += 110;
});

