test("v68-retry: mutations are caught by the pins", () => {
  const sha256 = (txt) =>
    createHash("sha256").update(txt, "utf8").digest("hex");
  const originalBuf = readFileSync(source);
  const originalHash = sha256(originalBuf.toString("utf8"));
  const original = originalBuf.toString("utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const withMutant = (label, mutate, check, probe) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      wasm = loadExports();
      wmem = new Uint8Array(wasm.memory.buffer);
      if (probe) {
        const diverged = probe();
        assert.ok(diverged, `${label}: rebuilt module not mutant (stale build)`);
      }
      check();
    } catch {
      threw = true;
    }
    writeSourceRetry(original);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    /* M1 (putc, LESSON 1): drop the ok short-circuit from the gate --
       the mutant then evaluates byte[pos-1] where the machine cannot
       reach it; the pos==0 world TRAPS in the mutant (divergence). */
    withMutant("putc gate ignores bounds",
      (s) => s.replace(
        "  if (ok != 0 && ch != 0xffffffffu) {",
        "  if (ch != 0xffffffffu) {"),
      () => {
        seedV68({ pos: PUT_POS, size: 0x10 });
        poke(PUT_POS - 1, [0x7e]);
        const { p } = runV68Putc(0x7e);
        eq(p.ok, 1, "match path unchanged");
      },
      () => {
        /* pos == 0, ch != -1: original returns -1; mutant traps. */
        seedV68({});
        wasm.isaac_anm2_mgr_putc_plan(V68_THIS, 0x41, V68_PLAN);
        return readPlanU32At(V68_PLAN, 16 * 4) === 0xffffffff;
      });
    /* M2 (putc, LESSON 2): un-simulate the post-dec store address --
       re-reading the stale cell was the aborted attempt's bug. */
    withMutant("putc store addr stale",
      (s) => s.replace(
        "      plan.ch_store_addr = plan.pos_dec_value;",
        "      plan.ch_store_addr = load_u32(guest_ptr(plan.pos_dec_addr));"),
      () => {
        seedV68({ pos: PUT_POS, size: 0x10 });
        poke(PUT_POS - 1, [0x7e]);
        const { p } = runV68Putc(0x7e);
        eq(p.chStoreAddr >>> 0, PUT_POS - 1, "store addr = POST-DEC pos");
      },
      () => {
        wasm.isaac_anm2_mgr_putc_plan(V68_THIS, 0x7e, V68_PLAN);
        return readPlanU32At(V68_PLAN, 14 * 4) !== PUT_POS - 1;
      });
    /* M3 (getc): end_val must INCLUDE pos -- the machine adds it
       (add eax,edx @0x413f9e..a0); dropping it flips direct->refresh. */
    withMutant("getc end val drops pos",
      (s) => s.replace(
        "    plan.end_val = end_base_val + plan.pos;  /* 0x413f9e..a0: pos ADDED */",
        "    plan.end_val = end_base_val;"),
      () => {
        seedV68({ pos: PUT_POS, size: 0x10, end: 0x40 });
        poke(PUT_POS, [0x5a]);
        const { p } = runV68Getc();
        eq(p.directHit, 1, "direct hit");
      },
      () => {
        wasm.isaac_anm2_mgr_getc_plan(V68_THIS, V68_PLAN);
        return readPlanU32At(V68_PLAN, 5 * 4) !== 1;
      });
    /* M4 (getc): cmovb max -> min -- the machine grows the limit
       (cmovb @0x413fc0 takes e only when lim <u e). */
    withMutant("getc lim min",
      (s) => s.replace(
        "      plan.lim_new = plan.lim_old < plan.e_val ? plan.e_val : plan.lim_old;",
        "      plan.lim_new = plan.lim_old < plan.e_val ? plan.lim_old : plan.e_val;"),
      () => {
        seedV68({ pos: PUT_POS, size: 0x10, end: 0, e: 0x300, lim: 0x100 });
        poke(PUT_POS, [0x5a]);
        const { p } = runV68Getc();
        eq(p.limNew >>> 0, 0x300, "lim_new = max");
      },
      () => {
        wasm.isaac_anm2_mgr_getc_plan(V68_THIS, V68_PLAN);
        return readPlanU32At(V68_PLAN, 11 * 4) !== 0x300;
      });
  } finally {
    writeSourceRetry(original);
  }
  wasm = loadExports(); /* clean rebuild after the round-trip */
  wmem = new Uint8Array(wasm.memory.buffer);
  /* sha256-identical restore proof. */
  const restoredHash = sha256(readFileSync(source).toString("utf8"));
  eq(restoredHash, originalHash, "source restored sha256-identical");
  COUNT.cases += 4;
});

/* =========== v71 unit: 0x004143f0 + 0x00414410 tiny getters =============== */

/* Pure scalar laws: no scratch, no pokes. */

function runV71Stride(base, arg) {
  wasm.isaac_anm2_stride24_offset(base, arg);
  return { w: wasm.isaac_anm2_stride24_offset(base, arg),
           o: anm2Stride24Offset(base, arg) >>> 0 };
}

function runV71Div3(lo, hi) {
  const w = wasm.isaac_anm2_diff_div24(lo, hi) | 0;
  const o = anm2DiffDiv24(lo, hi) | 0;
  return { w, o };
}

test("v71 unit: constants + census pins + fixed edges (tiny getters)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  /* loud export presence checks BEFORE any behavioural assertion */
  assert.equal(typeof wasm.isaac_anm2_stride24_offset, "function",
               "EXPORTS: isaac_anm2_stride24_offset");
  assert.equal(typeof wasm.isaac_anm2_diff_div24, "function",
               "EXPORTS: isaac_anm2_diff_div24");

  eq(ANM2_STRIDE24_GETTER_VA, 0x004143f0);
  eq(ANM2_STRIDE24_GETTER_END_VA, 0x00414401);
  eq(ANM2_STRIDE24_GETTER_BODY_BYTES, 0x12);
  eq(ANM2_STRIDE24_GETTER_CALLSITE_COUNT, 0);
  eq(ANM2_STRIDE24_GETTER_ADDR_TAKEN, 0);
  eq(ANM2_STRIDE24_GETTER_STRIDE, 24);
  eq(ANM2_STRIDE24_GETTER_RET_BYTES, 4);
  eq(ANM2_DIFF_DIV24_VA, 0x00414410);
  eq(ANM2_DIFF_DIV24_END_VA, 0x00414426);
  eq(ANM2_DIFF_DIV24_BODY_BYTES, 0x17);
  eq(ANM2_DIFF_DIV24_CALLSITE_COUNT, 0);
  eq(ANM2_DIFF_DIV24_ADDR_TAKEN, 0);
  eq(ANM2_DIFF_DIV24_MAGIC, 0x2aaaaaab);
  eq(ANM2_DIFF_DIV24_SHIFT, 2);

  /* stride-24 getter fixed edges. */
  eq(wasm.isaac_anm2_stride24_offset(0x100000, 0) >>> 0, 0x100000,
     "arg 0 -> base");
  eq(wasm.isaac_anm2_stride24_offset(0x100000, 1) >>> 0, 0x100018,
     "arg 1 -> base+24");
  eq(wasm.isaac_anm2_stride24_offset(0x100000, 3) >>> 0, 0x100048,
     "arg 3 -> base+72");
  /* wrap edge: arg*24 == 0 mod 2^32 when arg = 0x40000000 (6*2^32). */
  eq(wasm.isaac_anm2_stride24_offset(0x1234, 0x40000000) >>> 0, 0x1234,
     "LESSON/wrap: arg*24 wraps to 0");
  /* negative-ish arg: 0xffffffff * 24 = -24 mod 2^32. */
  eq(wasm.isaac_anm2_stride24_offset(0x1000, 0xffffffff) >>> 0,
     (0x1000 - 24) >>> 0, "arg -1 -> base-24");
  let r = runV71Stride(0x100000, 7);
  eq(r.w >>> 0, r.o >>> 0, "stride oracle agrees");

  /* div-by-24 fixed edges -- BYTE-VERIFIED semantics: d=3 -> 0,
     d=24 -> 1 (the MSVC /24 pattern, NOT /3). Truncation vs floor is
     THE discriminator on negatives. */
  eq(wasm.isaac_anm2_diff_div24(0, 0) | 0, 0, "d=0");
  eq(wasm.isaac_anm2_diff_div24(0, 3) | 0, 0, "d=3 -> 0 (/24)");
  eq(wasm.isaac_anm2_diff_div24(0, 24) | 0, 1, "d=24 -> 1");
  eq(wasm.isaac_anm2_diff_div24(0, 48) | 0, 2, "d=48 -> 2");
  eq(wasm.isaac_anm2_diff_div24(0, 23) | 0, 0, "d=23 -> 0 (trunc)");
  eq(wasm.isaac_anm2_diff_div24(24, 0) | 0, -1,
     "d=-24 -> -1 (trunc; dropping sign-add gives -2)");
  eq(wasm.isaac_anm2_diff_div24(48, 0) | 0, -2, "d=-48 -> -2");
  eq(wasm.isaac_anm2_diff_div24(25, 0) | 0, -1,
     "d=-25 -> -1 (trunc toward zero)");
  r = runV71Div3(72, 0);
  eq(r.w, r.o, "div24 oracle agrees (negative d=-72 -> -3)");

  eq(wasm.isaac_anm2_pure_helpers_abi_version(), 77, "ABI 73 export");
  COUNT.cases += 30;
});

