test("v71 unit: mutations are caught by the pins", () => {
  const sha256 = (txt) =>
    createHash("sha256").update(txt, "utf8").digest("hex");
  const originalBuf = readFileSync(source);
  const originalHash = sha256(originalBuf.toString("utf8"));
  const original = originalBuf.toString("utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const withMutant = (label, mutate, check, probe) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      wasm = loadExports();
      wmem = new Uint8Array(wasm.memory.buffer);
      if (probe) {
        const diverged = probe();
        assert.ok(diverged, `${label}: rebuilt module not mutant (stale build)`);
      }
      check();
    } catch {
      threw = true;
    }
    writeSourceRetry(original);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    /* M1 (stride): scale *8 -> *4 -- the machine's second lea uses
       edx*8 (0x4143fb); result = base + arg*12 in the mutant. */
    withMutant("stride x8 to x4",
      (s) => s.replace(
        "  return base + (triple * 8u);",
        "  return base + (triple * 4u);"),
      () => {
        eq(wasm.isaac_anm2_stride24_offset(0x100000, 1) >>> 0, 0x100018,
           "arg 1 -> base+24");
      },
      () => wasm.isaac_anm2_stride24_offset(0x100000, 1) !== 0x100018);
    /* M2 (stride): base dropped -- the machine adds [ecx]
       (mov eax,[ecx] @0x4143f9). */
    withMutant("stride base dropped",
      (s) => s.replace(
        "  return base + (triple * 8u);",
        "  return triple * 8u;"),
      () => {
        eq(wasm.isaac_anm2_stride24_offset(0x100000, 0) >>> 0, 0x100000,
           "arg 0 -> base");
      },
      () => wasm.isaac_anm2_stride24_offset(0x100000, 0) !== 0x100000);
    /* M3 (div24): sar 2 -> sar 1 -- wrong quotient scale
       (sar edx,2 @0x41441c). d=24 must give 1. */
    withMutant("div24 sar 1",
      (s) => s.replace(
        "  high >>= 2;",
        "  high >>= 1;"),
      () => {
        eq(wasm.isaac_anm2_diff_div24(0, 24) | 0, 1, "d=24 -> 1");
      },
      () => wasm.isaac_anm2_diff_div24(0, 24) !== 1);
    /* M4 (div24): sign-correction dropped -- result becomes floor for
       negatives; the machine ADDS the sign bit (add eax,edx
       @0x414424). d = -24 must give -1, not -2. */
    withMutant("div24 floor not trunc",
      (s) => s.replace(
        "  const uint32_t sign = static_cast<uint32_t>(high) >> 31;\n" +
        "  return static_cast<int32_t>(static_cast<uint32_t>(high) + sign);",
        "  return high;"),
      () => {
        eq(wasm.isaac_anm2_diff_div24(24, 0) | 0, -1,
           "d=-24 -> -1 (trunc toward zero)");
      },
      () => wasm.isaac_anm2_diff_div24(24, 0) !== -1);
  } finally {
    writeSourceRetry(original);
  }
  wasm = loadExports(); /* clean rebuild after the round-trip */
  wmem = new Uint8Array(wasm.memory.buffer);
  /* sha256-identical restore proof. */
  const restoredHash = sha256(readFileSync(source).toString("utf8"));
  eq(restoredHash, originalHash, "source restored sha256-identical");
  COUNT.cases += 4;
});

/* =========== v73 unit: 0x00414520 string resize-tail split law ============ */

/* Own scratch base (v65 hardening rule): below V68's block. */
const V73_BASE = SCRATCH_HI - 0x4000;    /* 0x11c000 (< V68_BASE) */
const V73_STR = V73_BASE + 0x0100;       /* string-like object */
const V73_HEAP = V73_BASE + 0x0300;      /* heap data buffer */
const V73_PLAN = V73_BASE + 0x0500;      /* plan (17 x 4 = 68 bytes) */

const RESIZE_FIELDS = [
  "entered", "thisAddr", "newSize", "curSize", "cap", "heapDataUsed",
  "grow", "delta", "sizeStoreApplied", "sizeStoreAddr", "sizeStoreValue",
  "termStoreApplied", "termStoreAddr", "termStoreValue", "hostTailVa",
  "pureComplete", "hostCallCount",
];

function readResizeFields(base) {
  return readPlanFields(base, {
    entered: 0, thisAddr: 4, newSize: 8, curSize: 12, cap: 16,
    heapDataUsed: 20, grow: 24, delta: 28, sizeStoreApplied: 32,
    sizeStoreAddr: 36, sizeStoreValue: 40, termStoreApplied: 44,
    termStoreAddr: 48, termStoreValue: 52, hostTailVa: 56,
    pureComplete: 60, hostCallCount: 64,
  }, {
    entered: "i", thisAddr: "u", newSize: "u", curSize: "u", cap: "u",
    heapDataUsed: "i", grow: "i", delta: "u", sizeStoreApplied: "i",
    sizeStoreAddr: "u", sizeStoreValue: "u", termStoreApplied: "i",
    termStoreAddr: "u", termStoreValue: "u", hostTailVa: "u",
    pureComplete: "i", hostCallCount: "i",
  });
}

/* seed the string-like object. LESSON 3: poke everywhere. */
function seedV73({ cur, cap, heapPtr }) {
  pokeU32(V73_STR + ANM2_STR_RESIZE_SIZE_OFF, cur);
  pokeU32(V73_STR + ANM2_STR_RESIZE_CAP_OFF, cap);
  pokeU32(V73_STR, heapPtr);
}

function runV73(newSize) {
  wasm.isaac_anm2_str_resize_plan(V73_STR, newSize, V73_PLAN);
  const p = readResizeFields(V73_PLAN);
  const o = numify(anm2StrResizePlan(shadow, { thisAddr: V73_STR, newSize }));
  return { p, o };
}

