test("v73 unit: mutations are caught by the pins", () => {
  const sha256 = (txt) =>
    createHash("sha256").update(txt, "utf8").digest("hex");
  const originalBuf = readFileSync(source);
  const originalHash = sha256(originalBuf.toString("utf8"));
  const original = originalBuf.toString("utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const withMutant = (label, mutate, check, probe) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      wasm = loadExports();
      wmem = new Uint8Array(wasm.memory.buffer);
      if (probe) {
        const diverged = probe();
        assert.ok(diverged, `${label}: rebuilt module not mutant (stale build)`);
      }
      check();
    } catch {
      threw = true;
    }
    writeSourceRetry(original);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    /* M1: grow polarity ja -> jbe -- the machine grows ONLY when
       arg >u cur (ja @0x00414529); equal must take the shrink arm. */
    withMutant("resize grow on equal",
      (s) => s.replace(
        "  const int grow = new_size > plan.cur_size ? 1 : 0;",
        "  const int grow = new_size >= plan.cur_size ? 1 : 0;"),
      () => {
        seedV73({ cur: 0x10, cap: 0xf, heapPtr: 0 });
        const { p } = runV73(0x10);
        eq(p.grow, 0, "equal takes the shrink arm");
      },
      () => {
        wasm.isaac_anm2_str_resize_plan(V73_STR, 0x10, V73_PLAN);
        return readPlanU32At(V73_PLAN, 6 * 4) !== 0;
      });
    /* M2: SSO select inverted (heap iff cap < 0x10) -- the machine's
       jb skips the deref for cap < 0x10 (0x0041452d..33). */
    withMutant("resize sso select inverted",
      (s) => s.replace(
        "  const int heap = plan.cap >= 0x10u ? 1 : 0;   /* jb skips the deref */",
        "  const int heap = plan.cap < 0x10u ? 1 : 0;   /* jb skips the deref */"),
      () => {
        seedV73({ cur: 0x20, cap: 0xf, heapPtr: 0 });
        const { p } = runV73(0x8);
        eq(p.heapDataUsed, 0, "cap 0xf is SSO");
        eq(p.termStoreAddr >>> 0, V73_STR + 8, "SSO term at this+arg");
      },
      () => {
        wasm.isaac_anm2_str_resize_plan(V73_STR, 8, V73_PLAN);
        return readPlanU32At(V73_PLAN, 5 * 4) !== 0;
      });
    /* M3: host tail dropped from the grow report -- the grow arm must
       report 0x00414870 (jmp @0x00414545). */
    withMutant("resize tail va dropped",
      (s) => s.replace(
        "    plan.host_tail_va =\n" +
        "        static_cast<uint32_t>(ISAAC_ANM2_STR_RESIZE_HOST_TAIL_VA);",
        "    plan.host_tail_va = 0u;"),
      () => {
        seedV73({ cur: 0x10, cap: 0xf, heapPtr: 0 });
        const { p } = runV73(0x30);
        eq(p.hostTailVa >>> 0, 0x00414870, "tail reported");
      },
      () => {
        wasm.isaac_anm2_str_resize_plan(V73_STR, 0x30, V73_PLAN);
        return readPlanU32At(V73_PLAN, 14 * 4) !== 0x00414870;
      });
    /* M4: terminator value 0 -> 0xff -- the machine stores a NUL
       (mov byte [ecx+eax],0 @0x00414537). */
    withMutant("resize term 0xff",
      (s) => s.replace(
        "  plan.term_store_value = 0u;",
        "  plan.term_store_value = 0xffu;"),
      () => {
        seedV73({ cur: 0x20, cap: 0xf, heapPtr: 0 });
        const { p } = runV73(0x8);
        eq(p.termStoreValue >>> 0, 0, "terminator is NUL");
      },
      () => {
        wasm.isaac_anm2_str_resize_plan(V73_STR, 8, V73_PLAN);
        return readPlanU32At(V73_PLAN, 13 * 4) !== 0;
      });
  } finally {
    writeSourceRetry(original);
  }
  wasm = loadExports(); /* clean rebuild after the round-trip */
  wmem = new Uint8Array(wasm.memory.buffer);
  /* sha256-identical restore proof. */
  const restoredHash = sha256(readFileSync(source).toString("utf8"));
  eq(restoredHash, originalHash, "source restored sha256-identical");
  COUNT.cases += 4;
});


/* =========== v76 unit: 0x00414a80 std::_Tree successor ==================== */

/* Own scratch base (v65 hardening rule): below V73's block. */
const V76_BASE = SCRATCH_HI - 0x4800;    /* 0x11b800 (< V73_BASE) */
const V76_SLOT = V76_BASE + 0x0100;      /* iterator slot */
const V76_PLAN = V76_BASE + 0x0200;      /* plan (8 x 4 = 32 bytes) */
const V76_NIL = V76_BASE + 0x0400;       /* node area; node 0 = nil head */

const TREE_FIELDS = [
  "entered", "thisAddr", "node", "resultNode", "path", "climbCount",
  "pureComplete", "hostCallCount",
];

function readTreePlan(base) {
  return readPlanFields(base, {
    entered: 0, thisAddr: 4, node: 8, resultNode: 12, path: 16,
    climbCount: 20, pureComplete: 24, hostCallCount: 28,
  }, {
    entered: "i", thisAddr: "u", node: "u", resultNode: "u", path: "i",
    climbCount: "i", pureComplete: "i", hostCallCount: "i",
  });
}

/* Node layout {left +0, parent +4, right +8, _Isnil byte +0xd}. */
function pokeV76Node(addr, { left = 0, parent = 0, right = 0, isnil = 0 }) {
  pokeU32(addr + 0x0, left);
  pokeU32(addr + 0x4, parent);
  pokeU32(addr + 0x8, right);
  poke(addr + 0xd, [isnil]);
}

function runV76(slot) {
  wasm.isaac_anm2_tree_next_plan(slot === null ? 0 : slot, V76_PLAN);
  const p = readTreePlan(V76_PLAN);
  const o = numify(anm2TreeNextPlan(shadow, { thisAddr: slot === null ? 0 : slot }));
  return { p, o };
}

/* Canonical test world (built once per test):
     N0 = nil head (isnil=1)
     R  root: left L, right RR
     L  : right LR
     LR : leaf
     RR : left RRL
   Successors: succ(L)=LR (PATH 0), succ(LR)=R (PATH 1 climb 1),
   succ(RRL)=N0 (PATH 1 climb 2), succ(RR)=R (PATH 3). */
function buildV76World() {
  const N0 = V76_NIL;
  const R  = V76_NIL + 0x10;
  const L  = V76_NIL + 0x20;
  const LR = V76_NIL + 0x30;
  const RR = V76_NIL + 0x40;
  const RRL = V76_NIL + 0x50;
  /* Leaves point at the NIL HEAD (real _Tree invariant) -- a 0 child
     would be walked as a real node (mem[0xd] reads static data). */
  pokeV76Node(N0, { left: 0, parent: 0, right: 0, isnil: 1 });
  pokeV76Node(R,  { left: L, parent: N0, right: RR });
  pokeV76Node(L,  { left: N0, parent: R, right: LR });
  pokeV76Node(LR, { left: N0, parent: L, right: N0 });
  pokeV76Node(RR, { left: RRL, parent: R, right: N0 });
  pokeV76Node(RRL,{ left: N0, parent: RR, right: N0 });
  return { N0, R, L, LR, RR, RRL };
}

test("v76 unit: constants + census pins + fixed edges (tree successor)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  assert.equal(typeof wasm.isaac_anm2_tree_next_plan, "function",
               "EXPORTS: isaac_anm2_tree_next_plan");

  eq(ANM2_TREE_NEXT_VA, 0x00414a80);
  eq(ANM2_TREE_NEXT_END_VA, 0x00414ad2);
  eq(ANM2_TREE_NEXT_BODY_BYTES, 0x53);
  eq(ANM2_TREE_NEXT_CALLSITE_COUNT, 0);
  eq(ANM2_TREE_NEXT_ADDR_TAKEN, 0);
  eq(ANM2_TREE_NEXT_LEFT_OFF, 0);
  eq(ANM2_TREE_NEXT_PARENT_OFF, 4);
  eq(ANM2_TREE_NEXT_RIGHT_OFF, 8);
  eq(ANM2_TREE_NEXT_ISNIL_OFF, 0xd);
  eq(ANM2_TREE_NEXT_PATH_LEFTMOST, 0);
  eq(ANM2_TREE_NEXT_PATH_CLIMB, 1);
  eq(ANM2_TREE_NEXT_PATH_PARENT_NIL, 2);
  eq(ANM2_TREE_NEXT_PATH_PARENT_DIRECT, 3);

  const { N0, R, L, LR, RR, RRL } = buildV76World();

  /* succ(L): non-nil right -> leftmost of it. PATH 0. */
  pokeU32(V76_SLOT, L);
  let { p, o } = runV76(V76_SLOT);
  eqV58PlanFields(p, o, TREE_FIELDS, "succ L");
  eq(p.path, ANM2_TREE_NEXT_PATH_LEFTMOST, "path 0");
  eq(p.resultNode >>> 0, LR, "leftmost of the right subtree");

  /* succ(LR): no right; node IS parent's right -> climb once to R.
     PATH 1. */
  pokeU32(V76_SLOT, LR);
  ({ p, o } = runV76(V76_SLOT));
  eqV58PlanFields(p, o, TREE_FIELDS, "succ LR");
  eq(p.path, ANM2_TREE_NEXT_PATH_CLIMB, "climb path");
  eq(p.climbCount, 1, "one hop");
  eq(p.resultNode >>> 0, R, "first non-right-child ancestor");

  /* succ(RRL): no right; RRL is RR's LEFT child (RR.right = N0) ->
     parent-direct, ZERO climbs. PATH 3. */
  pokeU32(V76_SLOT, RRL);
  ({ p, o } = runV76(V76_SLOT));
  eqV58PlanFields(p, o, TREE_FIELDS, "succ RRL");
  eq(p.path, ANM2_TREE_NEXT_PATH_PARENT_DIRECT, "left child -> parent");
  eq(p.climbCount, 0, "no climb");
  eq(p.resultNode >>> 0, RR, "result = parent RR");

  /* succ(RR): no right; RR IS R's right child -> climb to the nil
     head. PATH 1 (the machine's cmp edx,[eax+8] @0x00414a98 matches,
     back-edge je 0x00414a98..a8). */
  pokeU32(V76_SLOT, RR);
  ({ p, o } = runV76(V76_SLOT));
  eqV58PlanFields(p, o, TREE_FIELDS, "succ RR");
  eq(p.path, ANM2_TREE_NEXT_PATH_CLIMB, "right child climbs");
  eq(p.climbCount, 1, "one hop to the nil head");
  eq(p.resultNode >>> 0, N0, "result = nil head");

  /* null slot -> zeroed posture. */
  ({ p, o } = runV76(null));
  eqV58PlanFields(p, o, TREE_FIELDS, "null slot");
  eq(p.entered, 0, "null not entered");

  wasm.isaac_anm2_tree_next_plan(V76_SLOT, 0); /* null out */

  eq(wasm.isaac_anm2_pure_helpers_abi_version(), 77, "ABI 73 export");
  COUNT.cases += 55;
});

test("v76 unit: randomized differential (wasm vs oracle)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  assert.equal(typeof wasm.isaac_anm2_tree_next_plan, "function");
  const rng = makeRng((0x00414a80 ^ 0x00414730) >>> 0);
  for (let t = 0; t < 60; ++t) {
    /* Random acyclic binary tree: children drawn without replacement
       from later indices; parents patched from actual assignments. */
    const K = 3 + (rng.u32() % 6);
    const base = V76_NIL + 0x10;
    const addrs = [];
    for (let i = 0; i < K; ++i) addrs.push(base + i * 0x10);
    for (let i = 0; i < K; ++i) {
      pokeV76Node(addrs[i], { parent: i === 0 ? V76_NIL : 0xffffffff, isnil: 0 });
    }
    const used = new Array(K).fill(false);
    used[0] = true;
    for (let i = 0; i < K; ++i) {
      /* absent children point at the NIL head, never 0. */
      let left = V76_NIL, right = V76_NIL;
      if (rng.u32() % 2 === 0) {
        const j = used.indexOf(false);
        if (j >= 0) { left = addrs[j]; used[j] = true; }
      }
      if (rng.u32() % 2 === 0) {
        const j = used.indexOf(false);
        if (j >= 0) { right = addrs[j]; used[j] = true; }
      }
      pokeU32(addrs[i] + 0x0, left);
      pokeU32(addrs[i] + 0x8, right);
      if (left !== 0) pokeU32(left + 0x4, addrs[i]);
      if (right !== 0) pokeU32(right + 0x4, addrs[i]);
    }

    const pick = addrs[rng.u32() % K];
    pokeU32(V76_SLOT, pick);
    const { p, o } = runV76(V76_SLOT);
    eqV58PlanFields(p, o, TREE_FIELDS, `tree t${t}`);
  }
  COUNT.cases += 120;
});

