test("v76 unit: mutations are caught by the pins", () => {
  const sha256 = (txt) =>
    createHash("sha256").update(txt, "utf8").digest("hex");
  const originalBuf = readFileSync(source);
  const originalHash = sha256(originalBuf.toString("utf8"));
  const original = originalBuf.toString("utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const withMutant = (label, mutate, check, probe) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      wasm = loadExports();
      wmem = new Uint8Array(wasm.memory.buffer);
      if (probe) {
        const diverged = probe();
        assert.ok(diverged, `${label}: rebuilt module not mutant (stale build)`);
      }
      check();
    } catch {
      threw = true;
    }
    writeSourceRetry(original);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  buildV76World();
  try {
    /* M1: _Isnil polarity flipped on the RIGHT check -- the machine
       takes PATH 0 when [+0xd]==0 (je 0x00414ab1). The flip sends the
       real-right world into the parent logic instead. */
    withMutant("tree isnil polarity",
      (s) => s.replace(
        "  const int right_isnil = load_u8(guest_ptr(right) + 0xdu) != 0u ? 1 : 0;",
        "  const int right_isnil = load_u8(guest_ptr(right) + 0xdu) == 0u ? 1 : 0;"),
      () => {
        const { R, L } = buildV76World();
        pokeU32(V76_SLOT, L);
        const { p } = runV76(V76_SLOT);
        eq(p.path, ANM2_TREE_NEXT_PATH_LEFTMOST, "real-right still PATH 0");
        eq(p.resultNode >>> 0, V76_NIL + 0x30, "leftmost result");
      },
      () => {
        const { L } = buildV76World();
        pokeU32(V76_SLOT, L);
        wasm.isaac_anm2_tree_next_plan(V76_SLOT, V76_PLAN);
        return readPlanU32At(V76_PLAN, 4 * 4) !== ANM2_TREE_NEXT_PATH_LEFTMOST;
      });
    /* M2: leftmost descent follows PARENT (+4) instead of LEFT (+0) --
       the machine follows [ecx] (mov eax,[ecx] @0x00414ac0). */
    withMutant("tree leftmost follows parent",
      (s) => s.replace(
        "    uint32_t c = load_u32(guest_ptr(right));\n" +
        "    uint32_t leftmost = right;\n" +
        "    while (load_u8(guest_ptr(c) + 0xdu) == 0u) {\n" +
        "      leftmost = c;\n" +
        "      c = load_u32(guest_ptr(c));\n" +
        "    }",
        "    uint32_t c = load_u32(guest_ptr(right));\n" +
        "    uint32_t leftmost = right;\n" +
        "    while (load_u8(guest_ptr(c) + 0xdu) == 0u) {\n" +
        "      leftmost = c;\n" +
        "      c = load_u32(guest_ptr(c) + 0x4u);\n" +
        "    }"),
      () => {
        const { L, LR } = buildV76World();
        pokeU32(V76_SLOT, L);
        const { p } = runV76(V76_SLOT);
        eq(p.resultNode >>> 0, LR, "leftmost of the right subtree");
      },
      () => {
        const { L, LR } = buildV76World();
        pokeU32(V76_SLOT, L);
        wasm.isaac_anm2_tree_next_plan(V76_SLOT, V76_PLAN);
        return readPlanU32At(V76_PLAN, 3 * 4) !== LR;
      });
    /* M3: PATH_PARENT_DIRECT result dropped -- the plan must report
       the parent ([esi],eax store @0x00414aaa). */
    withMutant("tree direct result dropped",
      (s) => s.replace(
        "    plan.path = ISAAC_ANM2_TREE_NEXT_PATH_PARENT_DIRECT;\n" +
        "    plan.result_node = parent;",
        "    plan.path = ISAAC_ANM2_TREE_NEXT_PATH_PARENT_DIRECT;\n" +
        "    plan.result_node = 0u;"),
      () => {
        const { RR, R } = buildV76World();
        pokeU32(V76_SLOT, RR);
        const { p } = runV76(V76_SLOT);
        eq(p.resultNode >>> 0, R, "parent reported");
      },
      () => {
        const { RR } = buildV76World();
        pokeU32(V76_SLOT, RR);
        wasm.isaac_anm2_tree_next_plan(V76_SLOT, V76_PLAN);
        return readPlanU32At(V76_PLAN, 3 * 4) === 0;
      });
    /* M4: climb condition drops the side test -- the machine climbs
       ONLY while node == parent->right (cmp edx,[eax+8]
       @0x00414a98..9b); inverting it breaks the stop condition. */
    withMutant("tree climb ignores side",
      (s) => s.replace(
        "    if (cur != load_u32(guest_ptr(anc) + 0x8u)) break; /* left child */",
        "    if (cur == load_u32(guest_ptr(anc) + 0x8u)) break; /* inverted */"),
      () => {
        buildV76World();
        pokeU32(V76_SLOT, V76_NIL + 0x30); /* LR */
        const { p } = runV76(V76_SLOT);
        eq(p.climbCount, 1, "single hop");
        eq(p.resultNode >>> 0, V76_NIL + 0x10,
           "stops at first non-right ancestor");
      },
      () => {
        buildV76World();
        pokeU32(V76_SLOT, V76_NIL + 0x30);
        wasm.isaac_anm2_tree_next_plan(V76_SLOT, V76_PLAN);
        return readPlanU32At(V76_PLAN, 5 * 4) !== 1;
      });
  } finally {
    writeSourceRetry(original);
  }
  wasm = loadExports(); /* clean rebuild after the round-trip */
  wmem = new Uint8Array(wasm.memory.buffer);
  /* sha256-identical restore proof. */
  const restoredHash = sha256(readFileSync(source).toString("utf8"));
  eq(restoredHash, originalHash, "source restored sha256-identical");
  COUNT.cases += 4;
});

/* =========== v82 unit: 0x00415f80 _Tree erase-splice ====================== */

/* Own scratch base (v65 hardening rule): below V76's block. */
const V82_BASE = SCRATCH_HI - 0x5000;    /* 0x11b000 (< V76_BASE) */
const V82_CONTAINER = V82_BASE + 0x0100; /* holds header ptr */
const V82_HEADER = V82_BASE + 0x0200;    /* header (root @ +4) */
const V82_PLAN = V82_BASE + 0x0300;      /* plan (9 x 4 = 36 bytes) */
const V82_NODES = V82_BASE + 0x0500;     /* node area, stride 0x10 */
const V82_NIL = V82_NODES;               /* node 0 = nil head */

const SPLICE_FIELDS = [
  "entered", "container", "node", "leftChild", "parent",
  "nodeLeftAfter", "path", "pureComplete", "hostCallCount",
];

function readSplicePlan(base) {
  return readPlanFields(base, {
    entered: 0, container: 4, node: 8, leftChild: 12, parent: 16,
    nodeLeftAfter: 20, path: 24, pureComplete: 28, hostCallCount: 32,
  }, {
    entered: "i", container: "u", node: "u", leftChild: "u", parent: "u",
    nodeLeftAfter: "u", path: "i", pureComplete: "i", hostCallCount: "i",
  });
}

/* Node layout {left +0, parent +4, right +8, _Isnil byte +0xd}. */
function pokeV82Node(addr, { left = V82_NIL, parent = V82_NIL,
                             right = V82_NIL, isnil = 0 }) {
  pokeU32(addr + 0x0, left);
  pokeU32(addr + 0x4, parent);
  pokeU32(addr + 0x8, right);
  poke(addr + 0xd, [isnil]);
}

/* Build: N0 nil; ROOT with children PL (left) and PR (right); PL has
   left child PLL (the node being erased in the fixed edges). */
function buildV82World() {
  const N0 = V82_NIL;
  const ROOT = V82_NIL + 0x10;
  const PL = V82_NIL + 0x20;
  const PR = V82_NIL + 0x30;
  const PLL = V82_NIL + 0x40;
  const PLR = V82_NIL + 0x50;
  pokeV82Node(N0, { left: 0, parent: 0, right: 0, isnil: 1 });
  pokeV82Node(ROOT, { left: PL, parent: N0, right: PR });
  pokeV82Node(PL,  { left: PLL, parent: ROOT, right: PLR });
  pokeV82Node(PR,  { left: N0, parent: ROOT, right: N0 });
  /* PLL: the erase victim. Its children start empty (left = N0). */
  pokeV82Node(PLL, { left: N0, parent: PL, right: N0 });
  pokeV82Node(PLR, { left: N0, parent: PL, right: N0 });
  pokeU32(V82_HEADER + 0x4, ROOT);
  pokeU32(V82_CONTAINER, V82_HEADER);
  return { N0, ROOT, PL, PR, PLL, PLR };
}

function runV82(node) {
  wasm.isaac_anm2_tree_splice_plan(
    node === null ? 0 : V82_CONTAINER, node === null ? 0 : node, V82_PLAN);
  const p = readSplicePlan(V82_PLAN);
  const o = numify(anm2TreeSplicePlan(shadow, {
    container: node === null ? 0 : V82_CONTAINER,
    node: node === null ? 0 : node,
  }));
  return { p, o };
}

test("v82 unit: constants + census pins + fixed edges (erase-splice)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  assert.equal(typeof wasm.isaac_anm2_tree_splice_plan, "function",
               "EXPORTS: isaac_anm2_tree_splice_plan");

  eq(ANM2_TREE_SPLICE_VA, 0x00415f80);
  eq(ANM2_TREE_SPLICE_END_VA, 0x00415fd7);
  eq(ANM2_TREE_SPLICE_BODY_BYTES, 0x58);
  eq(ANM2_TREE_SPLICE_CALLSITE_COUNT, 0);
  eq(ANM2_TREE_SPLICE_ADDR_TAKEN, 0);
  eq(ANM2_TREE_SPLICE_PATH_ROOT, 0);
  eq(ANM2_TREE_SPLICE_PATH_RIGHT_CHILD, 1);
  eq(ANM2_TREE_SPLICE_PATH_LEFT_CHILD, 2);

  const { N0, ROOT, PL, PR, PLL, PLR } = buildV82World();

  /* PATH 2 (left child): erase PLL — PL's LEFT child. */
  let { p, o } = runV82(PLL);
  eqV58PlanFields(p, o, SPLICE_FIELDS, "splice left");
  eq(p.entered, 1, "entered");
  eq(p.leftChild >>> 0, N0, "left child = nil head");
  eq(p.parent >>> 0, PL, "parent = PL");
  eq(p.nodeLeftAfter >>> 0, 0, "node_left_after = [N0+8] = 0 (seeded)");
  eq(p.path, ANM2_TREE_SPLICE_PATH_LEFT_CHILD, "PATH 2 left child");

  /* PATH 1 (right child): erase PLR — PL's RIGHT child. */
  ({ p, o } = runV82(PLR));
  eqV58PlanFields(p, o, SPLICE_FIELDS, "splice right");
  eq(p.path, ANM2_TREE_SPLICE_PATH_RIGHT_CHILD, "PATH 1 right child");
  eq(p.parent >>> 0, PL, "parent = PL");

  /* PATH 0 (root): erase ROOT itself. */
  ({ p, o } = runV82(ROOT));
  eqV58PlanFields(p, o, SPLICE_FIELDS, "splice root");
  eq(p.path, ANM2_TREE_SPLICE_PATH_ROOT, "PATH 0 root");
  eq(p.parent >>> 0, N0, "root's parent = nil head");

  /* node_left_after reads the LEFT child's right subtree: give PLL a
     left child X with X.right = PLR — node_left_after must follow. */
  buildV82World();
  const X = V82_NIL + 0x60;
  pokeV82Node(X, { left: N0, parent: PLL, right: PLR });
  pokeU32(PLL + 0x0, X);
  ({ p, o } = runV82(PLL));
  eqV58PlanFields(p, o, SPLICE_FIELDS, "splice with subtree");
  eq(p.leftChild >>> 0, X, "left child is X");
  eq(p.nodeLeftAfter >>> 0, PLR, "node_left_after = left->right");

  /* null container / null node -> zeroed posture. */
  ({ p, o } = runV82(null));
  eqV58PlanFields(p, o, SPLICE_FIELDS, "null world");
  eq(p.entered, 0, "null not entered");

  wasm.isaac_anm2_tree_splice_plan(V82_CONTAINER, PLL, 0); /* null out */

  eq(wasm.isaac_anm2_pure_helpers_abi_version(), 77, "ABI 73 export");
  COUNT.cases += 45;
});

test("v82 unit: randomized differential (wasm vs oracle)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  assert.equal(typeof wasm.isaac_anm2_tree_splice_plan, "function");
  const rng = makeRng((0x00415f80 ^ 0x00415d20) >>> 0);
  for (let t = 0; t < 70; ++t) {
    const K = 3 + (rng.u32() % 5);
    const base = V82_NIL + 0x10;
    const addrs = [];
    for (let i = 0; i < K; ++i) addrs.push(base + i * 0x10);
    for (let i = 0; i < K; ++i) {
      pokeV82Node(addrs[i], { parent: i === 0 ? V82_NIL : 0xffffffff });
    }
    const used = new Array(K).fill(false);
    used[0] = true;
    for (let i = 0; i < K; ++i) {
      let left = V82_NIL, right = V82_NIL;
      if (rng.u32() % 2 === 0) {
        const j = used.indexOf(false);
        if (j >= 0) { left = addrs[j]; used[j] = true; }
      }
      if (rng.u32() % 2 === 0) {
        const j = used.indexOf(false);
        if (j >= 0) { right = addrs[j]; used[j] = true; }
      }
      pokeU32(addrs[i] + 0x0, left);
      pokeU32(addrs[i] + 0x8, right);
      if (left !== V82_NIL) pokeU32(left + 0x4, addrs[i]);
      if (right !== V82_NIL) pokeU32(right + 0x4, addrs[i]);
    }
    pokeU32(V82_HEADER + 0x4, addrs[0]);
    pokeU32(V82_CONTAINER, V82_HEADER);
    const pick = addrs[rng.u32() % K];
    wasm.isaac_anm2_tree_splice_plan(V82_CONTAINER, pick, V82_PLAN);
    const p = readSplicePlan(V82_PLAN);
    const o = numify(anm2TreeSplicePlan(shadow, {
      container: V82_CONTAINER, node: pick,
    }));
    eqV58PlanFields(p, o, SPLICE_FIELDS, `splice t${t}`);
  }
  COUNT.cases += 140;
});

test("v82 unit: header + model pins hold", () => {
  const headerText = readFileSync(header, "utf8");
  const modelText = readFileSync(model, "utf8");
  assert.match(headerText, /ISAAC_ANM2_TREE_SPLICE_VA = 0x00415f80u/);
  assert.match(headerText, /ISAAC_ANM2_TREE_SPLICE_END_VA = 0x00415fd7u/);
  assert.match(headerText, /ISAAC_ANM2_TREE_SPLICE_BODY_BYTES = 0x58u/);
  assert.match(headerText, /ISAAC_ANM2_TREE_SPLICE_CALLSITE_COUNT = 0/);
  assert.match(headerText, /ISAAC_ANM2_TREE_SPLICE_ADDR_TAKEN = 0/);
  assert.match(headerText, /IsaacAnm2TreeSplicePlan; \/\* 9 x 4 = 36 bytes \*\//);
  assert.match(modelText, /ANM2_TREE_SPLICE_VA = 0x00415f80/);
  assert.match(modelText, /export function anm2TreeSplicePlan/);
  const sourceText = readFileSync(source, "utf8");
  assert.match(sourceText, /ISAAC_ANM2_NO_NARROW_PARAMS\(isaac_anm2_tree_splice_plan\)/);
  COUNT.cases += 1;
});

test("v82 unit: mutations are caught by the pins", () => {
  const sha256 = (txt) =>
    createHash("sha256").update(txt, "utf8").digest("hex");
  const originalBuf = readFileSync(source);
  const originalHash = sha256(originalBuf.toString("utf8"));
  const original = originalBuf.toString("utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const withMutant = (label, mutate, check, probe) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      wasm = loadExports();
      wmem = new Uint8Array(wasm.memory.buffer);
      if (probe) {
        const diverged = probe();
        assert.ok(diverged, `${label}: rebuilt module not mutant (stale build)`);
      }
      check();
    } catch {
      threw = true;
    }
    writeSourceRetry(original);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  buildV82World();
  try {
    /* M1: root detection inverted -- the machine picks PATH 0 when
       node == header->root (cmp edx,[eax+4] @0x00415fa2..a5). */
    withMutant("splice root inverted",
      (s) => s.replace(
        "  if (node == root) {",
        "  if (node != root) {"),
      () => {
        const { ROOT } = buildV82World();
        const { p } = runV82(ROOT);
        eq(p.path, ANM2_TREE_SPLICE_PATH_ROOT, "root -> PATH 0");
      },
      () => {
        const { ROOT } = buildV82World();
        wasm.isaac_anm2_tree_splice_plan(V82_CONTAINER, ROOT, V82_PLAN);
        return readPlanU32At(V82_PLAN, 6 * 4) !== 0;
      });
    /* M2: node_left_after read from parent offset (+4) instead of
       left->right (+8) -- the machine reads [esi+8] @0x00415f8e. */
    withMutant("splice nla wrong offset",
      (s) => s.replace(
        "    nla = load_u32(guest_ptr(plan.left_child) + 0x8u);",
        "    nla = load_u32(guest_ptr(plan.left_child) + 0x4u);"),
      () => {
        const { N0, PL, PR } = buildV82World();
        const X = V82_NIL + 0x60;
        /* PLL.left := X where X.right = PR but X.parent = PL:
           original reads +8 (PR); mutant reads +4 (PL). */
        pokeV82Node(X, { left: N0, parent: PL, right: PR });
        pokeU32(PL + 0x0, X);
        const { p, o } = runV82(PLR);
        void o;
        eq(p.nodeLeftAfter >>> 0, PR >>> 0,
           "node_left_after = left->right (+8)");
      },
      () => {
        const { N0, PL, PR } = buildV82World();
        const X = V82_NIL + 0x60;
        pokeV82Node(X, { left: N0, parent: PL, right: PR });
        pokeU32(PL + 0x0, X);
        wasm.isaac_anm2_tree_splice_plan(V82_CONTAINER, PLR, V82_PLAN);
        return readPlanU32At(V82_PLAN, 5 * 4) !== (PR >>> 0);
      });
    /* M3: right-child path detection inverted -- the machine picks
       PATH 1 when node == parent->+8 (cmp edx,[eax+8] @0x00415fb8..bd).
       Inverting to +0 sends right children into PATH 2. */
    withMutant("splice path right inverted",
      (s) => s.replace(
        "             node == load_u32(guest_ptr(parent) + 0x8u)) {",
        "             node == load_u32(guest_ptr(parent))) {"),
      () => {
        const { PLR } = buildV82World();
        pokeU32(V82_CONTAINER, V82_HEADER);
        const { p } = runV82(PLR);
        eq(p.path, ANM2_TREE_SPLICE_PATH_RIGHT_CHILD, "right child -> PATH 1");
      },
      () => {
        const { PLR } = buildV82World();
        wasm.isaac_anm2_tree_splice_plan(V82_CONTAINER, PLR, V82_PLAN);
        return readPlanU32At(V82_PLAN, 6 * 4) !== 1;
      });
    /* M4: entered fold broken -- container 0 must yield the zeroed
       not-entered posture (v42). */
    withMutant("splice null container entered",
      (s) => s.replace(
        "  if (container == 0u || node == 0u) {",
        "  if (false) {"),
      () => {
        const { p, o } = runV82(null);
        eq(p.entered, 0, "null world not entered");
      },
      () => {
        wasm.isaac_anm2_tree_splice_plan(0, 0, V82_PLAN);
        return readPlanU32At(V82_PLAN, 0 * 4) !== 0;
      });
  } finally {
    writeSourceRetry(original);
  }
  wasm = loadExports(); /* clean rebuild after the round-trip */
  wmem = new Uint8Array(wasm.memory.buffer);
  /* sha256-identical restore proof. */
  const restoredHash = sha256(readFileSync(source).toString("utf8"));
  eq(restoredHash, originalHash, "source restored sha256-identical");
  COUNT.cases += 4;
});

/* =========== v83 unit: 0x00415fe0 _Tree erase-splice RIGHT =============== */

/* Own scratch base (v65 hardening rule): below V82's block. */
const V83_BASE = SCRATCH_HI - 0x5800;    /* 0x11a800 (< V82_BASE) */
const V83_CONTAINER = V83_BASE + 0x0100;
const V83_HEADER = V83_BASE + 0x0200;
const V83_PLAN = V83_BASE + 0x0300;      /* plan (9 x 4 = 36 bytes) */
const V83_NODES = V83_BASE + 0x0500;
const V83_NIL = V83_NODES;

const SPLICE_R_FIELDS = [
  "entered", "container", "node", "rightChild", "parent",
  "nodeRightAfter", "path", "pureComplete", "hostCallCount",
];

function readSpliceRPlan(base) {
  return readPlanFields(base, {
    entered: 0, container: 4, node: 8, rightChild: 12, parent: 16,
    nodeRightAfter: 20, path: 24, pureComplete: 28, hostCallCount: 32,
  }, {
    entered: "i", container: "u", node: "u", rightChild: "u",
    parent: "u", nodeRightAfter: "u", path: "i", pureComplete: "i",
    hostCallCount: "i",
  });
}

/* Node layout {left +0, parent +4, right +8, _Isnil byte +0xd}.
   Absent children point at the NIL head (never 0). */
function pokeV83Node(addr, { left = V83_NIL, parent = V83_NIL,
                             right = V83_NIL, isnil = 0 }) {
  pokeU32(addr + 0x0, left);
  pokeU32(addr + 0x4, parent);
  pokeU32(addr + 0x8, right);
  poke(addr + 0xd, [isnil]);
}

/* Build: N0 nil; ROOT{RL left, RR right}; RL has RIGHT child RLR
   (the erase victim for the fixed edges). */
function buildV83World() {
  const N0 = V83_NIL;
  const ROOT = V83_NIL + 0x10;
  const RL = V83_NIL + 0x20;
  const RR = V83_NIL + 0x30;
  const RLR = V83_NIL + 0x40;
  const RLL = V83_NIL + 0x50;
  pokeV83Node(N0, { isnil: 1 });
  pokeV83Node(ROOT, { left: RL, parent: N0, right: RR });
  pokeV83Node(RL,  { left: RLL, parent: ROOT, right: RLR });
  pokeV83Node(RR,  { left: N0, parent: ROOT, right: N0 });
  pokeV83Node(RLR, { left: N0, parent: RL, right: N0 });
  pokeV83Node(RLL, { left: N0, parent: RL, right: N0 });
  pokeU32(V83_HEADER + 0x4, ROOT);
  pokeU32(V83_CONTAINER, V83_HEADER);
  return { N0, ROOT, RL, RR, RLR, RLL };
}

function runV83(node) {
  wasm.isaac_anm2_tree_splice_r_plan(
    node === null ? 0 : V83_CONTAINER, node === null ? 0 : node, V83_PLAN);
  const p = readSpliceRPlan(V83_PLAN);
  const o = numify(anm2TreeSpliceRPlan(shadow, {
    container: node === null ? 0 : V83_CONTAINER,
    node: node === null ? 0 : node,
  }));
  return { p, o };
}

test("v83 unit: constants + census pins + fixed edges (splice RIGHT)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  assert.equal(typeof wasm.isaac_anm2_tree_splice_r_plan, "function",
               "EXPORTS: isaac_anm2_tree_splice_r_plan");

  eq(ANM2_TREE_SPLICE_R_VA, 0x00415fe0);
  eq(ANM2_TREE_SPLICE_R_END_VA, 0x00416034);
  eq(ANM2_TREE_SPLICE_R_BODY_BYTES, 0x55);
  eq(ANM2_TREE_SPLICE_R_CALLSITE_COUNT, 0);
  eq(ANM2_TREE_SPLICE_R_ADDR_TAKEN, 0);
  eq(ANM2_TREE_SPLICE_R_PATH_ROOT, 0);
  eq(ANM2_TREE_SPLICE_R_PATH_LEFT_CHILD, 1);
  eq(ANM2_TREE_SPLICE_R_PATH_RIGHT_CHILD, 2);

  const { N0, ROOT, RL, RR, RLR } = buildV83World();

  /* PATH 2 (right child): erase RLR — RL's RIGHT child. */
  let { p, o } = runV83(RLR);
  eqV58PlanFields(p, o, SPLICE_R_FIELDS, "splice right");
  eq(p.entered, 1, "entered");
  eq(p.rightChild >>> 0, N0, "right child = nil head");
  eq(p.parent >>> 0, RL, "parent = RL");
  eq(p.nodeRightAfter >>> 0, N0, "node_right_after = nil->left slot read");
  eq(p.path, ANM2_TREE_SPLICE_R_PATH_RIGHT_CHILD, "PATH 2 right child");

  /* PATH 1 (left child): erase RLL — RL's LEFT child. */
  const { RLL } = buildV83World();
  ({ p, o } = runV83(RLL));
  eqV58PlanFields(p, o, SPLICE_R_FIELDS, "splice left");
  eq(p.path, ANM2_TREE_SPLICE_R_PATH_LEFT_CHILD, "PATH 1 left child");
  eq(p.parent >>> 0, RL, "parent = RL");

  /* PATH 0 (root): erase ROOT itself. */
  ({ p, o } = runV83(ROOT));
  eqV58PlanFields(p, o, SPLICE_R_FIELDS, "splice root");
  eq(p.path, ANM2_TREE_SPLICE_R_PATH_ROOT, "PATH 0 root");
  eq(p.parent >>> 0, N0, "root's parent = nil head");

  /* node_right_after reads the RIGHT child's LEFT subtree: give the
     victim RLR a right child X with X.left = ROOT (distinct from
     X.parent = RL so the M2 offset mutant cannot alias it). */
  const X = V83_NIL + 0x60;
  pokeV83Node(X, { left: ROOT, parent: RL, right: N0 });
  pokeU32(RLR + 0x8, X);
  ({ p, o } = runV83(RLR));
  eqV58PlanFields(p, o, SPLICE_R_FIELDS, "splice with subtree");
  eq(p.nodeRightAfter >>> 0, ROOT, "node_right_after = right->left");

  /* null container / null node -> zeroed posture. */
  ({ p, o } = runV83(null));
  eqV58PlanFields(p, o, SPLICE_R_FIELDS, "null world");
  eq(p.entered, 0, "null not entered");

  wasm.isaac_anm2_tree_splice_r_plan(V83_CONTAINER, RLR, 0); /* null out */

  eq(wasm.isaac_anm2_pure_helpers_abi_version(), 77, "ABI 73 export");
  COUNT.cases += 45;
});

test("v83 unit: randomized differential (wasm vs oracle)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  assert.equal(typeof wasm.isaac_anm2_tree_splice_r_plan, "function");
  const rng = makeRng((0x00415fe0 ^ 0x00415d20) >>> 0);
  for (let t = 0; t < 70; ++t) {
    const K = 3 + (rng.u32() % 5);
    const base = V83_NIL + 0x10;
    const addrs = [];
    for (let i = 0; i < K; ++i) addrs.push(base + i * 0x10);
    for (let i = 0; i < K; ++i) {
      pokeV83Node(addrs[i], { parent: i === 0 ? V83_NIL : 0xffffffff });
    }
    const used = new Array(K).fill(false);
    used[0] = true;
    for (let i = 0; i < K; ++i) {
      let left = V83_NIL, right = V83_NIL;
      if (rng.u32() % 2 === 0) {
        const j = used.indexOf(false);
        if (j >= 0) { left = addrs[j]; used[j] = true; }
      }
      if (rng.u32() % 2 === 0) {
        const j = used.indexOf(false);
        if (j >= 0) { right = addrs[j]; used[j] = true; }
      }
      pokeU32(addrs[i] + 0x0, left);
      pokeU32(addrs[i] + 0x8, right);
      if (left !== V83_NIL) pokeU32(left + 0x4, addrs[i]);
      if (right !== V83_NIL) pokeU32(right + 0x4, addrs[i]);
    }
    pokeU32(V83_HEADER + 0x4, addrs[0]);
    pokeU32(V83_CONTAINER, V83_HEADER);
    const pick = addrs[rng.u32() % K];
    wasm.isaac_anm2_tree_splice_r_plan(V83_CONTAINER, pick, V83_PLAN);
    const p = readSpliceRPlan(V83_PLAN);
    const o = numify(anm2TreeSpliceRPlan(shadow, {
      container: V83_CONTAINER, node: pick,
    }));
    eqV58PlanFields(p, o, SPLICE_R_FIELDS, `splice-r t${t}`);
  }
  COUNT.cases += 140;
});

