test("v83 unit: mutations are caught by the pins", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  const sha256 = (txt) =>
    createHash("sha256").update(txt, "utf8").digest("hex");
  const originalBuf = readFileSync(source);
  const originalHash = sha256(originalBuf.toString("utf8"));
  const original = originalBuf.toString("utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const withMutant = (label, mutate, check, probe) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      wasm = loadExports();
      wmem = new Uint8Array(wasm.memory.buffer);
      if (probe) {
        const diverged = probe();
        assert.ok(diverged, `${label}: rebuilt module not mutant (stale build)`);
      }
      check();
    } catch {
      threw = true;
    }
    writeSourceRetry(original);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  buildV83World();
  try {
    /* M1: root detection inverted -- the machine picks PATH 0 when
       node == header->root (cmp edx,[eax+4] @0x00416002..05). */
    withMutant("splice-r root inverted",
      (s) => s.replace(
        "  if (node == root) {",
        "  if (node != root) {"),
      () => {
        const { ROOT } = buildV83World();
        const { p } = runV83(ROOT);
        eq(p.path, ANM2_TREE_SPLICE_R_PATH_ROOT, "root -> PATH 0");
      },
      () => {
        const { ROOT } = buildV83World();
        wasm.isaac_anm2_tree_splice_r_plan(V83_CONTAINER, ROOT, V83_PLAN);
        return readPlanU32At(V83_PLAN, 6 * 4) !== 0;
      });
    /* M2: node_right_after read from right's PARENT (+4) instead of
       right->LEFT (+0) -- the machine reads [esi] @0x00415fea. */
    withMutant("splice-r nra wrong offset",
      (s) => s.replace(
        "    nra = load_u32(guest_ptr(plan.right_child));",
        "    nra = load_u32(guest_ptr(plan.right_child) + 0x4u);"),
      () => {
        buildV83World();
        const X = V83_NIL + 0x60;
        pokeV83Node(X, { left: V83_NIL + 0x70, parent: V83_NIL + 0x80,
                         right: V83_NIL });
        pokeU32(V83_NIL + 0x40 + 0x8, X);   /* RLR.right := X */
        const { p, o } = runV83(V83_NIL + 0x40);
        void o;
        eq(p.nodeRightAfter >>> 0, V83_NIL + 0x70,
           "node_right_after = right->left (+0)");
      },
      () => {
        wasm.isaac_anm2_tree_splice_r_plan(
          V83_CONTAINER, V83_NIL + 0x40, V83_PLAN);
        return readPlanU32At(V83_PLAN, 5 * 4) !== (V83_NIL + 0x70) >>> 0;
      });
    /* M3: left-child path stores to parent->right ([eax+8]) instead of
       parent->left ([eax]) -- the machine's cmp edx,[eax] /
       mov [eax],esi @0x00416017..1b. */
    withMutant("splice-r left path to right",
      (s) => s.replace(
        "             node == load_u32(guest_ptr(parent))) {",
        "             node == load_u32(guest_ptr(parent) + 0x8u)) {"),
      () => {
        const { RLL } = buildV83World();
        const { p } = runV83(RLL);
        eq(p.path, ANM2_TREE_SPLICE_R_PATH_LEFT_CHILD, "left child");
      },
      () => {
        const { RLL } = buildV83World();
        wasm.isaac_anm2_tree_splice_r_plan(V83_CONTAINER, RLL, V83_PLAN);
        return readPlanU32At(V83_PLAN, 6 * 4) !== 1;
      });
    /* M4: entered fold broken -- container 0 must yield the zeroed
       not-entered posture (v42). */
    withMutant("splice-r null container entered",
      (s) => s.replace(
        "  if (container == 0u || node == 0u) {",
        "  if (false) {"),
      () => {
        const { p } = runV83(null);
        eq(p.entered, 0, "null world not entered");
      },
      () => {
        wasm.isaac_anm2_tree_splice_r_plan(0, 0, V83_PLAN);
        return readPlanU32At(V83_PLAN, 0 * 4) !== 0;
      });
  } finally {
    writeSourceRetry(original);
  }
  wasm = loadExports(); /* clean rebuild after the round-trip */
  wmem = new Uint8Array(wasm.memory.buffer);
  /* sha256-identical restore proof. */
  const restoredHash = sha256(readFileSync(source).toString("utf8"));
  eq(restoredHash, originalHash, "source restored sha256-identical");
  COUNT.cases += 4;
});

/* =========== v84-retry: 0x00416440 _Tree lower_bound ====================== */

/* Own scratch base (v65 hardening rule): below V83's block. */
const V84_BASE = SCRATCH_HI - 0x6000;    /* 0x11a000 (< V83_BASE) */
const V84_CONTAINER = V84_BASE + 0x0100;
const V84_HEADER = V84_BASE + 0x0200;
const V84_OUT = V84_BASE + 0x0300;       /* out slot (3 dwords) */
const V84_KEYCELL = V84_BASE + 0x0400;   /* key-slot dword */
const V84_PLAN = V84_BASE + 0x0500;      /* plan (13 x 4 = 52 bytes) */
const V84_NODES = V84_BASE + 0x0600;
const V84_NIL = V84_NODES;

const LB_FIELDS = [
  "entered", "container", "outSlot", "keySlot", "key", "root",
  "iterations", "yNode", "lastFlag", "finalX", "rootIsnilEarly",
  "pureComplete", "hostCallCount",
];

function readLBPlan(base) {
  return readPlanFields(base, {
    entered: 0, container: 4, outSlot: 8, keySlot: 12, key: 16,
    root: 20, iterations: 24, yNode: 28, lastFlag: 32, finalX: 36,
    rootIsnilEarly: 40, pureComplete: 44, hostCallCount: 48,
  }, {
    entered: "i", container: "u", outSlot: "u", keySlot: "u", key: "u",
    root: "u", iterations: "i", yNode: "u", lastFlag: "i", finalX: "u",
    rootIsnilEarly: "i", pureComplete: "i", hostCallCount: "i",
  });
}

function pokeV84Node(addr, { left = V84_NIL, parent = V84_NIL,
                             right = V84_NIL, isnil = 0, key = 0 }) {
  pokeU32(addr + 0x0, left);
  pokeU32(addr + 0x4, parent);
  pokeU32(addr + 0x8, right);
  pokeU32(addr + 0x10, key);
  poke(addr + 0xd, [isnil]);
}

/* NIL-HEAD INVARIANT (v84-abort lesson): absent children point at the
   NIL head, never 0; the head itself is poked with isnil=1. */
function buildV84World(keys) {
  const addrs = keys.map((k, i) => V84_NIL + 0x10 + i * 0x20);
  for (let i = 0; i < keys.length; ++i) {
    pokeV84Node(addrs[i], { key: keys[i], isnil: 0,
                            left: V84_NIL, right: V84_NIL,
                            parent: V84_NIL });
  }
  for (let i = 1; i < keys.length; ++i) {
    pokeU32(addrs[i] + 0x4, addrs[(i - 1) >> 1]);
    const p = (i - 1) >> 1;
    if (i % 2 === 1) pokeU32(addrs[p] + 0x0, addrs[i]);
    else pokeU32(addrs[p] + 0x8, addrs[i]);
  }
  /* Head poke must NOT write the full node shape: +0x10 IS root.left
     (nodes start at V84_NIL+0x10) — a key=0 stamp zeroes it and the
     below-minimum walk falls into address 0's static bytes forever. */
  poke(V84_NIL + 0xd, [1]);
  pokeU32(V84_HEADER + 0x4, addrs[0]);
  pokeU32(V84_CONTAINER, V84_CONTAINER === undefined ? V84_HEADER : V84_HEADER);
  return addrs;
}

function runV84() {
  wasm.isaac_anm2_tree_lower_bound_plan(
    V84_CONTAINER, V84_OUT, V84_KEYCELL, V84_PLAN);
  const p = readLBPlan(V84_PLAN);
  const o = numify(anm2TreeLowerBoundPlan(shadow, {
    container: V84_CONTAINER, outSlot: V84_OUT, keySlot: V84_KEYCELL,
  }));
  return { p, o };
}

test("v84-retry: constants + census pins + fixed edges (lower_bound)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  assert.equal(typeof wasm.isaac_anm2_tree_lower_bound_plan, "function",
               "EXPORTS: isaac_anm2_tree_lower_bound_plan");

  eq(ANM2_TREE_LOWER_BOUND_VA, 0x00416440);
  eq(ANM2_TREE_LOWER_BOUND_END_VA, 0x0041648c);
  eq(ANM2_TREE_LOWER_BOUND_BODY_BYTES, 0x4c);
  eq(ANM2_TREE_LOWER_BOUND_CALLSITE_COUNT, 0);
  eq(ANM2_TREE_LOWER_BOUND_ADDR_TAKEN, 0);
  eq(ANM2_TREE_LOWER_BOUND_KEY_OFF, 0x10);
  eq(ANM2_TREE_LOWER_BOUND_LEFT_OFF, 0);
  eq(ANM2_TREE_LOWER_BOUND_RIGHT_OFF, 8);
  eq(ANM2_TREE_LOWER_BOUND_ISNIL_OFF, 0xd);

  /* BST over keys [10, 20, 30, 40, 50]: idx0=10 root, idx1=20 left,
     idx2=30 right of root, idx3=40 left of idx1, idx4=50 right of idx1. */
  const addrs = buildV84World([10, 20, 30, 40, 50]);

  /* exact hit: key 30 at idx2. */
  pokeU32(V84_KEYCELL, 30);
  let { p, o } = runV84();
  eqV58PlanFields(p, o, LB_FIELDS, "lb exact");
  eq(p.entered, 1, "entered");
  eq(p.iterations, 2, "walked root -> idx2");
  eq(p.yNode >>> 0, addrs[2], "y = key-30 node");
  eq(p.lastFlag, 1, "candidate flag");
  eq(p.finalX >>> 0, addrs[2], "final x");

  /* below all: key 5 -> left chain, all candidates. */
  pokeU32(V84_KEYCELL, 5);
  ({ p, o } = runV84());
  eqV58PlanFields(p, o, LB_FIELDS, "lb below all");
  eq(p.iterations, 3, "walked root -> idx1 -> idx3");
  eq(p.lastFlag, 1, "all compares were >=");
  eq(p.yNode >>> 0, addrs[3], "y = leftmost leaf");

  /* above all: key 99 -> right chain, no candidates. */
  pokeU32(V84_KEYCELL, 99);
  ({ p, o } = runV84());
  eqV58PlanFields(p, o, LB_FIELDS, "lb above all");
  eq(p.iterations, 2, "right chain walked root -> idx2 (dump 00416440: je 0x416463 re-checks isnil per store)");
  eq(p.lastFlag, 0, "no candidate");
  eq(p.yNode >>> 0, 0, "y never set");

  /* empty tree: root nil -> immediate return. */
  poke(V84_NIL + 0xd, [1]);
  pokeU32(V84_HEADER + 0x4, V84_NIL);
  pokeU32(V84_KEYCELL, 7);
  ({ p, o } = runV84());
  eqV58PlanFields(p, o, LB_FIELDS, "lb empty");
  eq(p.rootIsnilEarly, 1, "empty root early exit");
  eq(p.iterations, 0, "no iterations");

  /* null container -> zeroed posture. */
  wasm.isaac_anm2_tree_lower_bound_plan(0, V84_OUT, V84_KEYCELL, V84_PLAN);
  const z = readLBPlan(V84_PLAN);
  eq(z.entered, 0, "null container not entered");
  eq(z.pureComplete, 1, "zeroed posture pure_complete");

  wasm.isaac_anm2_tree_lower_bound_plan(
    V84_CONTAINER, V84_OUT, V84_KEYCELL, 0); /* null out */

  eq(wasm.isaac_anm2_pure_helpers_abi_version(), 77, "ABI 73 export");
  COUNT.cases += 45;
});

test("v84-retry: randomized differential (wasm vs oracle)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  assert.equal(typeof wasm.isaac_anm2_tree_lower_bound_plan, "function");
  const rng = makeRng((0x00416440 ^ 0x00415fe0) >>> 0);
  for (let t = 0; t < 60; ++t) {
    const K = 3 + (rng.u32() % 6);
    const base = V84_NIL + 0x10;
    const addrs = [];
    for (let i = 0; i < K; ++i) addrs.push(base + i * 0x20);
    for (let i = 0; i < K; ++i) {
      pokeV84Node(addrs[i], { parent: i === 0 ? V84_NIL : 0xffffffff,
                              key: rng.u32() % 100, isnil: 0 });
    }
    const used = new Array(K).fill(false);
    used[0] = true;
    for (let i = 0; i < K; ++i) {
      let left = V84_NIL, right = V84_NIL;
      if (rng.u32() % 2 === 0) {
        const j = used.indexOf(false);
        if (j >= 0) { left = addrs[j]; used[j] = true; }
      }
      if (rng.u32() % 2 === 0) {
        const j = used.indexOf(false);
        if (j >= 0) { right = addrs[j]; used[j] = true; }
      }
      pokeU32(addrs[i] + 0x0, left);
      pokeU32(addrs[i] + 0x8, right);
      if (left !== V84_NIL) pokeU32(left + 0x4, addrs[i]);
      if (right !== V84_NIL) pokeU32(right + 0x4, addrs[i]);
    }
    poke(V84_NIL + 0xd, [1]);
    pokeU32(V84_HEADER + 0x4, addrs[0]);
    pokeU32(V84_KEYCELL, rng.u32() % 120);
    wasm.isaac_anm2_tree_lower_bound_plan(
      V84_CONTAINER, V84_OUT, V84_KEYCELL, V84_PLAN);
    const p = readLBPlan(V84_PLAN);
    const o = numify(anm2TreeLowerBoundPlan(shadow, {
      container: V84_CONTAINER, outSlot: V84_OUT, keySlot: V84_KEYCELL,
    }));
    eqV58PlanFields(p, o, LB_FIELDS, `lb t${t}`);
  }
  COUNT.cases += 130;
});

