test("v84-retry: mutations are caught by the pins", () => {
  const sha256 = (txt) =>
    createHash("sha256").update(txt, "utf8").digest("hex");
  const originalBuf = readFileSync(source);
  const originalHash = sha256(originalBuf.toString("utf8"));
  const original = originalBuf.toString("utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const withMutant = (label, mutate, check, probe) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      wasm = loadExports();
      wmem = new Uint8Array(wasm.memory.buffer);
      if (probe) {
        const diverged = probe();
        assert.ok(diverged, `${label}: rebuilt module not mutant (stale build)`);
      }
      check();
    } catch {
      threw = true;
    }
    writeSourceRetry(original);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  buildV84World([10, 20, 30, 40, 50]);
  try {
    /* M1: compare polarity jae -> jb -- the machine descends LEFT on
       node_key >=u key (jae @0x00416465). Flipping descends right and
       misses the y-candidate on the left chain. */
    withMutant("lb polarity flipped",
      (s) => s.replace(
        "    if (node_key >= key) {                    /* 0x00416465 jae */",
        "    if (node_key < key) {                    /* flipped */"),
      () => {
        buildV84World([10, 20, 30, 40, 50]);
        pokeU32(V84_KEYCELL, 5);
        const { p } = runV84();
        eq(p.iterations, 3, "left-chain walk intact");
        eq(p.yNode >>> 0, V84_NODES + 0x10 + 3 * 0x20, "y = idx3");
      },
      () => {
        buildV84World([10, 20, 30, 40, 50]);
        pokeU32(V84_KEYCELL, 5);
        wasm.isaac_anm2_tree_lower_bound_plan(
          V84_CONTAINER, V84_OUT, V84_KEYCELL, V84_PLAN);
        return readPlanU32At(V84_PLAN, 5 * 4) !== (V84_NODES + 0x10 + 3 * 0x20) >>> 0;
      });
    /* M2: candidate store dropped -- the machine writes y into
       [out+8] on every >= step (mov [edx+8],eax @0x00416471). */
    withMutant("lb y store dropped",
      (s) => s.replace(
        "      y = x;                                  /* 0x00416471: [out+8] := x */",
        "      /* y store removed */"),
      () => {
        buildV84World([10, 20, 30, 40, 50]);
        pokeU32(V84_KEYCELL, 30);
        const { p } = runV84();
        eq(p.yNode >>> 0, V84_NODES + 0x50, "y tracked to idx2");
      },
      () => {
        buildV84World([10, 20, 30, 40, 50]);
        pokeU32(V84_KEYCELL, 30);
        wasm.isaac_anm2_tree_lower_bound_plan(
          V84_CONTAINER, V84_OUT, V84_KEYCELL, V84_PLAN);
        return readPlanU32At(V84_PLAN, 7 * 4) !== (V84_NODES + 0x50) >>> 0;
      });
    /* M3: descent direction swapped -- >= must go LEFT (+0), the
       machine's ja-path reads [eax+0] @0x0041646a. */
    withMutant("lb descent swapped",
      (s) => s.replace(
        "      x = load_u32(guest_ptr(x));             /* left, 0x0041646a */",
        "      x = load_u32(guest_ptr(x) + 0x8u);      /* right instead */"),
      () => {
        buildV84World([10, 20, 30, 40, 50]);
        pokeU32(V84_KEYCELL, 5);
        const { p } = runV84();
        eq(p.iterations, 3, "left chain length for key 5");
      },
      () => {
        buildV84World([10, 20, 30, 40, 50]);
        pokeU32(V84_KEYCELL, 5);
        wasm.isaac_anm2_tree_lower_bound_plan(
          V84_CONTAINER, V84_OUT, V84_KEYCELL, V84_PLAN);
        return readPlanU32At(V84_PLAN, 6 * 4) !== 3;
      });
    /* M4: iteration counter dropped -- the machine increments per
       visited node ([out+0] := x each pass). */
    withMutant("lb iterations dropped",
      (s) => s.replace(
        "    plan.iterations++;                        /* 0x00416463: [out] := x */",
        "    /* iterations counter removed */"),
      () => {
        buildV84World([10, 20, 30, 40, 50]);
        pokeU32(V84_KEYCELL, 30);
        const { p } = runV84();
        eq(p.iterations, 2, "two nodes visited");
      },
      () => {
        buildV84World([10, 20, 30, 40, 50]);
        pokeU32(V84_KEYCELL, 30);
        wasm.isaac_anm2_tree_lower_bound_plan(
          V84_CONTAINER, V84_OUT, V84_KEYCELL, V84_PLAN);
        return readPlanU32At(V84_PLAN, 6 * 4) !== 2;
      });
  } finally {
    writeSourceRetry(original);
  }
  wasm = loadExports(); /* clean rebuild after the round-trip */
  wmem = new Uint8Array(wasm.memory.buffer);
  /* sha256-identical restore proof. */
  const restoredHash = sha256(readFileSync(source).toString("utf8"));
  eq(restoredHash, originalHash, "source restored sha256-identical");
  COUNT.cases += 4;
});
/* =========== v85 unit: XML entity-decode trio + UTF-8 leaf law ============ */

/* Own scratch base: below V84's block. Tables are byte-exact copies of
   the PE .rdata class tables, seeded from the verified dump (each table
   is all-1 with its zero set; hex table is 0xff except '0'-'9' -> 0..9
   and 'A'-'F'/'a'-'f' -> 10..15). */
const V85_BASE = SCRATCH_HI - 0x6800;      /* 0x119800 (< V84_BASE) */
const V85_TABLES = V85_BASE + 0x0100;      /* 7 x 0x100 class tables */
const V85_SKIP_0 = V85_TABLES + 0x000;
const V85_SKIP_1 = V85_TABLES + 0x100;
const V85_SKIP_2 = V85_TABLES + 0x200;
const V85_CLS_0 = V85_TABLES + 0x300;
const V85_CLS_1 = V85_TABLES + 0x400;
const V85_CLS_2 = V85_TABLES + 0x500;
const V85_HEX = V85_TABLES + 0x600;
const V85_BUF = V85_BASE + 0x0900;         /* decode input buffer */
const V85_CURSOR = V85_BASE + 0x0d00;      /* cursor slot dword */
const V85_UTF8_PLAN = V85_BASE + 0x0e00;   /* plan (14 x 4 = 56 bytes) */
const V85_DECODE_PLAN = V85_BASE + 0x0f00; /* plan (17 x 4 = 68 bytes) */
const V85_BUF_CAP = 0x380;
const V85_ABI = 77; /* bump target: depth-agent green lands at 73 -> 74 */

/* PE-derived zero sets (dumped from tools/isaac-ng.unpacked.exe). */
const V85_SKIP_ZEROS = [
  [0x00, 0x26, 0x27],                      /* site 0: NUL & ' */
  [0x00, 0x22, 0x26],                      /* site 1: NUL " */
  [0x00, 0x26, 0x3c],                      /* site 2: NUL < */
];
const V85_CLS_ZEROS = [
  [0x00, 0x27],
  [0x00, 0x22],
  [0x00, 0x3c],
];

function v85SeedTables() {
  const blank = new Array(256).fill(0);
  for (let s = 0; s < 3; ++s) {
    const skip = blank.map((_, i) => (V85_SKIP_ZEROS[s].includes(i) ? 0 : 1));
    const cls = blank.map((_, i) => (V85_CLS_ZEROS[s].includes(i) ? 0 : 1));
    poke(V85_SKIP_0 + s * 0x100, skip);
    poke(V85_CLS_0 + s * 0x100, cls);
  }
  const hex = blank.map(() => 0xff);
  for (let i = 0; i < 10; ++i) hex[0x30 + i] = i;
  for (let i = 0; i < 6; ++i) {
    hex[0x41 + i] = 10 + i;
    hex[0x61 + i] = 10 + i;
  }
  poke(V85_HEX, hex);
}

/* Seed `body` (array of byte values or Buffer) at V85_BUF + NUL guard. */
function v85SeedBody(body) {
  const arr = Array.isArray(body) ? body : [...Buffer.from(body)];
  assert.ok(arr.length < V85_BUF_CAP, "v85 body overflow");
  poke(V85_BUF, [...arr, 0].map((b) => b & 0xff));
  pokeU32(V85_CURSOR, V85_BUF);
}

const V85_DECODE_FIELDS = [
  "entered", "cursorSlotAddr", "scanIn", "scanAfterSkip", "skippedCount",
  "scanOut", "decodedEnd", "outBytes", "verbatimCopies", "namedEntities",
  "numericEntities", "utf8Calls", "semiErrors", "invalidCpErrors",
  "lastErrorStringVa", "pureComplete", "hostCallCount",
];

const V85_UTF8_FIELDS = [
  "entered", "cursorSlotAddr", "outStart", "codePoint", "length",
  "b0", "b1", "b2", "b3", "newCursor",
  "errorWritten", "errorStringVa", "pureComplete", "hostCallCount",
];

function readV85DecodePlan() {
  return readPlanFields(V85_DECODE_PLAN, {
    entered: 0, cursorSlotAddr: 4, scanIn: 8, scanAfterSkip: 12,
    skippedCount: 16, scanOut: 20, decodedEnd: 24, outBytes: 28,
    verbatimCopies: 32, namedEntities: 36, numericEntities: 40,
    utf8Calls: 44, semiErrors: 48, invalidCpErrors: 52,
    lastErrorStringVa: 56, pureComplete: 60, hostCallCount: 64,
  }, {
    entered: "i", cursorSlotAddr: "u", scanIn: "u", scanAfterSkip: "u",
    skippedCount: "u", scanOut: "u", decodedEnd: "u", outBytes: "u",
    verbatimCopies: "u", namedEntities: "u", numericEntities: "u",
    utf8Calls: "u", semiErrors: "u", invalidCpErrors: "u",
    lastErrorStringVa: "u", pureComplete: "i", hostCallCount: "i",
  });
}

function readV85Utf8Plan() {
  return readPlanFields(V85_UTF8_PLAN, {
    entered: 0, cursorSlotAddr: 4, outStart: 8, codePoint: 12,
    length: 16, b0: 20, b1: 24, b2: 28, b3: 32, newCursor: 36,
    errorWritten: 40, errorStringVa: 44, pureComplete: 48,
    hostCallCount: 52,
  }, {
    entered: "i", cursorSlotAddr: "u", outStart: "u", codePoint: "u",
    length: "u", b0: "u", b1: "u", b2: "u", b3: "u", newCursor: "u",
    errorWritten: "i", errorStringVa: "u", pureComplete: "i",
    hostCallCount: "i",
  });
}

/* Site table bases by index (matches the per-site pins in the model). */
function v85SiteTables(site) {
  return {
    skipTable: [V85_SKIP_0, V85_SKIP_1, V85_SKIP_2][site],
    classTable: [V85_CLS_0, V85_CLS_1, V85_CLS_2][site],
  };
}

function runV85Decode(site, body) {
  v85SeedBody(body);
  const t = v85SiteTables(site);
  wasm.isaac_anm2_xml_decode_text_plan(
    V85_CURSOR, t.skipTable, t.classTable, V85_HEX, V85_DECODE_PLAN);
  const p = readV85DecodePlan();
  const o = numify(anm2XmlDecodeTextPlan(shadow, {
    cursorSlotAddr: V85_CURSOR,
    skipTable: t.skipTable, classTable: t.classTable, hexTable: V85_HEX,
  }));
  return { p, o };
}

function runV85Utf8(cp) {
  pokeU32(V85_CURSOR, V85_BUF);
  wasm.isaac_anm2_xml_utf8_encode_plan(V85_CURSOR, cp >>> 0, V85_UTF8_PLAN);
  const p = readV85Utf8Plan();
  const o = numify(anm2XmlUtf8EncodePlan(shadow, {
    cursorSlotAddr: V85_CURSOR, codePoint: cp >>> 0,
  }));
  return { p, o };
}

test("v85 unit: constants + census pins + fixed edges (xml decode)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  assert.equal(typeof wasm.isaac_anm2_xml_decode_text_plan, "function",
               "EXPORTS: isaac_anm2_xml_decode_text_plan");
  assert.equal(typeof wasm.isaac_anm2_xml_utf8_encode_plan, "function",
               "EXPORTS: isaac_anm2_xml_utf8_encode_plan");

  eq(ANM2_XML_UTF8_VA, 0x00416dc0);
  eq(ANM2_XML_UTF8_END_VA, 0x00416e69);
  eq(ANM2_XML_UTF8_BODY_BYTES, 0xa9);
  eq(ANM2_XML_UTF8_CALLSITE_COUNT, 3);
  eq(ANM2_XML_UTF8_ADDR_TAKEN, 0);
  eq(ANM2_XML_UTF8_ERR_SLOT_VA, 0xc7de4c);
  eq(ANM2_XML_UTF8_INVALID_CP_VA, 0xb1b704);

  eq(ANM2_XML_DECODE_TEXT_VA_0, 0x00416920);
  eq(ANM2_XML_DECODE_TEXT_END_VA_0, 0x00416afb);
  eq(ANM2_XML_DECODE_SKIP_TABLE_VA_0, 0xb1a960);
  eq(ANM2_XML_DECODE_CLASS_TABLE_VA_0, 0xb1ac60);
  eq(ANM2_XML_DECODE_TERM_CHAR_0, 0x27);
  eq(ANM2_XML_DECODE_CALLSITE_VA_0, 0x0041671e);
  eq(ANM2_XML_DECODE_TEXT_VA_1, 0x00416b70);
  eq(ANM2_XML_DECODE_TEXT_END_VA_1, 0x00416d4c);
  eq(ANM2_XML_DECODE_SKIP_TABLE_VA_1, 0xb1a860);
  eq(ANM2_XML_DECODE_CLASS_TABLE_VA_1, 0xb1ab60);
  eq(ANM2_XML_DECODE_TERM_CHAR_1, 0x22);
  eq(ANM2_XML_DECODE_CALLSITE_VA_1, 0x004166de);
  eq(ANM2_XML_DECODE_TEXT_VA_2, 0x00416e80);
  eq(ANM2_XML_DECODE_TEXT_END_VA_2, 0x0041705c);
  eq(ANM2_XML_DECODE_SKIP_TABLE_VA_2, 0xb1a760);
  eq(ANM2_XML_DECODE_CLASS_TABLE_VA_2, 0xb1aa60);
  eq(ANM2_XML_DECODE_TERM_CHAR_2, 0x3c);
  eq(ANM2_XML_DECODE_CALLSITE_VA_2, 0x004167fd);
  eq(ANM2_XML_DECODE_HEX_TABLE_VA, 0xb1ad60);
  eq(ANM2_XML_DECODE_LOOKUP_VA_0, 0x00416b14);
  eq(ANM2_XML_DECODE_LOOKUP_VA_1, 0x00416d64);
  eq(ANM2_XML_DECODE_LOOKUP_VA_2, 0x00417074);
  eq(ANM2_XML_DECODE_JUMPTAB_VA_0, 0x00416afc);
  eq(ANM2_XML_DECODE_JUMPTAB_VA_1, 0x00416d4c);
  eq(ANM2_XML_DECODE_JUMPTAB_VA_2, 0x0041705c);
  eq(ANM2_XML_DECODE_ERROR_SLOT_VA, 0xc7de4c);
  eq(ANM2_XML_DECODE_EXPECTED_SEMI_VA, 0xb1b6f8);
  eq(ANM2_XML_DECODE_DISPATCH_BASE, -0x23);
  eq(ANM2_XML_DECODE_DISPATCH_BOUND, 0x4e);
  eq(ANM2_XML_DECODE_UTF8_CALLEE_VA, 0x00416dc0);

  v85SeedTables();

  /* Named entities on every site (template identity across sites). */
  for (let s = 0; s < ANM2_XML_DECODE_SITES; ++s) {
    let { p, o } = runV85Decode(s, "&amp;&apos;&quot;&gt;&lt;");
    eq(p.outBytes >>> 0, 5, `five emitted bytes s${s}`);
    eq(p.verbatimCopies >>> 0, 0, `no fallbacks s${s}`);
    eq(p.decodedEnd >>> 0, V85_BUF + 5, `in-place out end s${s}`);

    /* Numeric entities incl hex / capital-X hex / decimal. */
    ({ p, o } = runV85Decode(s, "&#65;&#x42;&#X43;&#123;"));
    eqV58PlanFields(p, o, V85_DECODE_FIELDS, `numeric s${s}`);
    eq(p.numericEntities >>> 0, 4, `four numerics s${s}`);
    eq(p.utf8Calls >>> 0, 4, `four utf8 calls s${s}`);
    eq(p.semiErrors >>> 0, 1, `exactly the X-variant semi error s${s}`);

    /* Missing ';' after numeric -> pinned error string VA. */
    ({ p, o } = runV85Decode(s, "&#65z"));
    eqV58PlanFields(p, o, V85_DECODE_FIELDS, `semi err s${s}`);
    eq(p.semiErrors >>> 0, 1, `missing semi reported s${s}`);
    eq(p.lastErrorStringVa >>> 0, ANM2_XML_DECODE_EXPECTED_SEMI_VA,
       `expected-; string s${s}`);

    /* Codepoint overflow: callee error arm, no bytes land. */
    ({ p, o } = runV85Decode(s, "&#x110000;"));
    eqV58PlanFields(p, o, V85_DECODE_FIELDS, `cp overflow s${s}`);
    eq(p.invalidCpErrors >>> 0, 1, `invalid cp reported s${s}`);
    eq(p.lastErrorStringVa >>> 0, ANM2_XML_UTF8_INVALID_CP_VA,
       `invalid-cp string s${s}`);
    /* Per-site terminator stops the scan (the template's only
       instantiation difference). Machine shape: the SKIP loop runs
       first and consumes up to '&'/term/NUL, so seed an ENTITY before
       the terminator to give the decode loop work. */
    const termChar = [0x27, 0x22, 0x3c][s];
    ({ p, o } = runV85Decode(s,
      [...Buffer.from("&amp;"), termChar,
       "r".charCodeAt(0), "e".charCodeAt(0), "s".charCodeAt(0)]));
    eqV58PlanFields(p, o, V85_DECODE_FIELDS, `terminator s${s}`);
    eq(p.skippedCount >>> 0, 0, `skip stops at '&' s${s}`);
    eq(p.namedEntities >>> 0, 1, `entity decoded s${s}`);
    eq(p.outBytes >>> 0, 1, `emits only the entity byte s${s}`);
    eq(p.scanOut >>> 0, V85_BUF + 5, `stops at terminator s${s}`);
    eq(p.decodedEnd >>> 0, V85_BUF + 1, `out ends after entity s${s}`);

    /* Plain prefix is SKIPPED, not decoded (machine skip loop). */
    ({ p, o } = runV85Decode(s, ["o".charCodeAt(0), "k".charCodeAt(0),
                                 termChar]));
    eqV58PlanFields(p, o, V85_DECODE_FIELDS, `prefix skip s${s}`);
    eq(p.skippedCount >>> 0, 2, `two prefix bytes skipped s${s}`);
    eq(p.scanOut >>> 0, V85_BUF + 2, `decode starts at term s${s}`);
    eq(p.outBytes >>> 0, 0, `nothing decoded s${s}`);
  }

  /* Fallback: '&' + non-entity chars copies '&' verbatim (machine
     default path handles plain chars AND failed entities alike). */
  let { p, o } = runV85Decode(2, "&foo&bar;");
  eqV58PlanFields(p, o, V85_DECODE_FIELDS, "fallback");
  eq(p.verbatimCopies >>> 0, 9, "two ampersand fallbacks + seven plain");
  eq(p.namedEntities >>> 0, 0, "no named match");
  eq(p.outBytes >>> 0, 9, "every byte copied");

  /* Leading skip loop: site-0 skips up to '&'/'\''/NUL. */
  ({ p, o } = runV85Decode(0, "ab &amp;"));
  eq(p.skippedCount >>> 0, 3, "skip loop consumed 'ab '");
  eq(p.scanAfterSkip >>> 0, V85_BUF + 3, "scan resumes at '&'");

  /* UTF-8 leaf: boundary sweep over the four arms + error arm. */
  for (const cp of [0x00, 0x41, 0x7f, 0x80, 0x07ff, 0x800, 0xffff,
                    0x10000, 0x10ffff]) {
    const r = runV85Utf8(cp);
    eqV58PlanFields(r.p, r.o, V85_UTF8_FIELDS, `utf8 ${cp}`);
  }
  let u = runV85Utf8(0x41);
  eq(u.p.length >>> 0, 1, "ascii one byte");
  eq(u.p.b0 >>> 0, 0x41, "ascii byte");
  eq(u.p.newCursor >>> 0, V85_BUF + 1, "cursor advanced 1");
  u = runV85Utf8(0x800);
  eq(u.p.length >>> 0, 3, "U+0800 opens the three-byte arm");
  eq(u.p.b0 >>> 0, 0xe0, "three-byte lead at the boundary");
  u = runV85Utf8(0x7ff);
  eq(u.p.length >>> 0, 2, "U+07ff still two-byte");
  u = runV85Utf8(0x10000);
  eq(u.p.length >>> 0, 4, "U+10000 four-byte arm");
  eq(u.p.b0 >>> 0, 0xf0, "four-byte lead");
  u = runV85Utf8(0x110000);
  eq(u.p.length >>> 0, 0, "overflow encodes nothing");
  eq(u.p.errorWritten, 1, "overflow errors");
  eq(u.p.errorStringVa >>> 0, ANM2_XML_UTF8_INVALID_CP_VA, "error string");
  eq(u.p.newCursor >>> 0, V85_BUF, "cursor unchanged on error");

  /* Null edges. */
  wasm.isaac_anm2_xml_decode_text_plan(
    0, V85_SKIP_0, V85_CLS_0, V85_HEX, V85_DECODE_PLAN);
  eq(readV85DecodePlan().entered, 0, "null cursor not entered");
  wasm.isaac_anm2_xml_decode_text_plan(
    V85_CURSOR, 0, V85_CLS_0, V85_HEX, V85_DECODE_PLAN);
  eq(readV85DecodePlan().entered, 0, "null skip table refused");
  wasm.isaac_anm2_xml_utf8_encode_plan(0, 0x41, V85_UTF8_PLAN);
  eq(readV85Utf8Plan().entered, 0, "null utf8 slot not entered");
  wasm.isaac_anm2_xml_decode_text_plan(
    V85_CURSOR, V85_SKIP_0, V85_CLS_0, V85_HEX, 0); /* null out ok */

  eq(wasm.isaac_anm2_pure_helpers_abi_version(), V85_ABI,
     "ABI bump export");
  COUNT.cases += 120;
});

test("v85 unit: randomized differential (wasm vs oracle)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  assert.equal(typeof wasm.isaac_anm2_xml_decode_text_plan, "function");
  v85SeedTables();
  const rng = makeRng(0x00416920);
  const alphabet = Buffer.from(
    "&;'\"<>=qpalmtxu#0123456789abcdefABCDEFgo \x01\xff");
  const randEntity = (depth) => {
    const roll = rng.below(100);
    if (roll < 12) return Buffer.from("&amp;");
    if (roll < 24) return Buffer.from("&apos;");
    if (roll < 36) return Buffer.from("&quot;");
    if (roll < 48) return Buffer.from("&gt;");
    if (roll < 60) return Buffer.from("&lt;");
    if (roll < 75) {
      let digits = "";
      const n = 1 + rng.below(6);
      const pool = "0123456789abcdefABCDEFg";
      for (let i = 0; i < n; ++i) digits += pool[rng.below(pool.length)];
      if (rng.below(100) < 85) digits += ";";
      return Buffer.from("#" + (rng.below(2) ? "x" : "") + digits);
    }
    if (depth < 2 && rng.below(100) < 10) {
      return Buffer.concat([Buffer.from("&"), randEntity(depth + 1)]);
    }
    const tail = [";", "", "x;"][rng.below(3)];
    return Buffer.from("&" +
      String.fromCharCode(0x61 + rng.below(26)) + tail);
  };
  for (let t = 0; t < 220; ++t) {
    const parts = [];
    const len = rng.below(15);
    for (let i = 0; i < len; ++i) {
      if (rng.below(100) < 55) {
        parts.push(Buffer.from([alphabet[rng.below(alphabet.length)]]));
      } else {
        parts.push(randEntity(0));
      }
    }
    const body = Buffer.concat(parts);
    const site = rng.below(3);
    const { p, o } = runV85Decode(site, body);
    eqV58PlanFields(p, o, V85_DECODE_FIELDS, `decode t${t} s${site}`);
  }
  for (let t = 0; t < 160; ++t) {
    const cp = rng.below(20) === 0
      ? rng.u32()
      : [0, 1, 0x7f, 0x80, 0x7ff, 0x800, 0xffff, 0x10000, 0x10ffff,
         0x110000, 0xffffff][rng.below(11)] + rng.below(4);
    const { p, o } = runV85Utf8(cp >>> 0);
    eqV58PlanFields(p, o, V85_UTF8_FIELDS, `utf8 t${t}`);
  }
  COUNT.cases += 380;
});

test("v85 unit: header + model pins hold", () => {
  const headerText = readFileSync(header, "utf8");
  const modelText = readFileSync(model, "utf8");
  assert.match(headerText, /ISAAC_ANM2_XML_UTF8_VA = 0x00416dc0u/);
  assert.match(headerText, /ISAAC_ANM2_XML_UTF8_BODY_BYTES = 0xa9u/);
  assert.match(headerText, /ISAAC_ANM2_XML_UTF8_CALLSITE_COUNT = 3/);
  assert.match(headerText, /ISAAC_ANM2_XML_DECODE_TEXT_VA_0 = 0x00416920u/);
  assert.match(headerText, /ISAAC_ANM2_XML_DECODE_TEXT_VA_1 = 0x00416b70u/);
  assert.match(headerText, /ISAAC_ANM2_XML_DECODE_TEXT_VA_2 = 0x00416e80u/);
  assert.match(headerText,
               /ISAAC_ANM2_XML_DECODE_SKIP_TABLE_VA_0 = 0xb1a960u/);
  assert.match(headerText,
               /ISAAC_ANM2_XML_DECODE_CLASS_TABLE_VA_2 = 0xb1aa60u/);
  assert.match(headerText,
               /IsaacAnm2XmlUtf8Plan; \/\* 14 x 4 = 56 bytes \*\//);
  assert.match(headerText,
               /IsaacAnm2XmlDecodeTextPlan; \/\* 17 x 4 = 68 bytes \*\//);
  assert.match(modelText, /ANM2_XML_UTF8_VA = 0x00416dc0/);
  assert.match(modelText, /export function anm2XmlUtf8EncodePlan/);
  assert.match(modelText, /export function anm2XmlDecodeTextPlan/);
  const sourceText = readFileSync(source, "utf8");
  assert.match(sourceText,
    /ISAAC_ANM2_NO_NARROW_PARAMS\(isaac_anm2_xml_utf8_encode_plan\)/);
  assert.match(sourceText,
    /ISAAC_ANM2_NO_NARROW_PARAMS\(isaac_anm2_xml_decode_text_plan\)/);
  assert.match(sourceText,
    /static_assert\(sizeof\(IsaacAnm2XmlUtf8Plan\) == 56/);
  assert.match(sourceText,
    /static_assert\(sizeof\(IsaacAnm2XmlDecodeTextPlan\) == 68/);
  COUNT.cases += 1;
});

test("v85 unit: mutations are caught by the pins", () => {
  const sha256 = (txt) =>
    createHash("sha256").update(txt, "utf8").digest("hex");
  const originalBuf = readFileSync(source);
  const originalHash = sha256(originalBuf.toString("utf8"));
  const original = originalBuf.toString("utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const withMutant = (label, mutate, check, probe) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      wasm = loadExports();
      wmem = new Uint8Array(wasm.memory.buffer);
      if (probe) {
        const diverged = probe();
        assert.ok(diverged,
                  `${label}: rebuilt module not mutant (stale build)`);
      }
      check();
    } catch {
      threw = true;
    }
    writeSourceRetry(original);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    /* M1: class-table exit inverted -- the loop exits when the class
       byte reads 0 (je @0x00416961), never when nonzero. */
    withMutant("decode class exit inverted",
      (s) => s.replace(
        "if (load_u8(guest_ptr(class_table) + bl) == 0u) break;",
        "if (load_u8(guest_ptr(class_table) + bl) != 0u) break;"),
      () => {
        v85SeedTables();
        const { p } = runV85Decode(2, Buffer.from("ok"));
        eq(p.outBytes >>> 0, 2, "'o' must copy while class says go");
      },
      () => {
        v85SeedTables();
        const { p } = runV85Decode(2, Buffer.from("ok"));
        return p.outBytes !== 2 || p.verbatimCopies !== 2;
      });
    /* M2: dispatch bound strict -- idx == 0x4e ('q') MUST take its case
       (ja @0x0041697a is unsigned STRICTLY-greater). */
    withMutant("decode quot falls to default",
      (s) => s.replace(
        "idx > static_cast<uint32_t>(ISAAC_ANM2_XML_DECODE_DISPATCH_BOUND)",
        "idx >= static_cast<uint32_t>(ISAAC_ANM2_XML_DECODE_DISPATCH_BOUND)"),
      () => {
        v85SeedTables();
        const { p } = runV85Decode(2, Buffer.from("&quot;"));
        eq(p.namedEntities >>> 0, 1, "&quot; must decode");
      },
      () => {
        v85SeedTables();
        const { p } = runV85Decode(2, Buffer.from("&quot;"));
        return p.namedEntities !== 1;
      });
    /* M3: decimal accumulation base corrupted (lea pair must be
       acc*10+v; acc*18 sends &#300; to a 3-byte instead of 2-byte
       codepoint). */
    withMutant("decimal base wrong",
      (s) => s.replace(
        "acc = ((acc + acc * 4u) << 1) + v;",
        "acc = ((acc + acc * 8u) << 1) + v;"),
      () => {
        v85SeedTables();
        const { p } = runV85Decode(2, Buffer.from("&#300;"));
        eq(p.outBytes >>> 0, 2, "decimal 300 encodes two bytes");
      },
      () => {
        v85SeedTables();
        const { p } = runV85Decode(2, Buffer.from("&#300;"));
        return p.utf8Calls === 1 && p.outBytes !== 2;
      });
    /* M4: missing-';' error string dropped from the report. */
    withMutant("expected-semi va dropped",
      (s) => s.replace(
        "plan.last_error_string_va = static_cast<uint32_t>(\n" +
        "                  ISAAC_ANM2_XML_DECODE_EXPECTED_SEMI_VA);",
        "plan.last_error_string_va = 0u;"),
      () => {
        v85SeedTables();
        const { p } = runV85Decode(2, Buffer.from("&#65z"));
        eq(p.lastErrorStringVa >>> 0, ANM2_XML_DECODE_EXPECTED_SEMI_VA,
           "expected-; VA must be reported");
      },
      () => {
        v85SeedTables();
        const { p } = runV85Decode(2, Buffer.from("&#65z"));
        return p.semiErrors === 1 && p.lastErrorStringVa === 0;
      });
    /* M5: 3-byte lead OR-mask wrong (0xe0 not 0xc0 -- or dl,0xe0 at
       0x00416e15 in the site-0 callee listing). */
    withMutant("utf8 3-byte lead corrupted",
      (s) => s.replace(
        "plan.b0 = (0xe0u | (cp >> 12)) & 0xffu;",
        "plan.b0 = (0xc0u | (cp >> 12)) & 0xffu;"),
      () => {
        const r = runV85Utf8(0xe9);
        eq(r.p.b0 >>> 0, 0xe3, "3-byte lead for U+00E9");
      },
      () => {
        const r = runV85Utf8(0xe9);
        return r.p.length === 3 && r.p.b0 !== 0xe3;
      });
    /* M6: 2-byte/3-byte threshold moved (cmp edx,0x800 jae chain). */
    withMutant("utf8 threshold 0x800 raised",
      (s) => s.replace(
        "} else if (cp < 0x800u) {",
        "} else if (cp < 0x1000u) {"),
      () => {
        const r = runV85Utf8(0x800);
        eq(r.p.length >>> 0, 3, "U+0800 must take the 3-byte arm");
      },
      () => {
        const r = runV85Utf8(0x800);
        return r.p.length !== 2;
      });
    /* M7: invalid-codepoint error string dropped (mov dword
       [0xc7de4c],0xb1b704 @0x00416e5e). */
    withMutant("invalid-cp va dropped",
      (s) => s.replace(
        "plan.error_string_va =\n" +
        "        static_cast<uint32_t>(ISAAC_ANM2_XML_UTF8_INVALID_CP_VA);",
        "plan.error_string_va = 0u;"),
      () => {
        const r = runV85Utf8(0x110000);
        eq(r.p.errorStringVa >>> 0, ANM2_XML_UTF8_INVALID_CP_VA,
           "invalid-cp VA must be reported");
      },
      () => {
        const r = runV85Utf8(0x110000);
        return r.p.errorWritten === 1 && r.p.errorStringVa === 0;
      });
  } finally {
    writeSourceRetry(original);
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  eq(sha256(readFileSync(source).toString("utf8")), originalHash,
     "v85 mutation round restored source byte-exact");
  COUNT.cases += 14;
});

/* =========== v86 unit: 0x00416510 XML arena allocator split law ========== */

const V86_BASE = SCRATCH_HI - 0x7000;      /* 0x119000 (< V85_BASE) */
const V86_ARENA = SCRATCH_BASE + 0x8000;   /* low arena: +0x1000c fn slot lands at 0x11800c < SCRATCH_HI */
const V86_PLAN = V86_BASE + 0x0200;        /* plan (18 x 4 = 72 bytes) */
const V86_ABI = 77; /* bump target on top of v85's 74 */

function v86SeedArena({ end, cap, fn }) {
  pokeU32(V86_ARENA, V86_ARENA);           /* begin (any non-zero) */
  pokeU32(V86_ARENA + 4, end >>> 0);
  pokeU32(V86_ARENA + 8, cap >>> 0);
  pokeU32(V86_ARENA + ANM2_XML_ALLOC_CUSTOM_FN_OFF, fn === undefined ? 0 : fn >>> 0);
}

const V86_FIELDS = [
  "entered", "arenaAddr", "needed", "curEnd", "alignPad", "alignedEnd",
  "reqEnd", "cap", "grow", "growBlocks", "allocSize", "customFn",
  "useCustom", "oomStringVa", "pureComplete", "hostCallCount",
  "newEnd", "retPtr",
];

function readV86Plan() {
  return readPlanFields(V86_PLAN, {
    entered: 0, arenaAddr: 4, needed: 8, curEnd: 12, alignPad: 16,
    alignedEnd: 20, reqEnd: 24, cap: 28, grow: 32, growBlocks: 36,
    allocSize: 40, customFn: 44, useCustom: 48, oomStringVa: 52,
    pureComplete: 56, hostCallCount: 60, newEnd: 64, retPtr: 68,
  }, {
    entered: "i", arenaAddr: "u", needed: "u", curEnd: "u", alignPad: "u",
    alignedEnd: "u", reqEnd: "u", cap: "u", grow: "i", growBlocks: "u",
    allocSize: "u", customFn: "u", useCustom: "i", oomStringVa: "u",
    pureComplete: "i", hostCallCount: "i", newEnd: "u", retPtr: "u",
  });
}

function runV86(needed, seed) {
  v86SeedArena(seed || { end: 0x2000, cap: 0x4000 });
  wasm.isaac_anm2_xml_alloc_plan(V86_ARENA, needed >>> 0, V86_PLAN);
  const p = readV86Plan();
  const o = numify(anm2XmlAllocPlan(shadow, { arenaAddr: V86_ARENA, needed: needed >>> 0 }));
  return { p, o };
}

test("v86 unit: constants + census pins + fixed edges (xml alloc)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  assert.equal(typeof wasm.isaac_anm2_xml_alloc_plan, "function",
               "EXPORTS: isaac_anm2_xml_alloc_plan");

  eq(ANM2_XML_ALLOC_VA, 0x00416510);
  eq(ANM2_XML_ALLOC_END_VA, 0x0041659a);
  eq(ANM2_XML_ALLOC_BODY_BYTES, 0x8d);
  eq(ANM2_XML_ALLOC_CALLSITE_COUNT, 16);
  eq(ANM2_XML_ALLOC_ADDR_TAKEN, 0);
  eq(ANM2_XML_ALLOC_ALIGN_MASK, 3);
  eq(ANM2_XML_ALLOC_GROW_FLOOR, 0x10000);
  eq(ANM2_XML_ALLOC_HDR_SLACK, 0xa);
  eq(ANM2_XML_ALLOC_CUSTOM_FN_OFF, 0x1000c);
  eq(ANM2_XML_ALLOC_OOM_STRING_VA, 0xb1b6b4);
  eq(ANM2_XML_ALLOC_ERROR_SLOT_VA, 0xc7de4c);
  eq(ANM2_XML_ALLOC_CRT_MALLOC_VA, 0xa0f4e0);

  /* FAST arm: aligned end, fits -> pure-complete bump. */
  let { p, o } = runV86(0x40);
  eqV58PlanFields(p, o, V86_FIELDS, "fast aligned");
  eq(p.grow, 0, "fits");
  eq(p.alignPad >>> 0, 0, "end already aligned");
  eq(p.retPtr >>> 0, 0x2000, "data ptr = end");
  eq(p.newEnd >>> 0, 0x2040, "end bumped by needed");
  eq(p.pureComplete, 1, "fast arm complete");
  eq(p.hostCallCount, 0, "no host call");

  /* Unaligned end: pad = (-end)&3 (end 0x2001 -> pad 3). */
  ({ p, o } = runV86(0x10, { end: 0x2001, cap: 0x4000 }));
  eqV58PlanFields(p, o, V86_FIELDS, "fast unaligned");
  eq(p.alignPad >>> 0, 3, "pad to 4");
  eq(p.retPtr >>> 0, 0x2004, "ptr skips pad");
  eq(p.newEnd >>> 0, 0x2014, "req from aligned");

  /* Exact fit is NOT growth: req == cap takes jbe (fast). */
  ({ p, o } = runV86(0x100, { end: 0x2000, cap: 0x2100 }));
  eqV58PlanFields(p, o, V86_FIELDS, "exact fit");
  eq(p.grow, 0, "req == cap stays fast");
  eq(p.reqEnd >>> 0, 0x2100, "required equals cap");

  /* GROW via custom fn: shape reported, call unresolved. */
  ({ p, o } = runV86(0x30, { end: 0x2000, cap: 0x2010, fn: 0xdead0 }));
  eqV58PlanFields(p, o, V86_FIELDS, "grow custom");
  eq(p.grow, 1, "grows");
  eq(p.customFn >>> 0, 0xdead0, "fn slot read");
  eq(p.useCustom, 1, "custom arm");
  eq(p.growBlocks >>> 0, 0x10000, "floor applies");
  eq(p.allocSize >>> 0, 0x1000a, "header slack added");
  eq(p.oomStringVa >>> 0, 0, "no CRT string on custom arm");
  eq(p.pureComplete, 0, "grow unresolved");
  eq(p.hostCallCount, 1, "one host call");
  eq(p.newEnd >>> 0, 0, "new end host-decided");
  eq(p.retPtr >>> 0, 0, "ret ptr host-decided");

  /* GROW above floor: blocks = needed verbatim. */
  ({ p, o } = runV86(0x20000, { end: 0x2000, cap: 0x2010 }));
  eqV58PlanFields(p, o, V86_FIELDS, "grow big");
  eq(p.growBlocks >>> 0, 0x20000, "needed above floor kept");
  eq(p.allocSize >>> 0, 0x2000a, "slack still added");
  eq(p.useCustom, 0, "falls back to CRT malloc");
  eq(p.oomStringVa >>> 0, ANM2_XML_ALLOC_OOM_STRING_VA,
     "CRT arm carries the OOM string pin");

  /* u32 wrap: req wraps past 2^32 -> huge unsigned -> grows. */

  /* Null edges. */
  wasm.isaac_anm2_xml_alloc_plan(0, 0x10, V86_PLAN);
  eq(readV86Plan().entered, 0, "null arena not entered");
  wasm.isaac_anm2_xml_alloc_plan(V86_ARENA, 0x10, 0); /* null out ok */

  eq(wasm.isaac_anm2_pure_helpers_abi_version(), V86_ABI,
     "ABI bump export");
  COUNT.cases += 90;
});

test("v86 unit: randomized differential (wasm vs oracle)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  assert.equal(typeof wasm.isaac_anm2_xml_alloc_plan, "function");
  const rng = makeRng(0x00416510);
  for (let t = 0; t < 220; ++t) {
    const end = rng.below(3) === 0 ? rng.u32() : rng.u32() & ~3;
    const cap = rng.below(4) === 0 ? 0 : rng.u32();
    const fn = rng.below(2) === 0 ? rng.u32() & ~1 : 0;
    const needed = rng.below(6) === 0 ? 0
      : rng.below(2) === 0 ? rng.u32() % 0x21000 : rng.u32();
    const { p, o } = runV86(needed, { end, cap, fn });
    eqV58PlanFields(p, o, V86_FIELDS, `alloc t${t}`);
  }
  COUNT.cases += 220;
});

