test("v87 unit: mutations are caught by the pins", () => {
  const sha256 = (txt) =>
    createHash("sha256").update(txt, "utf8").digest("hex");
  const originalBuf = readFileSync(source);
  const originalHash = sha256(originalBuf.toString("utf8"));
  const original = originalBuf.toString("utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const withMutant = (label, mutate, check, probe) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      wasm = loadExports();
      wmem = new Uint8Array(wasm.memory.buffer);
      if (probe) {
        const diverged = probe();
        assert.ok(diverged,
                  `${label}: rebuilt module not mutant (stale build)`);
      }
      check();
    } catch {
      threw = true;
    }
    writeSourceRetry(original);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    /* N1: name-length arithmetic loses the gate char (machine includes
       it: len = end - scan_in, scan starts cur+1). */
    withMutant("attr name len off by one",
      (s) => s.replace(
        "plan.name_len = ecx - esi;",
        "plan.name_len = ecx - esi - 1u;"),
      () => {
        const { p } = v87Run('width="10"');
        eq(p.nameLen >>> 0, 5, "gate char counts in the name");
      },
      () => {
        const { p } = v87Run('width="10"');
        return p.nameLen !== 5;
      });
    /* N2: link polarity inverted -- prev comes from LAST only when
       FIRST is nonzero (je @0x0041662e). */
    withMutant("attr link polarity inverted",
      (s) => s.replace(
        "plan.link_prev_value = parent_first != 0u ? parent_last_old : 0u;",
        "plan.link_prev_value = parent_first == 0u ? parent_last_old : 0u;"),
      () => {
        const { p } = v87Run('id="7"', { first: 0x3000, last: 0x3080 });
        eq(p.linkPrevValue >>> 0, 0x3080, "prev := old last");
      },
      () => {
        const { p } = v87Run('id="7"', { first: 0x3000, last: 0x3080 });
        return p.linkPrevValue !== 0x3080;
      });
    /* N3: '=' byte wrong -- cmp [ecx],0x3d (0x00416678). */
    withMutant("attr equals byte corrupted",
      (s) => s.replace(
        "plan.saw_equals = load_u8(guest_ptr(cur)) == 0x3du ? 1 : 0;",
        "plan.saw_equals = load_u8(guest_ptr(cur)) == 0x3eu ? 1 : 0;"),
      () => {
        const { p } = v87Run('width="10"');
        eq(p.sawEquals, 1, "= must be detected");
      },
      () => {
        const { p } = v87Run('width="10"');
        return p.sawEquals !== 1;
      });
    /* N4: single-quote site selection flipped (' -> site1). */
    withMutant("attr site selection flipped",
      (s) => s.replace(
        "  if (q == 0x27u) {\n    plan.decode_site = 0;",
        "  if (q == 0x27u) {\n    plan.decode_site = 1;"),
      () => {
        const { p } = v87Run("name='x'");
        eq(p.decodeSite, 0, "single quote -> site0");
      },
      () => {
        const { p } = v87Run("name='x'");
        return p.decodeSite !== 0;
      });
    /* N5: expected-= string dropped from the report (0xb1b6dc). */
    withMutant("attr missing-eq va dropped",
      (s) => s.replace(
        "  plan.missing_eq_va = plan.saw_equals != 0\n" +
        "      ? 0u : static_cast<uint32_t>(ISAAC_ANM2_XML_ATTR_EXPECTED_EQ_VA);",
        "  plan.missing_eq_va = 0u;"),
      () => {
        const { p } = v87Run("width:10");
        eq(p.missingEqVa >>> 0, ANM2_XML_ATTR_EXPECTED_EQ_VA,
           "eq error must be reported");
      },
      () => {
        const { p } = v87Run("width:10");
        return p.missingEqVa === 0;
      });
  } finally {
    writeSourceRetry(original);
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  eq(sha256(readFileSync(source).toString("utf8")), originalHash,
     "v87 mutation round restored source byte-exact");
  COUNT.cases += 10;
});

/* =========== v88 unit: accessor bulk band (3 template laws) ============= */

const V88_OBJ = V86_BASE + 0x0c00;         /* accessor target object */
const V88_PAIRPLAN = V86_BASE + 0x0e00;    /* pair plan (7 x 4 = 28 B) */

function v88Seed(lo, hi) {
  pokeU32(V88_OBJ, lo >>> 0);
  pokeU32(V88_OBJ + 4, hi >>> 0);
}

function v88RunU32(off) {
  const p = wasm.isaac_anm2_u32_field_get(V88_OBJ, off >>> 0) >>> 0;
  const o = anm2U32FieldGet(shadow, { thisAddr: V88_OBJ, off: off >>> 0 }) >>> 0;
  return { p, o };
}

function v88RunF32(off) {
  const p = wasm.isaac_anm2_f32_field_get_bits(V88_OBJ, off >>> 0) >>> 0;
  const o = anm2F32FieldGetBits(shadow, { thisAddr: V88_OBJ, off: off >>> 0 }) >>> 0;
  return { p, o };
}

function v88RunPair(off) {
  wasm.isaac_anm2_pair_field_get_plan(V88_OBJ, off >>> 0, V88_PAIRPLAN);
  const p = readPlanFields(V88_PAIRPLAN, {
    entered: 0, thisAddr: 4, off: 8, lo: 12, hi: 16,
    pureComplete: 20, hostCallCount: 24,
  }, {
    entered: "i", thisAddr: "u", off: "u", lo: "u", hi: "u",
    pureComplete: "i", hostCallCount: "i",
  });
  const o = numify(anm2PairFieldGetPlan(shadow, {
    thisAddr: V88_OBJ, off: off >>> 0,
  }));
  return { p, o };
}

test("v88 unit: constants + census pins + fixed edges (accessors)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  assert.equal(typeof wasm.isaac_anm2_u32_field_get, "function",
               "EXPORTS: isaac_anm2_u32_field_get");
  assert.equal(typeof wasm.isaac_anm2_f32_field_get_bits, "function",
               "EXPORTS: isaac_anm2_f32_field_get_bits");
  assert.equal(typeof wasm.isaac_anm2_pair_field_get_plan, "function",
               "EXPORTS: isaac_anm2_pair_field_get_plan");

  eq(ANM2_ACC_U32_GET_COUNT, 8);
  eq(ANM2_ACC_F32_GET_COUNT, 4);
  eq(ANM2_ACC_PAIR_GET_COUNT, 3);

  /* Byte-exact site pins: VA + offset per template instance. */
  const u32vas = ANM2_ACC_U32_SITES.map((s) => s.va);
  eq(u32vas[0], 0x00417260); eq(u32vas[1], 0x00417270);
  eq(u32vas[2], 0x00417280); eq(u32vas[3], 0x00417710);
  eq(u32vas[4], 0x00417380); eq(u32vas[5], 0x00417490);
  eq(u32vas[6], 0x004174a0); eq(u32vas[7], 0x00417860);
  const u32offs = ANM2_ACC_U32_SITES.map((s) => s.offset);
  eq(u32offs[0], 0x28); eq(u32offs[1], 0x2c); eq(u32offs[2], 0x30);
  eq(u32offs[3], 0xc); eq(u32offs[4], 0x188); eq(u32offs[5], 0x330);
  eq(u32offs[6], 0x3c8); eq(u32offs[7], 0x1e68);

  const f32vas = ANM2_ACC_F32_SITES.map((s) => s.va);
  eq(f32vas[0], 0x00417210); eq(f32vas[1], 0x00417330);
  eq(f32vas[2], 0x00417360); eq(f32vas[3], 0x00417370);
  const f32offs = ANM2_ACC_F32_SITES.map((s) => s.offset);
  eq(f32offs[0], 0xa4); eq(f32offs[1], 0xec);
  eq(f32offs[2], 0x384); eq(f32offs[3], 0x380);

  eq(ANM2_ACC_PAIR_SITES[0].va, 0x00417290);
  eq(ANM2_ACC_PAIR_SITES[0].offset0, 0x33c);
  eq(ANM2_ACC_PAIR_SITES[0].offset1, 0x340);
  eq(ANM2_ACC_PAIR_SITES[1].va, 0x004172b0);
  eq(ANM2_ACC_PAIR_SITES[1].offset0, 0x38c);
  eq(ANM2_ACC_PAIR_SITES[1].offset1, 0x390);
  eq(ANM2_ACC_PAIR_SITES[2].va, 0x004172d0);
  eq(ANM2_ACC_PAIR_SITES[2].offset0, 0x360);
  eq(ANM2_ACC_PAIR_SITES[2].offset1, 0x364);

  /* Fixed edges on every pinned offset. */
  for (const s of ANM2_ACC_U32_SITES) {
    pokeU32(V88_OBJ + s.offset, (0x11223344 ^ s.offset) >>> 0);
    const { p, o } = v88RunU32(s.offset);
    eq(p >>> 0, o >>> 0, `u32 ${s.va.toString(16)}`);
    eq(p >>> 0, (0x11223344 ^ s.offset) >>> 0, `u32 value ${s.va}`);
  }
  for (const s of ANM2_ACC_F32_SITES) {
    pokeU32(V88_OBJ + s.offset, 0x7fc00000);
    const { p, o } = v88RunF32(s.offset);
    eq(p >>> 0, o >>> 0, `f32 ${s.va.toString(16)}`);
  }
  for (const s of ANM2_ACC_PAIR_SITES) {
    pokeU32(V88_OBJ + s.offset0, 0xcafebabe);
    pokeU32(V88_OBJ + s.offset0 + 4, 0x0badf00d);
    const { p, o } = v88RunPair(s.offset0);
    eqV58PlanFields(p, o, ["entered","thisAddr","off","lo","hi",
                           "pureComplete","hostCallCount"],
                    `pair ${s.va.toString(16)}`);
    eq(p.lo >>> 0, 0xcafebabe, `pair lo ${s.va}`);
    eq(p.hi >>> 0, 0x0badf00d, `pair hi ${s.va}`);
    eq(p.pureComplete, 1, "pair pure");
    eq(p.hostCallCount, 0, "pair no host");
  }

  /* Null this. */
  eq(wasm.isaac_anm2_u32_field_get(0, 0x28) >>> 0, 0, "null u32");
  eq(wasm.isaac_anm2_f32_field_get_bits(0, 0xa4) >>> 0, 0, "null f32");
  wasm.isaac_anm2_pair_field_get_plan(0, 0x33c, V88_PAIRPLAN);
  eq(readPlanU32At(V88_PAIRPLAN, 0), 0, "null pair not entered");

  eq(wasm.isaac_anm2_pure_helpers_abi_version(), 77, "ABI bump export");
  COUNT.cases += 70;
});

test("v88 unit: randomized differential (wasm vs oracle)", () => {
  if (wasm === undefined) {
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  const rng = makeRng(0x00417260);
  for (let t = 0; t < 150; ++t) {
    const lo = rng.u32(), hi = rng.u32();
    v88Seed(lo, hi);
    const off = [0x28, 0x2c, 0x30, 0xc, 0x188, 0x330, 0x3c8, 0x1e68,
                 0x33c, 0x38c, 0x360][rng.below(11)];
    /* Shadow hygiene: earlier units may have poked these offsets under a
       since-rebuilt module instance, leaving stale shadow bytes the fresh
       wasm memory does not have. Re-plant both cells so wasm and oracle
       read an identical world. */
    pokeU32(V88_OBJ + off, lo >>> 0);
    pokeU32(V88_OBJ + off + 4, hi >>> 0);
    const kind = rng.below(3);
    if (kind === 0) {
      const { p, o } = v88RunU32(off);
      eq(p >>> 0, o >>> 0, `u32 t${t}`);
    } else if (kind === 1) {
      const { p, o } = v88RunF32(off);
      eq(p >>> 0, o >>> 0, `f32 t${t}`);
    } else {
      const { p, o } = v88RunPair(off);
      eqV58PlanFields(p, o, ["entered","thisAddr","off","lo","hi",
                             "pureComplete","hostCallCount"], `pair t${t}`);
    }
  }
  COUNT.cases += 150;
});

