test("v88 unit: mutations are caught by the pins", () => {
  const sha256 = (txt) =>
    createHash("sha256").update(txt, "utf8").digest("hex");
  const originalBuf = readFileSync(source);
  const originalHash = sha256(originalBuf.toString("utf8"));
  const original = originalBuf.toString("utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const withMutant = (label, mutate, check, probe) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      wasm = loadExports();
      wmem = new Uint8Array(wasm.memory.buffer);
      if (probe) {
        const diverged = probe();
        assert.ok(diverged,
                  `${label}: rebuilt module not mutant (stale build)`);
      }
      check();
    } catch {
      threw = true;
    }
    writeSourceRetry(original);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    /* G1: u32 getter reads the wrong cell (+4). */
    withMutant("u32 get off by 4",
      (s) => s.replace(
        "  return load_u32(th + off);          /* mov eax,[ecx+off]; ret */",
        "  return load_u32(th + off + 4u);     /* mov eax,[ecx+off]; ret */"),
      () => {
        v88Seed(0x11223344, 0);
        eq(wasm.isaac_anm2_u32_field_get(V88_OBJ, 0) >>> 0, 0x11223344,
           "lo word");
      },
      () => {
        v88Seed(0x11223344, 0);
        return (wasm.isaac_anm2_u32_field_get(V88_OBJ, 0) >>> 0) !==
               0x11223344;
      });
    /* G2: f32 getter rounds through a float -- must return raw bits. */
    withMutant("f32 get rounds",
      (s) => s.replace(
        "  /* fld dword [ecx+off]; ret -- value returned in st(0); we report the\n     raw 32-bit memory image (no rounding ever touches it). */\n  return load_u32(th + off);",
        "  /* fld dword [ecx+off]; ret -- value returned in st(0); we report the\n     raw 32-bit memory image (no rounding ever touches it). */\n  return static_cast<uint32_t>(*reinterpret_cast<const float*>(th + off));"),
      () => {
        pokeU32(V88_OBJ, 0x7fc00000);   /* quiet NaN: float round-trip
                                           via double narrows the payload */
        const got = wasm.isaac_anm2_f32_field_get_bits(V88_OBJ, 0) >>> 0;
        eq(got >>> 0, 0x7fc00000, "NaN payload must survive");
      },
      () => {
        pokeU32(V88_OBJ, 0x7fc00000);
        return (wasm.isaac_anm2_f32_field_get_bits(V88_OBJ, 0) >>> 0) !==
               0x7fc00000;
      });
    /* G3: pair plan swaps lo/hi. */
    withMutant("pair get swaps lo/hi",
      (s) => s.replace(
        "  plan.lo = load_u32(th + off);       /* 0x00417296/9c etc */\n  plan.hi = load_u32(th + off + 4u);  /* 0x0041729c/a2 */",
        "  plan.lo = load_u32(th + off + 4u);  /* 0x00417296/9c etc */\n  plan.hi = load_u32(th + off);       /* 0x0041729c/a2 */"),
      () => {
        v88Seed(0xcafebabe, 0x0badf00d);
        wasm.isaac_anm2_pair_field_get_plan(V88_OBJ, 0x33c, V88_PAIRPLAN);
        eq(readPlanU32At(V88_PAIRPLAN, 12) >>> 0, 0xcafebabe, "lo");
      },
      () => {
        v88Seed(0xcafebabe, 0x0badf00d);
        wasm.isaac_anm2_pair_field_get_plan(V88_OBJ, 0x33c, V88_PAIRPLAN);
        return readPlanU32At(V88_PAIRPLAN, 12) >>> 0 !== 0xcafebabe;
      });
    /* G4: pair purity flag flipped -- all three accessor templates are
       fully pure (no E8/indirect in any pinned body). */
    withMutant("pair purity flag dropped",
      (s) => s.replace(
        "  plan.pure_complete = 1;\n  plan.host_call_count = 0;\n\n  if (th == nullptr) {",
        "  plan.pure_complete = 0;\n  plan.host_call_count = 0;\n\n  if (th == nullptr) {"),
      () => {
        v88Seed(1, 2);
        const { p } = v88RunPair(0x33c);
        eq(p.pureComplete, 1, "pair law is pure-complete");
      },
      () => {
        v88Seed(1, 2);
        const { p } = v88RunPair(0x33c);
        return p.pureComplete !== 1;
      });
  } finally {
    writeSourceRetry(original);
    wasm = loadExports();
    wmem = new Uint8Array(wasm.memory.buffer);
  }
  eq(sha256(readFileSync(source).toString("utf8")), originalHash,
     "v88 mutation round restored source byte-exact");
  COUNT.cases += 8;
});

